// Execution practicality. PSX regular-market equities use a one-share
// marketable lot, but NOMAD still avoids economically trivial positions.
const DECISION_MIN_MEANINGFUL_POSITION_PKR = 1000;
const DECISION_MAX_MEANINGFUL_POSITION_FLOOR_PKR = 50000;
const DECISION_MEANINGFUL_POSITION_BUDGET_PCT = 0.05;

function decisionClamp(
  value,
  minimum = 0,
  maximum = 100
) {
  const number =
    safeNumber(value);

  if (number === null) {
    return minimum;
  }

  return Math.min(
    maximum,
    Math.max(
      minimum,
      number
    )
  );
}

function decisionRound(
  value,
  digits = 2
) {
  return roundMemoryNumber(
    value,
    digits
  );
}

function decisionPercentile(
  value,
  values,
  higherIsBetter = true
) {
  const number =
    safeNumber(value);

  const clean =
    (Array.isArray(values)
      ? values
      : [])
      .map(
        item =>
          safeNumber(item)
      )
      .filter(
        item =>
          item !== null
      )
      .sort(
        (
          a,
          b
        ) =>
          a - b
      );

  if (
    number === null ||
    !clean.length
  ) {
    return 40;
  }

  if (clean.length === 1) {
    return 60;
  }

  let belowOrEqual =
    0;

  for (
    const item
    of clean
  ) {
    if (item <= number) {
      belowOrEqual++;
    }
  }

  const percentile =
    (
      belowOrEqual - 1
    ) /
    Math.max(
      1,
      clean.length - 1
    );

  return decisionClamp(
    (
      higherIsBetter
        ? percentile
        : 1 - percentile
    ) *
      100
  );
}

function decisionFinancialRow(
  table,
  matcher
) {
  return table?.rows
    ?.find(
      row =>
        matcher.test(
          String(
            row.label ||
            ''
          )
        )
    ) ||
    null;
}

function decisionFinancialMetric(
  table,
  matcher
) {
  const row =
    decisionFinancialRow(
      table,
      matcher
    );

  const item =
    row?.values?.[0] ||
    null;

  return item
    ? {
        label:
          row.label,
        period:
          item.period ||
          null,
        value:
          safeNumber(
            item.value
          )
      }
    : null;
}

function decisionFinancialYoY(
  table,
  matcher
) {
  const row =
    decisionFinancialRow(
      table,
      matcher
    );

  if (
    !row?.values ||
    row.values.length < 2
  ) {
    return null;
  }

  const latest =
    safeNumber(
      row.values[0]?.value
    );

  const previous =
    safeNumber(
      row.values[1]?.value
    );

  if (
    latest === null ||
    previous === null ||
    previous === 0
  ) {
    return null;
  }

  return (
    latest -
    previous
  ) /
    Math.abs(previous) *
    100;
}

function decisionMetricFromRatios(
  ratios,
  matcher
) {
  return decisionFinancialMetric(
    ratios,
    matcher
  );
}

function scoreDecisionFundamentals(
  fundamentals
) {
  if (!fundamentals?.available) {
    return {
      available: false,
      score: 35,
      coverage: 0,
      metrics: {},
      reasons: [
        'Structured PSX fundamentals were unavailable during this decision run.'
      ],
      risks: [
        'NOMAD will not issue a fully supported long-term buy without sufficient fundamental evidence.'
      ]
    };
  }

  const eps =
    decisionFinancialMetric(
      fundamentals.annual,
      /^EPS$/i
    );

  const pat =
    decisionFinancialMetric(
      fundamentals.annual,
      /profit after taxation/i
    );

  const income =
    decisionFinancialMetric(
      fundamentals.annual,
      /^(sales|total income|mark-up earned|revenue)$/i
    );

  const roe =
    decisionMetricFromRatios(
      fundamentals.ratios,
      /return on equity|\broe\b/i
    );

  const margin =
    decisionMetricFromRatios(
      fundamentals.ratios,
      /net profit margin/i
    );

  const epsYoY =
    decisionFinancialYoY(
      fundamentals.annual,
      /^EPS$/i
    );

  const patYoY =
    decisionFinancialYoY(
      fundamentals.annual,
      /profit after taxation/i
    );

  const incomeYoY =
    decisionFinancialYoY(
      fundamentals.annual,
      /^(sales|total income|mark-up earned|revenue)$/i
    );

  let score = 50;
  let observed = 0;
  const reasons = [];
  const risks = [];

  if (eps?.value !== null && eps?.value !== undefined) {
    observed++;

    if (eps.value > 0) {
      score += 10;
      reasons.push(
        'Latest annual EPS is positive.'
      );
    } else {
      score -= 25;
      risks.push(
        'Latest annual EPS is not positive.'
      );
    }
  }

  if (epsYoY !== null) {
    observed++;

    if (epsYoY >= 15) {
      score += 12;
      reasons.push(
        'Annual EPS growth is strong.'
      );
    } else if (epsYoY >= 0) {
      score += 6;
      reasons.push(
        'Annual EPS is growing.'
      );
    } else if (epsYoY <= -20) {
      score -= 15;
      risks.push(
        'Annual EPS has declined materially.'
      );
    } else {
      score -= 6;
      risks.push(
        'Annual EPS growth is negative.'
      );
    }
  }

  if (pat?.value !== null && pat?.value !== undefined) {
    observed++;

    if (pat.value > 0) {
      score += 8;
      reasons.push(
        'Latest annual profit after tax is positive.'
      );
    } else {
      score -= 20;
      risks.push(
        'Latest annual profit after tax is not positive.'
      );
    }
  }

  if (patYoY !== null) {
    observed++;

    if (patYoY >= 15) {
      score += 10;
      reasons.push(
        'Profit after tax growth is strong.'
      );
    } else if (patYoY >= 0) {
      score += 5;
    } else if (patYoY <= -20) {
      score -= 12;
      risks.push(
        'Profit after tax has declined materially.'
      );
    } else {
      score -= 5;
    }
  }

  if (incomeYoY !== null) {
    observed++;

    if (incomeYoY >= 10) {
      score += 6;
      reasons.push(
        'Top-line/income growth is positive.'
      );
    } else if (incomeYoY < -10) {
      score -= 6;
      risks.push(
        'Top-line/income growth is weak.'
      );
    }
  }

  if (roe?.value !== null && roe?.value !== undefined) {
    observed++;

    if (roe.value >= 20) {
      score += 10;
      reasons.push(
        'Return on equity is strong.'
      );
    } else if (roe.value >= 12) {
      score += 6;
    } else if (roe.value < 0) {
      score -= 12;
      risks.push(
        'Return on equity is negative.'
      );
    }
  }

  if (margin?.value !== null && margin?.value !== undefined) {
    observed++;

    if (margin.value > 0) {
      score += 4;
    } else {
      score -= 8;
    }
  }

  const coverage =
    decisionClamp(
      observed /
        7 *
        100
    );

  if (coverage < 40) {
    risks.push(
      'Fundamental metric coverage is limited.'
    );
  }

  return {
    available: true,
    score:
      decisionRound(
        decisionClamp(score),
        2
      ),
    coverage:
      decisionRound(
        coverage,
        2
      ),
    metrics: {
      eps,
      epsYoY:
        decisionRound(
          epsYoY,
          2
        ),
      profitAfterTax:
        pat,
      profitAfterTaxYoY:
        decisionRound(
          patYoY,
          2
        ),
      income,
      incomeYoY:
        decisionRound(
          incomeYoY,
          2
        ),
      roe,
      netProfitMargin:
        margin
    },
    reasons,
    risks
  };
}

function scoreDecisionValuation(
  row,
  eligibleRows
) {
  const pe =
    safeNumber(
      row?.peRatio
    );

  const dividendYield =
    safeNumber(
      row?.dividendYield
    );

  const sectorRows =
    (eligibleRows || [])
      .filter(
        item =>
          String(
            item.sector ||
            ''
          ) ===
            String(
              row?.sector ||
              ''
            ) &&
          safeNumber(
            item.peRatio
          ) !== null &&
          safeNumber(
            item.peRatio
          ) > 0 &&
          safeNumber(
            item.peRatio
          ) < 100
      );

  const comparisonRows =
    sectorRows.length >= 4
      ? sectorRows
      : (eligibleRows || [])
          .filter(
            item => {
              const value =
                safeNumber(
                  item.peRatio
                );

              return (
                value !== null &&
                value > 0 &&
                value < 100
              );
            }
          );

  const relativePeScore =
    pe !== null &&
    pe > 0
      ? decisionPercentile(
          pe,
          comparisonRows.map(
            item =>
              item.peRatio
          ),
          false
        )
      : 40;

  let absolutePeScore = 40;

  if (
    pe !== null &&
    pe > 0
  ) {
    if (pe < 3) {
      absolutePeScore = 50;
    } else if (pe <= 10) {
      absolutePeScore = 90;
    } else if (pe <= 15) {
      absolutePeScore = 78;
    } else if (pe <= 25) {
      absolutePeScore = 62;
    } else if (pe <= 40) {
      absolutePeScore = 38;
    } else {
      absolutePeScore = 20;
    }
  }

  let dividendScore = 45;

  if (dividendYield !== null) {
    if (dividendYield >= 8 && dividendYield <= 15) {
      dividendScore = 88;
    } else if (dividendYield >= 4) {
      dividendScore = 72;
    } else if (dividendYield > 0) {
      dividendScore = 56;
    } else {
      dividendScore = 40;
    }

    if (dividendYield > 15) {
      dividendScore = 62;
    }
  }

  const score =
    relativePeScore *
      0.55 +
    absolutePeScore *
      0.30 +
    dividendScore *
      0.15;

  const reasons = [];
  const risks = [];

  if (pe !== null) {
    reasons.push(
      'P/E ' +
      decisionRound(
        pe,
        2
      ) +
      ' is compared with the stock\'s sector where sufficient peers exist.'
    );
  } else {
    risks.push(
      'Positive P/E data is unavailable.'
    );
  }

  if (
    dividendYield !== null &&
    dividendYield >= 4
  ) {
    reasons.push(
      'Dividend yield contributes positively to the valuation/income view.'
    );
  }

  return {
    score:
      decisionRound(
        decisionClamp(score),
        2
      ),
    peRatio:
      decisionRound(
        pe,
        2
      ),
    dividendYield:
      decisionRound(
        dividendYield,
        2
      ),
    relativePeScore:
      decisionRound(
        relativePeScore,
        2
      ),
    reasons,
    risks
  };
}

function scoreDecisionEntry(
  context,
  horizon,
  riskPolicy
) {
  if (!context?.available) {
    return {
      score: 20,
      reasons: [],
      risks: [
        'Historical price context is unavailable.'
      ]
    };
  }

  let score = 50;
  const reasons = [];
  const risks = [];
  const returns =
    context.returns ||
    {};
  const technical =
    context.technical ||
    {};
  const averages =
    context.movingAverages ||
    {};
  const price =
    safeNumber(
      context.price
    );

  const rsi =
    safeNumber(
      technical.rsi14
    );

  const macdHistogram =
    safeNumber(
      technical.macdHistogram
    );

  const volumeRatio =
    safeNumber(
      technical.volumeRatio20d
    );

  const volatility =
    safeNumber(
      technical.annualizedVolatility20dPct
    );

  if (horizon === 'short_term') {
    if (context.trend === 'Uptrend') {
      score += 18;
      reasons.push(
        'Short/medium trend is positive.'
      );
    } else if (context.trend === 'Downtrend') {
      score -= 18;
      risks.push(
        'Short/medium trend is negative.'
      );
    }

    const d5 =
      safeNumber(
        returns.d5
      );

    const m1 =
      safeNumber(
        returns.m1
      );

    if (d5 !== null) {
      if (d5 > 0 && d5 <= 8) {
        score += 8;
      } else if (d5 > 8 && d5 <= 15) {
        score += 3;
        risks.push(
          'Recent move is already extended; chase risk is higher.'
        );
      } else if (d5 > 15) {
        score -= 5;
        risks.push(
          'Five-session move is very extended.'
        );
      } else if (d5 < 0) {
        score -= 8;
      }
    }

    if (m1 !== null) {
      if (m1 > 0) {
        score += 10;
      } else {
        score -= 10;
      }
    }

    if (rsi !== null) {
      if (rsi >= 50 && rsi <= 68) {
        score += 8;
        reasons.push(
          'RSI supports positive momentum without being extremely extended.'
        );
      } else if (rsi >= 75) {
        score -= 10;
        risks.push(
          'RSI is highly extended.'
        );
      } else if (rsi < 35) {
        score -= 8;
        risks.push(
          'RSI shows weak momentum.'
        );
      }
    }

    if (macdHistogram !== null) {
      if (macdHistogram > 0) {
        score += 8;
      } else {
        score -= 8;
      }
    }

    if (volumeRatio !== null) {
      if (volumeRatio >= 1.2 && volumeRatio <= 3) {
        score += 8;
        reasons.push(
          'Volume participation is above its recent average.'
        );
      } else if (volumeRatio < 0.5) {
        score -= 5;
      }
    }
  } else {
    if (context.trend === 'Uptrend') {
      score += 15;
      reasons.push(
        'Price is above the short and medium moving averages.'
      );
    } else if (context.trend === 'Downtrend') {
      score -= 12;
      risks.push(
        'Price remains below the short and medium moving averages.'
      );
    }

    const sma200 =
      safeNumber(
        averages.sma200
      );

    if (
      price !== null &&
      sma200 !== null
    ) {
      if (price >= sma200) {
        score += 8;
        reasons.push(
          'Price is above the 200-session moving average.'
        );
      } else {
        score -= 8;
        risks.push(
          'Price is below the 200-session moving average.'
        );
      }
    }

    const m1 =
      safeNumber(
        returns.m1
      );

    const m3 =
      safeNumber(
        returns.m3
      );

    if (m1 !== null) {
      if (m1 >= -5 && m1 <= 10) {
        score += 5;
      } else if (m1 > 10 && m1 <= 20) {
        score += 2;
      } else if (m1 > 20) {
        score -= 4;
        risks.push(
          'One-month price move is extended; entry risk is higher.'
        );
      } else if (m1 < -10) {
        score -= 8;
        risks.push(
          'One-month performance is weak.'
        );
      }
    }

    if (m3 !== null) {
      if (m3 > 0) {
        score += 6;
      } else if (m3 < -15) {
        score -= 8;
      }
    }

    if (rsi !== null) {
      if (rsi >= 40 && rsi <= 65) {
        score += 8;
      } else if (rsi >= 70) {
        score -= 7;
        risks.push(
          'RSI indicates a stretched entry.'
        );
      } else if (rsi <= 25) {
        score -= 4;
        risks.push(
          'Very low RSI is treated as weakness, not an automatic buy signal.'
        );
      }
    }

    if (macdHistogram !== null) {
      if (macdHistogram > 0) {
        score += 6;
      } else {
        score -= 6;
      }
    }

    if (
      volumeRatio !== null &&
      volumeRatio >= 0.8 &&
      volumeRatio <= 2.5
    ) {
      score += 3;
    }
  }

  if (
    volatility !== null &&
    volatility >
      riskPolicy.maxAnnualizedVolatilityPct
  ) {
    score -= 12;
    risks.push(
      'Recent annualized volatility exceeds this risk profile\'s experimental limit.'
    );
  }

  return {
    score:
      decisionRound(
        decisionClamp(score),
        2
      ),
    reasons,
    risks
  };
}

function scoreDecisionRisk(
  row,
  context,
  eligibleRows
) {
  const liquidityScore =
    decisionPercentile(
      row?.averageVolume30d,
      (eligibleRows || []).map(
        item =>
          item.averageVolume30d
      ),
      true
    );

  const sizeScore =
    decisionPercentile(
      row?.marketCap,
      (eligibleRows || []).map(
        item =>
          item.marketCap
      ),
      true
    );

  const volatility =
    safeNumber(
      context?.technical
        ?.annualizedVolatility20dPct
    );

  let volatilityScore = 45;

  if (volatility !== null) {
    if (volatility <= 30) {
      volatilityScore = 90;
    } else if (volatility <= 45) {
      volatilityScore = 76;
    } else if (volatility <= 60) {
      volatilityScore = 58;
    } else if (volatility <= 80) {
      volatilityScore = 38;
    } else {
      volatilityScore = 18;
    }
  }

  const drawdown =
    safeNumber(
      context?.technical
        ?.maxDrawdown52wPct
    );

  let drawdownScore = 45;

  if (drawdown !== null) {
    if (drawdown >= -15) {
      drawdownScore = 88;
    } else if (drawdown >= -30) {
      drawdownScore = 68;
    } else if (drawdown >= -50) {
      drawdownScore = 42;
    } else {
      drawdownScore = 20;
    }
  }

  let score =
    liquidityScore * 0.35 +
    sizeScore * 0.25 +
    volatilityScore * 0.25 +
    drawdownScore * 0.15;

  const statusCodes =
    Array.isArray(
      row?.statusCodes
    )
      ? row.statusCodes
      : [];

  const risks = [];
  const reasons = [];

  if (statusCodes.includes('NC')) {
    score = Math.min(
      score,
      15
    );
    risks.push(
      'PSX non-compliant-segment status is present; NOMAD excludes this from new-buy decisions.'
    );
  }

  if (liquidityScore >= 70) {
    reasons.push(
      '30-day trading liquidity ranks well within the eligible universe.'
    );
  }

  if (
    volatility !== null &&
    volatility <= 45
  ) {
    reasons.push(
      'Recent volatility is moderate relative to the engine\'s current risk scale.'
    );
  }

  return {
    score:
      decisionRound(
        decisionClamp(score),
        2
      ),
    liquidityScore:
      decisionRound(
        liquidityScore,
        2
      ),
    sizeScore:
      decisionRound(
        sizeScore,
        2
      ),
    volatility:
      decisionRound(
        volatility,
        2
      ),
    maxDrawdown52wPct:
      decisionRound(
        drawdown,
        2
      ),
    reasons,
    risks
  };
}

function scoreDecisionDataQuality(
  row,
  context,
  fundamental
) {
  let score = 0;
  const missing = [];

  if (
    safeNumber(
      row?.price
    ) !== null
  ) {
    score += 10;
  } else {
    missing.push('price');
  }

  if (
    safeNumber(
      row?.averageVolume30d
    ) !== null
  ) {
    score += 10;
  } else {
    missing.push('30-day liquidity');
  }

  if (context?.available) {
    score += 25;

    if (
      safeNumber(
        context.validSessions
      ) >= 200
    ) {
      score += 10;
    }
  } else {
    missing.push('price history');
  }

  if (fundamental?.available) {
    score += 25;

    if (
      fundamental.coverage >= 40
    ) {
      score += 10;
    }
  } else {
    missing.push('structured fundamentals');
  }

  if (
    safeNumber(
      row?.peRatio
    ) !== null
  ) {
    score += 5;
  }

  if (
    row?.companyName &&
    row?.sector &&
    row.sector !== 'Unknown'
  ) {
    score += 5;
  }

  return {
    score:
      decisionRound(
        decisionClamp(score),
        2
      ),
    missing
  };
}

function decisionScreeningScore(
  row,
  eligibleRows
) {
  const liquidity =
    decisionPercentile(
      row.averageVolume30d,
      eligibleRows.map(
        item =>
          item.averageVolume30d
      ),
      true
    );

  const size =
    decisionPercentile(
      row.marketCap,
      eligibleRows.map(
        item =>
          item.marketCap
      ),
      true
    );

  const valuation =
    scoreDecisionValuation(
      row,
      eligibleRows
    ).score;

  const oneYear =
    safeNumber(
      row.change1yPct
    );

  let stability = 50;

  if (oneYear !== null) {
    if (
      oneYear >= -20 &&
      oneYear <= 60
    ) {
      stability = 70;
    } else if (
      oneYear < -40 ||
      oneYear > 120
    ) {
      stability = 25;
    } else {
      stability = 48;
    }
  }

  return decisionRound(
    liquidity * 0.35 +
    size * 0.20 +
    valuation * 0.35 +
    stability * 0.10,
    2
  );
}

function decisionTraderScreeningScore(
  row,
  eligibleRows
) {
  const liquidity =
    decisionPercentile(
      row?.averageVolume30d,
      (eligibleRows || []).map(
        item => item.averageVolume30d
      ),
      true
    );

  const size =
    decisionPercentile(
      row?.marketCap,
      (eligibleRows || []).map(
        item => item.marketCap
      ),
      true
    );

  const dayChange =
    safeNumber(row?.dayChangePct);
  const oneYear =
    safeNumber(row?.change1yPct);

  // Trader pre-screening should surface momentum and breakout candidates rather
  // than suppressing them merely because today's move was large. The deeper
  // OHLC engine still decides whether the move is extended or tradable.
  let moveQuality = 55;
  if (dayChange !== null) {
    if (dayChange >= 1 && dayChange <= 8) {
      moveQuality = 82;
    } else if (dayChange > 8 && dayChange <= 15) {
      moveQuality = 74;
    } else if (dayChange > 15) {
      moveQuality = 58;
    } else if (dayChange >= 0) {
      moveQuality = 64;
    } else if (dayChange >= -3) {
      moveQuality = 55;
    } else if (dayChange >= -8) {
      moveQuality = 42;
    } else {
      moveQuality = 28;
    }
  }

  let trendPrior = 55;
  if (oneYear !== null) {
    if (oneYear >= 0 && oneYear <= 150) {
      trendPrior = 70;
    } else if (oneYear > 150) {
      trendPrior = 58;
    } else if (oneYear >= -25) {
      trendPrior = 52;
    } else if (oneYear < -50) {
      trendPrior = 30;
    }
  }

  return decisionRound(
    liquidity * 0.40 +
    size * 0.10 +
    moveQuality * 0.30 +
    trendPrior * 0.20,
    2
  );
}

function decisionTraderHistoricalOpportunityScore(
  historicalContext,
  screeningScore,
  riskScore
) {
  const priceAction =
    historicalContext?.priceAction ||
    {};

  const setup =
    priceAction.setup ||
    'NO_CLEAR_SETUP';

  const setupScore =
    setup === 'CONFIRMED_BREAKOUT'
      ? 95
      : setup === 'TREND_PULLBACK'
        ? 90
        : setup === 'UPTREND_CONTINUATION'
          ? 82
          : setup === 'UNCONFIRMED_BREAKOUT'
            ? 76
            : setup === 'NO_CLEAR_SETUP'
              ? 45
              : setup === 'DOWNTREND'
                ? 24
                : setup === 'BREAKDOWN'
                  ? 10
                  : 40;

  const currentRewardRisk =
    safeNumber(
      priceAction?.tradePlan?.rewardRisk
    );
  const conditionalRewardRisk =
    safeNumber(
      priceAction?.conditionalTradePlan
        ?.rewardRisk
    );

  let planScore = 42;
  if (
    currentRewardRisk !== null &&
    currentRewardRisk >=
      DECISION_TRADER_MIN_REWARD_RISK
  ) {
    planScore = 95;
  } else if (
    conditionalRewardRisk !== null &&
    conditionalRewardRisk >=
      DECISION_TRADER_MIN_REWARD_RISK
  ) {
    planScore = 82;
  } else if (
    priceAction?.tradePlan?.complete
  ) {
    planScore = 58;
  }

  const timingScore =
    safeNumber(priceAction?.timingScore) ||
    0;

  return decisionRound(
    decisionClamp(
      setupScore * 0.28 +
      timingScore * 0.27 +
      planScore * 0.22 +
      (safeNumber(riskScore) || 0) * 0.13 +
      (safeNumber(screeningScore) || 0) * 0.10
    ),
    2
  );
}

function decisionCandidateAction(
  candidate,
  model,
  riskPolicy
) {
  const dataQuality =
    safeNumber(
      candidate.dataQuality?.score
    ) ||
    0;

  const fundamentalScore =
    safeNumber(
      candidate.fundamental?.score
    ) ||
    0;

  const entryScore =
    safeNumber(
      candidate.entry?.score
    ) ||
    0;

  const riskScore =
    safeNumber(
      candidate.risk?.score
    ) ||
    0;

  const overallScore =
    safeNumber(
      candidate.overallScore
    ) ||
    0;

  if (
    candidate.statusCodes
      ?.includes('NC')
  ) {
    return {
      action: 'AVOID',
      reason:
        'Listing-compliance status is present.'
    };
  }

  if (
    dataQuality <
    riskPolicy.minDataQualityScore
  ) {
    return {
      action: 'DATA_BLOCKED',
      reason:
        'Critical evidence coverage is below this risk profile\'s threshold.'
    };
  }

  if (
    !candidate.fundamental?.available
  ) {
    return {
      action: 'DATA_BLOCKED',
      reason:
        'NOMAD will not promote a new-buy candidate without structured company fundamentals.'
    };
  }

  if (fundamentalScore < 45) {
    return {
      action: 'AVOID',
      reason:
        'Current fundamental evidence is too weak for a new position.'
    };
  }

  if (
    riskScore <
    riskPolicy.minRiskScore
  ) {
    return {
      action: 'AVOID',
      reason:
        'Risk/liquidity evidence does not pass the selected profile.'
    };
  }

  if (
    overallScore >=
      riskPolicy.minOverallScore &&
    entryScore >=
      (
        model.horizon ===
          'short_term'
          ? 65
          : 60
      )
  ) {
    return {
      action: 'BUY_NOW',
      reason:
        'The current shadow model passes quality, risk and entry gates.'
    };
  }

  if (
    model.horizon ===
      'long_term' &&
    overallScore >=
      riskPolicy.minOverallScore - 2 &&
    fundamentalScore >= 62 &&
    entryScore >= 46
  ) {
    return {
      action: 'STAGED_BUY',
      reason:
        'Long-term evidence is acceptable, but entry quality is not strong enough for a full allocation.'
    };
  }

  if (
    overallScore >=
      riskPolicy.minOverallScore - 10 &&
    fundamentalScore >= 55
  ) {
    return {
      action: 'WAIT',
      reason:
        'The company remains worth monitoring, but the full decision threshold is not met.'
    };
  }

  return {
    action: 'AVOID',
    reason:
      'The candidate does not pass the current shadow model.'
  };
}

function decisionCenterAnalystGate(
  candidate
) {
  const analyst =
    candidate?.analystCore ||
    null;

  if (!analyst) {
    return {
      state: 'RESEARCHING',
      validationTier: 'NONE',
      reason:
        'NOMAD could not complete the first-pass Financial Analyst evidence. The company remains visible and enters automatic evidence research instead of being silently discarded.'
    };
  }

  const summaryCoverage =
    safeNumber(
      analyst.coverage
        ?.summaryCoveragePct ??
      analyst.coverage
        ?.coreCoveragePct
    ) ||
    0;

  const extendedCoverage =
    safeNumber(
      analyst.coverage
        ?.extendedCoveragePct
    ) ||
    0;

  const overall =
    String(
      analyst.overallFinancialView
        ?.state ||
      'UNRELIABLE'
    );

  const earnings =
    String(
      analyst.views
        ?.earningsQuality
        ?.state ||
      'UNRELIABLE'
    );

  const cash =
    String(
      analyst.views
        ?.cashFlowQuality
        ?.state ||
      'UNRELIABLE'
    );

  const balance =
    String(
      analyst.views
        ?.balanceSheet
        ?.state ||
      'UNRELIABLE'
    );

  if (
    analyst.company
      ?.financialSector ===
        true
  ) {
    return {
      state: 'RESEARCHING',
      validationTier: 'SECTOR_MODEL_REQUIRED',
      reason:
        'This company requires a financial-sector-specific analyst model before NOMAD can validate a new-money thesis. NOMAD keeps it in evidence research rather than applying the wrong generic model.'
    };
  }

  // Explicit negative evidence is different from missing evidence.
  // Missing evidence triggers research; verified weakness can reject a thesis.
  if (
    overall === 'WEAK' ||
    cash === 'WEAK'
  ) {
    return {
      state: 'REJECT',
      validationTier:
        extendedCoverage >= 67
          ? 'FULL_STATEMENT'
          : 'PSX_SUMMARY',
      reason:
        overall === 'WEAK'
          ? 'The available Financial Analyst evidence classifies the current financial view as weak.'
          : 'Verified cash-flow evidence is weak relative to reported earnings.'
    };
  }

  if (
    summaryCoverage < 80 ||
    overall === 'UNRELIABLE'
  ) {
    return {
      state: 'RESEARCHING',
      validationTier: 'INCOMPLETE_SUMMARY',
      reason:
        'Headline financial evidence is incomplete. NOMAD will keep researching the company and continue through the ranked universe instead of letting this missing evidence consume a deep-analysis slot.'
    };
  }

  if (
    earnings === 'QUESTIONABLE' ||
    cash === 'QUESTIONABLE' ||
    overall === 'MIXED'
  ) {
    return {
      state: 'REVIEW',
      validationTier:
        extendedCoverage >= 67
          ? 'FULL_STATEMENT'
          : 'PSX_SUMMARY',
      reason:
        'The evidence is usable, but a quality or trend concern prevents high-conviction validation.'
    };
  }

  const hasExtendedValidation =
    extendedCoverage >= 67 &&
    cash !== 'UNRELIABLE' &&
    balance !== 'UNRELIABLE' &&
    earnings !== 'UNRELIABLE';

  if (
    overall === 'GOOD' &&
    hasExtendedValidation
  ) {
    return {
      state: 'VALIDATED',
      validationTier: 'FULL_STATEMENT',
      reason:
        'Headline and extended financial evidence pass the current analyst gate.'
    };
  }

  if (overall === 'GOOD') {
    return {
      state: 'PARTIALLY_VALIDATED',
      validationTier: 'PSX_SUMMARY',
      reason:
        'Official PSX headline financials support the thesis, but full cash-flow/balance-sheet validation is not yet available. NOMAD can only consider staged exposure with lower confidence.'
    };
  }

  return {
    state: 'REVIEW',
    validationTier: 'PSX_SUMMARY',
    reason:
      'The headline evidence is usable but does not yet support a high-conviction thesis.'
  };
}

function decisionEvidenceProfile(
  candidate,
  analystGate
) {
  const analyst =
    candidate?.analystCore ||
    null;

  const summaryCoverage =
    safeNumber(
      analyst?.coverage
        ?.summaryCoveragePct ??
      analyst?.coverage
        ?.coreCoveragePct
    ) ||
    0;

  const extendedCoverage =
    safeNumber(
      analyst?.coverage
        ?.extendedCoveragePct
    ) ||
    0;

  const dataQuality =
    safeNumber(
      candidate?.dataQuality
        ?.score
    ) ||
    0;

  const evidenceState =
    String(
      candidate?.fundamentalEvidenceState ||
      ''
    );

  let freshnessScore = 85;

  if (
    evidenceState === 'LIVE' ||
    evidenceState === 'CACHE_FRESH'
  ) {
    freshnessScore = 100;
  } else if (
    evidenceState === 'CACHE_FALLBACK'
  ) {
    freshnessScore = 65;
  } else if (!evidenceState) {
    freshnessScore = 50;
  }

  let score =
    summaryCoverage * 0.40 +
    extendedCoverage * 0.25 +
    dataQuality * 0.20 +
    freshnessScore * 0.15;

  if (
    analystGate?.validationTier ===
      'SECTOR_MODEL_REQUIRED'
  ) {
    score = Math.min(
      score,
      45
    );
  }

  if (
    analystGate?.state ===
      'RESEARCHING'
  ) {
    score = Math.min(
      score,
      55
    );
  }

  score =
    decisionRound(
      decisionClamp(score),
      2
    );

  const confidence =
    score >= 82
      ? 'HIGH'
      : score >= 62
        ? 'MEDIUM'
        : score >= 42
          ? 'LOW'
          : 'UNRESOLVED';

  return {
    summaryCoveragePct:
      decisionRound(
        summaryCoverage,
        2
      ),
    extendedCoveragePct:
      decisionRound(
        extendedCoverage,
        2
      ),
    dataQualityPct:
      decisionRound(
        dataQuality,
        2
      ),
    freshnessScore,
    score,
    confidence,
    validationTier:
      analystGate?.validationTier ||
      'NONE',
    state:
      analystGate?.state ||
      'RESEARCHING',
    missingSummary:
      analyst?.coverage
        ?.coreMetricsMissing ||
      [],
    missingExtended:
      analyst?.coverage
        ?.extendedMetricsMissing ||
      []
  };
}


/* =========================================================
   PROFESSIONAL INVESTOR / TRADER DECISION FRAMEWORK - BUILD 0.9.1
   Long-term and short-term are separate analytical frameworks.
========================================================= */

function professionalStateScore(state, mapping) {
  const key = String(state || '').toUpperCase();
  return Object.prototype.hasOwnProperty.call(mapping, key)
    ? mapping[key]
    : 50;
}

function professionalFinancialQualityScore(analyst) {
  if (!analyst) {
    return 30;
  }

  const overall = professionalStateScore(
    analyst.overallFinancialView?.state,
    {
      STRONG: 92,
      GOOD: 82,
      ACCEPTABLE: 68,
      MIXED: 52,
      WEAK: 25,
      UNRELIABLE: 55
    }
  );

  const earnings = professionalStateScore(
    analyst.views?.earningsQuality?.state,
    {
      STRONG: 92,
      GOOD: 82,
      ACCEPTABLE: 70,
      IMPROVING: 78,
      QUESTIONABLE: 42,
      WEAK: 25,
      UNRELIABLE: 60
    }
  );

  const cash = professionalStateScore(
    analyst.views?.cashFlowQuality?.state,
    {
      STRONG: 90,
      GOOD: 80,
      ACCEPTABLE: 68,
      EVIDENCE_AVAILABLE: 65,
      QUESTIONABLE: 40,
      WEAK: 22,
      UNRELIABLE: 60
    }
  );

  const balance = professionalStateScore(
    analyst.views?.balanceSheet?.state,
    {
      STRONG: 90,
      GOOD: 80,
      ACCEPTABLE: 68,
      EVIDENCE_AVAILABLE: 65,
      QUESTIONABLE: 42,
      WEAK: 25,
      UNRELIABLE: 60
    }
  );

  return decisionRound(
    decisionClamp(
      overall * 0.40 +
      earnings * 0.25 +
      cash * 0.20 +
      balance * 0.15
    ),
    2
  );
}

function professionalValuationState(score) {
  const value = safeNumber(score) ?? 0;
  if (value >= 78) return 'ATTRACTIVE';
  if (value >= 62) return 'REASONABLE';
  if (value >= 48) return 'FAIR';
  return 'EXPENSIVE_OR_UNCLEAR';
}

function professionalRiskState(score) {
  const value = safeNumber(score) ?? 0;
  if (value >= 72) return 'LOW_TO_MODERATE';
  if (value >= 55) return 'ACCEPTABLE';
  if (value >= 40) return 'ELEVATED';
  return 'HIGH';
}


/* =========================================================
   LONG-TERM COMPOUNDER + DIVIDEND INTELLIGENCE - 0.9.6.14
   0.9.6.14 keeps the diagnostic model intact, then applies a bounded,
   evidence-gated activation layer inside professionalLongTermView(). The
   promoted layer can modestly influence long-term thesis/ranking, but it
   cannot bypass analyst, valuation, risk, timing or execution hard gates.
========================================================= */

function longTermShadowStateScore(
  state,
  mapping
) {
  const key =
    String(state || '')
      .trim()
      .toUpperCase();

  return Object.prototype.hasOwnProperty.call(
    mapping,
    key
  )
    ? mapping[key]
    : null;
}

function longTermShadowTrendScore(
  view
) {
  return longTermShadowStateScore(
    view?.state,
    {
      IMPROVING: 90,
      STRONG: 90,
      GOOD: 82,
      STABLE: 70,
      ACCEPTABLE: 68,
      MIXED: 52,
      DETERIORATING: 32,
      QUESTIONABLE: 38,
      WEAK: 22
    }
  );
}

function longTermShadowQualityScore(
  values
) {
  let weighted = 0;
  let observedWeight = 0;
  let totalWeight = 0;

  for (const item of values || []) {
    const weight =
      Math.max(
        0,
        safeNumber(item?.weight) || 0
      );
    totalWeight += weight;

    const value =
      safeNumber(item?.value);

    if (value === null) {
      continue;
    }

    observedWeight += weight;
    weighted +=
      decisionClamp(value) * weight;
  }

  const score =
    observedWeight > 0
      ? decisionRound(
          decisionClamp(
            weighted / observedWeight
          ),
          2
        )
      : null;

  const coveragePct =
    totalWeight > 0
      ? decisionRound(
          observedWeight / totalWeight * 100,
          2
        )
      : 0;

  const confidence =
    coveragePct >= 80
      ? 'HIGH'
      : coveragePct >= 55
        ? 'MEDIUM'
        : coveragePct >= 30
          ? 'LOW'
          : 'UNRESOLVED';

  return {
    score,
    coveragePct,
    confidence
  };
}

function longTermShadowRoeScore(
  candidate
) {
  const roe =
    safeNumber(
      candidate?.fundamental
        ?.metrics
        ?.roe
        ?.value
    );

  if (roe === null) {
    return null;
  }

  if (roe >= 25) return 95;
  if (roe >= 20) return 88;
  if (roe >= 15) return 78;
  if (roe >= 10) return 66;
  if (roe >= 5) return 52;
  if (roe >= 0) return 38;
  return 18;
}

function longTermShadowDividendHistory(
  analyst
) {
  const values =
    Array.isArray(
      analyst?.evidence
        ?.dividendPerShare
        ?.values
    )
      ? analyst.evidence
          .dividendPerShare
          .values
          .slice(0, 10)
      : [];

  const usable =
    values
      .map(item => ({
        period: item?.period || null,
        value: safeNumber(item?.value)
      }))
      .filter(item => item.value !== null);

  if (!usable.length) {
    return {
      periods: 0,
      paidPeriods: 0,
      consistencyPct: null,
      latestDps: null,
      direction: 'UNAVAILABLE',
      cutCount: null
    };
  }

  const paidPeriods =
    usable.filter(
      item => item.value > 0
    ).length;

  let cuts = 0;
  let rises = 0;
  let comparisons = 0;

  for (
    let index = 0;
    index < usable.length - 1;
    index++
  ) {
    const newer = usable[index].value;
    const older = usable[index + 1].value;
    if (
      newer === null ||
      older === null
    ) {
      continue;
    }
    comparisons++;
    if (newer < older) cuts++;
    if (newer > older) rises++;
  }

  let direction = 'STABLE';
  if (!comparisons) {
    direction = 'INSUFFICIENT_HISTORY';
  } else if (cuts === 0 && rises > 0) {
    direction = 'GROWING';
  } else if (cuts > rises) {
    direction = 'DECLINING';
  } else if (cuts > 0 && rises > 0) {
    direction = 'MIXED';
  }

  return {
    periods: usable.length,
    paidPeriods,
    consistencyPct:
      decisionRound(
        paidPeriods /
        usable.length *
        100,
        2
      ),
    latestDps:
      decisionRound(
        usable[0]?.value,
        4
      ),
    direction,
    cutCount: cuts
  };
}

function longTermShadowDividendYieldScore(
  yieldPct
) {
  const value = safeNumber(yieldPct);
  if (value === null) return null;
  if (value <= 0) return 35;
  if (value < 2) return 48;
  if (value < 4) return 60;
  if (value <= 8) return 78;
  if (value <= 12) return 86;
  if (value <= 15) return 76;
  return 58;
}

function longTermShadowPayoutScore(
  payoutRatio
) {
  const value = safeNumber(payoutRatio);
  if (value === null) return null;

  // PSX ratio tables normally report payout as percentage points. If a source
  // supplies a unit fraction, normalize only the plausible 0..2 range.
  const pct =
    value > 0 && value <= 2
      ? value * 100
      : value;

  if (pct < 0) return 15;
  if (pct <= 25) return 72;
  if (pct <= 60) return 92;
  if (pct <= 80) return 82;
  if (pct <= 100) return 65;
  if (pct <= 130) return 42;
  return 20;
}

function longTermShadowDividendConsistencyScore(
  history
) {
  const pct = safeNumber(history?.consistencyPct);
  if (pct === null) return null;
  if (pct >= 95) return 95;
  if (pct >= 80) return 84;
  if (pct >= 60) return 68;
  if (pct >= 40) return 52;
  return 30;
}

function longTermShadowDividendTrendScore(
  history
) {
  return ({
    GROWING: 90,
    STABLE: 76,
    MIXED: 56,
    DECLINING: 32,
    INSUFFICIENT_HISTORY: 55,
    UNAVAILABLE: null
  })[history?.direction || 'UNAVAILABLE'];
}

function buildLongTermCompounderDividendShadow(
  candidate
) {
  if (
    String(
      candidate?.horizon ||
      'long_term'
    ) !== 'long_term'
  ) {
    return null;
  }

  const analyst =
    candidate?.analystCore ||
    null;
  const views =
    analyst?.views ||
    {};
  const evidence =
    analyst?.evidence ||
    {};

  const financialQuality =
    analyst
      ? professionalFinancialQualityScore(
          analyst
        )
      : null;

  const compounderQuality =
    longTermShadowQualityScore([
      {
        value: financialQuality,
        weight: 25
      },
      {
        value:
          longTermShadowTrendScore(
            views.revenueTrend
          ),
        weight: 14
      },
      {
        value:
          longTermShadowTrendScore(
            views.profitTrend
          ),
        weight: 16
      },
      {
        value:
          longTermShadowTrendScore(
            views.epsTrend
          ),
        weight: 16
      },
      {
        value:
          longTermShadowTrendScore(
            views.marginTrend
          ),
        weight: 9
      },
      {
        value:
          longTermShadowRoeScore(
            candidate
          ),
        weight: 10
      },
      {
        value:
          longTermShadowStateScore(
            views.cashFlowQuality?.state,
            {
              STRONG: 92,
              GOOD: 84,
              ACCEPTABLE: 72,
              EVIDENCE_AVAILABLE: 66,
              QUESTIONABLE: 40,
              WEAK: 22
            }
          ),
        weight: 10
      }
    ]);

  const compounderState =
    compounderQuality.score === null
      ? 'UNRESOLVED'
      : compounderQuality.score >= 82
        ? 'STRONG'
        : compounderQuality.score >= 68
          ? 'GOOD'
          : compounderQuality.score >= 54
            ? 'MIXED'
            : 'WEAK';

  const dividendYield =
    safeNumber(
      candidate?.valuation
        ?.dividendYield
    );
  const payoutRatio =
    safeNumber(
      evidence.payoutRatio
        ?.latest?.value
    );
  const dividendHistory =
    longTermShadowDividendHistory(
      analyst
    );
  const hasDividendEvidence =
    (dividendYield !== null && dividendYield > 0) ||
    dividendHistory.paidPeriods > 0 ||
    safeNumber(
      dividendHistory.latestDps
    ) > 0;

  const cashSupport =
    longTermShadowStateScore(
      views.cashFlowQuality?.state,
      {
        STRONG: 92,
        GOOD: 84,
        ACCEPTABLE: 72,
        EVIDENCE_AVAILABLE: 66,
        QUESTIONABLE: 38,
        WEAK: 20
      }
    );
  const earningsSupport =
    longTermShadowTrendScore(
      views.epsTrend
    );

  const dividendQuality =
    hasDividendEvidence
      ? longTermShadowQualityScore([
          {
            value:
              longTermShadowDividendYieldScore(
                dividendYield
              ),
            weight: 18
          },
          {
            value:
              longTermShadowPayoutScore(
                payoutRatio
              ),
            weight: 22
          },
          {
            value:
              longTermShadowDividendConsistencyScore(
                dividendHistory
              ),
            weight: 20
          },
          {
            value:
              longTermShadowDividendTrendScore(
                dividendHistory
              ),
            weight: 15
          },
          {
            value: cashSupport,
            weight: 15
          },
          {
            value: earningsSupport,
            weight: 10
          }
        ])
      : {
          score: null,
          coveragePct: 0,
          confidence: 'UNRESOLVED'
        };

  let yieldTrapRisk = 'UNRESOLVED';
  const payoutScore =
    longTermShadowPayoutScore(
      payoutRatio
    );
  const weakSupportCount = [
    payoutScore !== null && payoutScore < 50,
    cashSupport !== null && cashSupport < 50,
    earningsSupport !== null && earningsSupport < 50,
    dividendHistory.direction === 'DECLINING'
  ].filter(Boolean).length;

  if (!hasDividendEvidence) {
    yieldTrapRisk = 'NOT_APPLICABLE';
  } else if (
    dividendYield !== null &&
    dividendYield >= 12 &&
    weakSupportCount >= 2
  ) {
    yieldTrapRisk = 'HIGH';
  } else if (
    dividendYield !== null &&
    dividendYield >= 10 &&
    weakSupportCount >= 1
  ) {
    yieldTrapRisk = 'MEDIUM';
  } else if (
    dividendQuality.confidence !==
      'UNRESOLVED'
  ) {
    yieldTrapRisk = 'LOW';
  }

  const dividendState =
    !hasDividendEvidence
      ? 'NO_DIVIDEND_EVIDENCE'
      : dividendQuality.score === null
        ? 'UNRESOLVED'
        : dividendQuality.score >= 82
          ? 'STRONG'
          : dividendQuality.score >= 68
            ? 'GOOD'
            : dividendQuality.score >= 54
              ? 'MIXED'
              : 'WEAK';

  let shareholderReturnStyle =
    'UNRESOLVED';

  if (
    (compounderState === 'STRONG' ||
      compounderState === 'GOOD') &&
    (dividendState === 'STRONG' ||
      dividendState === 'GOOD')
  ) {
    shareholderReturnStyle =
      'GROWTH_PLUS_INCOME';
  } else if (
    (compounderState === 'STRONG' ||
      compounderState === 'GOOD') &&
    !hasDividendEvidence
  ) {
    shareholderReturnStyle =
      'REINVESTMENT_COMPOUNDER';
  } else if (
    (dividendState === 'STRONG' ||
      dividendState === 'GOOD') &&
    compounderState === 'MIXED'
  ) {
    shareholderReturnStyle =
      'INCOME_LED_REVIEW';
  } else if (
    compounderState === 'WEAK' ||
    yieldTrapRisk === 'HIGH'
  ) {
    shareholderReturnStyle =
      'QUALITY_RISK';
  } else {
    shareholderReturnStyle =
      'MIXED';
  }

  return {
    version:
      'LT-COMPOUNDER-DIVIDEND-SHADOW-0.9.6.13',
    mode: 'SHADOW_ONLY',
    affectsDecision: false,
    compounder: {
      score:
        compounderQuality.score,
      state:
        compounderState,
      confidence:
        compounderQuality.confidence,
      coveragePct:
        compounderQuality.coveragePct
    },
    dividend: {
      score:
        dividendQuality.score,
      state:
        dividendState,
      confidence:
        dividendQuality.confidence,
      coveragePct:
        dividendQuality.coveragePct,
      yieldPct:
        decisionRound(
          dividendYield,
          2
        ),
      payoutRatio:
        decisionRound(
          payoutRatio,
          2
        ),
      history:
        dividendHistory,
      yieldTrapRisk
    },
    totalShareholderReturnStyle:
      shareholderReturnStyle,
    note:
      'Shadow intelligence only. It does not change today\'s ranking, allocation or action.'
  };
}


function longTermCompounderDividendActivation(
  intelligence
) {
  if (!intelligence) {
    return {
      applied: false,
      adjustment: 0,
      compounderAdjustment: 0,
      dividendAdjustment: 0,
      yieldTrapAdjustment: 0,
      reason:
        'Compounder/dividend intelligence is unavailable, so the stable Investor thesis is unchanged.'
    };
  }

  const compounder =
    intelligence.compounder || {};
  const dividend =
    intelligence.dividend || {};

  const compounderEligible =
    safeNumber(compounder.score) !== null &&
    safeNumber(compounder.coveragePct) >= 55 &&
    (
      compounder.confidence === 'MEDIUM' ||
      compounder.confidence === 'HIGH'
    );

  const dividendEligible =
    dividend.state !== 'NO_DIVIDEND_EVIDENCE' &&
    safeNumber(dividend.score) !== null &&
    safeNumber(dividend.coveragePct) >= 55 &&
    (
      dividend.confidence === 'MEDIUM' ||
      dividend.confidence === 'HIGH'
    );

  const compounderAdjustment =
    !compounderEligible
      ? 0
      : ({
          STRONG: 3.0,
          GOOD: 1.5,
          MIXED: -1.5,
          WEAK: -4.0
        })[compounder.state] || 0;

  // Dividends matter for long-term total return, but they are deliberately a
  // smaller influence than business quality. A company that reinvests well and
  // pays no dividend receives no dividend penalty at all.
  const dividendAdjustment =
    !dividendEligible
      ? 0
      : ({
          STRONG: 1.5,
          GOOD: 0.75,
          MIXED: -0.5,
          WEAK: -1.5
        })[dividend.state] || 0;

  const yieldTrapAdjustment =
    dividend.yieldTrapRisk === 'HIGH'
      ? -3.0
      : dividend.yieldTrapRisk === 'MEDIUM'
        ? -1.0
        : 0;

  const rawAdjustment =
    compounderAdjustment +
    dividendAdjustment +
    yieldTrapAdjustment;

  const adjustment =
    decisionRound(
      Math.max(
        -6,
        Math.min(
          4,
          rawAdjustment
        )
      ),
      2
    );

  const applied =
    compounderEligible ||
    dividendEligible ||
    yieldTrapAdjustment !== 0;

  let reason =
    'The active intelligence layer found no evidence-qualified reason to alter the stable Investor thesis.';

  if (applied && adjustment > 0) {
    reason =
      'Evidence-qualified compounder/dividend quality modestly strengthens the long-term thesis.';
  } else if (applied && adjustment < 0) {
    reason =
      dividend.yieldTrapRisk === 'HIGH'
        ? 'Dividend sustainability/yield-trap risk and business-quality evidence reduce long-term conviction.'
        : 'Evidence-qualified compounder/dividend quality modestly reduces long-term conviction.';
  } else if (applied) {
    reason =
      'Compounder/dividend evidence is active, but positive and negative effects currently offset.';
  }

  return {
    applied,
    adjustment,
    compounderEligible,
    dividendEligible,
    compounderAdjustment,
    dividendAdjustment,
    yieldTrapAdjustment,
    reason
  };
}

function buildLongTermCompounderDividendIntelligence(
  candidate
) {
  const diagnostic =
    buildLongTermCompounderDividendShadow(
      candidate
    );

  if (!diagnostic) {
    return null;
  }

  const activation =
    longTermCompounderDividendActivation(
      diagnostic
    );

  return {
    ...diagnostic,
    version:
      'LT-COMPOUNDER-DIVIDEND-ACTIVE-0.9.6.14',
    mode:
      'ACTIVE_GUARDED',
    affectsDecision:
      activation.applied,
    activation,
    note:
      activation.applied
        ? 'Active with bounded authority in Long-Term Investor thesis/ranking. Core analyst, valuation, risk, timing and execution gates remain unchanged.'
        : 'Active layer is evidence-gated; current coverage is insufficient to alter the stable Investor thesis.'
  };
}

function professionalLongTermEntryExtension(
  candidate
) {
  const context =
    candidate?.historicalContext ||
    {};
  const returns =
    context.returns ||
    {};
  const movingAverages =
    context.movingAverages ||
    {};
  const technical =
    context.technical ||
    {};

  const price =
    safeNumber(
      context.price
    ) ??
    safeNumber(
      candidate?.price
    );
  const m1 =
    safeNumber(
      returns.m1
    );
  const m3 =
    safeNumber(
      returns.m3
    );
  const m6 =
    safeNumber(
      returns.m6
    );
  const sma20 =
    safeNumber(
      movingAverages.sma20
    );
  const sma50 =
    safeNumber(
      movingAverages.sma50
    );
  const rsi14 =
    safeNumber(
      technical.rsi14
    );

  const distance20Pct =
    price !== null &&
    sma20 !== null &&
    sma20 > 0
      ? (
          price - sma20
        ) /
        sma20 *
        100
      : null;

  const distance50Pct =
    price !== null &&
    sma50 !== null &&
    sma50 > 0
      ? (
          price - sma50
        ) /
        sma50 *
        100
      : null;

  const sector =
    String(
      candidate?.sector ||
      ''
    ).toLowerCase();

  const cyclicalSector = [
    'refin',
    'cement',
    'steel',
    'engineering',
    'oil & gas',
    'oil and gas',
    'textile',
    'paper',
    'sugar',
    'automobile',
    'power generation'
  ].some(
    keyword =>
      sector.includes(
        keyword
      )
  );

  let score = 0;
  const reasons = [];

  if (m1 !== null && m1 >= 20) {
    score += m1 >= 35 ? 2 : 1;
    reasons.push(
      'The stock has already rerated sharply over the last month.'
    );
  }

  if (m3 !== null && m3 >= 50) {
    score +=
      m3 >= 120
        ? 3
        : m3 >= 80
          ? 2
          : 1;
    reasons.push(
      'The three-month price advance is large enough to increase chase risk.'
    );
  }

  if (m6 !== null && m6 >= 100) {
    score += 1;
    reasons.push(
      'The six-month rerating has been unusually strong.'
    );
  }

  if (
    distance20Pct !== null &&
    distance20Pct >= 10
  ) {
    score +=
      distance20Pct >= 18
        ? 2
        : 1;
    reasons.push(
      'Price is extended above its 20-session moving average.'
    );
  }

  if (
    distance50Pct !== null &&
    distance50Pct >= 18
  ) {
    score +=
      distance50Pct >= 30
        ? 2
        : 1;
    reasons.push(
      'Price is extended above its 50-session moving average.'
    );
  }

  if (rsi14 !== null && rsi14 >= 70) {
    score += 1;
    reasons.push(
      'RSI is elevated, which reduces the margin for an aggressive entry.'
    );
  }

  if (
    cyclicalSector &&
    m3 !== null &&
    m3 >= 50
  ) {
    score += 1;
    reasons.push(
      'This is a cyclical sector, so a strong rerating also raises peak-earnings and normalization risk.'
    );
  }

  const state =
    score >= 6
      ? 'EXTREME'
      : score >= 4
        ? 'HIGH'
        : score >= 2
          ? 'MODERATE'
          : 'LOW';

  const timingPenalty =
    state === 'EXTREME'
      ? 20
      : state === 'HIGH'
        ? 12
        : state === 'MODERATE'
          ? 6
          : 0;

  return {
    state,
    score,
    timingPenalty,
    distance20Pct:
      decisionRound(
        distance20Pct,
        2
      ),
    distance50Pct:
      decisionRound(
        distance50Pct,
        2
      ),
    cyclicalSector,
    reasons:
      uniqueTextValues(
        reasons
      )
  };
}

function professionalLongTermView(
  candidate,
  analystGate,
  evidence
) {
  const analyst = candidate?.analystCore || null;
  const financialScore =
    professionalFinancialQualityScore(analyst);
  const valuationScore =
    safeNumber(candidate?.valuation?.score) || 0;
  const riskScore =
    safeNumber(candidate?.risk?.score) || 0;
  const longTermIntelligence =
    buildLongTermCompounderDividendIntelligence(
      candidate
    );
  const intelligenceAdjustment =
    safeNumber(
      longTermIntelligence
        ?.activation
        ?.adjustment
    ) || 0;
  const intelligenceReason =
    longTermIntelligence
      ?.activation
      ?.reason ||
    'Compounder/dividend intelligence did not alter the stable Investor thesis.';
  // Long-term remains thesis-led, but a professional investor must not
  // confuse a strong business with a good entry after an extreme rerating.
  // This guard only affects entry timing/sizing; it does not rewrite the thesis.
  const baseTimingScore =
    safeNumber(candidate?.entry?.score) ??
    50;
  const entryExtension =
    professionalLongTermEntryExtension(
      candidate
    );
  const timingScore =
    decisionClamp(
      baseTimingScore -
      entryExtension.timingPenalty
    );
  const timingState =
    timingScore >= 72
      ? 'GOOD'
      : timingScore >= 58
        ? 'FAIR'
        : timingScore >= 42
          ? 'POOR'
          : 'RISKY';

  const baseThesisScore =
    decisionRound(
      decisionClamp(
        financialScore * 0.45 +
        valuationScore * 0.25 +
        riskScore * 0.15 +
        evidence.score * 0.15
      ),
      2
    );

  // 0.9.6.14: Compounder + Dividend Intelligence is promoted with bounded
  // authority. It can move the long-term thesis only a few points and only
  // when its own evidence coverage is sufficient. Hard safety gates below are
  // deliberately unchanged.
  const thesisScore =
    decisionRound(
      decisionClamp(
        baseThesisScore +
        intelligenceAdjustment
      ),
      2
    );

  const rankingScore =
    decisionRound(
      decisionClamp(
        thesisScore * 0.90 +
        timingScore * 0.10
      ),
      2
    );

  let thesisStatus =
    financialScore >= 78
      ? 'STRONG'
      : financialScore >= 64
        ? 'ACCEPTABLE'
        : financialScore >= 48
          ? 'MIXED'
          : 'WEAK';

  let marketAction = 'WATCH';
  let opportunityTier = 'PRIORITY_2';
  let reason = 'The long-term thesis is not yet strong enough for new capital.';

  if (analystGate.state === 'RESEARCHING') {
    thesisStatus = 'UNRESOLVED';
    return {
      framework: 'LONG_TERM_INVESTOR',
      thesisStatus,
      financialScore,
      valuationScore,
      valuationState: professionalValuationState(valuationScore),
      riskScore,
      riskState: professionalRiskState(riskScore),
      baseTimingScore,
      timingScore,
      timingState,
      entryExtensionRisk:
        entryExtension.state,
      entryExtensionScore:
        entryExtension.score,
      entryExtensionReasons:
        entryExtension.reasons,
      baseThesisScore,
      thesisScore,
      rankingScore,
      longTermIntelligence,
      intelligenceAdjustment,
      intelligenceReason,
      marketAction: 'RESEARCHING',
      opportunityTier: 'EVIDENCE_RESEARCH',
      reason: analystGate.reason
    };
  }

  if (
    analystGate.state === 'REJECT' ||
    financialScore < 42 ||
    riskScore < 38
  ) {
    return {
      framework: 'LONG_TERM_INVESTOR',
      thesisStatus: financialScore < 42 ? 'WEAK' : thesisStatus,
      financialScore,
      valuationScore,
      valuationState: professionalValuationState(valuationScore),
      riskScore,
      riskState: professionalRiskState(riskScore),
      baseTimingScore,
      timingScore,
      timingState,
      entryExtensionRisk:
        entryExtension.state,
      entryExtensionScore:
        entryExtension.score,
      entryExtensionReasons:
        entryExtension.reasons,
      baseThesisScore,
      thesisScore,
      rankingScore,
      longTermIntelligence,
      intelligenceAdjustment,
      intelligenceReason,
      marketAction: 'AVOID',
      opportunityTier: 'LOW_PRIORITY',
      reason:
        analystGate.state === 'REJECT'
          ? analystGate.reason
          : financialScore < 42
            ? 'Long-term financial quality is too weak for a new position.'
            : 'Risk and liquidity are too weak for a long-term allocation.'
    };
  }

  const thesisStrong =
    thesisScore >= 68 &&
    financialScore >= 65 &&
    valuationScore >= 55 &&
    riskScore >= 48;

  const highConviction =
    thesisScore >= 76 &&
    financialScore >= 72 &&
    valuationScore >= 62 &&
    evidence.confidence !== 'UNRESOLVED';

  const highChaseRisk =
    entryExtension.state === 'HIGH' ||
    entryExtension.state === 'EXTREME';

  const thesisDescription =
    thesisStatus === 'STRONG'
      ? 'strong'
      : thesisStatus === 'ACCEPTABLE'
        ? 'acceptable'
        : thesisStatus === 'MIXED'
          ? 'mixed'
          : 'weak';

  if (thesisStrong) {
    if (timingState === 'GOOD') {
      marketAction =
        analystGate.state === 'VALIDATED' &&
        highConviction &&
        !highChaseRisk
          ? 'BUY'
          : 'ACCUMULATE';
      opportunityTier = 'PRIORITY_1';
      reason =
        highChaseRisk
          ? 'The long-term thesis remains ' + thesisDescription + ', but the stock has rerated sharply and chase risk is elevated. NOMAD prefers staged accumulation rather than treating a strong recent run as a fresh full-size entry.'
          : marketAction === 'BUY'
            ? 'The long-term thesis, valuation, risk and current technical timing all support a new position.'
            : 'The long-term thesis is ' + thesisDescription + ', but NOMAD prefers staged exposure because conviction or evidence is not yet complete.';
    } else if (timingState === 'FAIR') {
      marketAction = 'ACCUMULATE';
      opportunityTier = 'PRIORITY_1';
      reason =
        entryExtension.state === 'HIGH' ||
        entryExtension.state === 'EXTREME'
          ? 'The long-term thesis is ' + thesisDescription + ', but recent price extension and rerating reduce the margin of safety. NOMAD prefers staged accumulation or a better entry rather than chasing the move.'
          : 'The long-term thesis is ' + thesisDescription + '. Entry timing is acceptable but not strong enough to justify aggressive deployment.';
    } else {
      marketAction = 'WATCH';
      opportunityTier = 'PRIORITY_2';
      reason = 'The long-term thesis remains ' + thesisDescription + ', but current price action is poor or extended. NOMAD prefers to wait for a better entry rather than abandon the thesis.';
    }
  } else if (
    thesisScore >= 58 &&
    financialScore >= 55
  ) {
    marketAction = 'WATCH';
    opportunityTier = 'PRIORITY_2';
    reason = 'The company remains a credible long-term candidate, but expected return, evidence or financial quality is not yet strong enough for new capital.';
  }

  return {
    framework: 'LONG_TERM_INVESTOR',
    thesisStatus,
    financialScore,
    valuationScore,
    valuationState: professionalValuationState(valuationScore),
    riskScore,
    riskState: professionalRiskState(riskScore),
    baseTimingScore,
    timingScore,
    timingState,
    entryExtensionRisk:
      entryExtension.state,
    entryExtensionScore:
      entryExtension.score,
    entryExtensionReasons:
      entryExtension.reasons,
    baseThesisScore,
    thesisScore,
    rankingScore,
    longTermIntelligence,
    intelligenceAdjustment,
    intelligenceReason,
    marketAction,
    opportunityTier,
    reason
  };
}

function decisionTraderEvidenceProfile(
  candidate
) {
  const context =
    candidate?.historicalContext ||
    null;
  const priceAction =
    context?.priceAction ||
    null;
  const technical =
    context?.technical ||
    {};
  const tradePlan =
    priceAction?.tradePlan ||
    null;

  const conditionalTradePlan =
    priceAction?.conditionalTradePlan ||
    null;

  let score = 0;
  const missing = [];

  if (context?.available) {
    score += 15;
  } else {
    missing.push('daily OHLC history');
  }

  if (
    safeNumber(context?.validSessions) >=
      DECISION_TRADER_MIN_VALID_SESSIONS
  ) {
    score += 10;
  } else {
    missing.push('sufficient recent sessions');
  }

  if (priceAction?.available) {
    score += 15;
  } else {
    missing.push('price-action structure');
  }

  if (safeNumber(technical.rsi14) !== null) {
    score += 8;
  } else {
    missing.push('RSI');
  }

  if (safeNumber(technical.macdHistogram) !== null) {
    score += 8;
  } else {
    missing.push('MACD');
  }

  if (safeNumber(technical.volumeRatio20d) !== null) {
    score += 8;
  } else {
    missing.push('volume confirmation');
  }

  if (safeNumber(priceAction?.atr14) !== null) {
    score += 8;
  } else {
    missing.push('ATR');
  }

  if (safeNumber(priceAction?.support) !== null) {
    score += 6;
  } else {
    missing.push('support');
  }

  if (safeNumber(priceAction?.resistance) !== null) {
    score += 6;
  } else {
    missing.push('resistance');
  }

  if (tradePlan?.complete) {
    score += 10;
  } else {
    missing.push('complete entry/stop/target plan');
  }

  const asOfMs =
    Date.parse(context?.asOf || '');
  const ageDays =
    Number.isFinite(asOfMs)
      ? Math.max(
          0,
          (Date.now() - asOfMs) /
            (24 * 60 * 60 * 1000)
        )
      : null;

  if (
    ageDays !== null &&
    ageDays <= 5
  ) {
    score += 6;
  } else {
    missing.push('recent technical session');
  }

  score = decisionRound(
    decisionClamp(score),
    2
  );

  const confidence =
    score >= 85
      ? 'HIGH'
      : score >= 70
        ? 'MEDIUM'
        : score >= 50
          ? 'LOW'
          : 'UNRESOLVED';

  return {
    framework: 'TRADER_TECHNICAL_EVIDENCE',
    confidence,
    score,
    technicalCoveragePct: score,
    tradePlanCoveragePct:
      tradePlan?.complete ||
      conditionalTradePlan?.complete
        ? 100
        : 0,
    // Generic aliases retained for storage/UI compatibility. In short-term
    // mode these represent technical evidence, not financial-statement depth.
    summaryCoveragePct: score,
    extendedCoveragePct:
      tradePlan?.complete
        ? 100
        : 0,
    validationTier:
      tradePlan?.complete ||
      conditionalTradePlan?.complete
        ? 'TRADE_PLAN_DEFINED'
        : priceAction?.available
          ? 'TECHNICAL_CONTEXT_ONLY'
          : 'TECHNICAL_DATA_INCOMPLETE',
    setupCompleteness:
      tradePlan?.complete ||
      conditionalTradePlan?.complete
        ? 'COMPLETE'
        : 'INCOMPLETE',
    missing,
    validSessions:
      safeNumber(context?.validSessions),
    asOf:
      context?.asOf ||
      null,
    ageDays:
      decisionRound(ageDays, 2)
  };
}

function decisionTraderRiskBudgetPct(
  riskPolicy
) {
  if (
    riskPolicy?.id ===
      'RISK-CONSERVATIVE-0.1'
  ) {
    return DECISION_TRADER_RISK_BUDGET_PCT.conservative;
  }

  if (
    riskPolicy?.id ===
      'RISK-AGGRESSIVE-0.1'
  ) {
    return DECISION_TRADER_RISK_BUDGET_PCT.aggressive;
  }

  return DECISION_TRADER_RISK_BUDGET_PCT.balanced;
}


function decisionTraderSetupFamily(setup) {
  const value = String(setup || '').trim().toUpperCase();

  if (value === 'CONFIRMED_BREAKOUT' || value === 'UNCONFIRMED_BREAKOUT') {
    return 'BREAKOUT';
  }
  if (value === 'TREND_PULLBACK') {
    return 'PULLBACK';
  }
  if (value === 'UPTREND_CONTINUATION') {
    return 'CONTINUATION';
  }
  if (value === 'SUPPORT_BOUNCE' || value === 'BOUNCE') {
    return 'SUPPORT_BOUNCE';
  }
  if (value === 'BREAKDOWN' || value === 'DOWNTREND') {
    return 'BEARISH';
  }
  return 'NO_CLEAR_SETUP';
}

function decisionTraderSetupQuality(setup) {
  const value = String(setup || '').trim().toUpperCase();
  if (value === 'CONFIRMED_BREAKOUT') return 95;
  if (value === 'TREND_PULLBACK') return 90;
  if (value === 'SUPPORT_BOUNCE') return 84;
  if (value === 'UPTREND_CONTINUATION') return 82;
  if (value === 'UNCONFIRMED_BREAKOUT') return 64;
  if (value === 'NO_CLEAR_SETUP') return 42;
  if (value === 'DOWNTREND') return 20;
  if (value === 'BREAKDOWN') return 8;
  return 38;
}

function decisionTraderRewardRiskScore(value) {
  const rr = safeNumber(value);
  if (rr === null || rr <= 0) return 0;
  if (rr >= 3) return 100;
  if (rr >= 2.5) return 92;
  if (rr >= 2) return 82;
  if (rr >= 1.5) return 68;
  if (rr >= 1.25) return 52;
  return 30;
}

function decisionTraderPlanAgeDays(candidate) {
  const raw = candidate?.historicalContext?.asOf || candidate?.historicalContext?.priceAction?.asOf || null;
  const timestamp = Date.parse(raw || '');
  if (!Number.isFinite(timestamp)) return null;
  return Math.max(0, (Date.now() - timestamp) / (24 * 60 * 60 * 1000));
}

// Production integrity 0.9.6.7: choose one server-side Trader plan for every
// execution surface. The browser receives the chosen plan as data and never
// calls this server helper directly.
function decisionTraderCanonicalPlan(
  professional,
  execution = null
) {
  const currentPlan =
    professional?.tradePlan ||
    null;
  const conditionalPlan =
    professional?.conditionalTradePlan ||
    null;

  if (
    execution?.actionableNow === true &&
    currentPlan?.complete === true
  ) {
    return {
      kind: 'ACTIVE',
      source: 'TRADE_PLAN',
      plan: currentPlan
    };
  }

  if (
    execution?.reservationEligible === true &&
    execution?.actionableNow !== true &&
    conditionalPlan?.complete === true
  ) {
    return {
      kind: 'CONDITIONAL',
      source: 'CONDITIONAL_TRADE_PLAN',
      plan: conditionalPlan
    };
  }

  const marketAction =
    String(
      professional?.marketAction ||
      ''
    ).toUpperCase();

  if (
    marketAction === 'BUY' &&
    currentPlan?.complete === true
  ) {
    return {
      kind: 'ACTIVE',
      source: 'TRADE_PLAN',
      plan: currentPlan
    };
  }

  if (
    marketAction === 'WATCH' &&
    conditionalPlan?.complete === true
  ) {
    return {
      kind: 'CONDITIONAL',
      source: 'CONDITIONAL_TRADE_PLAN',
      plan: conditionalPlan
    };
  }

  if (currentPlan?.complete === true) {
    return {
      kind: 'ACTIVE',
      source: 'TRADE_PLAN',
      plan: currentPlan
    };
  }

  if (
    conditionalPlan?.complete === true
  ) {
    return {
      kind: 'CONDITIONAL',
      source: 'CONDITIONAL_TRADE_PLAN',
      plan: conditionalPlan
    };
  }

  return {
    kind: 'NONE',
    source: null,
    plan: null
  };
}

function decisionTraderPlanPriceState(
  currentPrice,
  plan
) {
  const current =
    safeNumber(currentPrice);
  const stop =
    safeNumber(plan?.stop);
  const target =
    safeNumber(plan?.target1);

  if (plan?.complete !== true) {
    return {
      state: 'INCOMPLETE',
      current,
      stop,
      target
    };
  }

  if (current === null) {
    return {
      state: 'UNKNOWN',
      current,
      stop,
      target
    };
  }

  if (
    stop !== null &&
    current <= stop
  ) {
    return {
      state: 'INVALIDATED',
      current,
      stop,
      target
    };
  }

  if (
    target !== null &&
    current >= target
  ) {
    return {
      state: 'TARGET_REACHED',
      current,
      stop,
      target
    };
  }

  return {
    state: 'OPEN',
    current,
    stop,
    target
  };
}

// 0.9.6.16.5: advisory entry price only. This is deliberately not an
// allocation input, a new order trigger or a replacement for MAX BUY.
// History supports the preference; the official PSX quote remains the anchor.
function decisionSuggestedLongTermLimit(
  candidate,
  referencePrice,
  maxBuyPrice
) {
  const unavailable = reason => ({
    suggestedLimitPrice: null,
    suggestedLimitStatus: 'UNAVAILABLE',
    suggestedLimitMethod: null,
    suggestedLimitReason: reason
  });

  const current = safeNumber(referencePrice);
  const ceiling = safeNumber(maxBuyPrice);
  if (
    current === null || current <= 0 ||
    ceiling === null || ceiling <= 0 ||
    current > ceiling
  ) {
    return unavailable('Current official price or approved MAX BUY is unavailable.');
  }

  const marketAsOf = Date.parse(candidate?.marketAsOf || '');
  const marketAgeDays = (Date.now() - marketAsOf) / 86400000;
  if (
    !Number.isFinite(marketAgeDays) ||
    marketAgeDays < -1 || marketAgeDays > 4
  ) {
    return unavailable('The official market reference is stale or undated.');
  }

  const history = candidate?.historicalContext || {};
  const action = history.priceAction || {};
  const atr = safeNumber(action.atr14);
  const sessions = safeNumber(history.validSessions);
  if (
    history.available !== true ||
    action.available !== true ||
    sessions === null || sessions < 30 ||
    atr === null || atr <= 0
  ) {
    return unavailable('Reliable recent ATR history is not available.');
  }

  const historyDate = String(history.asOf || action.asOf || '').slice(0, 10);
  const historyTime = /^\d{4}-\d{2}-\d{2}$/.test(historyDate)
    ? Date.parse(historyDate + 'T00:00:00+05:00')
    : NaN;
  const ageDays = (Date.now() - historyTime) / 86400000;
  if (!Number.isFinite(ageDays) || ageDays < -1 || ageDays > 8) {
    return unavailable('Historical entry evidence is stale or undated.');
  }

  // Reject malformed/extreme ATR rather than creating a false sense of precision.
  const atrPct = atr / current * 100;
  if (atrPct < 0.10 || atrPct > 15) {
    return unavailable('Recent volatility is outside the reliable execution range.');
  }

  // Look for a small pullback, never a chase. Discount is bounded between
  // 0.15% and 0.75% of the canonical price even for high-volatility stocks.
  const discountPct = decisionClamp(atrPct * 0.20, 0.15, 0.75);
  let preferred = current * (1 - discountPct / 100);
  let method = 'ATR_PULLBACK';
  const support = safeNumber(action.support);
  if (
    support !== null && support > 0 && support < current &&
    Math.abs(support - preferred) <= atr * 0.35
  ) {
    // A nearby technical support may improve the limit; never lift the bid.
    const supportBid = support * 1.001;
    if (supportBid < preferred) {
      preferred = supportBid;
      method = 'ATR_NEAR_SUPPORT';
    }
  }

  // Downward two-decimal rounding is intentional: a preferred bid cannot
  // accidentally be rounded above current/reference price or MAX BUY.
  const suggested = Math.floor((Math.min(preferred, current, ceiling) + 1e-8) * 100) / 100;
  if (suggested <= 0 || suggested >= current || suggested > ceiling) {
    return unavailable('No distinct executable bid is supported by the available precision.');
  }

  return {
    suggestedLimitPrice: suggested,
    suggestedLimitStatus: 'AVAILABLE',
    suggestedLimitMethod: method,
    suggestedLimitReason:
      method === 'ATR_NEAR_SUPPORT'
        ? 'Preferred limit uses recent volatility and nearby historical support; execution is not guaranteed.'
        : 'Preferred limit uses a bounded recent-volatility pullback; execution is not guaranteed.'
  };
}

function decisionExecutionGuidance(
  candidate,
  riskPolicy
) {
  const canonical =
    candidate?.canonicalState ||
    decisionCanonicalCompanyState(
      candidate
    );

  const professional =
    canonical?.professional ||
    {};

  const currentPrice =
    safeNumber(candidate?.price);

  const profileSuitability =
    candidate?.profileSuitability ||
    decisionProfileSuitability(
      candidate,
      riskPolicy
    );

  const shortTerm =
    professional?.framework ===
      'SHORT_TERM_TRADER';

  if (currentPrice === null) {
    return {
      horizon:
        shortTerm
          ? 'short_term'
          : 'long_term',
      status: 'WAIT_FOR_PRICE',
      action: 'WAIT',
      orderType: null,
      referencePrice: null,
      limitPrice: null,
      maxAcceptablePrice: null,
      reason:
        'A current market price is required before NOMAD can define an execution price.'
    };
  }

  if (
    profileSuitability?.state !==
      'SUITABLE'
  ) {
    return {
      horizon:
        shortTerm
          ? 'short_term'
          : 'long_term',
      status: 'PROFILE_BLOCKED',
      action: 'NO_BUY',
      orderType: null,
      referencePrice:
        decisionRound(
          currentPrice,
          2
        ),
      limitPrice: null,
      maxAcceptablePrice: null,
      reason:
        (profileSuitability?.issues || [])
          .join(' ') ||
        'The opportunity does not fit the selected risk profile.'
    };
  }

  if (shortTerm) {
    const execution =
      candidate?.shortTermExecution ||
      shortTermProfileExecutionDecision(
        candidate,
        riskPolicy
      );

    const selection =
      decisionTraderCanonicalPlan(
        professional,
        execution
      );

    const plan =
      selection.plan;

    if (!plan?.complete) {
      return {
        horizon: 'short_term',
        status: 'WAIT_FOR_CONFIRMATION',
        action: 'WAIT',
        orderType: null,
        referencePrice:
          decisionRound(
            currentPrice,
            2
          ),
        limitPrice: null,
        maxAcceptablePrice: null,
        planKind:
          selection.kind,
        reason:
          'NOMAD does not have one complete entry, stop and target plan yet.'
      };
    }

    const entryLow =
      safeNumber(
        plan.entryLow ??
        plan.entryReference
      );
    const entryHigh =
      safeNumber(
        plan.entryHigh ??
        plan.entryReference
      );
    const stop =
      safeNumber(plan.stop);
    const target =
      safeNumber(plan.target1);
    const policy =
      decisionTraderProfilePolicy(
        riskPolicy
      );
    const family =
      decisionTraderSetupFamily(
        professional.setup
      );
    const trigger =
      shortTermTriggerSnapshot(
        professional.setup,
        currentPrice,
        entryLow,
        entryHigh,
        stop,
        riskPolicy
      );
    const priceState =
      decisionTraderPlanPriceState(
        currentPrice,
        plan
      );

    if (
      priceState.state ===
        'INVALIDATED'
    ) {
      return {
        horizon: 'short_term',
        status: 'INVALIDATED',
        action: 'NO_BUY',
        orderType: null,
        referencePrice:
          decisionRound(currentPrice, 2),
        limitPrice: null,
        maxAcceptablePrice: null,
        entryLow,
        entryHigh,
        stop,
        target,
        rewardRisk:
          safeNumber(plan.rewardRisk),
        planKind:
          selection.kind,
        reason:
          'The current price has broken the plan invalidation/stop level. Re-analyze before considering a new entry.'
      };
    }

    if (
      priceState.state ===
        'TARGET_REACHED'
    ) {
      return {
        horizon: 'short_term',
        status: 'DO_NOT_CHASE',
        action: 'NO_BUY',
        orderType: null,
        referencePrice:
          decisionRound(currentPrice, 2),
        limitPrice: null,
        maxAcceptablePrice:
          target !== null
            ? decisionRound(target, 2)
            : null,
        entryLow,
        entryHigh,
        stop,
        target,
        rewardRisk:
          safeNumber(plan.rewardRisk),
        planKind:
          selection.kind,
        reason:
          'Price has already reached or exceeded the plan target. NOMAD will not open a fresh long trade here.'
      };
    }

    let structuralMax =
      entryHigh;

    if (
      structuralMax !== null &&
      (
        family === 'BREAKOUT' ||
        family === 'CONTINUATION'
      )
    ) {
      structuralMax *=
        1 +
        policy.maxChasePct /
        100;
    }

    const minimumRewardRisk =
      safeNumber(
        policy.minRewardRisk
      ) ||
      1.5;

    let rewardRiskMax = null;

    if (
      target !== null &&
      stop !== null &&
      target > stop
    ) {
      rewardRiskMax =
        (
          target +
          minimumRewardRisk *
          stop
        ) /
        (
          1 +
          minimumRewardRisk
        );
    }

    let maxAcceptablePrice =
      structuralMax;

    if (
      rewardRiskMax !== null &&
      (
        maxAcceptablePrice === null ||
        rewardRiskMax <
          maxAcceptablePrice
      )
    ) {
      maxAcceptablePrice =
        rewardRiskMax;
    }

    if (
      target !== null &&
      (
        maxAcceptablePrice === null ||
        target < maxAcceptablePrice
      )
    ) {
      maxAcceptablePrice =
        target;
    }

    maxAcceptablePrice =
      maxAcceptablePrice !== null
        ? decisionRound(
            maxAcceptablePrice,
            2
          )
        : null;

    if (
      maxAcceptablePrice !== null &&
      currentPrice >
        maxAcceptablePrice
    ) {
      return {
        horizon: 'short_term',
        status: 'DO_NOT_CHASE',
        action: 'NO_BUY',
        orderType: null,
        referencePrice:
          decisionRound(currentPrice, 2),
        limitPrice: null,
        maxAcceptablePrice,
        entryLow,
        entryHigh,
        stop,
        target,
        rewardRisk:
          safeNumber(plan.rewardRisk),
        planKind:
          selection.kind,
        triggerStatus:
          trigger.status,
        reason:
          "Current price is above the maximum entry that preserves this setup and the selected profile\'s reward-to-risk. Do not chase; re-analyze."
      };
    }

    if (
      execution?.actionableNow === true &&
      [
        'TRIGGERED',
        'NEAR_TRIGGER'
      ].includes(
        trigger.status
      )
    ) {
      return {
        horizon: 'short_term',
        status: 'BUY_NOW',
        action:
          execution.action ===
            'BUY_SMALL'
            ? 'BUY_SMALL'
            : 'BUY',
        orderType: 'LIMIT',
        referencePrice:
          decisionRound(currentPrice, 2),
        limitPrice:
          maxAcceptablePrice,
        maxAcceptablePrice,
        entryLow,
        entryHigh,
        stop,
        target,
        rewardRisk:
          safeNumber(plan.rewardRisk),
        planKind:
          selection.kind,
        triggerStatus:
          trigger.status,
        reason:
          execution.action ===
            'BUY_SMALL'
            ? "The selected profile permits only a smaller early entry. Use a limit order and do not pay above NOMAD\'s maximum acceptable entry."
            : "The entry conditions currently pass. Use a limit order and do not pay above NOMAD\'s maximum acceptable entry."
      };
    }

    const waitStatus =
      family === 'PULLBACK' ||
      family === 'SUPPORT_BOUNCE'
        ? 'WAIT_FOR_ENTRY'
        : 'WAIT_FOR_CONFIRMATION';

    return {
      horizon: 'short_term',
      status:
        trigger.status ===
          'ABOVE_ENTRY_ZONE'
          ? 'DO_NOT_CHASE'
          : trigger.status ===
              'INVALIDATED'
            ? 'INVALIDATED'
            : waitStatus,
      action: 'WAIT',
      orderType: null,
      referencePrice:
        decisionRound(currentPrice, 2),
      limitPrice: null,
      maxAcceptablePrice,
      entryLow,
      entryHigh,
      stop,
      target,
      rewardRisk:
        safeNumber(plan.rewardRisk),
      planKind:
        selection.kind,
      triggerStatus:
        trigger.status,
      reason:
        trigger.status ===
          'ABOVE_ENTRY_ZONE'
          ? 'Price is beyond the planned entry range. Do not chase; wait for a new valid setup.'
          : family === 'PULLBACK' ||
              family === 'SUPPORT_BOUNCE'
            ? 'The stock remains interesting, but NOMAD is waiting for price to return to the planned entry area.'
            : 'The stock remains interesting, but NOMAD is waiting for the planned trigger/confirmation before placing a buy.'
    };
  }

  const marketAction =
    String(
      canonical?.marketAction ||
      'WATCH'
    ).toUpperCase();

  if (
    marketAction !== 'BUY' &&
    marketAction !== 'ACCUMULATE'
  ) {
    return {
      horizon: 'long_term',
      status:
        marketAction === 'AVOID'
          ? 'NO_BUY'
          : 'WAIT_FOR_ENTRY',
      action: 'WAIT',
      orderType: null,
      referencePrice:
        decisionRound(currentPrice, 2),
      limitPrice: null,
      maxAcceptablePrice: null,
      reason:
        marketAction === 'AVOID'
          ? 'The current long-term thesis does not permit a new buy.'
          : 'The company may remain interesting, but current price/timing does not justify new capital yet.'
    };
  }

  const priceAction =
    candidate?.historicalContext
      ?.priceAction ||
    {};
  const technical =
    candidate?.historicalContext
      ?.technical ||
    {};

  const atrPct =
    safeNumber(priceAction?.atrPct) ??
    (
      safeNumber(priceAction?.atr14) !== null &&
      currentPrice > 0
        ? safeNumber(priceAction?.atr14) /
          currentPrice *
          100
        : null
    );

  const annualizedVolatility =
    safeNumber(
      technical
        ?.annualizedVolatility20dPct
    );

  const dailyVolatilityPct =
    atrPct !== null
      ? atrPct
      : annualizedVolatility !== null
        ? annualizedVolatility /
          Math.sqrt(252)
        : 1;

  const baseTolerancePct =
    decisionClamp(
      dailyVolatilityPct *
      0.35,
      0.20,
      1.25
    );

  const timingState =
    String(
      professional?.timingState ||
      'FAIR'
    ).toUpperCase();
  const extensionState =
    String(
      professional?.entryExtensionRisk ||
      'LOW'
    ).toUpperCase();

  const timingFactor =
    timingState === 'GOOD'
      ? 1
      : timingState === 'FAIR'
        ? 0.65
        : 0.25;

  const extensionFactor =
    extensionState === 'LOW'
      ? 1
      : extensionState === 'MODERATE'
        ? 0.60
        : extensionState === 'HIGH'
          ? 0.20
          : 0;

  const actionFactor =
    marketAction === 'BUY'
      ? 1
      : 0.75;

  const maxChasePct =
    decisionRound(
      baseTolerancePct *
      timingFactor *
      extensionFactor *
      actionFactor,
      2
    );

  const maxAcceptablePrice =
    decisionRound(
      currentPrice *
      (
        1 +
        maxChasePct /
        100
      ),
      2
    );

  return {
    horizon: 'long_term',
    status:
      marketAction === 'BUY'
        ? 'BUY_NOW'
        : 'STAGED_BUY',
    action:
      marketAction,
    orderType: 'LIMIT',
    referencePrice:
      decisionRound(currentPrice, 2),
    limitPrice:
      maxAcceptablePrice,
    maxAcceptablePrice,
    // Advisory only: preserve legacy limitPrice/MAX BUY semantics and sizing.
    ...decisionSuggestedLongTermLimit(candidate, currentPrice, maxAcceptablePrice),
    maxChasePct,
    reason:
      extensionState === 'HIGH' ||
      extensionState === 'EXTREME'
        ? 'Long-term thesis remains actionable, but price-extension risk is elevated. Accumulate only at the current reference area; do not chase a higher opening price.'
        : marketAction === 'BUY'
          ? 'The long-term thesis and timing currently pass. Use a limit order so an opening gap cannot silently turn the approved price into a more expensive trade.'
          : 'NOMAD prefers staged accumulation. Use a limit order and re-analyze if price trades above the maximum acceptable entry.'
  };
}


function decisionExecutionAllowsAllocation(
  guidance
) {
  const status =
    String(
      guidance?.status ||
      ''
    ).toUpperCase();
  const action =
    String(
      guidance?.action ||
      ''
    ).toUpperCase();

  if (status === 'BUY_NOW') {
    return (
      action === 'BUY' ||
      action === 'BUY_SMALL'
    );
  }

  if (status === 'STAGED_BUY') {
    return (
      action === 'BUY' ||
      action === 'ACCUMULATE'
    );
  }

  return false;
}

function professionalShortTermView(
  candidate,
  analystGate,
  evidence
) {
  const priceAction =
    candidate?.historicalContext
      ?.priceAction ||
    null;

  const tradePlan =
    priceAction?.tradePlan ||
    null;

  const conditionalTradePlan =
    priceAction?.conditionalTradePlan ||
    null;

  const traderEvidence =
    evidence?.framework ===
      'TRADER_TECHNICAL_EVIDENCE'
      ? evidence
      : decisionTraderEvidenceProfile(
          candidate
        );

  const timingScore =
    safeNumber(priceAction?.timingScore) ??
    safeNumber(candidate?.entry?.score) ??
    0;
  const riskScore =
    safeNumber(candidate?.risk?.score) || 0;
  const liquidityScore =
    safeNumber(candidate?.risk?.liquidityScore) || 0;
  const technicalEvidenceScore =
    safeNumber(traderEvidence?.score) || 0;
  const rewardRisk =
    safeNumber(tradePlan?.rewardRisk);
  const setup =
    priceAction?.setup ||
    'NO_CLEAR_SETUP';

  const setupQuality =
    decisionTraderSetupQuality(setup);
  const setupFamily =
    decisionTraderSetupFamily(setup);

  const conditionalReady =
    conditionalTradePlan?.complete === true &&
    safeNumber(
      conditionalTradePlan?.rewardRisk
    ) !== null &&
    safeNumber(
      conditionalTradePlan?.rewardRisk
    ) >= 1.35;

  const rewardRiskScore =
    decisionTraderRewardRiskScore(
      rewardRisk ??
      conditionalTradePlan?.rewardRisk
    );

  const activePlanPriceState =
    decisionTraderPlanPriceState(
      candidate?.price,
      tradePlan
    );

  const activePlanOpen =
    activePlanPriceState.state === 'OPEN' ||
    activePlanPriceState.state === 'UNKNOWN';

  // 0.9.5.0: short-term ranking is deliberately execution-first. Long-term
  // valuation/fundamental weights do not leak into the Trader brain.
  const rankingScore =
    decisionRound(
      decisionClamp(
        setupQuality * 0.28 +
        timingScore * 0.26 +
        technicalEvidenceScore * 0.18 +
        liquidityScore * 0.12 +
        rewardRiskScore * 0.10 +
        riskScore * 0.06
      ),
      2
    );

  if (
    !priceAction?.available ||
    traderEvidence.confidence ===
      'UNRESOLVED'
  ) {
    return {
      framework: 'SHORT_TERM_TRADER',
      thesisStatus: 'NO_SETUP_DATA',
      timingScore,
      timingState: 'UNAVAILABLE',
      setup,
      setupFamily,
      rewardRisk,
      riskScore,
      riskState:
        professionalRiskState(
          riskScore
        ),
      rankingScore,
      technicalEvidence:
        traderEvidence,
      tradePlan,
      conditionalTradePlan,
      marketAction: 'RESEARCHING',
      opportunityTier: 'EVIDENCE_RESEARCH',
      reason:
        'Short-term technical evidence is incomplete. NOMAD is refreshing OHLC, momentum, volume and price-action context before forming a trade view.'
    };
  }

  if (
    setup === 'BREAKDOWN' ||
    setup === 'DOWNTREND' ||
    riskScore < 35
  ) {
    return {
      framework: 'SHORT_TERM_TRADER',
      thesisStatus: 'UNFAVORABLE_SETUP',
      timingScore,
      timingState:
        priceAction.timingState,
      setup,
      setupFamily,
      rewardRisk,
      riskScore,
      riskState:
        professionalRiskState(
          riskScore
        ),
      rankingScore,
      technicalEvidence:
        traderEvidence,
      tradePlan,
      conditionalTradePlan,
      marketAction: 'AVOID',
      opportunityTier: 'LOW_PRIORITY',
      reason:
        setup === 'BREAKDOWN'
          ? 'Price structure is in a confirmed breakdown state, so NOMAD will not initiate a long trade.'
          : setup === 'DOWNTREND'
            ? 'The current short-term structure is bearish. NOMAD waits for a new bullish setup rather than buying weakness.'
            : 'Short-term market/liquidity risk is below the trader framework minimum.'
    };
  }

  const definedTradePlan =
    tradePlan?.complete === true &&
    rewardRisk !== null;

  const actionableSetup =
    (
      setup === 'CONFIRMED_BREAKOUT' ||
      setup === 'TREND_PULLBACK' ||
      setup === 'UPTREND_CONTINUATION'
    ) &&
    timingScore >= 60 &&
    riskScore >= 30 &&
    technicalEvidenceScore >= 65 &&
    definedTradePlan &&
    rewardRisk >= 1.40 &&
    activePlanOpen;

  if (actionableSetup) {
    return {
      framework: 'SHORT_TERM_TRADER',
      thesisStatus: 'ACTIVE_SETUP',
      timingScore,
      timingState:
        priceAction.timingState,
      setup,
      setupFamily,
      rewardRisk,
      riskScore,
      riskState:
        professionalRiskState(
          riskScore
        ),
      rankingScore,
      technicalEvidence:
        traderEvidence,
      tradePlan,
      conditionalTradePlan,
      marketAction: 'BUY',
      opportunityTier: 'PRIORITY_1',
      reason:
        'A defined short-term setup passes trend/price-action, risk, technical-evidence and reward-to-risk gates. Entry, invalidation and target are explicitly defined.'
    };
  }

  if (
    activePlanPriceState.state ===
      'INVALIDATED'
  ) {
    return {
      framework: 'SHORT_TERM_TRADER',
      thesisStatus: 'INVALIDATED_SETUP',
      timingScore,
      timingState:
        priceAction.timingState,
      setup,
      setupFamily,
      rewardRisk,
      riskScore,
      riskState:
        professionalRiskState(
          riskScore
        ),
      rankingScore,
      technicalEvidence:
        traderEvidence,
      tradePlan,
      conditionalTradePlan,
      marketAction: 'WATCH',
      opportunityTier: 'PRIORITY_2',
      reason:
        'The active short-term plan is invalidated at the current price. NOMAD requires a fresh setup before a new long entry.'
    };
  }

  if (
    activePlanPriceState.state ===
      'TARGET_REACHED'
  ) {
    return {
      framework: 'SHORT_TERM_TRADER',
      thesisStatus: 'TARGET_REACHED',
      timingScore,
      timingState:
        priceAction.timingState,
      setup,
      setupFamily,
      rewardRisk,
      riskScore,
      riskState:
        professionalRiskState(
          riskScore
        ),
      rankingScore,
      technicalEvidence:
        traderEvidence,
      tradePlan,
      conditionalTradePlan,
      marketAction: 'WATCH',
      opportunityTier: 'PRIORITY_2',
      reason:
        'The current price has reached or exceeded the active target. NOMAD will not issue a fresh BUY above its own target; wait for a new setup.'
    };
  }

  if (conditionalReady) {
    return {
      framework: 'SHORT_TERM_TRADER',
      thesisStatus: 'CONDITIONAL_SETUP',
      timingScore,
      timingState:
        priceAction.timingState,
      setup,
      setupFamily,
      rewardRisk,
      riskScore,
      riskState:
        professionalRiskState(
          riskScore
        ),
      rankingScore,
      technicalEvidence:
        traderEvidence,
      tradePlan,
      conditionalTradePlan,
      marketAction: 'WATCH',
      opportunityTier: 'PRIORITY_2',
      reason:
        'No trade is justified at the current reference price, but NOMAD has a defined conditional entry with stop, target and reward-to-risk at or above the minimum threshold.'
    };
  }

  let reason =
    'The stock is technically interesting, but the setup does not yet pass the full short-term trade gate.';

  if (!definedTradePlan) {
    reason =
      'Technical context is available, but NOMAD cannot yet define a complete entry, invalidation and target. No trade is permitted without a complete plan.';
  } else if (
    rewardRisk <
      DECISION_TRADER_MIN_REWARD_RISK
  ) {
    reason =
      'The setup is visible, but the defined reward-to-risk is below NOMAD\'s minimum ' +
      DECISION_TRADER_MIN_REWARD_RISK +
      ':1 trade threshold.';
  } else if (
    setup === 'UNCONFIRMED_BREAKOUT'
  ) {
    reason =
      'Price is attempting a breakout, but confirmation is incomplete. NOMAD waits for confirmation rather than chasing the move.';
  } else if (timingScore < 60) {
    reason =
      'The setup exists, but current momentum/price-action timing is not yet strong enough for a profile-independent market BUY. The selected trader profile may still define a conditional or early-entry plan.';
  }

  return {
    framework: 'SHORT_TERM_TRADER',
    thesisStatus:
      definedTradePlan
        ? 'WATCH_SETUP'
        : 'SETUP_INCOMPLETE',
    timingScore,
    timingState:
      priceAction.timingState,
    setup,
    rewardRisk,
    riskScore,
    riskState:
      professionalRiskState(
        riskScore
      ),
    rankingScore,
    technicalEvidence:
      traderEvidence,
    tradePlan,
    conditionalTradePlan,
    marketAction: 'WATCH',
    opportunityTier: 'PRIORITY_2',
    reason
  };
}

function professionalDecisionView(
  candidate,
  analystGate,
  evidence
) {
  return String(candidate?.horizon || 'long_term') === 'short_term'
    ? professionalShortTermView(candidate, analystGate, evidence)
    : professionalLongTermView(candidate, analystGate, evidence);
}

function decisionCanonicalCompanyState(
  candidate
) {
  const shortTermMode =
    String(
      candidate?.horizon ||
      'long_term'
    ) === 'short_term';

  const analystGate =
    shortTermMode
      ? {
          state: 'NOT_REQUIRED',
          validationTier: 'TRADER_TECHNICAL',
          reason:
            'Short-term market action is driven by technical setup evidence. Financial evidence remains secondary context and does not block a trade merely because it is incomplete.'
        }
      : decisionCenterAnalystGate(
          candidate
        );

  const evidence =
    shortTermMode
      ? decisionTraderEvidenceProfile(
          candidate
        )
      : decisionEvidenceProfile(
          candidate,
          analystGate
        );

  const professional =
    professionalDecisionView(
      candidate,
      analystGate,
      evidence
    );

  const researchState =
    professional.opportunityTier ===
      'EVIDENCE_RESEARCH'
      ? 'ACTIVE'
      : 'COMPLETE';

  const marketAction =
    professional.marketAction;

  const opportunityTier =
    professional.opportunityTier;

  const allocationAllowed =
    (
      marketAction === 'BUY' ||
      marketAction === 'ACCUMULATE'
    ) &&
    researchState !== 'ACTIVE';

  const allocationReason =
    allocationAllowed
      ? 'The professional framework produced an actionable market state and evidence research is complete.'
      : researchState === 'ACTIVE'
        ? 'Automatic evidence research is still active, so allocation is blocked.'
        : marketAction === 'WATCH'
          ? 'WATCH is never allowed to receive new capital.'
          : 'The professional framework does not permit a new-money allocation.';

  return {
    securityState:
      'ACTIVE_CANDIDATE',
    evidence,
    analystGate,
    professional,
    researchState,
    marketAction,
    opportunityTier,
    reason:
      professional.reason,
    rankingScore:
      professional.rankingScore,
    thesisStatus:
      professional.thesisStatus,
    allocationPermission: {
      allowed:
        allocationAllowed,
      reason:
        allocationReason
    }
  };
}

function decisionCenterCandidateView(
  candidate
) {
  const canonicalState =
    decisionCanonicalCompanyState(
      candidate
    );

  const coverage =
    safeNumber(
      candidate?.analystCore
        ?.coverage
        ?.summaryCoveragePct ??
      candidate?.analystCore
        ?.coverage
        ?.coreCoveragePct
    ) ||
    0;

  const rankScore =
    decisionRound(
      safeNumber(
        canonicalState.rankingScore
      ) ??
      (
        safeNumber(
          candidate?.overallScore
        ) ||
        0
      ),
      2
    );

  return {
    ...candidate,
    canonicalState,
    analystGate:
      canonicalState.analystGate,
    decisionCenterView:
      canonicalState.marketAction,
    decisionCenterBucket:
      canonicalState.opportunityTier,
    decisionCenterReason:
      canonicalState.reason,
    opportunityRankScore:
      rankScore
  };
}

function decisionCenterSummary(
  candidate,
  rank
) {
  const analyst =
    candidate?.analystCore ||
    null;

  const canonical =
    candidate?.canonicalState ||
    decisionCanonicalCompanyState(
      candidate
    );

  const canonicalPlanSelection =
    canonical.professional
      ?.framework ===
        'SHORT_TERM_TRADER'
      ? decisionTraderCanonicalPlan(
          canonical.professional,
          candidate?.shortTermExecution ||
          null
        )
      : null;

  return {
    rank,
    symbol:
      candidate.symbol,
    companyName:
      candidate.companyName,
    sector:
      candidate.sector,
    price:
      candidate.price,
    marketAsOf:
      candidate.marketAsOf,
    decisionCenterView:
      canonical.marketAction,
    reason:
      canonical.reason,
    analystGate:
      canonical.analystGate,
    canonicalState:
      canonical,
    professional:
      canonical.professional || null,
    thesisStatus:
      canonical.thesisStatus || null,
    allocationPermission:
      canonical.allocationPermission,
    profileSuitability:
      candidate.profileSuitability ||
      null,
    shortTermExecution:
      candidate.shortTermExecution ||
      null,
    executionPlan:
      canonicalPlanSelection
        ? {
            kind:
              canonicalPlanSelection.kind,
            source:
              canonicalPlanSelection.source,
            plan:
              canonicalPlanSelection.plan
          }
        : null,
    executionGuidance:
      candidate.executionGuidance ||
      null,
    opportunityRankScore:
      candidate.opportunityRankScore,
    overallScore:
      candidate.overallScore,
    fundamentalScore:
      candidate.fundamental?.score ??
      null,
    valuationScore:
      candidate.valuation?.score ??
      null,
    entryScore:
      candidate.entry?.score ??
      null,
    riskScore:
      candidate.risk?.score ??
      null,
    dataQualityScore:
      candidate.dataQuality?.score ??
      null,
    longTermIntelligence:
      canonical.professional
        ?.longTermIntelligence ||
      buildLongTermCompounderDividendIntelligence(
        candidate
      ),
    finalVerdict:
      canonical.professional
        ?.framework ===
          'LONG_TERM_INVESTOR'
        ? decisionLongTermFinalVerdict(
            candidate
          )
        : null,
    analyst: {
      status:
        analyst?.status ||
        'UNAVAILABLE',
      financialView:
        analyst?.overallFinancialView
          ?.state ||
        'UNAVAILABLE',
      coveragePct:
        canonical.evidence
          .summaryCoveragePct,
      extendedCoveragePct:
        canonical.evidence
          .extendedCoveragePct,
      evidenceConfidence:
        canonical.evidence
          .confidence,
      evidenceScore:
        canonical.evidence
          .score,
      evidenceTier:
        canonical.evidence
          .validationTier,
      researchState:
        canonical.researchState,
      earningsQuality:
        analyst?.views
          ?.earningsQuality
          ?.state ||
        'UNAVAILABLE',
      cashFlowQuality:
        analyst?.views
          ?.cashFlowQuality
          ?.state ||
        'UNAVAILABLE',
      balanceSheet:
        analyst?.views
          ?.balanceSheet
          ?.state ||
        'UNAVAILABLE'
    },
    positives:
      canonical.professional
        ?.framework ===
        'SHORT_TERM_TRADER'
        ? candidate.historicalContext
            ?.priceAction
            ?.positives ||
          []
        : candidate.narrative
            ?.positives ||
          [],
    risks:
      canonical.professional
        ?.framework ===
        'SHORT_TERM_TRADER'
        ? candidate.historicalContext
            ?.priceAction
            ?.risks ||
          []
        : candidate.narrative
            ?.risks ||
          []
  };
}

function buildDecisionOpportunityBoard(
  candidates
) {
  const enriched =
    (candidates || [])
      .map(
        decisionCenterCandidateView
      );

  const sortGroup =
    list =>
      list.sort(
        (
          a,
          b
        ) =>
          b.opportunityRankScore -
          a.opportunityRankScore
      );

  const priority1 =
    sortGroup(
      enriched.filter(
        item =>
          item.canonicalState
            ?.opportunityTier ===
            'PRIORITY_1'
      )
    )
      .slice(0, 5);

  const priority2 =
    sortGroup(
      enriched.filter(
        item =>
          item.canonicalState
            ?.opportunityTier ===
            'PRIORITY_2'
      )
    )
      .slice(0, 5);

  const evidenceResearch =
    sortGroup(
      enriched.filter(
        item =>
          item.canonicalState
            ?.opportunityTier ===
            'EVIDENCE_RESEARCH'
      )
    )
      .slice(0, 5);

  const avoid =
    sortGroup(
      enriched.filter(
        item =>
          item.canonicalState
            ?.opportunityTier ===
            'LOW_PRIORITY'
      )
    )
      .slice(0, 5);

  const summarize =
    list =>
      list.map(
        (item, index) =>
          decisionCenterSummary(
            item,
            index + 1
          )
      );

  const researchSummaries =
    summarize(
      evidenceResearch
    );

  return {
    priority1:
      summarize(
        priority1
      ),
    priority2:
      summarize(
        priority2
      ),
    evidenceResearch:
      researchSummaries,
    // Backwards-compatible alias for older UI/storage readers.
    researchRequired:
      researchSummaries,
    avoid:
      summarize(
        avoid
      ),
    all:
      enriched
  };
}

async function buildDecisionPortfolioContext(
  market
) {
  try {
    const [
      holdings,
      transactions
    ] =
      await Promise.all([
        readPortfolioHoldings(),
        readPortfolioTransactions()
          .catch(
            () => ({
              configured: false,
              rows: []
            })
          )
      ]);

    // Portfolio context must mirror the same effective positions shown on the
    // Portfolio page. Transaction-ledger positions therefore override/augment
    // manual opening holdings instead of being invisible to the allocator.
    const effectiveHoldings =
      new Map();

    for (
      const holding
      of holdings.rows || []
    ) {
      const symbol =
        normalizeSymbol(
          holding.symbol
        );

      if (!symbol) {
        continue;
      }

      effectiveHoldings.set(
        symbol,
        {
          ...holding,
          symbol,
          ledgerBacked: false
        }
      );
    }

    if (
      transactions.configured &&
      Array.isArray(
        transactions.rows
      )
    ) {
      const ledger =
        computePortfolioTransactionLedger(
          transactions.rows
        );

      for (
        const [
          symbol,
          state
        ]
        of ledger.bySymbol.entries()
      ) {
        if (
          !state ||
          state.quantity <= 0
        ) {
          continue;
        }

        effectiveHoldings.set(
          normalizeSymbol(symbol),
          {
            symbol:
              normalizeSymbol(symbol),
            quantity:
              state.quantity,
            average_cost:
              state.averageCost,
            purchase_date:
              state.openDate,
            ledgerBacked: true
          }
        );
      }
    }

    if (!effectiveHoldings.size) {
      return {
        configured:
          Boolean(
            holdings.configured ||
            transactions.configured
          ),
        ledgerConfigured:
          transactions.configured ===
          true,
        holdingCount: 0,
        currentValuePkr: 0,
        symbolValues: {},
        sectorValues: {},
        symbols: [],
        holdings: []
      };
    }

    const marketMap =
      new Map(
        (market?.stocks || [])
          .map(
            row => [
              normalizeSymbol(
                row.symbol
              ),
              row
            ]
          )
      );

    const symbolValues = {};
    const sectorValues = {};
    const holdingDetails = {};
    let currentValuePkr = 0;

    for (
      const holding
      of effectiveHoldings.values()
    ) {
      const symbol =
        normalizeSymbol(
          holding.symbol
        );

      const quantity =
        safeNumber(
          holding.quantity
        ) ||
        0;

      const marketRow =
        marketMap.get(
          symbol
        ) ||
        null;

      const price =
        safeNumber(
          marketRow?.price
        );

      if (
        !symbol ||
        quantity <= 0 ||
        price === null ||
        price <= 0
      ) {
        continue;
      }

      const value =
        quantity *
        price;

      const sector =
        marketRow?.sector ||
        getUniverseMasterEntry(
          symbol
        )?.sector ||
        'Unknown';

      symbolValues[symbol] =
        (
          symbolValues[symbol] ||
          0
        ) +
        value;

      sectorValues[sector] =
        (
          sectorValues[sector] ||
          0
        ) +
        value;

      holdingDetails[symbol] = {
        symbol,
        quantity:
          decisionRound(
            quantity,
            6
          ),
        averageCost:
          decisionRound(
            safeNumber(
              holding.average_cost
            ) ||
            0,
            4
          ),
        purchaseDate:
          holding.purchase_date ||
          null,
        currentPrice:
          decisionRound(
            price,
            4
          ),
        currentValuePkr:
          decisionRound(
            value,
            2
          ),
        sector,
        ledgerBacked:
          holding.ledgerBacked === true
      };

      currentValuePkr +=
        value;
    }

    return {
      configured:
        Boolean(
          holdings.configured ||
          transactions.configured
        ),
      ledgerConfigured:
        transactions.configured ===
        true,
      holdingCount:
        Object.keys(
          symbolValues
        ).length,
      currentValuePkr:
        decisionRound(
          currentValuePkr,
          2
        ),
      symbolValues,
      sectorValues,
      symbols:
        Object.keys(
          symbolValues
        ),
      holdings:
        Object.values(
          holdingDetails
        )
    };
  } catch {
    return {
      configured: false,
      ledgerConfigured: false,
      holdingCount: 0,
      currentValuePkr: 0,
      symbolValues: {},
      sectorValues: {},
      symbols: [],
      holdings: []
    };
  }
}

function decisionOwnershipThesisState(
  candidate
) {
  const canonical =
    candidate?.canonicalState ||
    null;

  if (!canonical) {
    return 'UNRESOLVED';
  }

  if (
    canonical.researchState ===
      'ACTIVE'
  ) {
    return 'CHECKING';
  }

  const raw =
    String(
      canonical.thesisStatus ||
      canonical.professional
        ?.thesisStatus ||
      ''
    )
      .trim()
      .toUpperCase();

  if (raw === 'STRONG') {
    return 'STRONG';
  }

  if (
    raw === 'ACCEPTABLE' ||
    raw === 'GOOD'
  ) {
    return 'INTACT';
  }

  if (
    raw === 'MIXED'
  ) {
    return 'WEAKENING';
  }

  if (
    raw === 'WEAK' ||
    canonical.marketAction ===
      'AVOID'
  ) {
    return canonical.marketAction ===
      'AVOID'
        ? 'BROKEN'
        : 'WEAKENING';
  }

  return 'INTACT';
}

function decisionOwnershipThesisStrength(
  value
) {
  return ({
    STRONG: 5,
    INTACT: 4,
    CHECKING: 3,
    WEAKENING: 2,
    BROKEN: 1,
    UNRESOLVED: 0
  })[
    String(value || '')
      .toUpperCase()
  ] || 0;
}


function decisionLongTermTrendView(
  candidate
) {
  const context =
    candidate?.historicalContext ||
    {};
  const returns =
    context.returns ||
    {};
  const averages =
    context.movingAverages ||
    {};
  const technical =
    context.technical ||
    {};

  const price =
    safeNumber(
      candidate?.price ??
      context?.price
    );
  const sma50 =
    safeNumber(
      averages.sma50
    );
  const sma200 =
    safeNumber(
      averages.sma200
    );
  const m3 =
    safeNumber(
      returns.m3
    );
  const m6 =
    safeNumber(
      returns.m6
    );
  const y1 =
    safeNumber(
      returns.y1
    );
  const maxDrawdown52wPct =
    safeNumber(
      technical.maxDrawdown52wPct
    );

  const below50 =
    price !== null &&
    sma50 !== null &&
    sma50 > 0
      ? price < sma50
      : null;
  const below200 =
    price !== null &&
    sma200 !== null &&
    sma200 > 0
      ? price < sma200
      : null;

  let stress = 0;
  const reasons = [];

  if (below50 === true) {
    stress += 1;
    reasons.push(
      'Price is below the 50-session moving average.'
    );
  }

  if (below200 === true) {
    stress += 2;
    reasons.push(
      'Price is below the 200-session moving average.'
    );
  }

  if (m3 !== null && m3 <= -12) {
    stress +=
      m3 <= -25
        ? 2
        : 1;
    reasons.push(
      'Three-month price performance is persistently weak.'
    );
  }

  if (m6 !== null && m6 <= -18) {
    stress +=
      m6 <= -35
        ? 2
        : 1;
    reasons.push(
      'Six-month price performance is materially weak.'
    );
  }

  if (y1 !== null && y1 <= -25) {
    stress += 1;
    reasons.push(
      'One-year price performance is materially negative.'
    );
  }

  if (
    maxDrawdown52wPct !== null &&
    maxDrawdown52wPct <= -35
  ) {
    stress += 1;
    reasons.push(
      'The 52-week drawdown is deep enough to require a thesis review.'
    );
  }

  const state =
    stress >= 6
      ? 'SEVERE_WEAKNESS'
      : stress >= 4
        ? 'PERSISTENT_WEAKNESS'
        : stress >= 2
          ? 'MIXED'
          : 'HEALTHY';

  return {
    state,
    stressScore:
      stress,
    price:
      decisionRound(
        price,
        2
      ),
    sma50:
      decisionRound(
        sma50,
        2
      ),
    sma200:
      decisionRound(
        sma200,
        2
      ),
    below50,
    below200,
    return3mPct:
      decisionRound(
        m3,
        2
      ),
    return6mPct:
      decisionRound(
        m6,
        2
      ),
    return1yPct:
      decisionRound(
        y1,
        2
      ),
    maxDrawdown52wPct:
      decisionRound(
        maxDrawdown52wPct,
        2
      ),
    reasons:
      uniqueTextValues(
        reasons
      ),
    note:
      'Long-term price weakness is an investigation signal. It cannot by itself create an EXIT verdict.'
  };
}

function decisionLongTermFundamentalDeterioration(
  candidate
) {
  const analyst =
    candidate?.analystCore ||
    null;
  const views =
    analyst?.views ||
    {};
  const canonical =
    candidate?.canonicalState ||
    null;
  const intelligence =
    canonical?.professional
      ?.longTermIntelligence ||
    buildLongTermCompounderDividendIntelligence(
      candidate
    );

  const flags = [];

  const addFlag =
    (condition, text) => {
      if (condition) {
        flags.push(text);
      }
    };

  addFlag(
    ['WEAK', 'MIXED'].includes(
      String(
        analyst?.overallFinancialView
          ?.state ||
        ''
      ).toUpperCase()
    ),
    'Overall financial quality has weakened.'
  );

  addFlag(
    String(
      views.profitTrend?.state ||
      ''
    ).toUpperCase() === 'DETERIORATING',
    'Profit trend is deteriorating.'
  );

  addFlag(
    String(
      views.epsTrend?.state ||
      ''
    ).toUpperCase() === 'DETERIORATING',
    'EPS trend is deteriorating.'
  );

  addFlag(
    ['WEAK', 'QUESTIONABLE'].includes(
      String(
        views.cashFlowQuality?.state ||
        ''
      ).toUpperCase()
    ),
    'Cash-flow quality is weak or questionable.'
  );

  addFlag(
    ['WEAK', 'QUESTIONABLE'].includes(
      String(
        views.balanceSheet?.state ||
        ''
      ).toUpperCase()
    ),
    'Balance-sheet quality is weak or questionable.'
  );

  addFlag(
    String(
      intelligence?.compounder?.state ||
      ''
    ).toUpperCase() === 'WEAK',
    'Compounder quality is weak.'
  );

  addFlag(
    String(
      intelligence?.dividend
        ?.yieldTrapRisk ||
      ''
    ).toUpperCase() === 'HIGH',
    'Dividend yield-trap risk is high.'
  );

  const thesisState =
    decisionOwnershipThesisState(
      candidate
    );

  addFlag(
    thesisState === 'BROKEN',
    'The canonical long-term thesis is broken.'
  );

  const count =
    flags.length;

  const state =
    thesisState === 'BROKEN' &&
    count >= 2
      ? 'BROKEN'
      : count >= 3
        ? 'WEAKENING'
        : count >= 1
          ? 'WATCH'
          : 'STABLE';

  return {
    state,
    flagCount:
      count,
    flags:
      uniqueTextValues(
        flags
      )
  };
}

function decisionLongTermExitIntelligence(
  candidate,
  holding,
  baseline
) {
  if (!candidate) {
    return {
      verdict: 'HOLD_RESEARCH',
      tone: 'neutral',
      thesisState: 'UNRESOLVED',
      trend: {
        state: 'UNRESOLVED',
        reasons: []
      },
      fundamentals: {
        state: 'UNRESOLVED',
        flagCount: 0,
        flags: []
      },
      reason:
        'Fresh long-term evidence is incomplete. NOMAD will not invent a sell signal.'
    };
  }

  const canonical =
    candidate?.canonicalState ||
    decisionCanonicalCompanyState(
      candidate
    );
  const thesisState =
    decisionOwnershipThesisState(
      candidate
    );
  const evidenceConfidence =
    canonical?.evidence
      ?.confidence ||
    'UNRESOLVED';
  const trend =
    decisionLongTermTrendView(
      candidate
    );
  const fundamentals =
    decisionLongTermFundamentalDeterioration(
      candidate
    );
  const baselineStrength =
    decisionOwnershipThesisStrength(
      baseline?.thesisState
    );
  const currentStrength =
    decisionOwnershipThesisStrength(
      thesisState
    );
  const materialThesisDrop =
    baselineStrength > 0 &&
    currentStrength + 1 <
      baselineStrength;

  let verdict =
    'HOLD_CONFIRMED';
  let tone = 'positive';
  let reason =
    'The long-term thesis remains intact. Normal market movement does not independently justify selling.';

  const thesisBroken =
    thesisState === 'BROKEN' ||
    canonical?.marketAction === 'AVOID';
  const thesisWeakening =
    thesisState === 'WEAKENING' ||
    materialThesisDrop;
  const trendSevere =
    trend.state === 'SEVERE_WEAKNESS';
  const trendPersistent =
    trend.state === 'PERSISTENT_WEAKNESS';
  const evidenceUsable =
    evidenceConfidence !== 'UNRESOLVED';

  // A red chart alone never creates a long-term EXIT. EXIT requires a broken
  // thesis plus evidence-qualified fundamental deterioration. Price weakness
  // only changes urgency and confirmation.
  if (
    thesisBroken &&
    evidenceUsable &&
    fundamentals.flagCount >= 2
  ) {
    verdict =
      trendSevere ||
      trendPersistent
        ? 'EXIT_CONFIRMED'
        : 'EXIT_REVIEW';
    tone = 'negative';
    reason =
      verdict === 'EXIT_CONFIRMED'
        ? 'The original long-term thesis is broken and multiple fundamental warnings are confirmed. Persistent price weakness reinforces the evidence; review execution of an exit rather than holding solely because the position is down.'
        : 'The original long-term thesis is broken on fundamental evidence. Review an exit even though price weakness alone is not the reason.';
  } else if (
    thesisWeakening &&
    fundamentals.flagCount >= 2
  ) {
    verdict =
      trendSevere ||
      trendPersistent
        ? 'REDUCE'
        : 'REVIEW_CAUTION';
    tone = 'warning';
    reason =
      verdict === 'REDUCE'
        ? 'The thesis has weakened on multiple fundamental signals and long-term price structure is persistently weak. NOMAD recommends reducing risk while the thesis is reassessed.'
        : 'The thesis has weakened on multiple fundamental signals. Review the position closely before adding or continuing to hold unchanged.';
  } else if (
    trendSevere ||
    trendPersistent
  ) {
    verdict = 'HOLD_MONITOR';
    tone = 'warning';
    reason =
      'Long-term price structure is weak, but NOMAD does not have enough fundamental evidence to call the thesis broken. Hold/monitor rather than panic-selling on price alone.';
  } else if (
    fundamentals.state === 'WATCH' ||
    canonical?.researchState === 'ACTIVE'
  ) {
    verdict = 'HOLD_MONITOR';
    tone = 'warning';
    reason =
      'The position remains a hold, but one or more evidence items deserve monitoring before NOMAD becomes more confident.';
  }

  const averageCost =
    safeNumber(
      holding?.averageCost
    );
  const currentPrice =
    safeNumber(
      holding?.currentPrice ??
      candidate?.price
    );
  const returnPct =
    averageCost !== null &&
    averageCost > 0 &&
    currentPrice !== null
      ? (
          currentPrice -
          averageCost
        ) /
        averageCost *
        100
      : null;

  return {
    verdict,
    tone,
    thesisState,
    evidenceConfidence,
    fundamentals,
    trend,
    returnPct:
      decisionRound(
        returnPct,
        2
      ),
    reason,
    monitoringHorizon:
      'Continuous evidence review · 50/200-session trend · 3/6/12-month price context',
    rule:
      'Price weakness raises review urgency; thesis deterioration determines REDUCE/EXIT.'
  };
}

function decisionLongTermFinalVerdict(
  candidate
) {
  if (
    String(
      candidate?.horizon ||
      'long_term'
    ) !== 'long_term'
  ) {
    return null;
  }

  const canonical =
    candidate?.canonicalState ||
    decisionCanonicalCompanyState(
      candidate
    );
  const suitability =
    candidate?.profileSuitability ||
    null;
  const execution =
    candidate?.executionGuidance ||
    null;
  const marketAction =
    String(
      canonical?.marketAction ||
      'WATCH'
    ).toUpperCase();
  const executionStatus =
    String(
      execution?.status ||
      ''
    ).toUpperCase();

  let code = 'WAIT_FOR_ENTRY';
  let tone = 'warning';
  let title = 'GOOD COMPANY · WAIT FOR ENTRY';
  let reason =
    execution?.reason ||
    canonical?.reason ||
    'Current conditions do not justify new capital yet.';

  if (
    canonical?.researchState === 'ACTIVE' ||
    marketAction === 'RESEARCHING'
  ) {
    code = 'CHECK_EVIDENCE';
    tone = 'neutral';
    title = 'CHECK EVIDENCE';
    reason =
      'NOMAD is still validating evidence, so it will not confirm a new long-term buy yet.';
  } else if (
    marketAction === 'AVOID'
  ) {
    code = 'DO_NOT_BUY';
    tone = 'negative';
    title = 'DO NOT BUY';
  } else if (
    suitability?.state === 'NOT_SUITABLE' ||
    executionStatus === 'PROFILE_BLOCKED'
  ) {
    code = 'DO_NOT_BUY';
    tone = 'negative';
    title = 'DO NOT BUY FOR THIS PROFILE';
  } else if (
    marketAction === 'BUY' &&
    executionStatus === 'BUY_NOW'
  ) {
    code = 'BUY_CONFIRMED';
    tone = 'positive';
    title = 'LONG-TERM BUY CONFIRMED';
    reason =
      'Business/thesis, valuation, risk, profile and current execution price all pass NOMAD\'s long-term gates.';
  } else if (
    (
      marketAction === 'BUY' ||
      marketAction === 'ACCUMULATE'
    ) &&
    executionStatus === 'STAGED_BUY'
  ) {
    code = 'STAGED_BUY';
    tone = 'positive';
    title = 'BUY CONFIRMED · BUILD GRADUALLY';
    reason =
      execution?.reason ||
      'NOMAD approves the long-term buy at the current entry, but prefers building the position gradually rather than committing the full intended exposure at once.';
  } else if (
    executionStatus === 'DO_NOT_CHASE'
  ) {
    code = 'WAIT_FOR_ENTRY';
    tone = 'warning';
    title = 'GOOD COMPANY · DO NOT CHASE';
  } else if (
    marketAction === 'WATCH' ||
    [
      'WAIT_FOR_ENTRY',
      'WAIT_FOR_PRICE'
    ].includes(
      executionStatus
    )
  ) {
    code = 'WAIT_FOR_ENTRY';
    tone = 'warning';
    title = 'GOOD COMPANY · WAIT FOR ENTRY';
  }

  return {
    code,
    tone,
    title,
    reason,
    maxBuyPrice:
      safeNumber(
        execution?.maxAcceptablePrice
      ),
    referencePrice:
      safeNumber(
        execution?.referencePrice
      ),
    thesisStatus:
      canonical?.professional
        ?.thesisStatus ||
      canonical?.thesisStatus ||
      null,
    confidence:
      canonical?.evidence
        ?.confidence ||
      'UNRESOLVED'
  };
}

function decisionOwnershipPurchaseThesisSnapshot(
  baseline
) {
  if (!baseline) {
    return null;
  }

  return {
    label:
      baseline.label ||
      'first tracked baseline',
    asOf:
      baseline.createdAt ||
      null,
    price:
      safeNumber(
        baseline.price
      ),
    thesisState:
      baseline.thesisState ||
      'UNRESOLVED',
    marketAction:
      baseline.marketAction ||
      null,
    thesisScore:
      safeNumber(
        baseline.thesisScore
      ),
    financialScore:
      safeNumber(
        baseline.financialScore
      ),
    valuationScore:
      safeNumber(
        baseline.valuationScore
      ),
    valuationState:
      baseline.valuationState ||
      null,
    timingState:
      baseline.timingState ||
      null,
    evidenceConfidence:
      baseline.evidenceConfidence ||
      'UNRESOLVED',
    compounder:
      baseline.compounder ||
      null,
    dividend:
      baseline.dividend ||
      null
  };
}

function decisionOwnershipExistingAction(
  candidate,
  holding,
  portfolioContext,
  riskPolicy
) {
  const canonical =
    candidate?.canonicalState ||
    null;
  const suitability =
    candidate?.profileSuitability ||
    null;
  const thesis =
    decisionOwnershipThesisState(
      candidate
    );

  if (!canonical) {
    return {
      action: 'HOLD_RESEARCH',
      reason:
        'NOMAD could not complete a fresh ownership review, so it will not invent an exit or add decision.'
    };
  }

  if (
    canonical.researchState ===
      'ACTIVE' ||
    thesis === 'CHECKING'
  ) {
    return {
      action: 'HOLD_RESEARCH',
      reason:
        'The position remains owned while NOMAD refreshes missing long-term evidence.'
    };
  }

  if (
    canonical.marketAction ===
      'AVOID' ||
    thesis === 'BROKEN'
  ) {
    return {
      action: 'REVIEW_REDUCE',
      reason:
        'The current long-term framework is unfavorable. Review the original thesis before deciding whether to reduce or exit.'
    };
  }

  if (
    suitability?.state ===
      'NOT_SUITABLE'
  ) {
    return {
      action: 'HOLD_NO_ADD',
      reason:
        'The position does not automatically become a sell, but the selected profile does not support adding more capital today.'
    };
  }

  if (
    canonical.marketAction ===
      'WATCH'
  ) {
    return {
      action: 'HOLD',
      reason:
        'The long-term thesis does not independently trigger an exit; today\'s conditions simply do not justify adding fresh capital.'
    };
  }

  if (
    canonical.marketAction ===
      'BUY' ||
    canonical.marketAction ===
      'ACCUMULATE'
  ) {
    const portfolioValue =
      safeNumber(
        portfolioContext
          ?.currentValuePkr
      ) ||
      0;
    const holdingValue =
      safeNumber(
        holding?.currentValuePkr
      ) ||
      0;
    const weight =
      portfolioValue > 0
        ? holdingValue /
          portfolioValue
        : 0;
    const hardCap =
      Math.max(
        0.01,
        safeNumber(
          riskPolicy?.maxStockPct
        ) ||
        0.45
      );

    if (weight >= hardCap) {
      return {
        action: 'HOLD_NO_ADD',
        reason:
          'The thesis remains actionable, but your existing position is already at the selected profile\'s single-stock concentration ceiling.'
      };
    }

    return {
      action: 'ADD_CANDIDATE',
      reason:
        'You already own the company and the current long-term thesis remains actionable; any additional purchase must still pass today\'s entry and portfolio-fit gates.'
    };
  }

  return {
    action: 'HOLD',
    reason:
      'No current evidence independently requires an exit from the existing long-term position.'
  };
}

function decisionOwnershipNewMoneyAction(
  candidate,
  existingAction
) {
  const canonical =
    candidate?.canonicalState ||
    null;

  if (!canonical) {
    return 'WAIT_DATA';
  }

  if (
    existingAction?.action ===
      'HOLD_NO_ADD'
  ) {
    return 'DO_NOT_ADD';
  }

  if (
    canonical.researchState ===
      'ACTIVE'
  ) {
    return 'WAIT_DATA';
  }

  if (
    canonical.marketAction ===
      'AVOID'
  ) {
    return 'NO_BUY';
  }

  if (
    canonical.marketAction ===
      'WATCH'
  ) {
    return 'WAIT_FOR_ENTRY';
  }

  const guidance =
    candidate?.executionGuidance ||
    null;

  if (guidance?.status) {
    return guidance.status;
  }

  return canonical.marketAction ===
    'BUY'
      ? 'BUY_NOW'
      : canonical.marketAction ===
          'ACCUMULATE'
        ? 'STAGED_BUY'
        : 'WAIT_FOR_ENTRY';
}

function decisionOwnershipCandidateFromRun(
  run,
  symbol
) {
  const normalized =
    normalizeSymbol(
      symbol
    );
  const raw =
    run?.raw_result ||
    null;

  if (!raw || !normalized) {
    return null;
  }

  const candidate =
    (raw.candidates || [])
      .find(
        item =>
          normalizeSymbol(
            item?.symbol
          ) === normalized
      ) ||
    null;

  if (!candidate) {
    return null;
  }

  const canonical =
    candidate.canonicalState ||
    decisionCanonicalCompanyState(
      candidate
    );
  const professional =
    canonical?.professional ||
    {};
  const intelligence =
    professional?.longTermIntelligence ||
    candidate?.longTermIntelligence ||
    null;

  return {
    createdAt:
      run.created_at ||
      raw.completedAt ||
      null,
    price:
      safeNumber(
        candidate.price
      ),
    thesisState:
      decisionOwnershipThesisState({
        ...candidate,
        canonicalState:
          canonical
      }),
    marketAction:
      canonical.marketAction ||
      null,
    opportunityTier:
      canonical.opportunityTier ||
      null,
    timingState:
      canonical.professional
        ?.timingState ||
      null,
    valuationState:
      canonical.professional
        ?.valuationState ||
      null,
    thesisScore:
      safeNumber(
        professional.thesisScore
      ),
    financialScore:
      safeNumber(
        professional.financialScore
      ),
    valuationScore:
      safeNumber(
        professional.valuationScore
      ),
    riskScore:
      safeNumber(
        professional.riskScore
      ),
    evidenceConfidence:
      canonical?.evidence
        ?.confidence ||
      'UNRESOLVED',
    compounder:
      intelligence?.compounder
        ? {
            state:
              intelligence.compounder.state ||
              'UNRESOLVED',
            score:
              safeNumber(
                intelligence.compounder.score
              )
          }
        : null,
    dividend:
      intelligence?.dividend
        ? {
            state:
              intelligence.dividend.state ||
              'UNRESOLVED',
            score:
              safeNumber(
                intelligence.dividend.score
              ),
            yieldTrapRisk:
              intelligence.dividend.yieldTrapRisk ||
              'UNRESOLVED'
          }
        : null
  };
}

function decisionOwnershipBaseline(
  recentRuns,
  holding
) {
  const matches =
    (recentRuns || [])
      .map(
        run =>
          decisionOwnershipCandidateFromRun(
            run,
            holding?.symbol
          )
      )
      .filter(Boolean)
      .sort(
        (a, b) =>
          Date.parse(a.createdAt || '') -
          Date.parse(b.createdAt || '')
      );

  if (!matches.length) {
    return null;
  }

  const purchaseDate =
    holding?.purchaseDate ||
    null;
  const purchaseStart =
    purchaseDate
      ? Date.parse(
          String(purchaseDate)
            .slice(0, 10) +
          'T00:00:00+05:00'
        )
      : NaN;

  const sincePurchase =
    Number.isFinite(purchaseStart)
      ? matches.filter(
          item =>
            Date.parse(
              item.createdAt ||
              ''
            ) >= purchaseStart
        )
      : [];

  const baseline =
    sincePurchase[0] ||
    matches[0];

  const baselineDate =
    baseline?.createdAt
      ? String(
          baseline.createdAt
        ).slice(0, 10)
      : null;

  return {
    ...baseline,
    label:
      purchaseDate &&
      baselineDate ===
        String(purchaseDate).slice(0, 10)
        ? 'purchase-day baseline'
        : 'first tracked baseline'
  };
}

function decisionOwnershipChangeSummary(
  current,
  baseline,
  holding
) {
  const thesis =
    current?.thesisState ||
    'UNRESOLVED';
  const currentPrice =
    safeNumber(
      holding?.currentPrice
    );
  const averageCost =
    safeNumber(
      holding?.averageCost
    );
  const returnPct =
    currentPrice !== null &&
    averageCost !== null &&
    averageCost > 0
      ? (
          currentPrice -
          averageCost
        ) /
        averageCost *
        100
      : null;

  if (!baseline) {
    return {
      state: 'BASELINE_CREATED',
      text:
        'First tracked ownership continuity snapshot. Future long-term analyses will compare the thesis and entry state against this baseline.',
      returnPct:
        decisionRound(
          returnPct,
          2
        )
    };
  }

  const currentStrength =
    decisionOwnershipThesisStrength(
      thesis
    );
  const baselineStrength =
    decisionOwnershipThesisStrength(
      baseline.thesisState
    );

  let text;
  let state = 'UNCHANGED';

  if (
    currentStrength + 1 <
      baselineStrength
  ) {
    state = 'WEAKENED';
    text =
      'The long-term thesis has weakened versus the ' +
      baseline.label +
      '. This is a thesis change, not merely a lower new-money rank.';
  } else if (
    currentStrength >
      baselineStrength
  ) {
    state = 'IMPROVED';
    text =
      'The long-term thesis has improved versus the ' +
      baseline.label +
      '.';
  } else if (
    baseline.marketAction ===
      'BUY' ||
    baseline.marketAction ===
      'ACCUMULATE'
  ) {
    if (
      current?.marketAction ===
        'WATCH'
    ) {
      state = 'ENTRY_CHANGED';
      text =
        'No material thesis deterioration detected. The ownership case remains intact; only the new-money entry has become less attractive today.';
    } else {
      text =
        'No material thesis deterioration detected versus the ' +
        baseline.label +
        '. The current ownership case remains intact.';
    }
  } else {
    text =
      'The ownership thesis is broadly consistent with the ' +
      baseline.label +
      '; today\'s new-money ranking is a separate decision.';
  }

  return {
    state,
    text,
    returnPct:
      decisionRound(
        returnPct,
        2
      )
  };
}

async function analyzeLongTermOwnershipCandidate(
  marketRow,
  eligibleRows,
  memoryMap,
  model,
  riskPolicy
) {
  if (!marketRow) {
    return null;
  }

  const historicalContext =
    await decisionHistoricalContext(
      marketRow,
      memoryMap
    );

  const valuation =
    scoreDecisionValuation(
      marketRow,
      eligibleRows
    );

  const entry =
    scoreDecisionEntry(
      historicalContext,
      'long_term',
      riskPolicy
    );

  const riskScore =
    scoreDecisionRisk(
      marketRow,
      historicalContext,
      eligibleRows
    );

  const fundamentalEvidence =
    await decisionLoadFundamentals(
      marketRow,
      memoryMap
    );

  const fundamentals =
    fundamentalEvidence
      .fundamentals;

  const fundamental =
    scoreDecisionFundamentals(
      fundamentals
    );

  fundamental.evidenceState =
    fundamentalEvidence
      .evidenceState;
  fundamental.cachedAt =
    fundamentalEvidence
      .cachedAt;

  if (fundamentalEvidence.error) {
    fundamental.risks =
      uniqueTextValues([
        ...(fundamental.risks || []),
        fundamentalEvidence.error
      ]);
  }

  const dataQuality =
    scoreDecisionDataQuality(
      marketRow,
      historicalContext,
      fundamental
    );

  const overallScore =
    decisionOverallScore(
      model,
      fundamental,
      valuation,
      entry,
      riskScore,
      dataQuality
    );

  const candidate = {
    horizon: 'long_term',
    recommendationEligible:
      marketRow.recommendationEligible ===
        true,
    symbol:
      marketRow.symbol,
    companyName:
      marketRow.companyName,
    sector:
      marketRow.sector,
    statusCodes:
      marketRow.statusCodes ||
      [],
    price:
      decisionRound(
        marketRow.price,
        4
      ),
    marketAsOf:
      marketRow.asOf ||
      null,
    averageVolume30d:
      decisionRound(
        marketRow.averageVolume30d,
        0
      ),
    historicalContext,
    fundamental,
    analystCore:
      fundamentals?.analystCore ||
      null,
    fundamentalEvidenceState:
      fundamentalEvidence.evidenceState,
    fundamentalEvidenceDiagnostics:
      fundamentalEvidence.diagnostics ||
      null,
    valuation,
    entry,
    risk:
      riskScore,
    dataQuality,
    overallScore
  };

  const action =
    decisionCandidateAction(
      candidate,
      model,
      riskPolicy
    );

  candidate.action =
    action.action;
  candidate.actionReason =
    action.reason;
  candidate.narrative =
    decisionCandidateNarrative(
      candidate
    );
  candidate.canonicalState =
    decisionCanonicalCompanyState(
      candidate
    );
  candidate.profileSuitability =
    decisionProfileSuitability(
      candidate,
      riskPolicy
    );
  candidate.executionGuidance =
    decisionExecutionGuidance(
      candidate,
      riskPolicy
    );

  return candidate;
}

async function buildLongTermOwnershipContinuity(
  candidates,
  portfolioContext,
  market,
  eligibleRows,
  memoryMap,
  model,
  riskPolicy,
  risk
) {
  const holdings =
    Array.isArray(
      portfolioContext?.holdings
    )
      ? portfolioContext.holdings
      : [];

  if (!holdings.length) {
    return {
      available: false,
      holdings: [],
      summary: {
        holdingCount: 0,
        intactCount: 0,
        reviewCount: 0
      }
    };
  }

  const candidateMap =
    new Map(
      (candidates || [])
        .filter(item => item?.symbol)
        .map(
          item => [
            normalizeSymbol(
              item.symbol
            ),
            item
          ]
        )
    );

  const marketMap =
    new Map(
      (market?.stocks || [])
        .filter(item => item?.symbol)
        .map(
          item => [
            normalizeSymbol(
              item.symbol
            ),
            item
          ]
        )
    );

  const missing =
    holdings
      .filter(
        holding =>
          !candidateMap.has(
            normalizeSymbol(
              holding.symbol
            )
          )
      )
      .map(
        holding => ({
          holding,
          marketRow:
            marketMap.get(
              normalizeSymbol(
                holding.symbol
              )
            ) ||
            null
        })
      )
      .filter(
        item =>
          item.marketRow
      );

  const [
    supplemental,
    recentRuns
  ] =
    await Promise.all([
      decisionMapWithConcurrency(
        missing,
        2,
        async item =>
          analyzeLongTermOwnershipCandidate(
            item.marketRow,
            eligibleRows,
            memoryMap,
            model,
            riskPolicy
          )
      ),
      readRecentLongTermDecisionResults(
        risk,
        60
      )
    ]);

  for (const candidate of supplemental) {
    if (
      candidate &&
      !candidate.error &&
      candidate.symbol
    ) {
      candidateMap.set(
        normalizeSymbol(
          candidate.symbol
        ),
        candidate
      );
    }
  }

  const views =
    holdings.map(
      holding => {
        const symbol =
          normalizeSymbol(
            holding.symbol
          );
        const candidate =
          candidateMap.get(
            symbol
          ) ||
          null;
        const canonical =
          candidate?.canonicalState ||
          null;
        const thesisState =
          decisionOwnershipThesisState(
            candidate
          );
        const existingAction =
          decisionOwnershipExistingAction(
            candidate,
            holding,
            portfolioContext,
            riskPolicy
          );
        const newMoneyAction =
          decisionOwnershipNewMoneyAction(
            candidate,
            existingAction
          );
        const baseline =
          decisionOwnershipBaseline(
            recentRuns,
            holding
          );
        const change =
          decisionOwnershipChangeSummary(
            {
              thesisState,
              marketAction:
                canonical?.marketAction ||
                null
            },
            baseline,
            holding
          );
        const exitIntelligence =
          decisionLongTermExitIntelligence(
            candidate,
            holding,
            baseline
          );
        const purchaseThesis =
          decisionOwnershipPurchaseThesisSnapshot(
            baseline
          );
        const weightPct =
          safeNumber(
            portfolioContext
              ?.currentValuePkr
          ) > 0
            ? (
                safeNumber(
                  holding.currentValuePkr
                ) ||
                0
              ) /
              portfolioContext.currentValuePkr *
              100
            : 0;

        return {
          symbol,
          companyName:
            candidate?.companyName ||
            marketMap.get(symbol)
              ?.companyName ||
            symbol,
          sector:
            holding.sector ||
            candidate?.sector ||
            'Unknown',
          quantity:
            holding.quantity ||
            0,
          averageCost:
            holding.averageCost ||
            0,
          purchaseDate:
            holding.purchaseDate ||
            null,
          currentPrice:
            holding.currentPrice ||
            candidate?.price ||
            null,
          currentValuePkr:
            holding.currentValuePkr ||
            0,
          portfolioWeightPct:
            decisionRound(
              weightPct,
              2
            ),
          thesisState,
          thesisRaw:
            canonical?.thesisStatus ||
            canonical?.professional
              ?.thesisStatus ||
            null,
          marketAction:
            canonical?.marketAction ||
            'RESEARCHING',
          opportunityTier:
            canonical?.opportunityTier ||
            'EVIDENCE_RESEARCH',
          existingAction:
            existingAction.action,
          existingReason:
            existingAction.reason,
          newMoneyAction,
          newMoneyReason:
            candidate?.executionGuidance
              ?.reason ||
            canonical?.reason ||
            '',
          maxBuyPrice:
            safeNumber(
              candidate?.executionGuidance
                ?.maxAcceptablePrice
            ),
          timingState:
            canonical?.professional
              ?.timingState ||
            null,
          valuationState:
            canonical?.professional
              ?.valuationState ||
            null,
          evidenceConfidence:
            canonical?.evidence
              ?.confidence ||
            'UNRESOLVED',
          longTermIntelligence:
            canonical?.professional
              ?.longTermIntelligence ||
            buildLongTermCompounderDividendIntelligence(
              candidate
            ),
          finalVerdict:
            exitIntelligence,
          exitIntelligence,
          purchaseThesis,
          baseline,
          change,
          analyzed:
            Boolean(candidate)
        };
      }
    );

  const intactCount =
    views.filter(
      item =>
        item.thesisState ===
          'STRONG' ||
        item.thesisState ===
          'INTACT'
    ).length;
  const reviewCount =
    views.filter(
      item =>
        item.thesisState ===
          'WEAKENING' ||
        item.thesisState ===
          'BROKEN' ||
        item.existingAction ===
          'REVIEW_REDUCE'
    ).length;

  return {
    available: true,
    framework:
      'LONG_TERM_OWNERSHIP_CONTINUITY',
    holdings:
      views,
    summary: {
      holdingCount:
        views.length,
      intactCount,
      reviewCount,
      exitReviewCount:
        views.filter(
          item =>
            [
              'EXIT_CONFIRMED',
              'EXIT_REVIEW',
              'REDUCE'
            ].includes(
              item?.exitIntelligence
                ?.verdict
            )
        ).length,
      monitorCount:
        views.filter(
          item =>
            item?.exitIntelligence
              ?.verdict ===
              'HOLD_MONITOR'
        ).length,
      checkingCount:
        views.filter(
          item =>
            item.thesisState ===
              'CHECKING' ||
            item.thesisState ===
              'UNRESOLVED'
        ).length
    },
    note:
      'Ownership status is separate from the new-money ranking. Long-term exit intelligence treats price weakness as a review trigger, not an automatic sell; REDUCE/EXIT requires thesis deterioration.'
  };
}

function decisionProfileSuitability(
  candidate,
  riskPolicy
) {
  const issues = [];

  if (
    candidate?.recommendationEligible ===
      false
  ) {
    issues.push(
      'This security is not eligible for NOMAD new-money recommendations.'
    );
  }

  if (
    (candidate?.statusCodes || [])
      .includes('NC')
  ) {
    issues.push(
      'PSX non-compliant-segment status is present.'
    );
  }

  const avgVolume =
    safeNumber(
      candidate?.averageVolume30d
    );

  const shortTermMode =
    String(
      candidate?.horizon ||
      'long_term'
    ) === 'short_term';

  const traderProfilePolicy =
    shortTermMode
      ? decisionTraderProfilePolicy(riskPolicy)
      : null;

  const minimumAverageVolume30d =
    shortTermMode
      ? traderProfilePolicy.minAverageVolume30d
      : riskPolicy.minAverageVolume30d;

  if (
    avgVolume === null ||
    avgVolume < minimumAverageVolume30d
  ) {
    issues.push(
      shortTermMode
        ? '30-day liquidity is below the selected trader profile minimum.'
        : '30-day liquidity is below the selected risk profile minimum.'
    );
  }

  const volatility =
    safeNumber(
      candidate?.historicalContext
        ?.technical
        ?.annualizedVolatility20dPct
    );

  if (
    !shortTermMode &&
    volatility !== null &&
    volatility >
      riskPolicy.maxAnnualizedVolatilityPct
  ) {
    issues.push(
      'Recent annualized volatility exceeds the selected risk profile limit.'
    );
  }

  const traderPriceAction =
    shortTermMode
      ? candidate?.historicalContext
          ?.priceAction ||
        null
      : null;

  const currentTraderPlan =
    traderPriceAction?.tradePlan ||
    null;
  const conditionalTraderPlan =
    traderPriceAction?.conditionalTradePlan ||
    null;

  const currentTraderPlanActionable =
    currentTraderPlan?.complete === true &&
    safeNumber(
      currentTraderPlan?.rewardRisk
    ) !== null &&
    safeNumber(
      currentTraderPlan?.rewardRisk
    ) >= DECISION_TRADER_MIN_REWARD_RISK;

  const traderPlanForRisk =
    currentTraderPlanActionable
      ? currentTraderPlan
      : conditionalTraderPlan?.complete === true
        ? conditionalTraderPlan
        : currentTraderPlan?.complete === true
          ? currentTraderPlan
          : null;

  const traderStopRiskPct =
    safeNumber(
      traderPlanForRisk?.riskPct
    );

  const maxTraderStopRiskPct =
    shortTermMode
      ? traderProfilePolicy.maxStopRiskPct
      : null;

  if (
    shortTermMode &&
    traderStopRiskPct !== null &&
    traderStopRiskPct >
      maxTraderStopRiskPct
  ) {
    issues.push(
      'The defined stop distance is too wide for the selected short-term risk profile.'
    );
  }

  if (shortTermMode) {
    const volumeRatio20d = safeNumber(
      candidate?.historicalContext?.technical?.volumeRatio20d
    );
    if (
      volumeRatio20d !== null &&
      volumeRatio20d < traderProfilePolicy.minVolumeRatio20d
    ) {
      issues.push(
        'Current participation is too weak for the selected trader profile.'
      );
    }

    const planAgeDays = decisionTraderPlanAgeDays(candidate);
    if (
      planAgeDays !== null &&
      planAgeDays > traderProfilePolicy.maxPlanAgeDays
    ) {
      issues.push(
        'The short-term setup is stale and must be recalculated before entry.'
      );
    }
  }

  const applicableDataQualityScore =
    shortTermMode
      ? safeNumber(
          decisionTraderEvidenceProfile(
            candidate
          ).score
        )
      : safeNumber(
          candidate?.dataQuality?.score
        );

  const minimumEvidenceScore =
    shortTermMode
      ? traderProfilePolicy.minTechnicalEvidenceScore
      : riskPolicy.minDataQualityScore;

  if (
    applicableDataQualityScore <
      minimumEvidenceScore
  ) {
    issues.push(
      shortTermMode
        ? 'Technical evidence quality is below the selected trader profile minimum.'
        : 'Data quality is below the selected risk profile minimum.'
    );
  }

  const minimumRiskScore =
    shortTermMode
      ? traderProfilePolicy.minRiskScore
      : riskPolicy.minRiskScore;

  if (
    safeNumber(
      candidate?.risk?.score
    ) <
      minimumRiskScore
  ) {
    issues.push(
      shortTermMode
        ? 'Trade risk/liquidity quality is below the selected trader profile minimum.'
        : 'Risk quality is below the selected risk profile minimum.'
    );
  }

  return {
    state:
      issues.length
        ? 'NOT_SUITABLE'
        : 'SUITABLE',
    issues,
    profileId:
      riskPolicy.id,
    thresholds: {
      minAverageVolume30d:
        minimumAverageVolume30d,
      maxAnnualizedVolatilityPct:
        riskPolicy.maxAnnualizedVolatilityPct,
      ...(shortTermMode
        ? {
            maxTraderStopRiskPct
          }
        : {}),
      minDataQualityScore:
        shortTermMode
          ? traderProfilePolicy.minTechnicalEvidenceScore
          : riskPolicy.minDataQualityScore,
      minRiskScore:
        shortTermMode
          ? traderProfilePolicy.minRiskScore
          : riskPolicy.minRiskScore
    },
    observations: {
      averageVolume30d:
        avgVolume,
      annualizedVolatility20dPct:
        volatility,
      ...(shortTermMode
        ? {
            traderStopRiskPct,
            volumeRatio20d:
              safeNumber(candidate?.historicalContext?.technical?.volumeRatio20d),
            planAgeDays:
              decisionTraderPlanAgeDays(candidate)
          }
        : {}),
      dataQualityScore:
        applicableDataQualityScore,
      riskScore:
        safeNumber(
          candidate?.risk?.score
        )
    }
  };
}

function decisionMinimumMeaningfulPositionPkr(
  newMoneyAmountPkr,
  targetPositions =
    DECISION_CENTER_MIN_TARGET_POSITIONS
) {
  const amount =
    Math.max(
      0,
      safeNumber(
        newMoneyAmountPkr
      ) || 0
    );

  if (amount <= 0) {
    return 0;
  }

  const targetCount =
    Math.max(
      1,
      Math.floor(
        safeNumber(
          targetPositions
        ) ||
        DECISION_CENTER_MIN_TARGET_POSITIONS
      )
    );

  // Production hardening 0.9.6.5: the fixed PKR 1,000 floor is useful for
  // normal portfolios, but it must never create a hidden minimum account size.
  // If the whole budget is smaller than one legacy floor per target position,
  // switch to whole-share sizing and let affordability + risk/portfolio caps
  // determine the allocation. The analyst/evidence gates remain unchanged.
  if (
    amount <
      DECISION_MIN_MEANINGFUL_POSITION_PKR *
      targetCount
  ) {
    return 0;
  }

  return decisionRound(
    Math.min(
      amount,
      Math.max(
        DECISION_MIN_MEANINGFUL_POSITION_PKR,
        Math.min(
          DECISION_MAX_MEANINGFUL_POSITION_FLOOR_PKR,
          amount *
            DECISION_MEANINGFUL_POSITION_BUDGET_PCT
        )
      )
    ),
    2
  );
}

function decisionCenterTargetPositionCount(
  totalCapitalPkr,
  riskPolicy
) {
  const capital =
    Math.max(
      0,
      safeNumber(
        totalCapitalPkr
      ) ||
      0
    );

  // Locked professional portfolio-construction policy:
  // 3 is the minimum diversification TARGET, never a forced allocation.
  // The preferred count grows with capital, while the hard design ceiling is 8.
  // If fewer than 3 stocks pass the analyst/evidence/profile/portfolio gates,
  // NOMAD keeps the remainder in cash and reports a diversification exception.
  let target = 3;

  if (capital >= 25000) {
    target = 4;
  }

  if (capital >= 100000) {
    target = 5;
  }

  if (capital >= 300000) {
    target = 6;
  }

  if (capital >= 750000) {
    target = 7;
  }

  if (capital >= 2000000) {
    target = 8;
  }

  if (
    riskPolicy?.id ===
      'RISK-CONSERVATIVE-0.1'
  ) {
    target += 1;
  }

  if (
    riskPolicy?.id ===
      'RISK-AGGRESSIVE-0.1'
  ) {
    target -= 1;
  }

  return Math.max(
    DECISION_CENTER_MIN_TARGET_POSITIONS,
    Math.min(
      DECISION_CENTER_MAX_TARGET_POSITIONS,
      target
    )
  );
}

function decisionCenterDynamicCaps(
  targetPositions,
  riskPolicy
) {
  const count =
    Math.max(
      DECISION_CENTER_MIN_TARGET_POSITIONS,
      Number(
        targetPositions
      ) ||
      DECISION_CENTER_MIN_TARGET_POSITIONS
    );

  let stockMultiplier = 1.35;
  let minimumStockCap = 0.12;
  let sectorMultiplier = 2.1;
  let minimumSectorCap = 0.25;

  if (
    riskPolicy?.id ===
      'RISK-CONSERVATIVE-0.1'
  ) {
    stockMultiplier = 1.20;
    minimumStockCap = 0.10;
    sectorMultiplier = 1.90;
    minimumSectorCap = 0.22;
  }

  if (
    riskPolicy?.id ===
      'RISK-AGGRESSIVE-0.1'
  ) {
    stockMultiplier = 1.60;
    minimumStockCap = 0.15;
    sectorMultiplier = 2.20;
    minimumSectorCap = 0.35;
  }

  const stockCapPct =
    Math.min(
      safeNumber(
        riskPolicy?.maxStockPct
      ) ||
      1,
      Math.max(
        minimumStockCap,
        stockMultiplier /
        count
      )
    );

  const sectorCapPct =
    Math.min(
      safeNumber(
        riskPolicy?.maxSectorPct
      ) ||
      1,
      Math.max(
        minimumSectorCap,
        stockCapPct *
        sectorMultiplier
      )
    );

  return {
    stockCapPct,
    sectorCapPct
  };
}

function decisionCenterCandidateConviction(
  candidate
) {
  const professional =
    candidate?.canonicalState
      ?.professional ||
    candidate?.professional ||
    {};

  const evidenceScore =
    safeNumber(
      candidate?.canonicalState
        ?.evidence?.score
    ) ??
    safeNumber(
      candidate?.analyst?.evidenceScore
    ) ??
    50;

  const rankingScore =
    safeNumber(
      candidate?.opportunityRankScore
    ) ??
    safeNumber(
      professional?.rankingScore
    ) ??
    50;

  const riskScore =
    safeNumber(
      professional?.riskScore
    ) ??
    safeNumber(
      candidate?.risk?.score
    ) ??
    50;

  if (
    professional?.framework ===
      'SHORT_TERM_TRADER'
  ) {
    const timingScore =
      safeNumber(
        professional?.timingScore
      ) ??
      safeNumber(
        candidate?.entry?.score
      ) ??
      50;

    const liquidityScore =
      safeNumber(
        candidate?.risk?.liquidityScore
      ) ??
      50;

    const rewardRiskScore =
      decisionTraderRewardRiskScore(
        professional?.tradePlan?.rewardRisk ??
        professional?.conditionalTradePlan?.rewardRisk
      );
    const setupQuality =
      decisionTraderSetupQuality(
        professional?.setup
      );

    return decisionRound(
      decisionClamp(
        setupQuality * 0.24 +
        timingScore * 0.24 +
        rankingScore * 0.20 +
        liquidityScore * 0.12 +
        evidenceScore * 0.12 +
        rewardRiskScore * 0.08
      ),
      2
    );
  }

  const financialScore =
    safeNumber(
      professional?.financialScore
    ) ??
    safeNumber(
      candidate?.fundamental?.score
    ) ??
    50;

  const valuationScore =
    safeNumber(
      professional?.valuationScore
    ) ??
    safeNumber(
      candidate?.valuation?.score
    ) ??
    50;

  const timingScore =
    safeNumber(
      professional?.timingScore
    ) ??
    safeNumber(
      candidate?.entry?.score
    ) ??
    50;

  return decisionRound(
    decisionClamp(
      rankingScore * 0.30 +
      financialScore * 0.20 +
      valuationScore * 0.15 +
      riskScore * 0.15 +
      timingScore * 0.10 +
      evidenceScore * 0.10
    ),
    2
  );
}

function decisionCenterDeploymentPlan(
  candidates,
  targetPositions,
  riskPolicy
) {
  const list =
    Array.isArray(candidates)
      ? candidates
      : [];

  if (!list.length) {
    return {
      targetDeploymentPct: 0,
      intentionalCashReservePct: 100,
      averageConvictionScore: 0,
      averageExtendedCoveragePct: 0,
      reason:
        'No profile-suitable actionable opportunities passed the professional allocation gate.'
    };
  }

  const averageConvictionScore =
    list.reduce(
      (sum, candidate) =>
        sum +
        (
          safeNumber(
            candidate.allocationConvictionScore
          ) ||
          decisionCenterCandidateConviction(
            candidate
          )
        ),
      0
    ) /
    list.length;

  const averageExtendedCoveragePct =
    list.reduce(
      (sum, candidate) =>
        sum +
        (
          safeNumber(
            candidate?.canonicalState
              ?.evidence
              ?.extendedCoveragePct
          ) ||
          0
        ),
      0
    ) /
    list.length;

  const confidenceValues =
    list.map(
      candidate =>
        String(
          candidate?.canonicalState
            ?.evidence
            ?.confidence ||
          'LOW'
        )
    );

  const mediumOrBetterRatio =
    confidenceValues.filter(
      value =>
        value === 'HIGH' ||
        value === 'MEDIUM'
    ).length /
    list.length;

  let baseDeploymentPct = 0.86;

  if (
    riskPolicy?.id ===
      'RISK-CONSERVATIVE-0.1'
  ) {
    baseDeploymentPct = 0.76;
  } else if (
    riskPolicy?.id ===
      'RISK-AGGRESSIVE-0.1'
  ) {
    baseDeploymentPct = 0.90;
  }

  const target =
    Math.max(
      DECISION_CENTER_MIN_TARGET_POSITIONS,
      Number(targetPositions) ||
      DECISION_CENTER_MIN_TARGET_POSITIONS
    );

  const breadthRatio =
    Math.min(
      1,
      list.length /
      target
    );

  let breadthPenalty = 0;

  if (list.length === 1) {
    breadthPenalty = 0.24;
  } else if (list.length === 2) {
    breadthPenalty = 0.15;
  } else if (breadthRatio < 1) {
    breadthPenalty =
      (1 - breadthRatio) *
      0.10;
  }

  const evidencePenalty =
    mediumOrBetterRatio >= 0.99
      ? 0
      : mediumOrBetterRatio >= 0.66
        ? 0.025
        : 0.08;

  const extendedEvidencePenalty =
    averageExtendedCoveragePct >= 67
      ? 0
      : averageExtendedCoveragePct >= 25
        ? 0.02
        : 0.04;

  const convictionAdjustment =
    Math.max(
      -0.05,
      Math.min(
        0.05,
        (
          averageConvictionScore -
          70
        ) /
        300
      )
    );

  const minimumDeploymentPct =
    list.length >= 3
      ? 0.62
      : list.length === 2
        ? 0.42
        : 0.28;

  const targetDeploymentPct =
    Math.max(
      minimumDeploymentPct,
      Math.min(
        DECISION_CENTER_MAX_DEPLOYMENT_PCT,
        baseDeploymentPct +
        convictionAdjustment -
        breadthPenalty -
        evidencePenalty -
        extendedEvidencePenalty
      )
    );

  const roundedDeploymentPct =
    decisionRound(
      targetDeploymentPct *
      100,
      2
    );

  const reservePct =
    decisionRound(
      100 -
      roundedDeploymentPct,
      2
    );

  const reasons = [];

  if (list.length < target) {
    reasons.push(
      'Only ' +
      list.length +
      ' suitable actionable idea' +
      (list.length === 1 ? '' : 's') +
      ' passed against a target of ' +
      target +
      '.'
    );
  }

  if (averageExtendedCoveragePct < 67) {
    reasons.push(
      'Extended financial validation is incomplete across the funded opportunity set.'
    );
  }

  if (averageConvictionScore < 72) {
    reasons.push(
      'Average conviction is not high enough to justify maximum deployment.'
    );
  }

  if (!reasons.length) {
    reasons.push(
      'Opportunity breadth, conviction and evidence support a high deployment level while preserving a deliberate liquidity reserve.'
    );
  }

  return {
    targetDeploymentPct:
      roundedDeploymentPct,
    intentionalCashReservePct:
      reservePct,
    averageConvictionScore:
      decisionRound(
        averageConvictionScore,
        2
      ),
    averageExtendedCoveragePct:
      decisionRound(
        averageExtendedCoveragePct,
        2
      ),
    reason:
      reasons.join(' ')
  };
}

function decisionCenterFinancialSectorCandidate(
  candidate
) {
  if (
    candidate?.analystCore
      ?.company
      ?.financialSector ===
        true
  ) {
    return true;
  }

  const sector =
    String(
      candidate?.sector ||
      ''
    ).toLowerCase();

  return (
    sector.includes('commercial bank') ||
    sector.includes('bank') ||
    sector.includes('insurance') ||
    sector.includes('leasing') ||
    sector.includes('investment bank') ||
    sector.includes('securities') ||
    sector.includes('modaraba')
  );
}

function shortTermProfileExecutionDecision(
  candidate,
  riskPolicy
) {
  if (
    String(
      candidate?.horizon ||
      'long_term'
    ) !== 'short_term'
  ) {
    return null;
  }

  const policy =
    decisionTraderProfilePolicy(
      riskPolicy
    );

  const professional =
    candidate?.canonicalState
      ?.professional ||
    candidate?.professional ||
    {};

  const evidence =
    candidate?.canonicalState
      ?.evidence ||
    {};

  const suitability =
    candidate?.profileSuitability ||
    decisionProfileSuitability(
      candidate,
      riskPolicy
    );

  const timingScore =
    safeNumber(
      professional.timingScore
    ) || 0;

  const evidenceScore =
    safeNumber(
      evidence.technicalCoveragePct ??
      evidence.score
    ) || 0;

  const riskScore =
    safeNumber(
      professional.riskScore ??
      candidate?.risk?.score
    ) || 0;

  const currentPlan =
    professional.tradePlan ||
    null;

  const conditionalPlan =
    professional.conditionalTradePlan ||
    null;

  const currentRewardRisk =
    safeNumber(
      currentPlan?.rewardRisk
    );

  const conditionalRewardRisk =
    safeNumber(
      conditionalPlan?.rewardRisk
    );

  const currentStopRiskPct =
    safeNumber(
      currentPlan?.riskPct
    );

  const currentPlanPriceState =
    decisionTraderPlanPriceState(
      candidate?.price,
      currentPlan
    );

  const currentPlanOpen =
    currentPlanPriceState.state === 'OPEN' ||
    currentPlanPriceState.state === 'UNKNOWN';

  const conditionalStopRiskPct =
    safeNumber(
      conditionalPlan?.riskPct
    );

  const setup =
    String(
      professional.setup ||
      'NO_CLEAR_SETUP'
    );
  const setupFamily =
    decisionTraderSetupFamily(setup);

  if (setupFamily === 'BEARISH') {
    return {
      policyId: policy.id,
      state: 'INVALID_SETUP',
      action: 'PASS',
      marketAction: 'AVOID',
      actionableNow: false,
      reservationEligible: false,
      sizeMultiplier: 0,
      reason: 'The short-term structure is bearish or broken. Risk preference cannot turn a failed setup into a long entry.'
    };
  }

  if (
    suitability?.state !==
      'SUITABLE'
  ) {
    return {
      policyId: policy.id,
      state: 'PROFILE_BLOCKED',
      action: 'PASS',
      marketAction: 'WATCH',
      actionableNow: false,
      reservationEligible: false,
      sizeMultiplier: 0,
      reason:
        (suitability?.issues || [])
          .join(' ') ||
        'The setup does not fit the selected trader profile.'
    };
  }

  const profileGatePass =
    timingScore >=
      policy.minTimingScore &&
    evidenceScore >=
      policy.minTechnicalEvidenceScore &&
    riskScore >=
      policy.minRiskScore;

  const currentTrigger =
    currentPlan?.complete === true
      ? shortTermTriggerSnapshot(
          setup,
          candidate?.price,
          currentPlan?.entryLow ?? currentPlan?.entryReference,
          currentPlan?.entryHigh ?? currentPlan?.entryReference,
          currentPlan?.stop,
          riskPolicy
        )
      : null;

  const currentPlanPass =
    currentPlan?.complete === true &&
    currentRewardRisk !== null &&
    currentRewardRisk >=
      policy.minRewardRisk &&
    currentPlanOpen &&
    (
      currentStopRiskPct === null ||
      currentStopRiskPct <=
        policy.maxStopRiskPct
    ) &&
    (
      currentTrigger === null ||
      currentTrigger.status === 'TRIGGERED'
    );

  if (
    professional.marketAction ===
      'BUY' &&
    profileGatePass &&
    currentPlanPass
  ) {
    return {
      policyId: policy.id,
      state: 'ENTER_NOW',
      action: 'BUY',
      marketAction: 'BUY',
      actionableNow: true,
      reservationEligible: false,
      triggerStatus: currentTrigger?.status || 'TRIGGERED',
      sizeMultiplier:
        policy.activeSizeMultiplier,
      reason:
        'The current setup, timing, evidence, stop distance and reward-to-risk pass the selected trader profile.'
    };
  }

  const conditionalPass =
    conditionalPlan?.complete === true &&
    conditionalRewardRisk !== null &&
    conditionalRewardRisk >=
      policy.minRewardRisk &&
    evidenceScore >=
      policy.minTechnicalEvidenceScore &&
    riskScore >=
      policy.minRiskScore &&
    (
      conditionalStopRiskPct === null ||
      conditionalStopRiskPct <=
        policy.maxStopRiskPct
    );

  // Aggressive can take a deliberately smaller early entry only when there is
  // already a complete current trade plan. It never converts an incomplete
  // setup into a BUY merely because the profile is aggressive.
  const earlyEntryPass =
    policy.allowEarlyEntry === true &&
    currentPlan?.complete === true &&
    currentRewardRisk !== null &&
    currentRewardRisk >= 1.25 &&
    currentPlanOpen &&
    timingScore >=
      policy.minTimingScore &&
    evidenceScore >=
      policy.minTechnicalEvidenceScore &&
    riskScore >=
      policy.minRiskScore &&
    (
      currentStopRiskPct === null ||
      currentStopRiskPct <=
        policy.maxStopRiskPct
    ) &&
    [
      'CONFIRMED_BREAKOUT',
      'UNCONFIRMED_BREAKOUT',
      'TREND_PULLBACK',
      'UPTREND_CONTINUATION'
    ].includes(setup) &&
    currentTrigger !== null &&
    [
      'NEAR_TRIGGER',
      'TRIGGERED'
    ].includes(currentTrigger.status);

  if (earlyEntryPass) {
    return {
      policyId: policy.id,
      state: 'EARLY_ENTRY',
      action: 'BUY_SMALL',
      marketAction: 'BUY',
      actionableNow: true,
      reservationEligible:
        conditionalPass,
      triggerStatus: currentTrigger?.status || 'EARLY_ENTRY',
      sizeMultiplier: 0.55,
      reason:
        'Aggressive profile permits a smaller early entry because a complete current trade plan exists and stop-based risk remains controlled. Full sizing still waits for stronger confirmation.'
    };
  }

  if (conditionalPass) {
    return {
      policyId: policy.id,
      state: 'WAIT_FOR_TRIGGER',
      action: 'PLAN',
      marketAction: 'WATCH',
      actionableNow: false,
      reservationEligible: true,
      triggerStatus: 'WAITING',
      sizeMultiplier: 0,
      reason:
        'The stock is not a buy at the current reference price, but the selected profile has a valid conditional entry, stop and target plan.'
    };
  }

  return {
    policyId: policy.id,
    state: 'WATCH',
    action: 'WAIT',
    marketAction: 'WATCH',
    actionableNow: false,
    reservationEligible: false,
    sizeMultiplier: 0,
    reason:
      'The setup remains worth monitoring, but it does not yet pass this trader profile\'s execution thresholds.'
  };
}

function shortTermTriggerConditionText(setup) {
  const normalized = String(setup || '').toUpperCase();

  if (normalized.includes('BREAKOUT')) {
    return 'Price must enter or clear the entry zone and hold the breakout while the setup remains valid.';
  }

  if (normalized.includes('PULLBACK')) {
    return 'Price must pull back into the entry zone while the broader short-term trend remains intact.';
  }

  if (normalized.includes('CONTINUATION')) {
    return 'Price must reclaim or hold the entry zone with the continuation structure still intact.';
  }

  return 'Price must enter the defined entry zone while the setup, stop and reward-to-risk remain valid.';
}

function shortTermTriggerSnapshot(
  setup,
  currentPrice,
  entryLow,
  entryHigh,
  stop,
  riskPolicy = null
) {
  const current = safeNumber(currentPrice);
  const low = safeNumber(entryLow);
  const high = safeNumber(entryHigh);
  const invalidation = safeNumber(stop);
  const family = decisionTraderSetupFamily(setup);
  const policy = riskPolicy
    ? decisionTraderProfilePolicy(riskPolicy)
    : DECISION_TRADER_PROFILE_POLICIES.balanced;

  if (current === null || low === null || high === null) {
    return {
      status: 'WAITING',
      label: 'Waiting for live price',
      distancePct: null,
      direction: 'unknown',
      setupFamily: family
    };
  }

  if (invalidation !== null && current <= invalidation) {
    return {
      status: 'INVALIDATED',
      label: 'Invalidated — stop level broken',
      distancePct: 0,
      direction: 'invalid',
      setupFamily: family
    };
  }

  if (current >= low && current <= high) {
    return {
      status: 'TRIGGERED',
      label: 'Entry zone active',
      distancePct: 0,
      direction: 'inside',
      setupFamily: family
    };
  }

  if (family === 'PULLBACK' || family === 'SUPPORT_BOUNCE') {
    if (current > high) {
      const distancePct = ((current - high) / Math.max(high, 0.0001)) * 100;
      return {
        status: distancePct <= policy.nearTriggerTolerancePct ? 'NEAR_TRIGGER' : 'WAITING',
        label: distancePct <= policy.nearTriggerTolerancePct ? 'Near pullback entry' : 'Waiting for pullback',
        distancePct: decisionRound(distancePct, 2),
        direction: 'above',
        setupFamily: family
      };
    }

    const belowPct = ((low - current) / Math.max(low, 0.0001)) * 100;
    return {
      status: 'BELOW_ENTRY_ZONE',
      label: 'Below planned entry — reassess setup',
      distancePct: decisionRound(belowPct, 2),
      direction: 'below',
      setupFamily: family
    };
  }

  // Breakout/continuation logic: price normally approaches the entry zone from below.
  if (current < low) {
    const distancePct = ((low - current) / Math.max(current, 0.0001)) * 100;
    return {
      status: distancePct <= policy.nearTriggerTolerancePct ? 'NEAR_TRIGGER' : 'WAITING',
      label: distancePct <= policy.nearTriggerTolerancePct ? 'Near trigger' : 'Waiting below trigger',
      distancePct: decisionRound(distancePct, 2),
      direction: 'below',
      setupFamily: family
    };
  }

  const abovePct = ((current - high) / Math.max(high, 0.0001)) * 100;
  return {
    status: abovePct <= policy.maxChasePct ? 'TRIGGERED' : 'ABOVE_ENTRY_ZONE',
    label: abovePct <= policy.maxChasePct ? 'Entry still valid' : 'Above entry zone — do not chase',
    distancePct: decisionRound(abovePct, 2),
    direction: 'above',
    setupFamily: family
  };
}

function buildShortTermTriggerPlan(
  opportunityBoard,
  amount,
  riskPolicy,
  alreadyInvestedPkr = 0
) {
  const policy =
    decisionTraderProfilePolicy(
      riskPolicy
    );

  const riskBudgetPct =
    decisionTraderRiskBudgetPct(
      riskPolicy
    );

  const technicalReadyCandidates =
    [
      ...(opportunityBoard?.priority1 || []),
      ...(opportunityBoard?.priority2 || [])
    ]
      .filter(
        item =>
          item?.professional
            ?.conditionalTradePlan
            ?.complete === true
      );

  const allCandidates =
    technicalReadyCandidates
      .filter(
        item =>
          item?.shortTermExecution
            ?.reservationEligible === true
      )
      .sort(
        (a, b) =>
          (safeNumber(b?.professional?.rankingScore) || 0) -
          (safeNumber(a?.professional?.rankingScore) || 0)
      );

  const plans = [];
  const unfunded = [];

  // Capital accounting is deliberately performed in paisa. This prevents
  // floating-point rounding from ever creating a false Trader integrity block.
  const totalCapitalPaisa =
    Math.max(
      0,
      Math.round(
        (Number(amount) || 0) * 100
      )
    );

  const investedNowPaisa =
    Math.max(
      0,
      Math.min(
        totalCapitalPaisa,
        Math.round(
          (Number(alreadyInvestedPkr) || 0) * 100
        )
      )
    );

  const availableForTriggersPaisa =
    Math.max(
      0,
      totalCapitalPaisa - investedNowPaisa
    );

  const totalCapital =
    totalCapitalPaisa / 100;

  const slotDivisor =
    Math.max(
      1,
      Math.min(
        policy.maxConditionalPlans,
        allCandidates.length || 1
      )
    );

  let reservedPaisa = 0;

  for (const item of allCandidates) {
    const plan =
      item.professional
        .conditionalTradePlan;

    const entryLow =
      safeNumber(plan.entryLow);
    const entryHigh =
      safeNumber(plan.entryHigh);
    const stop =
      safeNumber(plan.stop);
    const currentPrice =
      safeNumber(item.price);

    if (
      entryLow === null ||
      entryHigh === null ||
      stop === null
    ) {
      unfunded.push({
        symbol: item.symbol,
        state: 'READY_UNFUNDED',
        reasonCode: 'INVALID_PLAN_LEVELS',
        reason: 'The conditional setup is visible, but its entry or stop levels are incomplete.'
      });
      continue;
    }

    const triggerSnapshot =
      shortTermTriggerSnapshot(
        item.professional.setup,
        currentPrice,
        entryLow,
        entryHigh,
        stop,
        riskPolicy
      );

    if (
      [
        'INVALIDATED',
        'BELOW_ENTRY_ZONE',
        'ABOVE_ENTRY_ZONE'
      ].includes(triggerSnapshot.status)
    ) {
      unfunded.push({
        symbol: item.symbol,
        state: 'READY_UNFUNDED',
        reasonCode: triggerSnapshot.status,
        reason: triggerSnapshot.label
      });
      continue;
    }

    if (
      plans.length >=
        policy.maxConditionalPlans
    ) {
      unfunded.push({
        symbol: item.symbol,
        state: 'READY_UNFUNDED',
        reasonCode: 'PROFILE_SLOT_LIMIT',
        reason:
          'Valid setup, but the selected profile funds at most ' +
          policy.maxConditionalPlans +
          ' simultaneous trigger plan' +
          (policy.maxConditionalPlans === 1 ? '' : 's') +
          '. Higher-ranked setups received the available slots.'
      });
      continue;
    }

    const entry =
      (entryLow + entryHigh) / 2;
    const entryPaisa =
      Math.max(
        1,
        Math.round(entry * 100)
      );
    const riskPerShare =
      Math.max(
        0,
        entry - stop
      );

    if (
      entry <= 0 ||
      riskPerShare <= 0
    ) {
      unfunded.push({
        symbol: item.symbol,
        state: 'READY_UNFUNDED',
        reasonCode: 'INVALID_RISK_GEOMETRY',
        reason: 'The setup does not have a positive stop-defined risk per share.'
      });
      continue;
    }

    const maxRiskPkr =
      totalCapital *
      riskBudgetPct;
    const sharesByRisk =
      Math.floor(
        maxRiskPkr /
        riskPerShare
      );

    const maxPrincipalBySlotPaisa =
      Math.floor(
        availableForTriggersPaisa /
        slotDivisor
      );

    const sharesBySlot =
      Math.floor(
        maxPrincipalBySlotPaisa /
        entryPaisa
      );

    const shares =
      Math.max(
        0,
        Math.min(
          sharesByRisk,
          sharesBySlot
        )
      );

    if (shares < 1) {
      unfunded.push({
        symbol: item.symbol,
        state: 'READY_UNFUNDED',
        reasonCode: 'RISK_OR_SLOT_TOO_SMALL',
        reason: 'The setup is technically valid, but one whole share cannot fit the profile risk budget and trigger-plan sizing limit.'
      });
      continue;
    }

    const remainingTriggerCapitalPaisa =
      Math.max(
        0,
        availableForTriggersPaisa - reservedPaisa
      );

    const affordableShares =
      Math.floor(
        remainingTriggerCapitalPaisa /
        entryPaisa
      );

    const fundedShares =
      Math.max(
        0,
        Math.min(
          shares,
          affordableShares
        )
      );

    if (fundedShares < 1) {
      unfunded.push({
        symbol: item.symbol,
        state: 'READY_UNFUNDED',
        reasonCode: 'NO_TRIGGER_CAPITAL_LEFT',
        reason: 'The setup remains valid, but higher-ranked immediate and trigger plans already use the available capital.'
      });
      continue;
    }

    const principalPaisa =
      fundedShares *
      entryPaisa;

    reservedPaisa +=
      principalPaisa;

    plans.push({
      symbol: item.symbol,
      companyName:
        item.companyName,
      state:
        triggerSnapshot.status,
      triggerStatus:
        triggerSnapshot.status,
      triggerLabel:
        triggerSnapshot.label,
      triggerDirection:
        triggerSnapshot.direction,
      distancePct:
        triggerSnapshot.distancePct,
      triggerCondition:
        shortTermTriggerConditionText(
          item.professional.setup
        ),
      currentPrice:
        currentPrice !== null
          ? decisionRound(currentPrice, 2)
          : null,
      setup:
        item.professional.setup ||
        null,
      shares: fundedShares,
      entryLow:
        decisionRound(entryLow, 2),
      entryHigh:
        decisionRound(entryHigh, 2),
      entryReference:
        decisionRound(
          entryPaisa / 100,
          2
        ),
      stop:
        decisionRound(stop, 2),
      target1:
        safeNumber(plan.target1) !== null
          ? decisionRound(
              safeNumber(plan.target1),
              2
            )
          : null,
      rewardRisk:
        safeNumber(plan.rewardRisk) !== null
          ? decisionRound(
              safeNumber(plan.rewardRisk),
              2
            )
          : null,
      plannedPrincipalPkr:
        principalPaisa / 100,
      riskBudgetPct:
        decisionRound(
          riskBudgetPct * 100,
          2
        ),
      profilePolicyId:
        policy.id
    });
  }

  const plannedCapitalPaisa =
    Math.min(
      availableForTriggersPaisa,
      reservedPaisa
    );

  const uncommittedCapitalPaisa =
    Math.max(
      0,
      totalCapitalPaisa -
      investedNowPaisa -
      plannedCapitalPaisa
    );

  const reconciliationDeltaPaisa =
    totalCapitalPaisa -
    investedNowPaisa -
    plannedCapitalPaisa -
    uncommittedCapitalPaisa;

  return {
    policyId: policy.id,
    // readyCount is kept for compatibility and now means all technically
    // complete conditional setups visible on the board.
    readyCount:
      technicalReadyCandidates.length,
    technicalReadyCount:
      technicalReadyCandidates.length,
    profileReadyCount:
      allCandidates.length,
    count: plans.length,
    fundedCount: plans.length,
    plannedCapitalPkr:
      plannedCapitalPaisa / 100,
    uncommittedCapitalPkr:
      uncommittedCapitalPaisa / 100,
    buyNowCapitalPkr:
      investedNowPaisa / 100,
    availableForTriggersPkr:
      availableForTriggersPaisa / 100,
    reconciliation: {
      totalCapitalPkr:
        totalCapitalPaisa / 100,
      buyNowPkr:
        investedNowPaisa / 100,
      reservedPkr:
        plannedCapitalPaisa / 100,
      freeCashPkr:
        uncommittedCapitalPaisa / 100,
      deltaPkr:
        reconciliationDeltaPaisa / 100,
      ok:
        reconciliationDeltaPaisa === 0
    },
    plans,
    unfunded
  };
}

function shortTermDecisionStabilityAudit(
  amount,
  allocation,
  triggerPlan,
  riskPolicy
) {
  const issues = [];
  const totalPaisa =
    Math.max(
      0,
      Math.round(
        (safeNumber(amount) || 0) * 100
      )
    );
  const buyNowPaisa =
    Math.max(
      0,
      Math.round(
        (safeNumber(allocation?.amountInvestedPkr) || 0) * 100
      )
    );
  const reservedPaisa =
    Math.max(
      0,
      Math.round(
        (safeNumber(triggerPlan?.plannedCapitalPkr) || 0) * 100
      )
    );
  const freeCashPaisa =
    Math.max(
      0,
      Math.round(
        (safeNumber(triggerPlan?.uncommittedCapitalPkr) || 0) * 100
      )
    );
  const deltaPaisa =
    totalPaisa -
    buyNowPaisa -
    reservedPaisa -
    freeCashPaisa;
  const policy =
    decisionTraderProfilePolicy(
      riskPolicy
    );
  const plans =
    Array.isArray(triggerPlan?.plans)
      ? triggerPlan.plans
      : [];
  const symbols =
    new Set();

  if (deltaPaisa !== 0) {
    issues.push(
      'Capital reconciliation failed by PKR ' +
      formatNumber(
        deltaPaisa / 100,
        2
      ) +
      '.'
    );
  }

  if (
    plans.length >
      policy.maxConditionalPlans
  ) {
    issues.push(
      'Funded trigger count exceeds the selected profile limit.'
    );
  }

  let principalSumPaisa = 0;

  for (const plan of plans) {
    if (!plan?.symbol) {
      issues.push(
        'A funded trigger plan is missing its symbol.'
      );
      continue;
    }

    if (symbols.has(plan.symbol)) {
      issues.push(
        'Duplicate funded trigger plan for ' +
        plan.symbol +
        '.'
      );
    }
    symbols.add(plan.symbol);

    const shares =
      safeNumber(plan.shares);
    const entryLow =
      safeNumber(plan.entryLow);
    const entryHigh =
      safeNumber(plan.entryHigh);
    const entryReference =
      safeNumber(plan.entryReference) ??
      (
        entryLow !== null &&
        entryHigh !== null
          ? (entryLow + entryHigh) / 2
          : null
      );
    const stop =
      safeNumber(plan.stop);
    const target1 =
      safeNumber(plan.target1);
    const rr =
      safeNumber(plan.rewardRisk);
    const principalPaisa =
      Math.max(
        0,
        Math.round(
          (safeNumber(plan.plannedPrincipalPkr) || 0) * 100
        )
      );

    principalSumPaisa +=
      principalPaisa;

    if (
      shares === null ||
      shares < 1 ||
      !Number.isInteger(shares)
    ) {
      issues.push(
        plan.symbol +
        ' funded trigger has no valid whole-share quantity.'
      );
    }

    if (
      entryLow === null ||
      entryHigh === null ||
      entryReference === null ||
      stop === null ||
      target1 === null ||
      !(entryLow <= entryHigh) ||
      !(stop < entryReference) ||
      !(target1 > entryReference)
    ) {
      issues.push(
        plan.symbol +
        ' funded trigger has invalid entry/stop/target geometry.'
      );
    }

    if (
      rr === null ||
      rr + 0.01 <
        policy.minRewardRisk
    ) {
      issues.push(
        plan.symbol +
        ' funded trigger is below the selected profile reward-to-risk floor.'
      );
    }

    if (
      [
        'INVALIDATED',
        'BELOW_ENTRY_ZONE',
        'ABOVE_ENTRY_ZONE'
      ].includes(
        String(plan.triggerStatus || '')
      )
    ) {
      issues.push(
        plan.symbol +
        ' received capital despite an invalid trigger state.'
      );
    }
  }

  if (
    principalSumPaisa !==
      reservedPaisa
  ) {
    issues.push(
      'Funded trigger principals do not match reserved capital.'
    );
  }

  const immediateAllocations =
    Array.isArray(allocation?.allocations)
      ? allocation.allocations
      : [];

  for (const item of immediateAllocations) {
    if (
      !decisionExecutionAllowsAllocation(
        item?.executionGuidance
      )
    ) {
      issues.push(
        String(item?.symbol || 'Unknown') +
        ' received buy-now capital despite a non-actionable execution state.'
      );
    }
  }

  const allocationPrincipalPaisa =
    immediateAllocations
      .reduce(
        (sum, item) =>
          sum +
          Math.max(
            0,
            Math.round(
              (safeNumber(item?.principalPkr) || 0) * 100
            )
          ),
        0
      );

  // A one-paisa-per-position display/rounding difference is harmless; anything
  // larger indicates a real allocator inconsistency.
  if (
    Math.abs(
      allocationPrincipalPaisa -
      buyNowPaisa
    ) > Math.max(2, plans.length)
  ) {
    issues.push(
      'Immediate allocation principals do not match buy-now capital.'
    );
  }

  return {
    status:
      issues.length
        ? 'BLOCKED'
        : 'PASS',
    ok:
      issues.length === 0,
    issues,
    capital: {
      requestedPkr:
        totalPaisa / 100,
      buyNowPkr:
        buyNowPaisa / 100,
      reservedPkr:
        reservedPaisa / 100,
      freeCashPkr:
        freeCashPaisa / 100,
      deltaPkr:
        deltaPaisa / 100
    },
    fundedTriggerCount:
      plans.length,
    profileTriggerLimit:
      policy.maxConditionalPlans
  };
}

function decisionCenterAllocationCandidatePool(
  opportunityBoard,
  riskPolicy,
  targetPositions
) {
  const all =
    Array.isArray(
      opportunityBoard?.all
    )
      ? opportunityBoard.all
      : [];

  const eligible =
    all
      .map(
        item => ({
          item,
          profileSuitability:
            item?.profileSuitability ||
            decisionProfileSuitability(
              item,
              riskPolicy
            ),
          executionGuidance:
            item?.executionGuidance ||
            decisionExecutionGuidance(
              item,
              riskPolicy
            )
        })
      )
      .filter(
        wrapped => {
          const shortTermMode =
            String(
              wrapped.item?.horizon ||
              'long_term'
            ) === 'short_term';

          const execution =
            shortTermMode
              ? (
                  wrapped.item
                    ?.shortTermExecution ||
                  shortTermProfileExecutionDecision(
                    wrapped.item,
                    riskPolicy
                  )
                )
              : null;

          return (
            wrapped.profileSuitability
              ?.state === 'SUITABLE' &&
            decisionExecutionAllowsAllocation(
              wrapped.executionGuidance
            ) &&
            (
              shortTermMode
                ? execution
                    ?.actionableNow === true
                : (
                    wrapped.item?.canonicalState
                      ?.allocationPermission
                      ?.allowed === true &&
                    (
                      wrapped.item.canonicalState
                        ?.marketAction === 'BUY' ||
                      wrapped.item.canonicalState
                        ?.marketAction === 'ACCUMULATE'
                    )
                  )
            )
          );
        }
      )
      .map(
        wrapped => {
          const item =
            wrapped.item;

          const profileSuitability =
            wrapped.profileSuitability;
          const shortTermMode =
            String(
              item?.horizon ||
              'long_term'
            ) === 'short_term';

          const shortTermExecution =
            shortTermMode
              ? (
                  item.shortTermExecution ||
                  shortTermProfileExecutionDecision(
                    item,
                    riskPolicy
                  )
                )
              : null;

          const action =
            shortTermMode &&
            shortTermExecution
              ?.actionableNow === true
              ? 'BUY'
              : item.canonicalState
                  .marketAction;

          const tier =
            item.canonicalState
              .opportunityTier;

          const confidence =
            item.canonicalState
              .evidence
              .confidence;

          const actionMultiplier =
            action === 'BUY'
              ? 1
              : 0.76;

          const tierMultiplier =
            tier === 'PRIORITY_1'
              ? 1
              : 0.72;

          const confidenceMultiplier =
            confidence === 'HIGH'
              ? 1
              : confidence === 'MEDIUM'
                ? 0.86
                : 0.68;

          const riskScore =
            safeNumber(
              item.risk?.score
            ) ||
            50;

          const entryScore =
            safeNumber(
              item.entry?.score
            ) ||
            50;

          const riskMultiplier =
            0.82 +
            decisionClamp(
              riskScore
            ) /
            100 *
            0.24;

          const entryMultiplier =
            0.86 +
            decisionClamp(
              entryScore
            ) /
            100 *
            0.18;

          const allocationConvictionScore =
            decisionCenterCandidateConviction(
              item
            );

          const allocationStrengthMultiplier =
            actionMultiplier *
            tierMultiplier *
            confidenceMultiplier *
            riskMultiplier *
            entryMultiplier;

          let allocationCapMultiplier =
            action === 'BUY'
              ? 1
              : 0.84;

          if (
            shortTermMode &&
            shortTermExecution
          ) {
            allocationCapMultiplier *=
              Math.max(
                0.35,
                safeNumber(
                  shortTermExecution.sizeMultiplier
                ) ||
                1
              );
          }

          if (
            tier === 'PRIORITY_2'
          ) {
            allocationCapMultiplier *=
              0.72;
          }

          if (
            confidence === 'LOW'
          ) {
            allocationCapMultiplier *=
              0.75;
          }

          return {
            ...item,
            profileSuitability,
            shortTermExecution,
            executionGuidance:
              wrapped.executionGuidance,
            allocationAction:
              action,
            allocationTier:
              tier,
            allocationConvictionScore,
            allocationStrengthMultiplier,
            allocationCapMultiplier
          };
        }
      )
      .sort(
        (
          a,
          b
        ) => {
          if (
            a.allocationTier !==
            b.allocationTier
          ) {
            return a.allocationTier ===
              'PRIORITY_1'
                ? -1
                : 1;
          }

          return (
            b.opportunityRankScore -
            a.opportunityRankScore
          );
        }
      );

  // Keep a small ranked reserve beyond the preferred funded count so the
  // allocator can backfill when a higher-ranked name cannot fit because of
  // whole-share, stock-cap, sector-cap, or existing-portfolio constraints.
  const traderPool =
    eligible.some(
      item => item?.canonicalState?.professional?.framework === 'SHORT_TERM_TRADER'
    );

  const reserveLimit =
    traderPool
      ? Math.min(
          eligible.length,
          Math.max(
            1,
            decisionTraderProfilePolicy(riskPolicy).maxOpenPositions + 2
          )
        )
      : Math.min(
          eligible.length,
          Math.max(
            DECISION_CENTER_MIN_TARGET_POSITIONS,
            Math.min(
              12,
              Number(targetPositions || 0) + 4
            )
          )
        );

  return eligible.slice(
    0,
    reserveLimit
  );
}

function decisionTraderAllocationCaps(riskPolicy) {
  const policy = decisionTraderProfilePolicy(riskPolicy);
  return {
    maxOpenPositions: policy.maxOpenPositions,
    stockCapPct: policy.maxPositionValuePct,
    sectorCapPct: policy.maxSectorValuePct
  };
}

function decisionTraderDeploymentPlan(candidates, riskPolicy) {
  const list = Array.isArray(candidates) ? candidates : [];
  const policy = decisionTraderProfilePolicy(riskPolicy);

  if (!list.length) {
    return {
      targetDeploymentPct: 0,
      intentionalCashReservePct: 100,
      averageConvictionScore: 0,
      averageExtendedCoveragePct: 0,
      reason: 'No current short-term entry passes the selected profile. Capital remains available for valid triggers.'
    };
  }

  const averageConvictionScore = list.reduce(
    (sum, item) => sum + (safeNumber(item.allocationConvictionScore) || decisionCenterCandidateConviction(item)),
    0
  ) / list.length;

  // Short-term cash is not a diversification failure. Stop-based risk budgets
  // and the maximum number of simultaneous positions determine deployment.
  const breadth = Math.min(1, list.length / Math.max(1, policy.maxOpenPositions));
  let base = riskPolicy?.id === 'RISK-CONSERVATIVE-0.1'
    ? 0.58
    : riskPolicy?.id === 'RISK-AGGRESSIVE-0.1'
      ? 0.88
      : 0.74;
  base += Math.max(-0.06, Math.min(0.06, (averageConvictionScore - 70) / 250));
  base *= 0.78 + breadth * 0.22;

  const pct = decisionRound(Math.max(20, Math.min(92, base * 100)), 2);
  return {
    targetDeploymentPct: pct,
    intentionalCashReservePct: decisionRound(100 - pct, 2),
    averageConvictionScore: decisionRound(averageConvictionScore, 2),
    averageExtendedCoveragePct: 100,
    reason: 'Trader deployment is governed by valid entries, stop-based risk budgets and simultaneous-position limits rather than long-term diversification targets.'
  };
}

function allocateDecisionCenterOpportunities(
  opportunityBoard,
  amount,
  riskPolicy,
  portfolioContext = null,
  options = {}
) {
  const sectorConstraint =
    String(
      options?.sectorConstraint ||
      ''
    ).trim() ||
    null;
  const budgetPaisa =
    Math.max(
      0,
      Math.round(
        Number(amount) *
        100
      )
    );

  const existingPortfolioValuePaisa =
    Math.max(
      0,
      Math.round(
        (
          safeNumber(
            portfolioContext
              ?.currentValuePkr
          ) ||
          0
        ) *
        100
      )
    );

  const postFundingCapitalBasePaisa =
    existingPortfolioValuePaisa +
    budgetPaisa;

  const traderMode =
    (opportunityBoard?.all || []).some(
      item => item?.canonicalState?.professional?.framework === 'SHORT_TERM_TRADER'
    );

  const traderCaps =
    traderMode
      ? decisionTraderAllocationCaps(riskPolicy)
      : null;

  const targetPositionCount =
    traderMode
      ? traderCaps.maxOpenPositions
      : decisionCenterTargetPositionCount(
          postFundingCapitalBasePaisa /
          100,
          riskPolicy
        );

  const existingSymbolValues =
    portfolioContext?.symbolValues ||
    {};

  const existingSectorValues =
    portfolioContext?.sectorValues ||
    {};

  let candidates =
    decisionCenterAllocationCandidatePool(
      opportunityBoard,
      riskPolicy,
      targetPositionCount
    );

  // Build 0.9.3.6: rank the next rupee, not just the stock in isolation.
  // Investment merit stays dominant. Portfolio fit adjusts sizing and ordering,
  // but diversification must never force a materially weaker name ahead of a
  // substantially stronger actionable holding.
  candidates = candidates
    .map(candidate => {
      const shortTermCandidate =
        candidate?.canonicalState?.professional?.framework === 'SHORT_TERM_TRADER';

      const meritScore =
        decisionClamp(
          safeNumber(
            candidate.allocationConvictionScore
          ) ||
          decisionCenterCandidateConviction(
            candidate
          )
        );

      const existingStockValue =
        safeNumber(
          existingSymbolValues[
            candidate.symbol
          ]
        ) ||
        0;

      const existingSectorValue =
        safeNumber(
          existingSectorValues[
            candidate.sector
          ]
        ) ||
        0;

      const stockWeight =
        existingPortfolioValuePaisa > 0
          ? existingStockValue /
            (existingPortfolioValuePaisa / 100)
          : 0;

      const sectorWeight =
        existingPortfolioValuePaisa > 0
          ? existingSectorValue /
            (existingPortfolioValuePaisa / 100)
          : 0;

      const hardStockCap =
        Math.max(
          0.01,
          safeNumber(
            riskPolicy?.maxStockPct
          ) ||
          0.45
        );

      const hardSectorCap =
        sectorConstraint
          ? 1
          : Math.max(
              0.01,
              safeNumber(
                riskPolicy?.maxSectorPct
              ) ||
              0.60
            );

      let portfolioFitScore = 100;

      if (existingStockValue > 0) {
        portfolioFitScore -=
          Math.min(
            42,
            stockWeight *
            100 *
            1.15
          );
      }

      if (existingSectorValue > 0) {
        portfolioFitScore -=
          Math.min(
            24,
            sectorWeight *
            100 *
            0.45
          );
      }

      if (
        stockWeight >=
          hardStockCap
      ) {
        portfolioFitScore -= 25;
      }

      if (
        !sectorConstraint &&
        sectorWeight >=
          hardSectorCap
      ) {
        portfolioFitScore -= 18;
      }

      portfolioFitScore =
        decisionClamp(
          portfolioFitScore
        );

      const marginalAllocationScore =
        shortTermCandidate
          ? meritScore * 0.94 + portfolioFitScore * 0.06
          : meritScore * 0.82 + portfolioFitScore * 0.18;

      const concentrationScale =
        shortTermCandidate
          ? 1
          : Math.max(
              existingStockValue > 0
                ? 0.30
                : 0.70,
              Math.min(
                1,
                1 -
                  stockWeight *
                  0.90 -
                  (
                    sectorConstraint
                      ? 0
                      : sectorWeight *
                        0.35
                  )
              )
            );

      return {
        ...candidate,
        marginalInvestmentMeritScore:
          decisionRound(
            meritScore,
            2
          ),
        portfolioFitScore:
          decisionRound(
            portfolioFitScore,
            2
          ),
        marginalAllocationScore:
          decisionRound(
            marginalAllocationScore,
            2
          ),
        concentrationScale
      };
    })
    .sort((a, b) => {
      if (
        a.allocationTier !==
        b.allocationTier
      ) {
        return a.allocationTier ===
          'PRIORITY_1'
            ? -1
            : 1;
      }

      return (
        b.marginalAllocationScore -
        a.marginalAllocationScore
      );
    });

  // Build 0.9.3.5: concentration caps are derived from the portfolio target,
  // not from the number of currently actionable candidates. Relaxing the cap
  // when only a few names pass research caused NOMAD to average further into
  // already-large holdings instead of preserving diversification and cash.
  // A thin opportunity set must therefore reduce deployment, not widen caps.
  const sizingPositionCount =
    traderMode
      ? targetPositionCount
      : Math.max(
          DECISION_CENTER_MIN_TARGET_POSITIONS,
          Math.min(
            DECISION_CENTER_MAX_TARGET_POSITIONS,
            Math.max(
              targetPositionCount,
              Number(
                portfolioContext?.holdingCount ||
                0
              )
            )
          )
        );

  const dynamicCaps =
    traderMode
      ? {
          stockCapPct: traderCaps.stockCapPct,
          sectorCapPct: traderCaps.sectorCapPct
        }
      : decisionCenterDynamicCaps(
          sizingPositionCount,
          riskPolicy
        );

  const effectiveSectorCapPct =
    sectorConstraint
      ? 1
      : dynamicCaps.sectorCapPct;

  const smallCapitalWholeShareMode =
    budgetPaisa > 0 &&
    budgetPaisa <
      DECISION_MIN_MEANINGFUL_POSITION_PKR *
      Math.max(1, targetPositionCount) *
      100;

  const minimumMeaningfulPositionPkr =
    decisionMinimumMeaningfulPositionPkr(
      amount,
      targetPositionCount
    );
  const minimumMeaningfulPositionPaisa =
    Math.round(
      minimumMeaningfulPositionPkr *
      100
    );

  const deploymentPlan =
    traderMode
      ? decisionTraderDeploymentPlan(
          candidates,
          riskPolicy
        )
      : decisionCenterDeploymentPlan(
          candidates,
          targetPositionCount,
          riskPolicy
        );

  const deployCap =
    Math.floor(
      budgetPaisa *
      deploymentPlan.targetDeploymentPct /
      100
    );

  if (!candidates.length) {
    return {
      allocations: [],
      amountInvestedPkr: 0,
      cashRemainingPkr:
        decisionRound(
          amount,
          2
        ),
      investedPct: 0,
      deploymentCapPct:
        deploymentPlan.targetDeploymentPct,
      portfolioAware:
        Boolean(
          portfolioContext?.holdingCount
        ),
      existingPortfolioValuePkr:
        decisionRound(
          existingPortfolioValuePaisa /
          100,
          2
        ),
      targetPositionCount,
      sizingPositionCount,
      targetDeploymentPct:
        deploymentPlan.targetDeploymentPct,
      intentionalCashReservePct:
        deploymentPlan.intentionalCashReservePct,
      averageConvictionScore:
        deploymentPlan.averageConvictionScore,
      cashReserveReason:
        deploymentPlan.reason,
      minimumTargetPositions:
        traderMode ? 1 : DECISION_CENTER_MIN_TARGET_POSITIONS,
      maximumTargetPositions:
        traderMode ? traderCaps.maxOpenPositions : DECISION_CENTER_MAX_TARGET_POSITIONS,
      achievedPositionCount: 0,
      diversificationException: {
        triggered: traderMode ? false : true,
        reason:
          traderMode
            ? 'No current short-term entry passes the selected trader profile. This is an execution-state result, not a diversification failure.'
            : 'No profile-suitable actionable stock currently passes the full allocation gate, so NOMAD retains the capital in cash rather than forcing positions.'
      },
      eligibleAllocationCandidates: 0,
      priorityOneAllocationCandidates: 0,
      priorityTwoAllocationCandidates: 0,
      dynamicMaxStockPct:
        decisionRound(
          dynamicCaps.stockCapPct *
          100,
          2
        ),
      dynamicMaxSectorPct:
        decisionRound(
          effectiveSectorCapPct *
          100,
          2
        ),
      sectorConstraint,
      concentrationWarning:
        sectorConstraint
          ? 'This plan is intentionally restricted to ' + sectorConstraint + '. Cross-sector diversification is disabled by user choice; stock-level evidence, risk and sizing gates remain active.'
          : null,
      minimumMeaningfulPositionPkr,
      smallCapitalWholeShareMode,
      marketableLotPolicy:
        'PSX_REGULAR_ONE_SHARE',
      unfundedPriorityOne: [],
      personalActions: []
    };
  }

  // With very small budgets, reserve candidates must not dilute each preferred
  // position below whole-share affordability. Size from the preferred target
  // set first; reserve candidates remain available only as fallback choices.
  const strengthSizingCandidates =
    smallCapitalWholeShareMode
      ? candidates.slice(
          0,
          Math.max(
            1,
            targetPositionCount
          )
        )
      : candidates;

  const strengthTotal =
    strengthSizingCandidates.reduce(
      (
        sum,
        candidate
      ) =>
        sum +
        Math.max(
          1,
          safeNumber(
            candidate.allocationConvictionScore
          ) ||
          decisionCenterCandidateConviction(
            candidate
          )
        ) *
        candidate.allocationStrengthMultiplier *
        (
          safeNumber(
            candidate.concentrationScale
          ) ||
          1
        ),
      0
    );

  let remainingDeploy =
    deployCap;

  const allocations = [];
  const sectorSpent =
    new Map();
  const personalActions = [];

  for (
    const candidate
    of candidates
  ) {
    if (
      allocations.length >=
        targetPositionCount
    ) {
      break;
    }

    if (
      !decisionExecutionAllowsAllocation(
        candidate.executionGuidance ||
        decisionExecutionGuidance(
          candidate,
          riskPolicy
        )
      )
    ) {
      continue;
    }

    const pricePaisa =
      Math.round(
        Number(
          candidate.price
        ) *
        100
      );

    if (
      !Number.isFinite(
        pricePaisa
      ) ||
      pricePaisa <= 0
    ) {
      continue;
    }

    const strength =
      Math.max(
        1,
        safeNumber(
          candidate.allocationConvictionScore
        ) ||
        decisionCenterCandidateConviction(
          candidate
        )
      ) *
      candidate.allocationStrengthMultiplier *
      (
        safeNumber(
          candidate.concentrationScale
        ) ||
        1
      );

    const proportionalTarget =
      Math.floor(
        deployCap *
        strength /
        strengthTotal
      );

    const existingStockValuePaisa =
      Math.round(
        (
          safeNumber(
            existingSymbolValues[
              candidate.symbol
            ]
          ) ||
          0
        ) *
        100
      );

    const existingStockWeightPct =
      existingPortfolioValuePaisa > 0
        ? existingStockValuePaisa /
          existingPortfolioValuePaisa *
          100
        : 0;

    const effectiveStockCapPct =
      traderMode
        ? dynamicCaps.stockCapPct
        : existingStockValuePaisa > 0
          ? Math.max(
              dynamicCaps.stockCapPct,
              Math.min(
                safeNumber(
                  riskPolicy?.maxStockPct
                ) ||
                dynamicCaps.stockCapPct,
                0.75
              )
            )
          : dynamicCaps.stockCapPct;

    const stockTotalCap =
      Math.floor(
        postFundingCapitalBasePaisa *
        effectiveStockCapPct *
        candidate.allocationCapMultiplier
      );

    const stockGap =
      Math.max(
        0,
        stockTotalCap -
        existingStockValuePaisa
      );

    const existingSectorValuePaisa =
      Math.round(
        (
          safeNumber(
            existingSectorValues[
              candidate.sector
            ]
          ) ||
          0
        ) *
        100
      );

    const existingSectorSpent =
      sectorSpent.get(
        candidate.sector
      ) ||
      0;

    const effectiveCandidateSectorCapPct =
      traderMode
        ? effectiveSectorCapPct
        : existingSectorValuePaisa > 0 &&
          !sectorConstraint
          ? Math.max(
              effectiveSectorCapPct,
              Math.min(
                safeNumber(
                  riskPolicy?.maxSectorPct
                ) ||
                effectiveSectorCapPct,
                0.90
              )
            )
          : effectiveSectorCapPct;

    const sectorTotalCap =
      Math.floor(
        postFundingCapitalBasePaisa *
        effectiveCandidateSectorCapPct
      );

    const sectorGap =
      Math.max(
        0,
        sectorTotalCap -
        existingSectorValuePaisa -
        existingSectorSpent
      );

    // Build 0.9.3.6: concentration is a sizing penalty before it becomes a
    // hard veto. A strong existing holding may still receive additional capital
    // when weaker alternatives would reduce investment quality. The absolute
    // risk-profile stock/sector caps remain hard limits.
    const preAddStockWeightPct =
      existingPortfolioValuePaisa > 0
        ? existingStockValuePaisa /
          existingPortfolioValuePaisa
        : 0;

    const preAddSectorWeightPct =
      existingPortfolioValuePaisa > 0
        ? existingSectorValuePaisa /
          existingPortfolioValuePaisa
        : 0;

    const existingHoldingElevated =
      existingStockValuePaisa > 0 &&
      preAddStockWeightPct >=
        dynamicCaps.stockCapPct *
        0.85;

    const existingSectorElevated =
      existingSectorValuePaisa > 0 &&
      !sectorConstraint &&
      preAddSectorWeightPct >=
        dynamicCaps.sectorCapPct *
        0.85;

    const shortTermCandidate =
      candidate?.canonicalState
        ?.professional
        ?.framework ===
        'SHORT_TERM_TRADER';

    const traderRiskBudgetPct =
      shortTermCandidate
        ? decisionTraderRiskBudgetPct(
            riskPolicy
          )
        : null;

    const traderRiskPerShare =
      shortTermCandidate
        ? safeNumber(
            candidate?.canonicalState
              ?.professional
              ?.tradePlan
              ?.riskPerShare
          )
        : null;

    const traderRiskShareCap =
      shortTermCandidate &&
      traderRiskPerShare !== null &&
      traderRiskPerShare > 0
        ? Math.floor(
            (
              budgetPaisa /
              100 *
              traderRiskBudgetPct
            ) /
            traderRiskPerShare
          )
        : null;

    const traderRiskValueCap =
      shortTermCandidate
        ? Math.max(
            0,
            (
              traderRiskShareCap ||
              0
            ) *
            pricePaisa
          )
        : Number.MAX_SAFE_INTEGER;

    const allowed =
      Math.max(
        0,
        Math.min(
          remainingDeploy,
          proportionalTarget,
          stockGap,
          sectorGap,
          traderRiskValueCap
        )
      );

    if (
      allowed > 0 &&
      allowed <
        minimumMeaningfulPositionPaisa &&
      budgetPaisa >=
        minimumMeaningfulPositionPaisa
    ) {
      personalActions.push({
        symbol:
          candidate.symbol,
        marketView:
          candidate.canonicalState
            ?.marketAction ||
          candidate.decisionCenterView,
        portfolioAction:
          'NO_ADD',
        allocationTier:
          candidate.allocationTier,
        existingWeightPct:
          decisionRound(
            existingStockWeightPct,
            2
          ),
        targetWeightPct:
          decisionRound(
            stockTotalCap /
            Math.max(
              1,
              postFundingCapitalBasePaisa
            ) *
            100,
            2
          ),
        reason:
          "The feasible new-money position would be below NOMAD\'s minimum meaningful position of PKR " +
          decisionRound(
            minimumMeaningfulPositionPkr,
            0
          ) +
          ', so the engine does not create an economically trivial holding.'
      });
      continue;
    }

    const shares =
      Math.floor(
        allowed /
        pricePaisa
      );

    if (shares < 1) {
      let personalAction =
        'NO_ADD';
      let personalReason =
        shortTermCandidate &&
        traderRiskValueCap < pricePaisa
          ? 'One whole share would exceed the selected profile\'s stop-based per-trade risk budget, so NOMAD does not force the trade.'
          : 'The opportunity remains ranked, but this new capital cannot fit one whole share inside the current target-weight and sector limits.';

      if (
        existingStockValuePaisa >=
          stockTotalCap &&
        existingStockValuePaisa > 0
      ) {
        personalAction =
          'HOLD';
        personalReason =
          'NOMAD still likes the opportunity, but your current holding is already at or above its portfolio target. Do not add with this new money.';
      } else if (
        existingSectorValuePaisa >=
          sectorTotalCap &&
        existingSectorValuePaisa > 0
      ) {
        personalAction =
          'DO_NOT_ADD';
        personalReason =
          'The stock remains attractive, but your existing sector exposure is already at the current portfolio cap.';
      }

      personalActions.push({
        symbol:
          candidate.symbol,
        marketView:
          candidate.decisionCenterView,
        portfolioAction:
          personalAction,
        allocationTier:
          candidate.allocationTier,
        existingWeightPct:
          decisionRound(
            existingStockWeightPct,
            2
          ),
        targetWeightPct:
          decisionRound(
            stockTotalCap /
            Math.max(
              1,
              postFundingCapitalBasePaisa
            ) *
            100,
            2
          ),
        reason:
          personalReason
      });

      continue;
    }

    const spent =
      shares *
      pricePaisa;

    remainingDeploy -=
      spent;

    sectorSpent.set(
      candidate.sector,
      existingSectorSpent +
        spent
    );

    const postStockValue =
      existingStockValuePaisa +
      spent;

    const traderPlanSelection =
      shortTermCandidate
        ? decisionTraderCanonicalPlan(
            candidate.canonicalState
              ?.professional ||
            candidate.professional ||
            {},
            candidate.shortTermExecution ||
            null
          )
        : null;

    const traderPlan =
      traderPlanSelection?.plan ||
      null;

    const executionGuidance =
      candidate.executionGuidance ||
      decisionExecutionGuidance(
        candidate,
        riskPolicy
      );

    allocations.push({
      symbol:
        candidate.symbol,
      companyName:
        candidate.companyName,
      sector:
        candidate.sector,
      action:
        candidate.allocationAction ||
        candidate.canonicalState
          ?.marketAction ||
        candidate.decisionCenterView,
      marketView:
        candidate.allocationAction ||
        candidate.canonicalState
          ?.marketAction ||
        candidate.decisionCenterView,
      allocationTier:
        candidate.allocationTier,
      shares,
      referencePrice:
        decisionRound(
          candidate.price,
          2
        ),
      traderPlan:
        shortTermCandidate
          ? {
              source:
                traderPlanSelection?.source ||
                null,
              kind:
                traderPlanSelection?.kind ||
                null,
              setup:
                candidate.canonicalState
                  ?.professional
                  ?.setup ||
                null,
              entryLow:
                traderPlan?.entryLow ??
                traderPlan?.entryReference ??
                null,
              entryHigh:
                traderPlan?.entryHigh ??
                traderPlan?.entryReference ??
                null,
              stop:
                traderPlan?.stop ??
                null,
              target1:
                traderPlan?.target1 ??
                null,
              rewardRisk:
                traderPlan?.rewardRisk ??
                null,
              riskPerShare:
                traderRiskPerShare,
              riskBudgetPct:
                decisionRound(
                  traderRiskBudgetPct *
                  100,
                  2
                )
            }
          : null,
      executionGuidance,
      principalPkr:
        decisionRound(
          spent /
          100,
          2
        ),
      targetWeightPct:
        decisionRound(
          stockTotalCap /
          Math.max(
            1,
            postFundingCapitalBasePaisa
          ) *
          100,
          2
        ),
      newMoneyWeightPct:
        decisionRound(
          budgetPaisa > 0
            ? spent /
              budgetPaisa *
              100
            : 0,
          2
        ),
      postPortfolioWeightPct:
        decisionRound(
          postFundingCapitalBasePaisa > 0
            ? postStockValue /
              postFundingCapitalBasePaisa *
              100
            : 0,
          2
        ),
      existingWeightPct:
        decisionRound(
          existingStockWeightPct,
          2
        ),
      actualWeightPct:
        decisionRound(
          budgetPaisa > 0
            ? spent /
              budgetPaisa *
              100
            : 0,
          2
        ),
      overallScore:
        candidate.overallScore,
      opportunityRankScore:
        candidate.opportunityRankScore,
      allocationConvictionScore:
        candidate.allocationConvictionScore,
      marginalInvestmentMeritScore:
        candidate.marginalInvestmentMeritScore,
      portfolioFitScore:
        candidate.portfolioFitScore,
      marginalAllocationScore:
        candidate.marginalAllocationScore,
      evidenceStrength:
        candidate.analystCore
          ?.coverage
          ?.coreCoveragePct ??
        null,
      note:
        shortTermCandidate
          ? 'Short-term shadow trade candidate: position value is capped by the defined stop distance and the selected profile\'s per-trade risk budget. Brokerage, taxes, levies and execution slippage are not included.'
          : candidate.allocationTier ===
              'PRIORITY_2'
            ? 'Actionable Priority 2 position: the canonical market action is ACCUMULATE, evidence passes the allocation gate, and NOMAD deliberately sizes it below Priority 1.'
            : candidate.decisionCenterView ===
                'ACCUMULATE'
              ? 'Staged Priority 1 exposure: the analyst thesis passes, but NOMAD is not sizing this as a full position yet.'
              : 'Priority 1 shadow allocation. Brokerage, taxes, levies and execution slippage are not included.'
    });

    personalActions.push({
      symbol:
        candidate.symbol,
      marketView:
        candidate.canonicalState
          ?.marketAction ||
        candidate.decisionCenterView,
      portfolioAction:
        existingStockValuePaisa > 0
          ? 'ADD'
          : 'BUY',
      allocationTier:
        candidate.allocationTier,
      existingWeightPct:
        decisionRound(
          existingStockWeightPct,
          2
        ),
      targetWeightPct:
        decisionRound(
          stockTotalCap /
          Math.max(
            1,
            postFundingCapitalBasePaisa
          ) *
          100,
          2
        ),
      postPortfolioWeightPct:
        decisionRound(
          postFundingCapitalBasePaisa > 0
            ? postStockValue /
              postFundingCapitalBasePaisa *
              100
            : 0,
          2
        ),
      reason:
        shortTermCandidate
          ? 'The trade setup passes the Trader brain and the position fits the selected profile\'s stop-based risk budget plus portfolio concentration limits.'
          : existingStockValuePaisa > 0
            ? (
                existingHoldingElevated ||
                existingSectorElevated
                  ? 'The investment thesis remains strong enough to justify adding, but existing stock/sector concentration reduces the recommended size. NOMAD prefers diversification when comparable-quality alternatives exist, without replacing this holding with a materially weaker idea.'
                  : 'The holding remains attractive and has room for additional capital within the selected risk profile and portfolio limits.'
              )
            : candidate.allocationTier ===
                'PRIORITY_2'
              ? 'The canonical market action is actionable, but this is a lower-priority opportunity, so NOMAD limits the position size.'
              : 'The opportunity passes the current allocation gate and fits the portfolio diversification limits.'
    });
  }

  // Whole-share rounding pass. It can add one share at a time only to already
  // selected candidates and never above the dynamic post-portfolio target cap.
  let progressed = true;

  while (
    remainingDeploy > 0 &&
    progressed
  ) {
    progressed = false;

    for (
      const candidate
      of candidates
    ) {
      const pricePaisa =
        Math.round(
          Number(
            candidate.price
          ) *
          100
        );

      if (
        !Number.isFinite(
          pricePaisa
        ) ||
        pricePaisa <= 0 ||
        pricePaisa >
          remainingDeploy
      ) {
        continue;
      }

      const allocation =
        allocations.find(
          item =>
            item.symbol ===
              candidate.symbol
        );

      if (!allocation) {
        continue;
      }

      const currentSpent =
        Math.round(
          allocation.principalPkr *
          100
        );

      const existingStockValuePaisa =
        Math.round(
          (
            safeNumber(
              existingSymbolValues[
                candidate.symbol
              ]
            ) ||
            0
          ) *
          100
        );

      const stockTotalCap =
        Math.floor(
          postFundingCapitalBasePaisa *
          dynamicCaps.stockCapPct *
          candidate.allocationCapMultiplier
        );

      const sectorCurrent =
        sectorSpent.get(
          candidate.sector
        ) ||
        0;

      const existingSectorValuePaisa =
        Math.round(
          (
            safeNumber(
              existingSectorValues[
                candidate.sector
              ]
            ) ||
            0
          ) *
          100
        );

      const effectiveRoundingSectorCapPct =
        existingSectorValuePaisa > 0 &&
        !sectorConstraint
          ? Math.max(
              dynamicCaps.sectorCapPct,
              Math.min(
                safeNumber(
                  riskPolicy?.maxSectorPct
                ) ||
                dynamicCaps.sectorCapPct,
                0.90
              )
            )
          : (
              sectorConstraint
                ? 1
                : dynamicCaps.sectorCapPct
            );

      const sectorTotalCap =
        Math.floor(
          postFundingCapitalBasePaisa *
          effectiveRoundingSectorCapPct
        );

      const shortTermCandidate =
        candidate?.canonicalState
          ?.professional
          ?.framework ===
          'SHORT_TERM_TRADER';

      const traderRiskPerShare =
        shortTermCandidate
          ? safeNumber(
              candidate?.canonicalState
                ?.professional
                ?.tradePlan
                ?.riskPerShare
            )
          : null;

      const traderRiskValueCap =
        shortTermCandidate &&
        traderRiskPerShare !== null &&
        traderRiskPerShare > 0
          ? Math.floor(
              (
                budgetPaisa /
                100 *
                decisionTraderRiskBudgetPct(
                  riskPolicy
                ) /
                traderRiskPerShare
              )
            ) *
            pricePaisa
          : Number.MAX_SAFE_INTEGER;

      if (
        existingStockValuePaisa +
          currentSpent +
          pricePaisa >
            stockTotalCap ||
        existingSectorValuePaisa +
          sectorCurrent +
          pricePaisa >
            sectorTotalCap ||
        currentSpent +
          pricePaisa >
            traderRiskValueCap
      ) {
        continue;
      }

      allocation.shares += 1;
      allocation.principalPkr =
        decisionRound(
          allocation.principalPkr +
            pricePaisa /
            100,
          2
        );
      allocation.newMoneyWeightPct =
        decisionRound(
          allocation.principalPkr /
            amount *
            100,
          2
        );
      allocation.actualWeightPct =
        allocation.newMoneyWeightPct;
      allocation.postPortfolioWeightPct =
        decisionRound(
          (
            existingStockValuePaisa /
              100 +
            allocation.principalPkr
          ) /
          Math.max(
            0.01,
            postFundingCapitalBasePaisa /
              100
          ) *
          100,
          2
        );

      remainingDeploy -=
        pricePaisa;

      sectorSpent.set(
        candidate.sector,
        sectorCurrent +
          pricePaisa
      );

      progressed = true;

      if (remainingDeploy <= 0) {
        break;
      }
    }
  }

  const investedPaisa =
    allocations.reduce(
      (
        sum,
        item
      ) =>
        sum +
        Math.round(
          item.principalPkr *
          100
        ),
      0
    );

  const allocatedSymbols =
    new Set(
      allocations.map(
        item =>
          item.symbol
      )
    );

  const achievedPositionCount =
    allocations.length;

  const diversificationExceptionTriggered =
    traderMode
      ? false
      : achievedPositionCount <
          DECISION_CENTER_MIN_TARGET_POSITIONS;

  let diversificationExceptionReason = null;

  if (diversificationExceptionTriggered) {
    if (
      candidates.length <
        DECISION_CENTER_MIN_TARGET_POSITIONS
    ) {
      diversificationExceptionReason =
        'Only ' +
        candidates.length +
        ' profile-suitable actionable stock' +
        (candidates.length === 1 ? '' : 's') +
        ' passed the professional allocation gate after deeper research. NOMAD will not force a weaker third position; the remainder stays in cash.';
    } else {
      diversificationExceptionReason =
        'At least three actionable stocks passed research, but whole-share affordability, existing holdings, stock caps, or sector caps prevented three prudent funded positions. NOMAD retains the remainder in cash rather than forcing exposure.';
    }
  }

  const unfundedPriorityOne =
    candidates
      .filter(
        candidate =>
          candidate.allocationTier ===
            'PRIORITY_1' &&
          !allocatedSymbols.has(
            candidate.symbol
          )
      )
      .map(
        candidate => ({
          symbol:
            candidate.symbol,
          price:
            candidate.price,
          reason:
            Boolean(portfolioContext?.holdingCount)
              ? 'Priority 1 remains valid, but your existing holding/sector exposure or whole-share feasibility leaves no prudent room to add it with this capital.'
              : 'Priority 1 remains valid, but whole-share feasibility or the dynamic diversification cap prevents a prudent allocation with this amount.'
      }));

  return {
    allocations,
    amountInvestedPkr:
      decisionRound(
        investedPaisa /
        100,
        2
      ),
    cashRemainingPkr:
      decisionRound(
        Math.max(
          0,
          budgetPaisa -
            investedPaisa
        ) /
        100,
        2
      ),
    investedPct:
      decisionRound(
        budgetPaisa > 0
          ? investedPaisa /
            budgetPaisa *
            100
          : 0,
        2
      ),
    deploymentCapPct:
      deploymentPlan.targetDeploymentPct,
    portfolioAware:
      Boolean(
        portfolioContext?.holdingCount
      ),
    existingPortfolioValuePkr:
      decisionRound(
        existingPortfolioValuePaisa /
        100,
        2
      ),
    targetPositionCount,
    sizingPositionCount,
    targetDeploymentPct:
      deploymentPlan.targetDeploymentPct,
    intentionalCashReservePct:
      deploymentPlan.intentionalCashReservePct,
    averageConvictionScore:
      deploymentPlan.averageConvictionScore,
    cashReserveReason:
      deploymentPlan.reason,
    minimumTargetPositions:
      traderMode ? 1 : DECISION_CENTER_MIN_TARGET_POSITIONS,
    maximumTargetPositions:
      traderMode ? traderCaps.maxOpenPositions : DECISION_CENTER_MAX_TARGET_POSITIONS,
    achievedPositionCount,
    diversificationException: {
      triggered:
        diversificationExceptionTriggered,
      reason:
        diversificationExceptionReason
    },
    eligibleAllocationCandidates:
      candidates.length,
    priorityOneAllocationCandidates:
      candidates.filter(
        item =>
          item.allocationTier ===
            'PRIORITY_1'
      ).length,
    priorityTwoAllocationCandidates:
      candidates.filter(
        item =>
          item.allocationTier ===
            'PRIORITY_2'
      ).length,
    dynamicMaxStockPct:
      decisionRound(
        dynamicCaps.stockCapPct *
        100,
        2
      ),
    dynamicMaxSectorPct:
      decisionRound(
        effectiveSectorCapPct *
        100,
        2
      ),
    sectorConstraint,
    traderMode,
    traderMaxOpenPositions:
      traderMode ? traderCaps.maxOpenPositions : null,
    traderRiskBudgetPct:
      traderMode ? decisionRound(decisionTraderRiskBudgetPct(riskPolicy) * 100, 2) : null,
    concentrationWarning:
      sectorConstraint
        ? 'This plan is intentionally restricted to ' + sectorConstraint + '. Cross-sector diversification is disabled by user choice; stock-level evidence, risk and sizing gates remain active.'
        : null,
    minimumMeaningfulPositionPkr,
    smallCapitalWholeShareMode,
    marketableLotPolicy:
      'PSX_REGULAR_ONE_SHARE',
    unfundedPriorityOne,
    personalActions
  };
}

async function decisionMapWithConcurrency(
  items,
  concurrency,
  worker
) {
  const source =
    Array.isArray(items)
      ? items
      : [];

  const results =
    new Array(
      source.length
    );

  let nextIndex = 0;

  async function runWorker() {
    while (true) {
      const index =
        nextIndex++;

      if (index >= source.length) {
        return;
      }

      try {
        results[index] =
          await worker(
            source[index],
            index
          );
      } catch (error) {
        results[index] = {
          error:
            error.message ||
            'Decision evidence request failed.'
        };
      }
    }
  }

  await Promise.all(
    Array.from(
      {
        length:
          Math.max(
            1,
            Math.min(
              concurrency,
              source.length ||
              1
            )
          )
      },
      () =>
        runWorker()
    )
  );

  return results;
}

async function decisionWithTimeout(
  promise,
  milliseconds,
  label
) {
  let timeoutId;

  const timeoutPromise =
    new Promise(
      (
        resolve,
        reject
      ) => {
        timeoutId =
          setTimeout(
            () =>
              reject(
                new Error(
                  label +
                  ' timed out.'
                )
              ),
            milliseconds
          );
      }
    );

  try {
    return await Promise.race([
      promise,
      timeoutPromise
    ]);
  } finally {
    clearTimeout(
      timeoutId
    );
  }
}

async function decisionHistoricalContext(
  row,
  memoryMap
) {
  const symbol =
    normalizeSymbol(
      row.symbol
    );

  const memory =
    memoryMap?.get(
      symbol
    ) ||
    null;

  const cachedContext =
    memory?.market_state
      ?.historicalContext ||
    null;

  const evaluatedAt =
    Date.parse(
      memory?.evaluated_at ||
      ''
    );

  if (
    cachedContext?.available &&
    cachedContext?.contextSchemaVersion ===
      DECISION_HISTORICAL_CONTEXT_SCHEMA_VERSION &&
    cachedContext?.priceAction &&
    Number.isFinite(
      evaluatedAt
    ) &&
    Date.now() -
      evaluatedAt <
      24 *
        60 *
        60 *
        1000
  ) {
    return {
      ...cachedContext,
      cacheState: 'memory'
    };
  }

  const context =
    await decisionWithTimeout(
      getHistoricalSituation(
        symbol,
        row.price
      ),
      7000,
      symbol +
      ' history'
    );

  if (context?.available) {
    saveHistoricalSituationToMemory(
      symbol,
      context,
      row
    ).catch(
      () => {}
    );
  }

  return {
    ...context,
    cacheState: 'fresh'
  };
}

function decisionFundamentalCache(
  memory
) {
  const cache =
    memory?.fundamental_state
      ?.decisionEvidence ||
    null;

  const cachedAt =
    Date.parse(
      cache?.cachedAt ||
      ''
    );

  if (
    !cache?.data?.available ||
    !Number.isFinite(
      cachedAt
    )
  ) {
    return null;
  }

  return {
    data:
      cache.data,
    cachedAt:
      cache.cachedAt,
    ageMs:
      Math.max(
        0,
        Date.now() -
          cachedAt
      )
  };
}

async function saveDecisionFundamentalCache(
  symbol,
  fundamentals,
  memory
) {
  if (
    !continuousMemoryConfigured() ||
    !memory ||
    !fundamentals?.available
  ) {
    return false;
  }

  const fundamentalState = {
    ...(
      memory.fundamental_state ||
      {}
    ),
    decisionEvidence: {
      cachedAt:
        new Date()
          .toISOString(),
      source:
        fundamentals.source ||
        null,
      sourceUrl:
        fundamentals.sourceUrl ||
        null,
      data: {
        symbol:
          fundamentals.symbol ||
          normalizeSymbol(
            symbol
          ),
        company:
          fundamentals.company ||
          null,
        source:
          fundamentals.source ||
          null,
        sourceUrl:
          fundamentals.sourceUrl ||
          null,
        fetchedAt:
          fundamentals.fetchedAt ||
          new Date()
            .toISOString(),
        valuation:
          fundamentals.valuation ||
          null,
        annual:
          fundamentals.annual ||
          null,
        quarterly:
          fundamentals.quarterly ||
          null,
        ratios:
          fundamentals.ratios ||
          null,
        analystCore:
          fundamentals.analystCore ||
          buildFinancialAnalystCore(
            fundamentals
          ),
        available: true
      }
    }
  };

  try {
    await supabaseRest(
      'security_state?symbol=eq.' +
        encodeURIComponent(
          normalizeSymbol(
            symbol
          )
        ),
      {
        method: 'PATCH',
        prefer:
          'return=minimal',
        body: {
          fundamental_state:
            fundamentalState
        }
      }
    );

    memory.fundamental_state =
      fundamentalState;

    return true;
  } catch {
    return false;
  }
}

async function decisionLoadFundamentals(
  row,
  memoryMap
) {
  const symbol =
    normalizeSymbol(
      row.symbol
    );

  const memory =
    memoryMap?.get(
      symbol
    ) ||
    null;

  const cache =
    decisionFundamentalCache(
      memory
    );

  if (
    cache &&
    cache.ageMs <=
      DECISION_FUNDAMENTAL_CACHE_FRESH_MS
  ) {
    const cachedFundamentals = {
      ...cache.data,
      analystCore:
        cache.data?.analystCore ||
        buildFinancialAnalystCore(
          cache.data
        )
    };

    return {
      fundamentals:
        cachedFundamentals,
      evidenceState:
        'CACHE_FRESH',
      cachedAt:
        cache.cachedAt,
      diagnostics: {
        source:
          'CACHE_FRESH',
        cacheAgeMs:
          cache.ageMs,
        liveAttempted:
          false
      },
      error: null
    };
  }

  let fresh = null;
  let freshError = null;

  try {
    fresh =
      await decisionWithTimeout(
        getFundamentals(
          symbol
        ),
        18000,
        symbol +
          ' fundamentals'
      );
  } catch (error) {
    freshError =
      error.message ||
      'Fundamental evidence unavailable.';
  }

  if (
    fresh &&
    !fresh.available &&
    !freshError
  ) {
    freshError =
      fresh.evidenceError ||
      'Structured company fundamentals were not available from the PSX company page.';
  }

  if (fresh?.available) {
    await saveDecisionFundamentalCache(
      symbol,
      fresh,
      memory
    );

    return {
      fundamentals:
        fresh,
      evidenceState:
        'LIVE',
      cachedAt:
        fresh.fetchedAt ||
        new Date()
          .toISOString(),
      diagnostics: {
        source:
          'LIVE',
        cacheAgeMs:
          cache?.ageMs ??
          null,
        liveAttempted:
          true,
        fundamentals:
          fresh.diagnostics ||
          null
      },
      error: null
    };
  }

  if (
    cache &&
    cache.ageMs <=
      DECISION_FUNDAMENTAL_CACHE_FALLBACK_MS
  ) {
    const cachedFundamentals = {
      ...cache.data,
      analystCore:
        cache.data?.analystCore ||
        buildFinancialAnalystCore(
          cache.data
        )
    };

    return {
      fundamentals:
        cachedFundamentals,
      evidenceState:
        'CACHE_FALLBACK',
      cachedAt:
        cache.cachedAt,
      diagnostics: {
        source:
          'CACHE_FALLBACK',
        cacheAgeMs:
          cache.ageMs,
        liveAttempted:
          true,
        liveFailure:
          freshError ||
          null,
        fundamentals:
          fresh?.diagnostics ||
          null
      },
      error:
        freshError ||
        'Live fundamentals were unavailable; NOMAD used recent cached company evidence.'
    };
  }

  return {
    fundamentals:
      fresh,
    evidenceState:
      'BLOCKED',
    cachedAt: null,
    diagnostics: {
      source:
        'BLOCKED',
      cacheAgeMs:
        cache?.ageMs ??
        null,
      liveAttempted:
        true,
      liveFailure:
        freshError ||
        null,
      fundamentals:
        fresh?.diagnostics ||
        null
    },
    error:
      freshError ||
      'Structured company fundamentals are unavailable.'
  };
}

function decisionOverallScore(
  model,
  fundamental,
  valuation,
  entry,
  risk,
  dataQuality
) {
  const weights =
    model.weights;

  return decisionRound(
    decisionClamp(
      (
        safeNumber(
          fundamental?.score
        ) ||
        0
      ) *
        weights.fundamental +
      (
        safeNumber(
          valuation?.score
        ) ||
        0
      ) *
        weights.valuation +
      (
        safeNumber(
          entry?.score
        ) ||
        0
      ) *
        weights.entry +
      (
        safeNumber(
          risk?.score
        ) ||
        0
      ) *
        weights.risk +
      (
        safeNumber(
          dataQuality?.score
        ) ||
        0
      ) *
        weights.dataQuality
    ),
    2
  );
}

function decisionCandidateNarrative(
  candidate
) {
  const positives = [
    ...(
      candidate.fundamental
        ?.reasons ||
      []
    ),
    ...(
      candidate.valuation
        ?.reasons ||
      []
    ),
    ...(
      candidate.entry
        ?.reasons ||
      []
    ),
    ...(
      candidate.risk
        ?.reasons ||
      []
    )
  ];

  const risks = [
    ...(
      candidate.fundamental
        ?.risks ||
      []
    ),
    ...(
      candidate.valuation
        ?.risks ||
      []
    ),
    ...(
      candidate.entry
        ?.risks ||
      []
    ),
    ...(
      candidate.risk
        ?.risks ||
      []
    )
  ];

  return {
    positives:
      uniqueStrings(
        positives
      ).slice(0, 4),
    risks:
      uniqueStrings(
        risks
      ).slice(0, 4)
  };
}

function allocateDecisionCandidates(
  candidates,
  amount,
  riskPolicy
) {
  const budgetPaisa =
    Math.max(
      0,
      Math.round(
        Number(amount) *
        100
      )
    );

  let remaining =
    budgetPaisa;

  const allocations = [];
  const sectorSpent =
    new Map();

  const actionable =
    candidates
      .filter(
        candidate =>
          candidate.action ===
            'BUY_NOW' ||
          candidate.action ===
            'STAGED_BUY'
      )
      .sort(
        (
          a,
          b
        ) =>
          b.overallScore -
          a.overallScore
      )
      .slice(
        0,
        riskPolicy.maxAllocations
      );

  for (
    const candidate
    of actionable
  ) {
    const pricePaisa =
      Math.round(
        Number(
          candidate.price
        ) *
        100
      );

    if (
      !Number.isFinite(
        pricePaisa
      ) ||
      pricePaisa <= 0
    ) {
      continue;
    }

    const stagedMultiplier =
      candidate.action ===
        'STAGED_BUY'
        ? 0.50
        : 1;

    const stockCap =
      Math.floor(
        budgetPaisa *
        riskPolicy.maxStockPct *
        stagedMultiplier
      );

    const existingSectorSpent =
      sectorSpent.get(
        candidate.sector
      ) ||
      0;

    const sectorCap =
      Math.floor(
        budgetPaisa *
        riskPolicy.maxSectorPct
      );

    const allowed =
      Math.max(
        0,
        Math.min(
          remaining,
          stockCap,
          sectorCap -
            existingSectorSpent
        )
      );

    const shares =
      Math.floor(
        allowed /
        pricePaisa
      );

    if (shares < 1) {
      continue;
    }

    const spent =
      shares *
      pricePaisa;

    remaining -=
      spent;

    sectorSpent.set(
      candidate.sector,
      existingSectorSpent +
        spent
    );

    allocations.push({
      symbol:
        candidate.symbol,
      companyName:
        candidate.companyName,
      sector:
        candidate.sector,
      action:
        candidate.action,
      shares,
      referencePrice:
        decisionRound(
          candidate.price,
          2
        ),
      principalPkr:
        decisionRound(
          spent /
          100,
          2
        ),
      budgetPct:
        decisionRound(
          budgetPaisa > 0
            ? spent /
              budgetPaisa *
              100
            : 0,
          2
        ),
      overallScore:
        candidate.overallScore,
      evidenceStrength:
        candidate.dataQuality
          ?.score ||
        null,
      note:
        candidate.action ===
          'STAGED_BUY'
          ? 'Shadow model limits this to a smaller staged allocation because entry quality is not yet strong.'
          : 'Shadow-model allocation before brokerage, levies, taxes and execution slippage.'
    });
  }

  const investedPaisa =
    budgetPaisa -
    remaining;

  return {
    allocations,
    amountInvestedPkr:
      decisionRound(
        investedPaisa /
        100,
        2
      ),
    cashRemainingPkr:
      decisionRound(
        remaining /
        100,
        2
      ),
    investedPct:
      decisionRound(
        budgetPaisa > 0
          ? investedPaisa /
            budgetPaisa *
            100
          : 0,
        2
      ),
    executionCostsIncluded: false
  };
}

async function recordDecisionRun(
  result
) {
  if (!continuousMemoryConfigured()) {
    return {
      recorded: false,
      reason:
        'Supabase is not configured.'
    };
  }

  try {
    const rows =
      await supabaseRest(
        'decision_runs?select=id,created_at',
        {
          method: 'POST',
          prefer:
            'return=representation',
          body: {
            model_id:
              result.model.id,
            engine_mode:
              'shadow',
            validation_status:
              result.validationStatus,
            real_money_eligible:
              false,
            horizon:
              result.input.horizon,
            risk_profile:
              result.input.risk,
            amount_pkr:
              result.input.amount,
            market_as_of:
              result.market.asOf ||
              null,
            decision_action:
              result.decision.action,
            amount_invested_pkr:
              result.decision.amountInvestedPkr,
            cash_remaining_pkr:
              result.decision.cashRemainingPkr,
            evidence_strength:
              result.decision.evidenceStrength,
            data_quality: {
              deepCandidates:
                result.screening.deepAnalyzed,
              eligibleUniverse:
                result.screening.eligibleUniverse,
              affordableUniverse:
                result.screening.affordableUniverse
            },
            allocation:
              result.allocations,
            summary: {
              headline:
                result.decision.headline,
              reason:
                result.decision.reason,
              topCandidates:
                result.candidates
                  .slice(0, 5)
                  .map(
                    candidate => ({
                      symbol:
                        candidate.symbol,
                      action:
                        candidate.action,
                      overallScore:
                        candidate.overallScore
                    })
                  )
            },
            raw_result:
              result
          }
        }
      );

    const run =
      Array.isArray(rows) &&
      rows.length
        ? rows[0]
        : null;

    if (!run?.id) {
      return {
        recorded: false,
        reason:
          'Decision run insert did not return an ID.'
      };
    }

    const candidateRows =
      result.candidates
        .slice(0, 8)
        .map(
          (
            candidate,
            index
          ) => {
            const allocation =
              result.allocations.find(
                item =>
                  item.symbol ===
                  candidate.symbol
              );

            return {
              run_id:
                run.id,
              symbol:
                candidate.symbol,
              company_name:
                candidate.companyName,
              sector:
                candidate.sector,
              candidate_rank:
                index + 1,
              candidate_action:
                candidate.action,
              reference_price:
                candidate.price,
              shares:
                allocation?.shares ||
                0,
              allocated_pkr:
                allocation?.principalPkr ||
                0,
              overall_score:
                candidate.overallScore,
              fundamental_score:
                candidate.fundamental
                  ?.score ||
                null,
              valuation_score:
                candidate.valuation
                  ?.score ||
                null,
              entry_score:
                candidate.entry
                  ?.score ||
                null,
              risk_score:
                candidate.risk
                  ?.score ||
                null,
              data_quality_score:
                candidate.dataQuality
                  ?.score ||
                null,
              evidence: {
                historicalContext:
                  candidate.historicalContext,
                fundamentalMetrics:
                  candidate.fundamental
                    ?.metrics ||
                  {},
                analystCore:
                  candidate.analystCore ||
                  null,
                fundamentalEvidenceState:
                  candidate.fundamentalEvidenceState ||
                  null,
                fundamentalEvidenceDiagnostics:
                  candidate.fundamentalEvidenceDiagnostics ||
                  null,
                narrative:
                  candidate.narrative,
                reason:
                  candidate.actionReason
              }
            };
          }
        );

    if (candidateRows.length) {
      await supabaseRest(
        'decision_candidates?select=id',
        {
          method: 'POST',
          prefer:
            'return=minimal',
          body:
            candidateRows
        }
      );
    }

    return {
      recorded: true,
      runId:
        run.id,
      createdAt:
        run.created_at ||
        null
    };
  } catch (error) {
    return {
      recorded: false,
      reason:
        error.message ||
        'Decision run could not be recorded.'
    };
  }
}

/* =========================================================
   ASK NOMAD - GROUNDED CONVERSATIONAL ORCHESTRATOR
   Build 0.9.6.3
   The chat layer never invents an investment conclusion. It routes a
   question through NOMAD's existing portfolio, Investor, Trader and
   allocation engines, then explains the structured result.
========================================================= */

function askNomadNormalizeText(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

function askNomadExtractCapital(message) {
  const text = askNomadNormalizeText(message).toLowerCase().replace(/,/g, '');
  const patterns = [
    /(?:pkr|rs\.?|rupees?)\s*([0-9]+(?:\.[0-9]+)?)\s*(k|m|million|thousand|lakh|lac|crore)?/i,
    /([0-9]+(?:\.[0-9]+)?)\s*(k|m|million|thousand|lakh|lac|crore)\b/i
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (!match) continue;
    let amount = Number(match[1]);
    if (!Number.isFinite(amount) || amount <= 0) continue;
    const unit = String(match[2] || '').toLowerCase();
    if (unit === 'k' || unit === 'thousand') amount *= 1000;
    else if (unit === 'm' || unit === 'million') amount *= 1000000;
    else if (unit === 'lakh' || unit === 'lac') amount *= 100000;
    else if (unit === 'crore') amount *= 10000000;
    return amount;
  }
  return null;
}

function askNomadFindSymbols(message, market) {
  const raw = askNomadNormalizeText(message);
  const upper = ' ' + raw.toUpperCase() + ' ';
  const rows = Array.isArray(market?.stocks) ? market.stocks : [];
  const found = [];
  const conceptWords = new Set([
    'CASH','COST','BUY','SELL','HOLD','ADD','REDUCE','EXIT','WAIT','PASS','AVOID',
    'MARKET','STOCK','STOCKS','PORTFOLIO','RISK','PRICE','VALUE','CAPITAL','TODAY',
    'LONG','SHORT','TERM','BANK','POWER','OIL','GAS','TRADE','TRADING','INVEST','INVESTMENT'
  ]);
  for (const row of rows) {
    const symbol = normalizeSymbol(row.symbol);
    if (!symbol || found.includes(symbol)) continue;
    const escaped = symbol.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const tokenRegex = new RegExp('(^|[^A-Z0-9])' + escaped + '([^A-Z0-9]|$)');
    const tokenHit = tokenRegex.test(upper);
    const explicitTickerHit = new RegExp('\\b(?:ticker|symbol|stock)\\s+' + escaped + '\\b', 'i').test(raw);
    const exactUpperToken = new RegExp('(^|[^A-Z0-9])' + escaped + '([^A-Z0-9]|$)').test(' ' + raw + ' ') && raw.includes(symbol);
    const name = String(row.companyName || '').trim();
    const nameHit = name.length >= 4 && upper.includes(' ' + name.toUpperCase() + ' ');
    const symbolAllowed = !conceptWords.has(symbol) || explicitTickerHit;
    if ((symbolAllowed && tokenHit && (exactUpperToken || symbol.length <= 5)) || explicitTickerHit || nameHit) found.push(symbol);
    if (found.length >= 4) break;
  }
  return found;
}

function askNomadInferHorizon(message, fallback) {
  const text = askNomadNormalizeText(message).toLowerCase();
  if (/\b(today|intraday|trade|trading|short[ -]?term|tomorrow|this week|entry|stop|target|breakout|pullback)\b/.test(text)) return 'short_term';
  if (/\b(long[ -]?term|invest|investment|years?|fundamental|dividend|portfolio strategy)\b/.test(text)) return 'long_term';
  return fallback === 'short_term' ? 'short_term' : 'long_term';
}

function askNomadClassifyIntent(message, symbols) {
  const text = askNomadNormalizeText(message).toLowerCase();
  if (/\b(need|raise|withdraw|take out|free up|require)\b[\s\S]{0,45}\b(cash|money|pkr|rs\.?|rupees?)\b|\bcash within\b|\bneed cash\b|\braise cash\b/.test(text)) return 'LIQUIDITY_PLAN';
  if (symbols.length >= 2 && /\b(compare|versus|vs\.?|better)\b/.test(text)) return 'COMPARE_STOCKS';
  if (symbols.length >= 1) return 'STOCK_ANALYSIS';
  if (/\b(market|psx|index|breadth|gainers|losers|session)\b/.test(text) && !/\bportfolio|my stocks?|holdings?\b/.test(text)) return 'MARKET_OUTLOOK';
  if (/\b(invest more|deploy|put in|allocate|new capital|new money|where should i invest|what should i buy|buy anything)\b/.test(text)) return 'CAPITAL_DECISION';
  if (/\b(sell|reduce|exit|buy|add|hold|steps?|action|do anything|should i|rebalance|rotate)\b/.test(text) && /\b(portfolio|my stocks?|holdings?|anything|positions?)\b/.test(text)) return 'PORTFOLIO_ACTIONS';
  if (/\b(portfolio|my stocks?|holdings?|how.*doing|how.*look|today|concentration|diversif|risk)\b/.test(text)) return 'PORTFOLIO_REVIEW';
  return 'GENERAL';
}

function askNomadMoney(value) {
  const n = safeNumber(value);
  if (n === null) return 'N/A';
  return 'PKR ' + Math.round(n).toLocaleString('en-US');
}

function askNomadPct(value) {
  const n = safeNumber(value);
  if (n === null) return 'N/A';
  return (n >= 0 ? '+' : '') + decisionRound(n, 2) + '%';
}

function askNomadMarketSummary(market) {
  const rows = (market?.stocks || []).filter(row => safeNumber(row.price) !== null);
  let advancers = 0, decliners = 0, unchanged = 0;
  const changes = [];
  for (const row of rows) {
    const change = safeNumber(row.dayChangePct);
    if (change === null) continue;
    changes.push(change);
    if (change > 0.001) advancers += 1;
    else if (change < -0.001) decliners += 1;
    else unchanged += 1;
  }
  const sorted = rows.filter(r => safeNumber(r.dayChangePct) !== null).slice().sort((a,b) => (safeNumber(b.dayChangePct)||0) - (safeNumber(a.dayChangePct)||0));
  const breadthPct = (advancers + decliners) > 0 ? advancers / (advancers + decliners) * 100 : null;
  return {
    asOf: market?.marketWatchAsOf || market?.asOf || null,
    total: rows.length,
    advancers,
    decliners,
    unchanged,
    breadthPct: decisionRound(breadthPct, 2),
    leaders: sorted.slice(0, 3).map(r => ({symbol: normalizeSymbol(r.symbol), changePct: decisionRound(r.dayChangePct,2), price: decisionRound(r.price,4)})),
    laggards: sorted.slice(-3).reverse().map(r => ({symbol: normalizeSymbol(r.symbol), changePct: decisionRound(r.dayChangePct,2), price: decisionRound(r.price,4)}))
  };
}

async function askNomadRunHoldingStrategies(portfolio, horizon, risk) {
  const holdings = (portfolio?.holdings || []).filter(h => h?.symbol).slice(0, 8);
  const results = [];
  for (const holding of holdings) {
    try {
      const result = await runSingleStockStrategy({symbol: holding.symbol, horizon, risk});
      results.push(result);
    } catch (error) {
      results.push({status:'ERROR', identity:{symbol:holding.symbol}, message:error?.message || 'Analysis failed.'});
    }
  }
  return results;
}

function askNomadStrategyCard(result) {
  return {
    type: 'stock',
    symbol: result?.identity?.symbol || result?.input?.symbol || '',
    companyName: result?.identity?.companyName || '',
    price: result?.market?.price ?? null,
    dayChangePct: result?.market?.dayChangePct ?? null,
    marketAction: result?.professional?.marketAction || 'UNAVAILABLE',
    personalAction: result?.personal?.action || 'UNAVAILABLE',
    personalReason: result?.personal?.reason || '',
    setup: result?.technical?.setup || null,
    entryLow: result?.technical?.entryLow ?? result?.technical?.conditionalEntryLow ?? null,
    entryHigh: result?.technical?.entryHigh ?? result?.technical?.conditionalEntryHigh ?? null,
    stop: result?.technical?.stop ?? result?.technical?.conditionalStop ?? null,
    target: result?.technical?.target1 ?? result?.technical?.conditionalTarget1 ?? null,
    rewardRisk: result?.technical?.rewardRisk ?? result?.technical?.conditionalRewardRisk ?? null,
    weightPct: result?.personal?.currentPortfolioWeightPct ?? null
  };
}


function askNomadActionWeakness(action, marketAction) {
  const a = String(action || '').toUpperCase();
  const m = String(marketAction || '').toUpperCase();
  let score = 0;
  if (/SELL|EXIT|REDUCE|DO_NOT_ADD|PASS|AVOID/.test(a)) score += 5;
  else if (/WAIT|NO_ACTION|HOLD/.test(a)) score += 2;
  else if (/BUY|ADD|ACCUMULATE/.test(a)) score -= 4;
  if (m === 'AVOID') score += 4;
  else if (m === 'RESEARCHING' || m === 'WATCH') score += 1;
  else if (m === 'BUY' || m === 'ACCUMULATE') score -= 3;
  return score;
}


function askNomadCurrentHoldingMap(portfolio) {
  return new Map(
    (Array.isArray(portfolio?.holdings) ? portfolio.holdings : [])
      .filter(item => item?.symbol && safeNumber(item?.quantity) > 0)
      .map(item => [normalizeSymbol(item.symbol), item])
  );
}

function askNomadCombinedReason(item) {
  const longAction = String(item?.long?.personalAction || '').toUpperCase();
  const shortAction = String(item?.short?.personalAction || '').toUpperCase();
  const longMarket = String(item?.long?.marketAction || '').toUpperCase();
  const shortMarket = String(item?.short?.marketAction || '').toUpperCase();
  const reasons = [];

  if (/SELL|EXIT|REDUCE|DO_NOT_ADD|PASS|AVOID/.test(longAction) || longMarket === 'AVOID') {
    reasons.push('weaker long-term suitability');
  }
  if (/SELL|EXIT|REDUCE|DO_NOT_ADD|PASS|AVOID/.test(shortAction) || shortMarket === 'AVOID') {
    reasons.push('weaker short-term setup');
  } else if (/WAIT|NO_ACTION|HOLD/.test(shortAction) || shortMarket === 'WATCH') {
    reasons.push('no strong short-term entry edge');
  }
  const weight = safeNumber(item?.holding?.weightPct);
  if (weight !== null && weight >= 20) reasons.push('meaningful portfolio concentration');
  if (!reasons.length) reasons.push('weaker combined forward outlook than the positions NOMAD is preserving');

  return 'NOMAD ranks this position lower on ' + reasons.slice(0, 3).join(', ') + '.';
}

function askNomadPreserveReason(item) {
  const longAction = String(item?.long?.personalAction || '').toUpperCase();
  const shortAction = String(item?.short?.personalAction || '').toUpperCase();
  if (/BUY|ADD|ACCUMULATE/.test(longAction)) return 'Stronger long-term portfolio fit under the Investor brain.';
  if (/BUY|ADD/.test(shortAction)) return 'Current Trader setup remains comparatively stronger.';
  return 'Ranks stronger than the positions selected to fund the cash requirement.';
}

async function askNomadBuildLiquidityPlan(portfolio, cashNeed, risk) {
  const holdings = Array.isArray(portfolio?.holdings)
    ? portfolio.holdings.filter(h => h?.symbol && safeNumber(h.quantity) > 0 && safeNumber(h.currentValue) > 0)
    : [];
  const currentHoldingMap = askNomadCurrentHoldingMap(portfolio);

  const [longResults, shortResults] = await Promise.all([
    askNomadRunHoldingStrategies(portfolio, 'long_term', risk),
    askNomadRunHoldingStrategies(portfolio, 'short_term', risk)
  ]);
  const longMap = new Map(longResults.filter(x => x?.status === 'OK').map(x => [normalizeSymbol(x?.identity?.symbol || x?.input?.symbol), askNomadStrategyCard(x)]));
  const shortMap = new Map(shortResults.filter(x => x?.status === 'OK').map(x => [normalizeSymbol(x?.identity?.symbol || x?.input?.symbol), askNomadStrategyCard(x)]));

  const ranked = holdings.map(h => {
    const symbol = normalizeSymbol(h.symbol);
    const l = longMap.get(symbol) || null;
    const t = shortMap.get(symbol) || null;
    const currentValue = safeNumber(h.currentValue) || 0;
    const currentPrice = safeNumber(h.currentPrice) || 0;
    const quantity = safeNumber(h.quantity) || 0;
    const weakness = askNomadActionWeakness(l?.personalAction, l?.marketAction) * 2 + askNomadActionWeakness(t?.personalAction, t?.marketAction);
    return {symbol, holding:h, long:l, short:t, currentValue, currentPrice, quantity, weakness};
  }).sort((a,b) => b.weakness - a.weakness || b.currentValue - a.currentValue);

  let remaining = Math.max(0, cashNeed || 0);
  const reductions = [];
  for (const item of ranked) {
    if (remaining <= 0.01) break;
    if (!currentHoldingMap.has(item.symbol)) continue;
    // Never manufacture a sale of a holding that both locked brains actively prefer to buy/add.
    if (item.weakness < 1) continue;
    if (!(item.currentPrice > 0) || !(item.quantity > 0)) continue;

    const targetValue = Math.min(item.currentValue, remaining);
    const shares = Math.min(item.quantity, Math.max(1, Math.ceil(targetValue / item.currentPrice)));
    if (!(shares > 0)) continue;
    const amountPkr = decisionRound(shares * item.currentPrice, 2);
    if (!(amountPkr > 0)) continue;

    reductions.push({
      symbol:item.symbol,
      shares:decisionRound(shares, 6),
      amountPkr,
      fullExit:shares >= item.quantity - 0.000001,
      longAction:item.long?.personalAction || 'UNAVAILABLE',
      shortAction:item.short?.personalAction || 'UNAVAILABLE',
      reason:askNomadCombinedReason(item)
    });
    remaining = Math.max(0, decisionRound(remaining - amountPkr, 2));
  }

  // Hard integrity check: every recommendation must still exist in the freshly rebuilt portfolio
  // and cannot exceed owned quantity.
  for (const reduction of reductions) {
    const holding = currentHoldingMap.get(reduction.symbol);
    if (!holding || safeNumber(holding.quantity) === null || reduction.shares - safeNumber(holding.quantity) > 0.000001) {
      throw new Error('Portfolio changed while NOMAD was building the plan. Please run the question again so I can use the latest holdings.');
    }
  }

  const reducedSymbols = new Set(reductions.map(r => r.symbol));
  const preserved = ranked
    .filter(item => !reducedSymbols.has(item.symbol))
    .slice(0, 4)
    .map(item => ({
      symbol:item.symbol,
      longAction:item.long?.personalAction || 'UNAVAILABLE',
      shortAction:item.short?.personalAction || 'UNAVAILABLE',
      reason:askNomadPreserveReason(item)
    }));

  const raised = decisionRound(reductions.reduce((sum, row) => sum + (safeNumber(row.amountPkr) || 0), 0), 2);
  const excess = decisionRound(Math.max(0, raised - cashNeed), 2);

  return {cashNeed, reductions, raised, excess, remaining, preserved, longResults, shortResults};
}

async function runAskNomad(input) {
  const message = askNomadNormalizeText(input?.message);
  if (!message) bad('Ask NOMAD a question first.');
  if (message.length > 1200) bad('Keep one Ask NOMAD question under 1,200 characters.');

  const requestedRisk = String(input?.risk || 'balanced');
  if (!DECISION_RISK_POLICIES[requestedRisk]) bad('Select a valid risk profile.');

  // Always rebuild the effective portfolio for a new chat answer. Supabase GETs
  // are no-store, so deleted/closed positions cannot survive as recommendation input.
  const [market, portfolio] = await Promise.all([
    loadPSXMarket(),
    getPortfolioSnapshot().catch(() => ({configured:false, holdings:[], summary:null, health:null}))
  ]);
  const currentHoldingSymbols = new Set(
    (portfolio?.holdings || [])
      .filter(item => safeNumber(item?.quantity) > 0)
      .map(item => normalizeSymbol(item.symbol))
      .filter(Boolean)
  );

  let symbols = askNomadFindSymbols(message, market);
  const contextSymbols = Array.isArray(input?.contextSymbols)
    ? input.contextSymbols.map(normalizeSymbol).filter(Boolean).slice(0, 2)
    : [];
  if (!symbols.length && /\b(it|that stock|this stock|that one|this one|same stock)\b/i.test(message)) {
    symbols = contextSymbols;
  }
  const horizon = askNomadInferHorizon(message, String(input?.horizon || 'long_term'));
  const intent = askNomadClassifyIntent(message, symbols);
  const explicitCapital = safeNumber(input?.capital) || askNomadExtractCapital(message);
  const basis = {
    marketSource: 'Official PSX Data Portal',
    marketAsOf: market?.marketWatchAsOf || market?.asOf || null,
    portfolioLoaded: portfolio?.configured === true,
    horizon,
    risk: requestedRisk,
    engines: []
  };

  if (intent === 'LIQUIDITY_PLAN') {
    if (!portfolio?.configured || !(portfolio?.holdings || []).length) {
      return {status:'NEEDS_INPUT',build:VERSION,intent,basis,answer:{headline:'I need your portfolio before I can build this cash plan.',summary:'Add your holdings or transactions first. I will not guess what you own.',bullets:[]},needs:{portfolio:true},cards:[]};
    }
    const cashNeed = askNomadExtractCapital(message);
    if (cashNeed === null || cashNeed <= 0) {
      return {status:'NEEDS_INPUT',build:VERSION,intent,basis,answer:{headline:'How much cash do you need?',summary:'Include the PKR amount in your question so I can calculate which holdings, if any, should fund it.',bullets:[]},needs:{capital:true},cards:[]};
    }
    const plan = await askNomadBuildLiquidityPlan(portfolio, cashNeed, requestedRisk);
    basis.horizon = 'mixed';
    basis.engines.push('Portfolio intelligence','Long-term Investor brain','Short-term Trader brain','Portfolio suitability engine');
    const raised = plan.raised;
    const cards = plan.reductions
      .filter(r => currentHoldingSymbols.has(normalizeSymbol(r.symbol)))
      .map(r => ({type:'allocation',symbol:r.symbol,shares:r.shares,amountPkr:r.amountPkr,personalAction:r.fullExit?'SELL':'REDUCE',note:r.reason}));
    const keepText = plan.preserved.length ? plan.preserved.map(x => x.symbol).join(', ') : null;
    const preserveDetails = plan.preserved.slice(0,4).map(x => x.symbol + ': ' + x.reason);
    return {
      status:'OK',build:VERSION,intent,basis,
      answer:{
        headline: plan.remaining <= 1 ? 'Here is the cleanest way NOMAD found to raise '+askNomadMoney(cashNeed)+'.' : 'NOMAD would not force enough selling to raise the full '+askNomadMoney(cashNeed)+'.',
        summary: plan.reductions.length ? 'I ranked your holdings using both the locked Investor and Trader brains, then used the weaker eligible positions first. Stronger holdings were preserved rather than simply selling your worst performer.' : 'None of your holdings currently passes a strong enough reduce/sell test for NOMAD to manufacture a liquidation plan.',
        bullets:[
          plan.reductions.length ? 'Estimated cash raised: '+askNomadMoney(raised)+(plan.excess > 0 ? ' · '+askNomadMoney(plan.excess)+' above target because shares trade in whole units.' : '') : null,
          plan.remaining > 1 ? 'Still required: '+askNomadMoney(plan.remaining)+' — NOMAD will not force a weaker sale just to fill the target.' : 'Keep the raised amount in cash because you said it is required within 30 days; do not reallocate that cash unless your objective changes.',
          keepText ? 'Preserve first: '+keepText : null,
          'Estimated proceeds are before taxes/charges unless verified transaction-cost data is available in your records.',
          ...preserveDetails
        ].filter(Boolean)
      },
      cards,
      plan:{cashNeed,raised,excess:plan.excess,remaining:plan.remaining,reductions:plan.reductions,preserved:plan.preserved,keepRaisedCash:true},
      disclaimer:'NOMAD used current portfolio and market evidence; no order is placed.'
    };
  }

  if (intent === 'MARKET_OUTLOOK') {
    const summary = askNomadMarketSummary(market);
    basis.engines.push('Market breadth engine');
    const tone = summary.breadthPct === null ? 'mixed' : summary.breadthPct >= 58 ? 'constructive' : summary.breadthPct <= 42 ? 'weak' : 'mixed';
    return {
      status:'OK', build:VERSION, intent, basis,
      answer:{
        headline:'PSX session looks ' + tone + '.',
        summary: summary.advancers + ' stocks are advancing versus ' + summary.decliners + ' declining in NOMAD\'s current eligible market snapshot. ' + (tone === 'constructive' ? 'Breadth is supportive, but stock selection and entry quality still matter.' : tone === 'weak' ? 'Breadth is defensive, so NOMAD would demand stronger individual setups before adding risk.' : 'There is no broad directional edge strong enough to replace stock-by-stock analysis.'),
        bullets:[
          'Advancers: ' + summary.advancers + ' · Decliners: ' + summary.decliners + ' · Unchanged: ' + summary.unchanged,
          summary.leaders.length ? 'Leaders: ' + summary.leaders.map(x => x.symbol + ' ' + askNomadPct(x.changePct)).join(', ') : null,
          summary.laggards.length ? 'Laggards: ' + summary.laggards.map(x => x.symbol + ' ' + askNomadPct(x.changePct)).join(', ') : null
        ].filter(Boolean)
      },
      cards:[], marketSummary:summary,
      disclaimer:'NOMAD is decision intelligence; no order is placed.'
    };
  }

  if (intent === 'CAPITAL_DECISION') {
    if (explicitCapital === null || explicitCapital <= 0) {
      return {
        status:'NEEDS_INPUT', build:VERSION, intent, basis,
        answer:{headline:'How much new capital should NOMAD evaluate?', summary:'I will not invent a capital amount. Include the PKR amount in your question, then I can run the full Decision Center allocator against your current portfolio.', bullets:[]},
        needs:{capital:true}, cards:[]
      };
    }
    const decision = await runDecisionLab({amount:explicitCapital, horizon, risk:requestedRisk, sector:String(input?.sector || '')});
    basis.engines.push(horizon === 'short_term' ? 'Short-term Trader brain' : 'Long-term Investor brain', 'Decision Center allocator', 'Portfolio-fit engine');
    const allocations = (decision?.allocations || []).map(a => ({type:'allocation',symbol:a.symbol,shares:a.shares,amountPkr:a.principalPkr,marketAction:a.marketView || a.decisionCenterView || null,personalAction:a.portfolioAction || null,note:a.note || ''}));
    return {
      status:'OK', build:VERSION, intent, basis,
      answer:{
        headline: decision?.decision?.action === 'INVEST' ? 'NOMAD would deploy most of this capital.' : decision?.decision?.action === 'PARTIAL_INVEST' ? 'NOMAD would deploy only part of this capital.' : 'NOMAD would keep this capital in cash for now.',
        summary: decision?.decision?.headline || decision?.decision?.reason || 'Decision Center completed.',
        bullets:[
          'Capital evaluated: ' + askNomadMoney(explicitCapital),
          'Deploy now: ' + askNomadMoney(decision?.decision?.amountInvestedPkr),
          horizon === 'short_term' && safeNumber(decision?.shortTermTriggerPlan?.reservedPkr) !== null ? 'Reserved for valid triggers: ' + askNomadMoney(decision.shortTermTriggerPlan.reservedPkr) : null,
          'Cash remaining: ' + askNomadMoney(decision?.decision?.cashRemainingPkr)
        ].filter(Boolean)
      },
      cards:allocations,
      decision:{action:decision?.decision?.action, amountInvestedPkr:decision?.decision?.amountInvestedPkr, cashRemainingPkr:decision?.decision?.cashRemainingPkr, reason:decision?.decision?.reason},
      disclaimer:'Shadow decision intelligence only; no order is placed.'
    };
  }

  if (intent === 'STOCK_ANALYSIS' || intent === 'COMPARE_STOCKS') {
    const targets = symbols.slice(0, intent === 'COMPARE_STOCKS' ? 2 : 1);
    const results = [];
    for (const symbol of targets) results.push(await runSingleStockStrategy({symbol, horizon, risk:requestedRisk}));
    basis.engines.push(horizon === 'short_term' ? 'Short-term Trader brain' : 'Long-term Investor brain', 'Portfolio suitability engine');
    const cards = results.map(askNomadStrategyCard);
    if (intent === 'COMPARE_STOCKS') {
      const a=cards[0], b=cards[1];
      return {status:'OK',build:VERSION,intent,basis,answer:{headline:a.symbol+' vs '+b.symbol,summary:'NOMAD ran the same '+(horizon==='short_term'?'Trader':'Investor')+' framework on both companies under your '+requestedRisk+' profile. The market view and your personal action remain separate.',bullets:[a.symbol+': Market '+a.marketAction+' · For you '+a.personalAction,b.symbol+': Market '+b.marketAction+' · For you '+b.personalAction]},cards,disclaimer:'No order is placed.'};
    }
    const c=cards[0];
    return {status:'OK',build:VERSION,intent,basis,answer:{headline:c.symbol+': Market '+c.marketAction+' · For you '+c.personalAction,summary:c.personalReason || results[0]?.professional?.reason || 'Analysis completed.',bullets:[c.dayChangePct!==null?'Today: '+askNomadPct(c.dayChangePct)+' at '+askNomadMoney(c.price):null,c.setup?'Setup: '+c.setup:null,c.entryLow!==null?'Entry: '+c.entryLow+(c.entryHigh!==null?'–'+c.entryHigh:''):null,c.stop!==null?'Stop: '+c.stop:null,c.target!==null?'Target: '+c.target:null,c.rewardRisk!==null?'Reward/risk: '+decisionRound(c.rewardRisk,2)+':1':null].filter(Boolean)},cards,disclaimer:'No order is placed.'};
  }

  if (intent === 'PORTFOLIO_REVIEW' || intent === 'PORTFOLIO_ACTIONS') {
    if (!portfolio?.configured || !(portfolio?.holdings || []).length) {
      return {status:'NEEDS_INPUT',build:VERSION,intent,basis,answer:{headline:'Your portfolio is empty in NOMAD.',summary:'Add holdings or transactions first. I will not guess what you own.',bullets:[]},needs:{portfolio:true},cards:[]};
    }
    const strategies = await askNomadRunHoldingStrategies(portfolio, horizon, requestedRisk);
    basis.engines.push('Portfolio intelligence', horizon === 'short_term' ? 'Short-term Trader brain' : 'Long-term Investor brain', 'Portfolio suitability engine');
    const cards = strategies.filter(x => x?.status === 'OK').map(askNomadStrategyCard);
    const actions = cards.filter(c => !['HOLD','WAIT','NO_ACTION_YET','UNAVAILABLE'].includes(c.personalAction));
    const topGain = (portfolio.holdings || []).slice().sort((a,b)=>(safeNumber(b.dayPnlPct)||-999)-(safeNumber(a.dayPnlPct)||-999))[0];
    const topLoss = (portfolio.holdings || []).slice().sort((a,b)=>(safeNumber(a.dayPnlPct)||999)-(safeNumber(b.dayPnlPct)||999))[0];
    const summary = portfolio.summary || {};
    const health = portfolio.health || {};
    const headline = 'Portfolio ' + (safeNumber(summary.dayPnlPct) > 0 ? 'is up ' : safeNumber(summary.dayPnlPct) < 0 ? 'is down ' : 'is flat ') + (safeNumber(summary.dayPnlPct) !== null ? Math.abs(decisionRound(summary.dayPnlPct,2))+'% today.' : 'today.');
    return {
      status:'OK',build:VERSION,intent,basis,
      answer:{headline,summary: intent==='PORTFOLIO_ACTIONS' ? (actions.length ? 'NOMAD found '+actions.length+' holding'+(actions.length===1?'':'s')+' where your current personal action is stronger than a simple HOLD/WAIT. Review the cards below; the engine result, not the chat layer, drives each action.' : 'NOMAD did not find a holding that currently warrants a stronger personal action than HOLD/WAIT under this profile.') : 'Current value is '+askNomadMoney(summary.currentValue)+' with total P&L of '+askNomadMoney(summary.totalPnl)+'. NOMAD re-ran the '+(horizon==='short_term'?'Trader':'Investor')+' brain across your holdings before answering.',bullets:[topGain?.symbol?'Best today: '+topGain.symbol+' '+askNomadPct(topGain.dayPnlPct):null,topLoss?.symbol?'Weakest today: '+topLoss.symbol+' '+askNomadPct(topLoss.dayPnlPct):null,health?.largestPositionSymbol?'Largest position: '+health.largestPositionSymbol+' '+decisionRound(health.largestPositionPct,1)+'%':null,health?.largestSector?'Largest sector: '+health.largestSector+' '+decisionRound(health.largestSectorPct,1)+'%':null].filter(Boolean)},
      cards, portfolio:{summary,health}, disclaimer:'NOMAD re-ran its engines before answering; no order is placed.'
    };
  }

  return {
    status:'NEEDS_INPUT', build:VERSION, intent, basis,
    answer:{headline:'I need a more specific investment question.',summary:'Ask about your portfolio, a PSX stock, the market, or a capital decision. I will route it through the relevant NOMAD engine rather than guess.',bullets:['Example: “How does my portfolio look today?”','Example: “Should I buy or sell anything?”','Example: “How does PRL look today?”','Example: “Where should I invest PKR 100,000?”']},
    cards:[]
  };
}

async function runSingleStockStrategy(
  input
) {
  const requestedSymbol =
    normalizeSymbol(
      input?.symbol
    );

  const horizon =
    String(
      input?.horizon ||
      'long_term'
    );

  const risk =
    String(
      input?.risk ||
      'balanced'
    );

  if (!requestedSymbol) {
    bad(
      'Enter a PSX symbol to analyze.'
    );
  }

  const model =
    DECISION_MODELS[
      horizon
    ];

  const riskPolicy =
    DECISION_RISK_POLICIES[
      risk
    ];

  if (!model) {
    bad(
      'Select a valid investment horizon.'
    );
  }

  if (!riskPolicy) {
    bad(
      'Select a valid risk profile.'
    );
  }

  const symbolContext =
    await resolveSymbolContext(
      requestedSymbol
    );

  const canonicalSymbol =
    normalizeSymbol(
      symbolContext?.canonicalSymbol ||
      symbolContext?.tradingSymbol ||
      requestedSymbol
    );

  const [
    market,
    memoryRows
  ] =
    await Promise.all([
      loadPSXMarket(),
      continuousMemoryConfigured()
        ? readAllSecurityMemory()
            .catch(
              () => []
            )
        : Promise.resolve([])
    ]);

  const marketRow =
    (market.stocks || [])
      .find(
        row =>
          normalizeSymbol(
            row.symbol
          ) ===
            canonicalSymbol ||
          normalizeSymbol(
            row.rawMarketSymbol
          ) ===
            canonicalSymbol
      ) ||
    null;

  if (!marketRow) {
    bad(
      canonicalSymbol +
      ' is not available in the current Official PSX market universe.'
    );
  }

  const eligibleRows =
    (market.stocks || [])
      .filter(
        row =>
          row.recommendationEligible ===
            true &&
          safeNumber(
            row.price
          ) !== null &&
          safeNumber(
            row.price
          ) > 0
      );

  const memoryMap =
    new Map(
      (memoryRows || [])
        .map(
          row => [
            normalizeSymbol(
              row.symbol
            ),
            row
          ]
        )
    );

  const historicalContext =
    await decisionHistoricalContext(
      marketRow,
      memoryMap
    );

  const valuation =
    scoreDecisionValuation(
      marketRow,
      eligibleRows
    );

  const entry =
    scoreDecisionEntry(
      historicalContext,
      horizon,
      riskPolicy
    );

  const riskScore =
    scoreDecisionRisk(
      marketRow,
      historicalContext,
      eligibleRows
    );

  const fundamentalEvidence =
    await decisionLoadFundamentals(
      marketRow,
      memoryMap
    );

  const fundamentals =
    fundamentalEvidence
      .fundamentals;

  const fundamental =
    scoreDecisionFundamentals(
      fundamentals
    );

  fundamental.evidenceState =
    fundamentalEvidence
      .evidenceState;

  fundamental.cachedAt =
    fundamentalEvidence
      .cachedAt;

  if (
    fundamentalEvidence.error
  ) {
    fundamental.risks =
      uniqueTextValues([
        ...(
          fundamental.risks ||
          []
        ),
        fundamentalEvidence.error
      ]);
  }

  const dataQuality =
    scoreDecisionDataQuality(
      marketRow,
      historicalContext,
      fundamental
    );

  const overallScore =
    decisionOverallScore(
      model,
      fundamental,
      valuation,
      entry,
      riskScore,
      dataQuality
    );

  const candidate = {
    horizon,
    riskProfile:
      risk,
    recommendationEligible:
      marketRow.recommendationEligible ===
        true,
    symbol:
      canonicalSymbol,
    companyName:
      marketRow.companyName ||
      symbolContext?.companyName ||
      canonicalSymbol,
    sector:
      marketRow.sector ||
      symbolContext?.sector ||
      'Unknown',
    statusCodes:
      marketRow.statusCodes ||
      [],
    price:
      decisionRound(
        marketRow.price,
        4
      ),
    marketAsOf:
      marketRow.asOf ||
      market.marketWatchAsOf ||
      market.asOf ||
      null,
    averageVolume30d:
      decisionRound(
        marketRow.averageVolume30d,
        0
      ),
    historicalContext,
    fundamental,
    analystCore:
      fundamentals?.analystCore ||
      null,
    fundamentalEvidenceState:
      fundamentalEvidence
        .evidenceState,
    fundamentalEvidenceDiagnostics:
      fundamentalEvidence
        .diagnostics ||
      null,
    valuation,
    entry,
    risk:
      riskScore,
    dataQuality,
    overallScore
  };

  const legacyAction =
    decisionCandidateAction(
      candidate,
      model,
      riskPolicy
    );

  candidate.action =
    legacyAction.action;

  candidate.actionReason =
    legacyAction.reason;

  candidate.narrative =
    decisionCandidateNarrative(
      candidate
    );

  candidate.canonicalState =
    decisionCanonicalCompanyState(
      candidate
    );

  const profileSuitability =
    decisionProfileSuitability(
      candidate,
      riskPolicy
    );

  candidate.profileSuitability =
    profileSuitability;

  candidate.shortTermExecution =
    horizon === 'short_term'
      ? shortTermProfileExecutionDecision(
          candidate,
          riskPolicy
        )
      : null;

  candidate.executionGuidance =
    decisionExecutionGuidance(
      candidate,
      riskPolicy
    );

  const suitabilityIssues =
    profileSuitability.issues;

  const riskSuitability =
    profileSuitability.state;

  const portfolioContext =
    await buildDecisionPortfolioContext(
      market
    );

  const existingValue =
    safeNumber(
      portfolioContext
        ?.symbolValues
        ?.[canonicalSymbol]
    ) ||
    0;

  const portfolioValue =
    safeNumber(
      portfolioContext
        ?.currentValuePkr
    ) ||
    0;

  const existingWeightPct =
    portfolioValue > 0
      ? existingValue /
        portfolioValue *
        100
      : 0;

  const canonical =
    candidate.canonicalState;

  let personalAction =
    canonical.marketAction;

  let personalReason =
    canonical.reason;

  if (
    canonical.researchState ===
      'ACTIVE'
  ) {
    personalAction =
      existingValue > 0
        ? 'HOLD_RESEARCH'
        : 'NO_ACTION_YET';
    personalReason =
      canonical.reason;
  } else if (
    riskSuitability ===
      'NOT_SUITABLE'
  ) {
    personalAction =
      'DO_NOT_ADD';
    personalReason =
      suitabilityIssues.join(' ');
  } else if (
    horizon === 'short_term' &&
    existingValue <= 0 &&
    canonical.marketAction ===
      'WATCH'
  ) {
    personalAction = 'WAIT';
    personalReason =
      canonical.reason;
  } else if (
    existingValue > 0
  ) {
    if (
      canonical.marketAction ===
        'BUY' ||
      canonical.marketAction ===
        'ACCUMULATE'
    ) {
      if (
        existingWeightPct >=
          riskPolicy.maxStockPct *
          100
      ) {
        personalAction =
          'DO_NOT_ADD';
        personalReason =
          'The market thesis is actionable, but your existing position already reaches the selected profile\'s hard single-stock ceiling.';
      } else {
        personalAction =
          'ADD_CANDIDATE';
        personalReason =
          'You already own this company and the current professional state remains actionable for the selected profile.';
      }
    } else if (
      canonical.marketAction ===
        'WATCH'
    ) {
      personalAction =
        'HOLD';
      personalReason =
        'You already own the stock. The current thesis does not justify adding new capital, but it does not independently trigger an exit.';
    } else if (
      canonical.marketAction ===
        'AVOID'
    ) {
      personalAction =
        'REVIEW_REDUCE';
      personalReason =
        'You already own the stock and the current professional framework is unfavorable. Review the original thesis before deciding whether to reduce or exit.';
    }
  }

  const priceAction =
    historicalContext
      ?.priceAction ||
    null;

  const strategyTraderPlanSelection =
    horizon === 'short_term'
      ? decisionTraderCanonicalPlan(
          canonical.professional ||
          {},
          candidate.shortTermExecution
        )
      : null;

  const strategyTraderPlan =
    strategyTraderPlanSelection
      ?.plan ||
    priceAction?.tradePlan ||
    null;

  const volatility =
    safeNumber(
      historicalContext
        ?.technical
        ?.annualizedVolatility20dPct
    );

  const avgVolume =
    safeNumber(
      candidate.averageVolume30d
    );

  return {
    status: 'OK',
    build: VERSION,
    engineMode: 'SHADOW',
    realMoneyEligible: false,
    input: {
      requestedSymbol,
      symbol:
        canonicalSymbol,
      horizon,
      risk
    },
    identity: {
      symbol:
        canonicalSymbol,
      companyName:
        candidate.companyName,
      sector:
        candidate.sector,
      statusCodes:
        candidate.statusCodes,
      recommendationEligible:
        marketRow.recommendationEligible ===
        true
    },
    market: {
      price:
        candidate.price,
      dayChangePct:
        decisionRound(
          marketRow.dayChangePct,
          2
        ),
      asOf:
        candidate.marketAsOf,
      source:
        'Official PSX Data Portal screener'
    },
    professional: {
      ...canonical.professional,
      marketAction:
        canonical.marketAction,
      opportunityTier:
        canonical.opportunityTier,
      allocationAllowed:
        canonical.allocationPermission
          ?.allowed === true
    },
    personal: {
      action:
        personalAction,
      reason:
        personalReason,
      hasPosition:
        existingValue > 0,
      currentPositionValuePkr:
        decisionRound(
          existingValue,
          2
        ),
      currentPortfolioWeightPct:
        decisionRound(
          existingWeightPct,
          2
        ),
      portfolioValuePkr:
        decisionRound(
          portfolioValue,
          2
        )
    },
    riskSuitability: {
      ...profileSuitability,
      profile:
        risk
    },
    execution:
      candidate.executionGuidance ||
      null,
    evidence:
      canonical.evidence,
    financial: {
      analystStatus:
        candidate.analystCore
          ?.status ||
        'UNAVAILABLE',
      overall:
        candidate.analystCore
          ?.overallFinancialView
          ?.state ||
        'UNAVAILABLE',
      headlineView:
        candidate.analystCore
          ?.overallFinancialView
          ?.state ||
        'UNAVAILABLE',
      deepValidation:
        safeNumber(
          candidate.analystCore
            ?.coverage
            ?.extendedCoveragePct
        ) >= 67
          ? 'VALIDATED'
          : safeNumber(
              candidate.analystCore
                ?.coverage
                ?.extendedCoveragePct
            ) > 0
            ? 'PARTIAL'
            : 'INCOMPLETE',
      earningsQuality:
        candidate.analystCore
          ?.views
          ?.earningsQuality
          ?.state ||
        'UNAVAILABLE',
      cashFlowQuality:
        candidate.analystCore
          ?.views
          ?.cashFlowQuality
          ?.state ||
        'UNAVAILABLE',
      balanceSheet:
        candidate.analystCore
          ?.views
          ?.balanceSheet
          ?.state ||
        'UNAVAILABLE',
      fundamentalScore:
        candidate.fundamental
          ?.score ??
        null
    },
    valuation: {
      state:
        canonical.professional
          ?.valuationState ||
        'UNAVAILABLE',
      score:
        candidate.valuation
          ?.score ??
        null,
      peRatio:
        candidate.valuation
          ?.peRatio ??
        null,
      dividendYield:
        candidate.valuation
          ?.dividendYield ??
        null
    },
    risk: {
      state:
        canonical.professional
          ?.riskState ||
        'UNAVAILABLE',
      score:
        candidate.risk
          ?.score ??
        null,
      annualizedVolatility20dPct:
        volatility,
      maxDrawdown52wPct:
        historicalContext
          ?.technical
          ?.maxDrawdown52wPct ??
        null,
      averageVolume30d:
        avgVolume
    },
    performance: {
      todayPct:
        decisionRound(
          marketRow.dayChangePct,
          2
        ),
      d5Pct:
        historicalContext
          ?.returns
          ?.d5 ??
        null,
      m1Pct:
        historicalContext
          ?.returns
          ?.m1 ??
        null,
      m3Pct:
        historicalContext
          ?.returns
          ?.m3 ??
        null,
      m6Pct:
        historicalContext
          ?.returns
          ?.m6 ??
        null,
      y1Pct:
        historicalContext
          ?.returns
          ?.y1 ??
        null
    },
    technical: {
      trend:
        historicalContext
          ?.trend ||
        'UNAVAILABLE',
      timingState:
        canonical.professional
          ?.timingState ||
        priceAction?.timingState ||
        'UNAVAILABLE',
      timingScore:
        canonical.professional
          ?.timingScore ??
        priceAction?.timingScore ??
        null,
      setup:
        priceAction?.setup ||
        'NO_CLEAR_SETUP',
      candlePattern:
        priceAction
          ?.candlePattern
          ?.label ||
        'NONE',
      candlePolarity:
        priceAction
          ?.candlePattern
          ?.polarity ||
        'NEUTRAL',
      support:
        priceAction?.support ??
        null,
      resistance:
        priceAction?.resistance ??
        null,
      rewardRisk:
        strategyTraderPlan
          ?.rewardRisk ??
        priceAction?.rewardRisk ??
        null,
      entryLow:
        strategyTraderPlan
          ?.entryLow ??
        null,
      entryHigh:
        strategyTraderPlan
          ?.entryHigh ??
        null,
      stop:
        strategyTraderPlan
          ?.stop ??
        null,
      target1:
        strategyTraderPlan
          ?.target1 ??
        null,
      target2:
        strategyTraderPlan
          ?.target2 ??
        null,
      riskPerShare:
        strategyTraderPlan
          ?.riskPerShare ??
        null,
      riskPct:
        strategyTraderPlan
          ?.riskPct ??
        null,
      targetSource:
        strategyTraderPlan
          ?.targetSource ||
        null,
      tradePlanState:
        strategyTraderPlan
          ?.state ||
        'INCOMPLETE',
      invalidation:
        strategyTraderPlan
          ?.invalidation ||
        null,
      conditionalPlanState:
        priceAction?.conditionalTradePlan
          ?.state ||
        null,
      conditionalActivation:
        priceAction?.conditionalTradePlan
          ?.activation ||
        null,
      conditionalEntryLow:
        priceAction?.conditionalTradePlan
          ?.entryLow ??
        null,
      conditionalEntryHigh:
        priceAction?.conditionalTradePlan
          ?.entryHigh ??
        null,
      conditionalStop:
        priceAction?.conditionalTradePlan
          ?.stop ??
        null,
      conditionalTarget1:
        priceAction?.conditionalTradePlan
          ?.target1 ??
        null,
      conditionalTarget2:
        priceAction?.conditionalTradePlan
          ?.target2 ??
        null,
      conditionalRewardRisk:
        priceAction?.conditionalTradePlan
          ?.rewardRisk ??
        null,
      structureBias:
        priceAction?.structure
          ?.bias ||
        'UNAVAILABLE',
      atr14:
        priceAction?.atr14 ??
        null,
      atrPct:
        priceAction?.atrPct ??
        null,
      rsi14:
        historicalContext
          ?.technical
          ?.rsi14 ??
        null,
      macdHistogram:
        historicalContext
          ?.technical
          ?.macdHistogram ??
        null,
      volumeRatio20d:
        historicalContext
          ?.technical
          ?.volumeRatio20d ??
        null,
      positives:
        priceAction?.positives ||
        [],
      risks:
        priceAction?.risks ||
        []
    },
    reasons: {
      thesis:
        canonical.reason,
      positives:
        horizon === 'short_term'
          ? priceAction?.positives ||
            []
          : candidate.narrative
              ?.positives ||
            [],
      risks:
        horizon === 'short_term'
          ? priceAction?.risks ||
            []
          : candidate.narrative
              ?.risks ||
            []
    },
    diagnostics: {
      overallScore,
      dataQualityScore:
        dataQuality.score,
      legacyAction:
        candidate.action,
      fundamentalEvidenceState:
        candidate.fundamentalEvidenceState
    },
    warnings: [
      'This is shadow decision intelligence, not a trade instruction.',
      'The single-stock strategy view does not place orders.'
    ]
  };
}

async function runDecisionLab(
  input
) {
  const amount =
    safeNumber(
      input?.amount
    );

  const horizon =
    String(
      input?.horizon ||
      'long_term'
    );

  const risk =
    String(
      input?.risk ||
      'balanced'
    );

  const requestedSector =
    String(
      input?.sector ||
      ''
    ).trim();

  if (
    amount === null ||
    amount <= 0 ||
    amount > 100000000000
  ) {
    bad(
      'Enter a valid positive PKR amount.'
    );
  }

  const model =
    DECISION_MODELS[
      horizon
    ];

  const riskPolicy =
    DECISION_RISK_POLICIES[
      risk
    ];

  if (!model) {
    bad(
      'Select a valid investment horizon.'
    );
  }

  if (!riskPolicy) {
    bad(
      'Select a valid risk profile.'
    );
  }

  const startedAt =
    new Date()
      .toISOString();

  const [
    market,
    memoryRows
  ] =
    await Promise.all([
      loadPSXMarket(),
      continuousMemoryConfigured()
        ? readAllSecurityMemory()
            .catch(
              () => []
            )
        : Promise.resolve([])
    ]);

  const portfolioContext =
    await buildDecisionPortfolioContext(
      market
    );

  const availableSectors =
    [
      ...new Set(
        (market.stocks || [])
          .map(
            row =>
              String(
                row.sector ||
                ''
              ).trim()
          )
          .filter(
            sector =>
              sector &&
              sector.toUpperCase() !==
                'UNKNOWN'
          )
      )
    ].sort();

  const selectedSector =
    requestedSector
      ? availableSectors.find(
          sector =>
            sector.toLowerCase() ===
            requestedSector.toLowerCase()
        ) || null
      : null;

  if (
    requestedSector &&
    !selectedSector
  ) {
    bad(
      'Select a valid PSX industry/sector.'
    );
  }

  const scopedMarketRows =
    selectedSector
      ? (market.stocks || []).filter(
          row =>
            String(
              row.sector ||
              ''
            ).trim() ===
            selectedSector
        )
      : market.stocks;

  const researchCapitalBasePkr =
    amount +
    (
      safeNumber(
        portfolioContext?.currentValuePkr
      ) ||
      0
    );

  // Locked professional-PM behavior: the entered capital never changes the
  // ranking, but it does determine how many suitable actionable ideas NOMAD
  // should try to validate before accepting a large cash remainder.
  const researchActionableTarget =
    Math.min(
      8,
      decisionCenterTargetPositionCount(
        researchCapitalBasePkr,
        riskPolicy
      )
    );

  const eligibleRows =
    scopedMarketRows
      .filter(
        row =>
          row.recommendationEligible ===
            true &&
          safeNumber(
            row.price
          ) !== null &&
          safeNumber(
            row.price
          ) > 0
      );

  const affordableRows =
    eligibleRows
      .filter(
        row =>
          safeNumber(
            row.price
          ) <= amount
      );

  // Opportunity ranking is independent of the entered budget. The amount is
  // applied only by the separate whole-share allocator later.
  const liquidityPassed =
    eligibleRows
      .filter(
        row => {
          const volume =
            safeNumber(
              row.averageVolume30d
            );

          return (
            volume !== null &&
            volume >=
              riskPolicy.minAverageVolume30d &&
            !(
              row.statusCodes ||
              []
            ).includes('NC')
          );
        }
      );

  const preScreened =
    liquidityPassed
      .map(
        row => ({
          row,
          screeningScore:
            horizon === 'short_term'
              ? decisionTraderScreeningScore(
                  row,
                  eligibleRows
                )
              : decisionScreeningScore(
                  row,
                  eligibleRows
                )
        })
      )
      .sort(
        (
          a,
          b
        ) =>
          b.screeningScore -
          a.screeningScore
      );

  const shortList = [];
  const sectorCounts =
    new Map();

  for (
    const item
    of preScreened
  ) {
    const sector =
      item.row.sector ||
      'Unknown';

    const count =
      sectorCounts.get(
        sector
      ) ||
      0;

    if (
      !selectedSector &&
      count >=
        DECISION_CENTER_MAX_SHORTLIST_PER_SECTOR
    ) {
      continue;
    }

    shortList.push(
      item
    );

    sectorCounts.set(
      sector,
      count + 1
    );

    const shortlistLimit =
      horizon === 'short_term'
        ? 64
        : DECISION_CENTER_SHORTLIST_LIMIT;

    if (shortList.length >= shortlistLimit) {
      break;
    }
  }

  if (!shortList.length) {
    const emptyResult = {
      status: 'OK',
      build: VERSION,
      engineMode: 'SHADOW',
      validationStatus:
        model.status,
      realMoneyEligible: false,
      startedAt,
      completedAt:
        new Date()
          .toISOString(),
      model,
      riskPolicy: {
        id:
          riskPolicy.id
      },
      input: {
        amount:
          decisionRound(
            amount,
            2
          ),
        horizon,
        risk,
        sector:
          selectedSector
      },
      market: {
        asOf:
          market.marketWatchAsOf ||
          market.asOf ||
          null,
        source:
          'Official PSX Data Portal screener'
      },
      screening: {
        eligibleUniverse:
          eligibleRows.length,
        affordableUniverse:
          affordableRows.length,
        liquidityPassed:
          liquidityPassed.length,
        historicalAnalyzed: 0,
        deepAnalyzed: 0
      },
      decision: {
        action: 'WAIT',
        headline:
          'No investable candidate passed the first safety gates.',
        reason:
          'The current liquidity policy and eligible universe produced no candidate suitable for deeper analysis. The entered amount did not affect opportunity ranking.',
        amountInvestedPkr: 0,
        cashRemainingPkr:
          decisionRound(
            amount,
            2
          ),
        evidenceStrength: 0
      },
      allocations: [],
      candidates: [],
      exclusions: {
        unaffordable:
          eligibleRows.length -
          affordableRows.length,
        liquidityOrStatus:
          eligibleRows.length -
          liquidityPassed.length
      },
      warnings: [
        'This is an experimental shadow decision, not a real-money instruction.',
        'No order-execution capability exists.'
      ]
    };

    emptyResult.recording =
      await recordDecisionRun(
        emptyResult
      );

    return emptyResult;
  }

  const memoryMap =
    new Map(
      memoryRows.map(
        row => [
          normalizeSymbol(
            row.symbol
          ),
          row
        ]
      )
    );

  const historyResults =
    await decisionMapWithConcurrency(
      shortList,
      4,
      async item => {
        const historicalContext =
          await decisionHistoricalContext(
            item.row,
            memoryMap
          );

        const valuation =
          scoreDecisionValuation(
            item.row,
            eligibleRows
          );

        const entry =
          scoreDecisionEntry(
            historicalContext,
            horizon,
            riskPolicy
          );

        const riskScore =
          scoreDecisionRisk(
            item.row,
            historicalContext,
            eligibleRows
          );

        return {
          ...item,
          historicalContext,
          valuation,
          entry,
          risk:
            riskScore,
          deepProxyScore:
            decisionRound(
              horizon === 'short_term'
                ? decisionTraderHistoricalOpportunityScore(
                    historicalContext,
                    item.screeningScore,
                    riskScore.score
                  )
                : (
                    item.screeningScore * 0.30 +
                    valuation.score * 0.20 +
                    entry.score * 0.30 +
                    riskScore.score * 0.20
                  ),
              2
            )
        };
      }
    );

  const historyReady =
    historyResults
      .filter(
        item =>
          item &&
          !item.error &&
          item.historicalContext
            ?.available
      )
      .sort(
        (
          a,
          b
        ) =>
          b.deepProxyScore -
          a.deepProxyScore
      );

  // 0.9.0 adaptive deep-analysis backfill. Missing evidence no longer consumes
  // the entire comparable set: NOMAD keeps moving through the ranked history-ready
  // universe until it reaches the comparable target or exhausts the bounded research budget.
  const deepResults = [];
  const deepAttemptedItems = [];
  let comparableCount = 0;
  let actionableSuitableCount = 0;
  let deepCursor = 0;

  while (
    deepCursor < historyReady.length &&
    deepAttemptedItems.length <
      DECISION_CENTER_DEEP_ATTEMPT_LIMIT &&
    (
      comparableCount <
        DECISION_CENTER_COMPARABLE_TARGET ||
      actionableSuitableCount <
        researchActionableTarget
    )
  ) {
    const remainingAttempts =
      DECISION_CENTER_DEEP_ATTEMPT_LIMIT -
      deepAttemptedItems.length;

    const batch =
      historyReady.slice(
        deepCursor,
        deepCursor +
          Math.min(
            DECISION_CENTER_DEEP_BATCH_SIZE,
            remainingAttempts
          )
      );

    if (!batch.length) {
      break;
    }

    deepCursor +=
      batch.length;

    deepAttemptedItems.push(
      ...batch
    );

    const batchResults =
      await decisionMapWithConcurrency(
        batch,
        4,
        async item => {
          let fundamentalEvidence;
          let fundamentals;
          let fundamental;

          if (horizon === 'short_term') {
            fundamentalEvidence = {
              evidenceState: 'SECONDARY_NOT_REQUIRED',
              cachedAt: null,
              error: null,
              diagnostics: null,
              fundamentals: null
            };
            fundamentals = null;
            fundamental = {
              available: false,
              score: 50,
              coverage: 0,
              metrics: {},
              reasons: [
                'Short-term market action is not gated by financial-statement completeness.'
              ],
              risks: [],
              evidenceState: 'SECONDARY_NOT_REQUIRED',
              cachedAt: null
            };
          } else {
            fundamentalEvidence =
              await decisionLoadFundamentals(
                item.row,
                memoryMap
              );

            fundamentals =
              fundamentalEvidence
                .fundamentals;

            fundamental =
              scoreDecisionFundamentals(
                fundamentals
              );

            fundamental.evidenceState =
              fundamentalEvidence
                .evidenceState;

            fundamental.cachedAt =
              fundamentalEvidence
                .cachedAt;

            if (
              fundamentalEvidence.error
            ) {
              fundamental.risks =
                uniqueTextValues([
                  ...(
                    fundamental.risks ||
                    []
                  ),
                  fundamentalEvidence.error
                ]);
            }
          }

          const traderEvidence =
            horizon === 'short_term'
              ? decisionTraderEvidenceProfile({
                  horizon,
                  historicalContext:
                    item.historicalContext
                })
              : null;

          const dataQuality =
            horizon === 'short_term'
              ? {
                  score:
                    traderEvidence.score,
                  missing:
                    traderEvidence.missing
                }
              : scoreDecisionDataQuality(
                  item.row,
                  item.historicalContext,
                  fundamental
                );

          const overallScore =
            horizon === 'short_term'
              ? decisionRound(
                  decisionClamp(
                    (
                      safeNumber(
                        item.historicalContext
                          ?.priceAction
                          ?.timingScore
                      ) ||
                      item.entry.score
                    ) * 0.55 +
                    item.risk.score * 0.25 +
                    dataQuality.score * 0.20
                  ),
                  2
                )
              : decisionOverallScore(
                  model,
                  fundamental,
                  item.valuation,
                  item.entry,
                  item.risk,
                  dataQuality
                );

          const candidate = {
            horizon,
            recommendationEligible:
              item.row.recommendationEligible ===
                true,
            symbol:
              item.row.symbol,
            companyName:
              item.row.companyName,
            sector:
              item.row.sector,
            statusCodes:
              item.row.statusCodes ||
              [],
            price:
              decisionRound(
                item.row.price,
                4
              ),
            marketAsOf:
              item.row.asOf ||
              market.asOf ||
              null,
            averageVolume30d:
              decisionRound(
                item.row.averageVolume30d,
                0
              ),
            screeningScore:
              item.screeningScore,
            historicalContext:
              item.historicalContext,
            fundamental,
            analystCore:
              fundamentals?.analystCore ||
              null,
            fundamentalEvidenceState:
              fundamentalEvidence
                .evidenceState,
            fundamentalEvidenceDiagnostics:
              fundamentalEvidence
                .diagnostics ||
              null,
            valuation:
              item.valuation,
            entry:
              item.entry,
            risk:
              item.risk,
            dataQuality,
            overallScore
          };

          const action =
            horizon === 'short_term'
              ? {
                  action: 'WAIT',
                  reason:
                    'Legacy weighted action is bypassed in short-term mode; the dedicated Trader brain is authoritative.'
                }
              : decisionCandidateAction(
                  candidate,
                  model,
                  riskPolicy
                );

          candidate.action =
            action.action;

          candidate.actionReason =
            action.reason;

          candidate.narrative =
            decisionCandidateNarrative(
              candidate
            );

          candidate.canonicalState =
            decisionCanonicalCompanyState(
              candidate
            );

          if (horizon === 'short_term') {
            candidate.action =
              candidate.canonicalState
                .marketAction;
            candidate.actionReason =
              candidate.canonicalState
                .reason;
          }

          candidate.profileSuitability =
            decisionProfileSuitability(
              candidate,
              riskPolicy
            );

          candidate.shortTermExecution =
            horizon === 'short_term'
              ? shortTermProfileExecutionDecision(
                  candidate,
                  riskPolicy
                )
              : null;

          candidate.executionGuidance =
            decisionExecutionGuidance(
              candidate,
              riskPolicy
            );

          return candidate;
        }
      );

    deepResults.push(
      ...batchResults
    );

    comparableCount =
      deepResults.filter(
        candidate =>
          candidate &&
          !candidate.error &&
          candidate.symbol &&
          candidate.canonicalState
            ?.opportunityTier !==
            'EVIDENCE_RESEARCH'
      ).length;

    actionableSuitableCount =
      deepResults.filter(
        candidate =>
          candidate &&
          !candidate.error &&
          candidate.symbol &&
          candidate.profileSuitability
            ?.state === 'SUITABLE' &&
          safeNumber(candidate.price) !== null &&
          safeNumber(candidate.price) <= amount &&
          decisionExecutionAllowsAllocation(
            candidate.executionGuidance
          ) &&
          (
            horizon === 'short_term'
              ? candidate.shortTermExecution
                  ?.actionableNow === true
              : (
                  candidate.canonicalState
                    ?.allocationPermission
                    ?.allowed === true &&
                  (
                    candidate.canonicalState
                      ?.marketAction === 'BUY' ||
                    candidate.canonicalState
                      ?.marketAction === 'ACCUMULATE'
                  )
                )
          )
      ).length;
  }

  const deepShortList =
    deepAttemptedItems;

  const candidates =
    deepResults
      .filter(
        candidate =>
          candidate &&
          !candidate.error &&
          candidate.symbol
      )
      .sort(
        (
          a,
          b
        ) =>
          b.overallScore -
          a.overallScore
      );

  const opportunityBoard =
    buildDecisionOpportunityBoard(
      candidates
    );

  const ownershipContinuity =
    horizon === 'long_term' &&
    portfolioContext?.holdingCount > 0
      ? await buildLongTermOwnershipContinuity(
          candidates,
          portfolioContext,
          market,
          eligibleRows,
          memoryMap,
          model,
          riskPolicy,
          risk
        )
      : {
          available: false,
          holdings: [],
          summary: {
            holdingCount: 0,
            intactCount: 0,
            reviewCount: 0,
            checkingCount: 0
          }
        };

  const allocation =
    allocateDecisionCenterOpportunities(
      opportunityBoard,
      amount,
      riskPolicy,
      portfolioContext,
      {
        sectorConstraint:
          selectedSector
      }
    );

  const shortTermTriggerPlan =
    horizon === 'short_term'
      ? buildShortTermTriggerPlan(
          opportunityBoard,
          amount,
          riskPolicy,
          allocation.amountInvestedPkr || 0
        )
      : null;

  const shortTermStability =
    horizon === 'short_term'
      ? shortTermDecisionStabilityAudit(
          amount,
          allocation,
          shortTermTriggerPlan,
          riskPolicy
        )
      : null;

  let action = 'WATCH';
  let headline =
    'No Priority 1 allocation currently passes the shadow allocation gates.';
  let reason =
    'NOMAD keeps opportunities visible. Only canonical BUY or ACCUMULATE states that pass evidence, profile suitability and portfolio-fit gates may receive capital; WATCH, RESEARCHING and AVOID receive PKR 0.';

  const dataBlockedCount =
    candidates.filter(
      candidate =>
        candidate.action ===
          'DATA_BLOCKED'
    ).length;

  const priorityOneCount =
    opportunityBoard
      .priority1
      .length;

  const priorityTwoCount =
    opportunityBoard
      .priority2
      .length;

  const evidenceResearchCount =
    opportunityBoard
      .evidenceResearch
      .length;

  const researchRequiredCount =
    evidenceResearchCount;

  const conditionalSetupCount =
    horizon === 'short_term'
      ? opportunityBoard.priority2.filter(
          item =>
            item?.professional
              ?.thesisStatus ===
              'CONDITIONAL_SETUP'
        ).length
      : 0;

  const decisionBlocked =
    candidates.length === 0 &&
    (
      deepShortList.length > 0 ||
      (
        shortList.length > 0 &&
        historyReady.length === 0
      )
    );

  if (decisionBlocked) {
    action =
      'DATA_BLOCKED';
    headline =
      'Decision blocked — required market evidence could not be completed.';
    reason =
      'This is a data/reliability failure, not an investment view. NOMAD did not substitute a guess.';
  } else if (
    allocation.allocations.length
  ) {
    action =
      allocation.investedPct >= 75
        ? 'INVEST'
        : 'PARTIAL_INVEST';
    headline =
      horizon === 'short_term'
        ? (
            priorityOneCount === 1
              ? 'One active short-term trade setup currently passes the Trader brain gates.'
              : 'Active short-term trade setups currently pass the Trader brain gates.'
          )
        : (
            priorityOneCount === 1
              ? 'One Priority 1 opportunity currently passes the shadow allocation gates.'
              : 'Priority 1 opportunities currently pass the shadow allocation gates.'
          );
    reason =
      horizon === 'short_term'
        ? 'The Trader brain requires a defined setup, technical evidence, profile suitability, entry, invalidation, target and minimum reward-to-risk before capital is permitted. Position size is also capped by the selected profile\'s per-trade risk budget.'
        : 'The capital allocator builds a portfolio-aware target from the strongest opportunities that passed the current shadow allocation gates. Position sizes are conviction-weighted, profile-gated and constrained by stock/sector limits; existing holdings are applied to the combined post-investment portfolio before whole shares are calculated.';
  } else if (
    priorityOneCount > 0
  ) {
    action = 'WATCH';
    headline =
      'Priority 1 opportunities exist, but this amount cannot express them within current risk limits.';
    reason =
      'The opportunity ranking is independent of budget. NOMAD did not replace a better stock with a weaker one simply because the weaker share price fit the entered amount.';
  } else if (
    priorityTwoCount > 0
  ) {
    action =
      horizon === 'short_term' &&
      shortTermTriggerPlan
        ?.count > 0
        ? 'TRIGGER_PLAN'
        : 'WATCH';
    headline =
      horizon === 'short_term'
        ? (
            shortTermTriggerPlan
              ?.count > 0
              ? 'No forced buy now. NOMAD has built a profile-specific short-term trigger plan for the next valid entries.'
              : conditionalSetupCount > 0
                ? 'No trade is active at the current reference price; conditional setups are defined for the next valid trigger.'
                : 'No active short-term setup passes the full trade gate; the best current setups remain on watch.'
          )
        : 'No Priority 1 idea passes the full standard; the best current ideas remain Priority 2.';
    reason =
      horizon === 'short_term'
        ? (
            shortTermTriggerPlan
              ?.count > 0
              ? 'Short-term risk is handled through setup quality, explicit invalidation, reward-to-risk and stop-based position sizing. Capital is planned against valid triggers instead of being rejected simply because volatility is high or being deployed before the setup activates.'
              : conditionalSetupCount > 0
                ? 'NOMAD will not manufacture a BUY before the trigger. It has instead calculated pullback/retest or breakout-confirmation levels where selected setups become tradable with explicit stops and targets.'
                : 'These stocks have technical context worth monitoring, but setup confirmation, timing, reward-to-risk or trade-plan completeness is not yet strong enough for entry.'
          )
        : 'These companies remain worth monitoring, but one or more thesis, evidence, valuation or entry conditions do not pass the current shadow allocation gate.';
  } else if (
    researchRequiredCount > 0
  ) {
    action =
      'EVIDENCE_RESEARCH';
    headline =
      horizon === 'short_term'
        ? 'Potential setups exist and NOMAD is refreshing the missing technical evidence.'
        : 'Interesting candidates exist and NOMAD is automatically researching the missing evidence.';
    reason =
      horizon === 'short_term'
        ? 'Missing OHLC, momentum, volume, level or trade-plan evidence is a research trigger, not a trade signal. Allocation remains blocked until a complete setup is available.'
        : 'Missing evidence is a research trigger, not a final verdict. NOMAD keeps these names visible, backfills additional candidates, and blocks allocation until the evidence state becomes actionable.';
  }

  if (
    allocation.diversificationException
      ?.triggered === true
  ) {
    reason +=
      ' Diversification exception: ' +
      allocation.diversificationException.reason;
  }

  const evidencePool =
    opportunityBoard.priority1.length
      ? opportunityBoard.priority1
      : opportunityBoard.priority2.length
        ? opportunityBoard.priority2
        : opportunityBoard.evidenceResearch;

  const averageMetric =
    (
      list,
      getter
    ) => {
      if (!list.length) {
        return 0;
      }

      return decisionRound(
        list.reduce(
          (
            sum,
            item
          ) =>
            sum +
            (
              safeNumber(
                getter(item)
              ) ||
              0
            ),
          0
        ) /
        list.length,
        2
      );
    };

  const evidenceSample =
    evidencePool.slice(
      0,
      5
    );

  const evidenceProfile = {
    confidenceScore:
      averageMetric(
        evidenceSample,
        item =>
          item.canonicalState
            ?.evidence
            ?.score
      ),
    summaryCoveragePct:
      averageMetric(
        evidenceSample,
        item =>
          item.canonicalState
            ?.evidence
            ?.summaryCoveragePct
      ),
    extendedCoveragePct:
      averageMetric(
        evidenceSample,
        item =>
          item.canonicalState
            ?.evidence
            ?.extendedCoveragePct
      ),
    technicalCoveragePct:
      horizon === 'short_term'
        ? averageMetric(
            evidenceSample,
            item =>
              item.canonicalState
                ?.evidence
                ?.technicalCoveragePct
          )
        : null,
    tradePlanCoveragePct:
      horizon === 'short_term'
        ? averageMetric(
            evidenceSample,
            item =>
              item.canonicalState
                ?.evidence
                ?.tradePlanCoveragePct
          )
        : null,
    dataQualityPct:
      averageMetric(
        evidenceSample,
        item =>
          item.canonicalState
            ?.evidence
            ?.dataQualityPct
      )
  };

  if (horizon === 'short_term') {
    evidenceProfile.setupCompleteness =
      evidenceProfile.tradePlanCoveragePct >= 99
        ? 'COMPLETE'
        : evidenceProfile.tradePlanCoveragePct > 0
          ? 'PARTIAL'
          : 'INCOMPLETE';
  }

  evidenceProfile.confidence =
    evidenceProfile.confidenceScore >= 82
      ? 'HIGH'
      : evidenceProfile.confidenceScore >= 62
        ? 'MEDIUM'
        : evidenceProfile.confidenceScore >= 42
          ? 'LOW'
          : 'UNRESOLVED';

  const evidenceStrength =
    evidenceProfile.confidenceScore;

  const result = {
    status: 'OK',
    build: VERSION,
    engineMode: 'SHADOW',
    validationStatus:
      model.status,
    realMoneyEligible: false,
    startedAt,
    completedAt:
      new Date()
        .toISOString(),
    model: {
      id:
        model.id,
      horizon:
        model.horizon,
      status:
        model.status,
      realMoneyEligible:
        false,
      weights:
        model.weights
    },
    riskPolicy: {
      id:
        riskPolicy.id,
      assumptions: {
        minAverageVolume30d:
          riskPolicy.minAverageVolume30d,
        maxAnnualizedVolatilityPct:
          riskPolicy.maxAnnualizedVolatilityPct,
        minDataQualityScore:
          riskPolicy.minDataQualityScore,
        minOverallScore:
          riskPolicy.minOverallScore,
        minRiskScore:
          riskPolicy.minRiskScore,
        maxStockPct:
          riskPolicy.maxStockPct *
          100,
        maxSectorPct:
          riskPolicy.maxSectorPct *
          100,
        ...(horizon === 'short_term'
          ? {
              traderProfile:
                decisionTraderProfilePolicy(
                  riskPolicy
                ).id,
              minTraderTimingScore:
                decisionTraderProfilePolicy(
                  riskPolicy
                ).minTimingScore,
              minTraderTechnicalEvidenceScore:
                decisionTraderProfilePolicy(
                  riskPolicy
                ).minTechnicalEvidenceScore,
              minTraderRewardRisk:
                decisionTraderProfilePolicy(
                  riskPolicy
                ).minRewardRisk,
              maxTraderStopRiskPct:
                decisionTraderProfilePolicy(
                  riskPolicy
                ).maxStopRiskPct,
              perTradeRiskBudgetPct:
                decisionRound(
                  decisionTraderRiskBudgetPct(
                    riskPolicy
                  ) * 100,
                  2
                )
            }
          : {})
      }
    },
    input: {
      amount:
        decisionRound(
          amount,
          2
        ),
      horizon,
      risk
    },
    market: {
      asOf:
        market.marketWatchAsOf ||
        market.asOf ||
        null,
      source:
        'Official PSX Data Portal screener',
      canonicalUniverseVersion:
        PSX_UNIVERSE_MASTER.masterVersion
    },
    screening: {
      eligibleUniverse:
        eligibleRows.length,
      affordableUniverse:
        affordableRows.length,
      liquidityPassed:
        liquidityPassed.length,
      shortlisted:
        shortList.length,
      historicalAnalyzed:
        historyReady.length,
      deepAnalyzed:
        deepAttemptedItems.length,
      comparableAnalyzed:
        comparableCount,
      actionableProfileFit:
        actionableSuitableCount,
      conditionalSetups:
        conditionalSetupCount,
      actionableResearchTarget:
        researchActionableTarget,
      evidenceResearch:
        evidenceResearchCount,
      deepAttemptLimit:
        DECISION_CENTER_DEEP_ATTEMPT_LIMIT,
      comparableTarget:
        DECISION_CENTER_COMPARABLE_TARGET,
      dataBlocked:
        dataBlockedCount,
      rankingBudgetIndependent:
        true,
      sectorConstraint:
        selectedSector,
      availableSectorCount:
        availableSectors.length,
      scopedUniverseCount:
        scopedMarketRows.length
    },
    decision: {
      action,
      headline,
      reason,
      amountInvestedPkr:
        allocation.amountInvestedPkr,
      cashRemainingPkr:
        allocation.cashRemainingPkr,
      investedPct:
        allocation.investedPct,
      evidenceStrength,
      evidence:
        evidenceProfile,
      probabilityClaim:
        'NONE — evidence strength is not a calibrated probability.'
    },
    allocations:
      allocation.allocations,
    shortTermTriggerPlan,
    shortTermStability,
    opportunityBoard: {
      priority1:
        opportunityBoard.priority1,
      priority2:
        opportunityBoard.priority2,
      evidenceResearch:
        opportunityBoard.evidenceResearch,
      researchRequired:
        opportunityBoard.evidenceResearch,
      avoid:
        opportunityBoard.avoid
    },
    allocationDiagnostics: {
      deploymentCapPct:
        allocation.deploymentCapPct,
      portfolioAware:
        allocation.portfolioAware ===
          true,
      existingPortfolioValuePkr:
        allocation.existingPortfolioValuePkr ||
        0,
      targetPositionCount:
        allocation.targetPositionCount ||
        0,
      sizingPositionCount:
        allocation.sizingPositionCount ||
        0,
      targetDeploymentPct:
        allocation.targetDeploymentPct ??
        allocation.deploymentCapPct ??
        0,
      intentionalCashReservePct:
        allocation.intentionalCashReservePct ??
        0,
      averageConvictionScore:
        allocation.averageConvictionScore ??
        0,
      cashReserveReason:
        allocation.cashReserveReason ||
        '',
      minimumTargetPositions:
        allocation.minimumTargetPositions ||
        DECISION_CENTER_MIN_TARGET_POSITIONS,
      maximumTargetPositions:
        allocation.maximumTargetPositions ||
        DECISION_CENTER_MAX_TARGET_POSITIONS,
      achievedPositionCount:
        allocation.achievedPositionCount ||
        0,
      diversificationException:
        allocation.diversificationException ||
        { triggered: false, reason: null },
      eligibleAllocationCandidates:
        allocation.eligibleAllocationCandidates ||
        0,
      priorityOneAllocationCandidates:
        allocation.priorityOneAllocationCandidates ||
        0,
      priorityTwoAllocationCandidates:
        allocation.priorityTwoAllocationCandidates ||
        0,
      dynamicMaxStockPct:
        allocation.dynamicMaxStockPct ||
        0,
      dynamicMaxSectorPct:
        allocation.dynamicMaxSectorPct ||
        0,
      sectorConstraint:
        allocation.sectorConstraint ||
        null,
      concentrationWarning:
        allocation.concentrationWarning ||
        null,
      minimumMeaningfulPositionPkr:
        allocation.minimumMeaningfulPositionPkr ||
        0,
      marketableLotPolicy:
        allocation.marketableLotPolicy ||
        'PSX_REGULAR_ONE_SHARE',
      personalActions:
        allocation.personalActions ||
        [],
      unfundedPriorityOne:
        allocation.unfundedPriorityOne
    },
    portfolioContext: {
      holdingCount:
        portfolioContext.holdingCount ||
        0,
      currentValuePkr:
        portfolioContext.currentValuePkr ||
        0
    },
    ownershipContinuity,
    candidates,
    exclusions: {
      unaffordable:
        eligibleRows.length -
        affordableRows.length,
      liquidityOrStatus:
        eligibleRows.length -
        liquidityPassed.length,
      historicalUnavailable:
        shortList.length -
        historyReady.length
    },
    warnings: [
      'SHADOW MODE: this model has not passed historical and forward validation for real-money use.',
      'Allocations are planning principals only. Brokerage, levies, taxes and execution slippage are not yet included.',
      'No order-execution capability exists. The user remains the final decision maker.',
      'Current scoring rules remain supporting evidence only; Priority 1 now also requires the Financial Analyst evidence gate.',
      'Opportunity ranking is independent of the entered budget. Portfolio construction targets at least three funded stocks and scales up to eight, but never forces a weak, unresolved, profile-unsuitable, unaffordable, or portfolio-incompatible name merely to hit the count.',
      'PSX regular-market equities use a one-share marketable lot; NOMAD therefore uses a minimum meaningful PKR position instead of outdated 20/50/100/500-share board-lot rules.',
      ...(
        selectedSector
          ? [
              'Industry constraint active: ranking, research and allocation are restricted to ' + selectedSector + '. Cross-sector diversification is intentionally disabled by user choice.'
            ]
          : []
      ),
      ...(
        candidates.some(
          candidate =>
            candidate.fundamentalEvidenceState ===
              'CACHE_FALLBACK'
        )
          ? [
              'At least one candidate used recent cached company fundamentals because the live PSX company evidence request was unavailable.'
            ]
          : []
      )
    ]
  };

  if (
    horizon === 'short_term' &&
    shortTermStability &&
    shortTermStability.ok !== true
  ) {
    // Fail closed, and fail coherently. A blocked Trader plan must never leave
    // stale buy-now capital, personal BUY actions or trigger reservations on
    // screen. This is a last-resort guard, not a normal decision path.
    result.decision.action = 'DATA_BLOCKED';
    result.decision.headline = 'Trader plan withheld — internal consistency check failed.';
    result.decision.reason = 'NOMAD detected an internal capital or trade-plan inconsistency and withheld the short-term plan rather than presenting an unreliable action.';
    result.decision.amountInvestedPkr = 0;
    result.decision.investedPct = 0;
    result.decision.cashRemainingPkr = decisionRound(amount, 2);
    result.allocations = [];
    if (result.shortTermTriggerPlan) {
      result.shortTermTriggerPlan.plans = [];
      result.shortTermTriggerPlan.count = 0;
      result.shortTermTriggerPlan.fundedCount = 0;
      result.shortTermTriggerPlan.plannedCapitalPkr = 0;
      result.shortTermTriggerPlan.buyNowCapitalPkr = 0;
      result.shortTermTriggerPlan.availableForTriggersPkr = decisionRound(amount, 2);
      result.shortTermTriggerPlan.uncommittedCapitalPkr = decisionRound(amount, 2);
      result.shortTermTriggerPlan.reconciliation = {
        totalCapitalPkr: decisionRound(amount, 2),
        buyNowPkr: 0,
        reservedPkr: 0,
        freeCashPkr: decisionRound(amount, 2),
        deltaPkr: 0,
        ok: true
      };
    }
    if (result.allocationDiagnostics) {
      result.allocationDiagnostics.personalActions = [];
    }
    result.warnings.push(
      ...shortTermStability.issues.map(
        issue => 'TRADER STABILITY CHECK: ' + issue
      )
    );
  }

  result.recording =
    await recordDecisionRun(
      result
    );

  return result;
}

