/* =========================================================
   CONTINUOUS INTELLIGENCE SCANNER - BUILD 0.8.4B.1
========================================================= */

function scannerSecretConfigured() {
  return Boolean(
    NOMAD_SCANNER_SECRET
  );
}

function scannerRequestAuthorized(
  request
) {
  if (!scannerSecretConfigured()) {
    return false;
  }

  const direct =
    String(
      request.headers[
        'x-nomad-scanner-secret'
      ] ||
      ''
    ).trim();

  const authorization =
    String(
      request.headers.authorization ||
      ''
    ).trim();

  const bearer =
    authorization
      .replace(
        /^Bearer\s+/i,
        ''
      )
      .trim();

  const supplied =
    direct ||
    (
      /^Bearer\s+/i.test(
        authorization
      )
        ? bearer
        : ''
    );

  return Boolean(
    supplied &&
    safeEqual(
      supplied,
      NOMAD_SCANNER_SECRET
    )
  );
}

function normalizeStatusArray(
  value
) {
  return (
    Array.isArray(value)
      ? value
      : []
  )
    .map(
      item =>
        String(item || '')
          .trim()
          .toUpperCase()
    )
    .filter(Boolean)
    .sort();
}

function sameStringArray(
  a,
  b
) {
  return (
    JSON.stringify(
      normalizeStatusArray(a)
    ) ===
    JSON.stringify(
      normalizeStatusArray(b)
    )
  );
}

function marketMoveSignificance(
  percentageChange
) {
  const absolute =
    Math.abs(
      safeNumber(
        percentageChange
      ) || 0
    );

  if (absolute >= 8) {
    return 'critical';
  }

  if (absolute >= 4) {
    return 'high';
  }

  if (absolute >= 1.5) {
    return 'medium';
  }

  return 'low';
}

function scannerStateHash(
  marketState,
  previous
) {
  return crypto
    .createHash('sha256')
    .update(
      JSON.stringify({
        marketState,
        technicalState:
          previous?.technical_state ||
          {},
        fundamentalState:
          previous?.fundamental_state ||
          {},
        currentView:
          previous?.current_view ||
          null
      })
    )
    .digest('hex');
}

function buildScannerSecurityState(
  marketRow,
  previous,
  runId,
  evaluatedAt
) {
  const symbol =
    normalizeSymbol(
      marketRow.symbol
    );

  const currentPrice =
    safeNumber(
      marketRow.price
    );

  const previousPrice =
    safeNumber(
      previous?.market_price
    );

  const scanChangePct =
    previousPrice !== null &&
    previousPrice !== 0 &&
    currentPrice !== null
      ? (
          (
            currentPrice -
            previousPrice
          ) /
          Math.abs(
            previousPrice
          )
        ) * 100
      : null;

  const marketState = {
    asOf:
      marketRow.asOf ||
      null,
    price:
      roundMemoryNumber(
        currentPrice,
        4
      ),
    peRatio:
      roundMemoryNumber(
        marketRow.peRatio,
        4
      ),
    dividendYield:
      roundMemoryNumber(
        marketRow.dividendYield,
        4
      ),
    averageVolume30d:
      roundMemoryNumber(
        marketRow.averageVolume30d,
        2
      ),
    change1yPct:
      roundMemoryNumber(
        marketRow.change1yPct,
        2
      ),
    dayChangePct:
      roundMemoryNumber(
        marketRow.dayChangePct,
        2
      ),
    previousClose:
      roundMemoryNumber(
        marketRow.previousClose,
        4
      ),
    sessionOpen:
      roundMemoryNumber(
        marketRow.sessionOpen,
        4
      ),
    sessionHigh:
      roundMemoryNumber(
        marketRow.sessionHigh,
        4
      ),
    sessionLow:
      roundMemoryNumber(
        marketRow.sessionLow,
        4
      ),
    sessionVolume:
      roundMemoryNumber(
        marketRow.sessionVolume,
        2
      ),
    statusCodes:
      normalizeStatusArray(
        marketRow.statusCodes
      ),
    scanChangePct:
      roundMemoryNumber(
        scanChangePct,
        4
      )
  };

  const state = {
    symbol,
    company_name:
      marketRow.companyName ||
      previous?.company_name ||
      symbol,
    sector:
      marketRow.sector ||
      previous?.sector ||
      null,
    universe_class:
      marketRow.universeClass ||
      previous?.universe_class ||
      null,
    eligibility:
      marketRow.recommendationEligible === true
        ? 'RECOMMENDATION_ELIGIBLE'
        : 'NOT_RECOMMENDATION_ELIGIBLE',
    market_price:
      roundMemoryNumber(
        currentPrice,
        4
      ),
    market_change_pct:
      roundMemoryNumber(
        marketRow.dayChangePct,
        4
      ),
    volume:
      roundMemoryNumber(
        marketRow.sessionVolume,
        2
      ) ??
      previous?.volume ??
      null,
    volume_ratio_20d:
      safeNumber(
        marketRow.sessionVolume
      ) !== null &&
      safeNumber(
        marketRow.averageVolume30d
      ) !== null &&
      safeNumber(
        marketRow.averageVolume30d
      ) > 0
        ? roundMemoryNumber(
            safeNumber(
              marketRow.sessionVolume
            ) /
            safeNumber(
              marketRow.averageVolume30d
            ),
            2
          )
        : previous?.volume_ratio_20d ??
          null,
    technical_score:
      previous?.technical_score ??
      null,
    fundamental_score:
      previous?.fundamental_score ??
      null,
    risk_score:
      previous?.risk_score ??
      null,
    overall_score:
      previous?.overall_score ??
      null,
    technical_state:
      previous?.technical_state ||
      {},
    fundamental_state:
      previous?.fundamental_state ||
      {},
    risk_state:
      previous?.risk_state ||
      {},
    market_state:
      marketState,
    current_view:
      previous?.current_view ||
      'Market baseline established',
    current_view_reason:
      previous?.current_view_reason ||
      'NOMAD has a persistent market baseline. Deeper technical and fundamental views are updated by their respective intelligence engines.',
    data_quality_score:
      previous?.data_quality_score ??
      70,
    source_timestamp:
      marketRow.asOf ||
      null,
    last_run_id:
      runId,
    state_hash:
      scannerStateHash(
        marketState,
        previous
      ),
    evaluated_at:
      evaluatedAt,
    created_at:
      previous?.created_at ||
      evaluatedAt
  };

  return {
    state,
    scanChangePct
  };
}

function detectScannerChanges(
  marketRow,
  previous,
  currentState,
  scanChangePct
) {
  if (!previous) {
    return [];
  }

  const changes = [];
  const absoluteMove =
    Math.abs(
      safeNumber(
        scanChangePct
      ) || 0
    );

  if (
    scanChangePct !== null &&
    absoluteMove >= 1.5
  ) {
    const oldPrice =
      safeNumber(
        previous.market_price
      );

    const newPrice =
      safeNumber(
        currentState.market_price
      );

    changes.push({
      symbol:
        currentState.symbol,
      change_category:
        'market',
      field_name:
        'market_price',
      old_value: {
        value: oldPrice
      },
      new_value: {
        value: newPrice
      },
      absolute_change:
        roundMemoryNumber(
          newPrice !== null &&
          oldPrice !== null
            ? newPrice - oldPrice
            : null,
          4
        ),
      percentage_change:
        roundMemoryNumber(
          scanChangePct,
          4
        ),
      significance:
        marketMoveSignificance(
          scanChangePct
        ),
      summary:
        currentState.symbol +
        ' moved ' +
        (
          scanChangePct > 0
            ? '+'
            : ''
        ) +
        roundMemoryNumber(
          scanChangePct,
          2
        ) +
        '% since NOMAD\'s previous market snapshot.',
      evidence: {
        source:
          'psxdata-api',
        previousPrice:
          oldPrice,
        currentPrice:
          newPrice,
        sourceTimestamp:
          marketRow.asOf ||
          null
      }
    });
  }

  const previousStatuses =
    previous.market_state
      ?.statusCodes ||
    [];

  const currentStatuses =
    marketRow.statusCodes ||
    [];

  if (
    !sameStringArray(
      previousStatuses,
      currentStatuses
    )
  ) {
    changes.push({
      symbol:
        currentState.symbol,
      change_category:
        'security_status',
      field_name:
        'status_codes',
      old_value: {
        value:
          normalizeStatusArray(
            previousStatuses
          )
      },
      new_value: {
        value:
          normalizeStatusArray(
            currentStatuses
          )
      },
      absolute_change:
        null,
      percentage_change:
        null,
      significance:
        'high',
      summary:
        currentState.symbol +
        ' market-status code changed from [' +
        normalizeStatusArray(
          previousStatuses
        ).join(', ') +
        '] to [' +
        normalizeStatusArray(
          currentStatuses
        ).join(', ') +
        '].',
      evidence: {
        source:
          'PSX market feed'
      }
    });
  }

  return changes;
}

async function readAllSecurityMemory() {
  const rows =
    await supabaseRest(
      'security_state?select=*'
    );

  return Array.isArray(rows)
    ? rows
    : [];
}

async function upsertSecurityStatesBulk(
  states
) {
  const saved = [];
  const chunkSize = 100;

  for (
    let index = 0;
    index < states.length;
    index += chunkSize
  ) {
    const chunk =
      states.slice(
        index,
        index + chunkSize
      );

    const rows =
      await supabaseRest(
        'security_state?on_conflict=symbol&select=symbol,evaluated_at,market_price',
        {
          method: 'POST',
          prefer:
            'resolution=merge-duplicates,return=representation',
          body:
            chunk
        }
      );

    if (Array.isArray(rows)) {
      saved.push(
        ...rows
      );
    }
  }

  return saved;
}

async function saveScannerChangesBulk(
  runId,
  changes
) {
  if (!changes.length) {
    return [];
  }

  const saved = [];
  const chunkSize = 100;

  for (
    let index = 0;
    index < changes.length;
    index += chunkSize
  ) {
    const chunk =
      changes
        .slice(
          index,
          index + chunkSize
        )
        .map(
          change => ({
            run_id:
              runId,
            ...change
          })
        );

    const rows =
      await supabaseRest(
        'state_changes?select=id,symbol,field_name,percentage_change,significance,summary,detected_at',
        {
          method: 'POST',
          prefer:
            'return=representation',
          body:
            chunk
        }
      );

    if (Array.isArray(rows)) {
      saved.push(
        ...rows
      );
    }
  }

  return saved;
}

async function runMarketSnapshotScan(
  runType = 'manual'
) {
  if (!continuousMemoryConfigured()) {
    bad(
      'Continuous intelligence database is not configured.',
      503
    );
  }

  const run =
    await createIntelligenceRun(
      {
        scanner:
          'CORE_EQUITY_MARKET_SNAPSHOT',
        build:
          VERSION,
        purpose:
          'Detect meaningful market-state changes without waiting for the user to open a stock.'
      },
      runType
    );

  try {
    const [
      market,
      previousRows
    ] =
      await Promise.all([
        loadPSXMarket(),
        readAllSecurityMemory()
      ]);

    const previousMap =
      new Map(
        previousRows.map(
          row => [
            normalizeSymbol(
              row.symbol
            ),
            row
          ]
        )
      );

    const coreRows =
      market.stocks.filter(
        row =>
          row.recommendationEligible ===
          true
      );

    const evaluatedAt =
      new Date().toISOString();

    const states = [];
    const changes = [];
    let firstBaselines = 0;

    for (
      const marketRow
      of coreRows
    ) {
      const symbol =
        normalizeSymbol(
          marketRow.symbol
        );

      const previous =
        previousMap.get(
          symbol
        ) ||
        null;

      if (!previous) {
        firstBaselines += 1;
      }

      const built =
        buildScannerSecurityState(
          marketRow,
          previous,
          run.id,
          evaluatedAt
        );

      states.push(
        built.state
      );

      changes.push(
        ...detectScannerChanges(
          marketRow,
          previous,
          built.state,
          built.scanChangePct
        )
      );
    }

    const holdingsResult =
      await readPortfolioHoldings()
        .catch(
          () => ({
            configured: false,
            rows: []
          })
        );

    const prioritySymbols =
      uniqueStrings(
        (
          holdingsResult.rows ||
          []
        ).map(
          row =>
            normalizeSymbol(
              row.symbol
            )
        )
      );

    const contextBatchSize =
      8;

    const rotationStart =
      coreRows.length
        ? (
            Math.floor(
              Date.now() /
              (15 * 60 * 1000)
            ) *
            contextBatchSize
          ) %
          coreRows.length
        : 0;

    const rotationSymbols = [];

    for (
      let offset = 0;
      offset < contextBatchSize &&
      offset < coreRows.length;
      offset++
    ) {
      rotationSymbols.push(
        coreRows[
          (
            rotationStart +
            offset
          ) %
          coreRows.length
        ]?.symbol
      );
    }

    const contextSymbols =
      uniqueStrings([
        ...prioritySymbols,
        ...rotationSymbols
      ])
        .slice(
          0,
          16
        );

    const marketRowMap =
      new Map(
        coreRows.map(
          row => [
            normalizeSymbol(
              row.symbol
            ),
            row
          ]
        )
      );

    const stateMap =
      new Map(
        states.map(
          state => [
            normalizeSymbol(
              state.symbol
            ),
            state
          ]
        )
      );

    let historicalContextsUpdated =
      0;

    const contextResults =
      await mapWithConcurrency(
        contextSymbols,
        2,
        async symbol => {
          const row =
            marketRowMap.get(
              normalizeSymbol(
                symbol
              )
            );

          if (!row) {
            return null;
          }

          try {
            const context =
              await getHistoricalSituation(
                symbol,
                row.price
              );

            return {
              symbol:
                normalizeSymbol(
                  symbol
                ),
              context
            };
          } catch {
            return null;
          }
        }
      );

    for (
      const item
      of contextResults
    ) {
      if (
        !item?.context?.available
      ) {
        continue;
      }

      const state =
        stateMap.get(
          item.symbol
        );

      if (!state) {
        continue;
      }

      state.market_state = {
        ...(
          state.market_state ||
          {}
        ),
        historicalContext:
          item.context
      };

      state.state_hash =
        scannerStateHash(
          state.market_state,
          previousMap.get(
            item.symbol
          ) ||
          null
        );

      historicalContextsUpdated +=
        1;
    }

    await upsertSecurityStatesBulk(
      states
    );

    const savedChanges =
      await saveScannerChangesBulk(
        run.id,
        changes
      );

    await finishIntelligenceRun(
      run.id,
      {
        status:
          'completed',
        securities_processed:
          states.length,
        changes_detected:
          changes.length,
        signals_generated:
          0,
        alerts_generated:
          0,
        predictions_generated:
          0,
        metadata: {
          scanner:
            'CORE_EQUITY_MARKET_SNAPSHOT',
          build:
            VERSION,
          marketAsOf:
            market.asOf,
          firstBaselines,
          historicalContextsUpdated,
          contextSymbols
        }
      }
    );

    const attention =
      [...savedChanges]
        .sort(
          (
            a,
            b
          ) =>
            Math.abs(
              safeNumber(
                b.percentage_change
              ) || 0
            ) -
            Math.abs(
              safeNumber(
                a.percentage_change
              ) || 0
            )
        )
        .slice(0, 10);

    return {
      status:
        'OK',
      runId:
        run.id,
      runType,
      marketAsOf:
        market.asOf,
      coreUniverse:
        coreRows.length,
      securitiesProcessed:
        states.length,
      firstBaselines,
      historicalContextsUpdated,
      contextSymbols,
      changesDetected:
        changes.length,
      meaningfulChanges:
        savedChanges.filter(
          item =>
            item.significance !==
            'low'
        ).length,
      attention
    };
  } catch (error) {
    await finishIntelligenceRun(
      run.id,
      {
        status:
          'failed',
        error_message:
          String(
            error.message ||
            'Scanner failed.'
          ).slice(
            0,
            1000
          )
      }
    ).catch(
      () => {}
    );

    throw error;
  }
}

function buildMarketPulseFromRows(
  rows
) {
  const liveRows =
    (
      Array.isArray(
        rows
      )
        ? rows
        : []
    )
      .filter(
        row =>
          row &&
          row.marketFactEligible !==
            false &&
          safeNumber(
            row.changePct
          ) !== null
      );

  const moverShape =
    row => ({
      symbol:
        row.symbol,
      canonicalSymbol:
        row.canonicalSymbol ||
        row.symbol,
      companyName:
        row.companyName,
      price:
        row.price,
      changePct:
        roundMemoryNumber(
          row.changePct,
          2
        ),
      volume:
        row.volume,
      sector:
        row.sector,
      recommendationEligible:
        row.recommendationEligible ===
        true
    });

  const gainers =
    [...liveRows]
      .filter(
        row =>
          safeNumber(
            row.changePct
          ) > 0
      )
      .sort(
        (
          a,
          b
        ) =>
          safeNumber(
            b.changePct
          ) -
          safeNumber(
            a.changePct
          )
      )
      .slice(0, 5)
      .map(
        moverShape
      );

  const losers =
    [...liveRows]
      .filter(
        row =>
          safeNumber(
            row.changePct
          ) < 0
      )
      .sort(
        (
          a,
          b
        ) =>
          safeNumber(
            a.changePct
          ) -
          safeNumber(
            b.changePct
          )
      )
      .slice(0, 5)
      .map(
        moverShape
      );

  const breadth =
    liveRows.length
      ? {
          advancers:
            liveRows.filter(
              row =>
                safeNumber(
                  row.changePct
                ) > 0
            ).length,
          decliners:
            liveRows.filter(
              row =>
                safeNumber(
                  row.changePct
                ) < 0
            ).length,
          unchanged:
            liveRows.filter(
              row =>
                safeNumber(
                  row.changePct
                ) === 0
            ).length
        }
      : null;

  return {
    gainers,
    losers,
    breadth,
    rowCount:
      liveRows.length
  };
}

async function getIntelligenceFeed() {
  if (!continuousMemoryConfigured()) {
    return {
      configured: false,
      latestRun: null,
      stateCoverage: 0,
      historicalContextCoverage: 0,
      coreUniverse:
        PSX_UNIVERSE_MASTER.summary
          .coreEquity,
      attention: [],
      marketPulse: null,
      portfolioConfigured: false
    };
  }

  const [
    runs,
    states,
    changes,
    holdingsResult,
    market,
    marketStatus
  ] =
    await Promise.all([
      supabaseRest(
        'intelligence_runs?select=id,run_type,status,started_at,completed_at,securities_processed,changes_detected,error_message,metadata&order=started_at.desc&limit=5'
      ),
      supabaseRest(
        'security_state?select=symbol,market_price,market_change_pct,current_view,evaluated_at,market_state&eligibility=eq.RECOMMENDATION_ELIGIBLE'
      ),
      supabaseRest(
        'state_changes?select=id,symbol,change_category,field_name,old_value,new_value,percentage_change,significance,summary,detected_at&order=detected_at.desc&limit=80'
      ),
      readPortfolioHoldings()
        .catch(
          () => ({
            configured: false,
            rows: []
          })
        ),
      loadPSXMarket()
        .catch(
          () => null
        ),
      getPyPSXMarketStatus()
        .catch(
          () => null
        )
    ]);

  const stateRows =
    Array.isArray(states)
      ? states
      : [];

  const historicalContextCoverage =
    stateRows.filter(
      row =>
        row?.market_state
          ?.historicalContext
          ?.available ===
        true
    ).length;

  const recentChanges =
    (
      Array.isArray(changes)
        ? changes
        : []
    )
      .filter(
        item =>
          [
            'medium',
            'high',
            'critical'
          ].includes(
            item.significance
          )
      )
      .slice(0, 20);

  const stateMap =
    new Map(
      stateRows.map(
        row => [
          normalizeSymbol(
            row.symbol
          ),
          row
        ]
      )
    );

  const conditionAttention = [];

  for (
    const holding
    of holdingsResult.rows || []
  ) {
    const symbol =
      normalizeSymbol(
        holding.symbol
      );

    const state =
      stateMap.get(
        symbol
      );

    const context =
      state?.market_state
        ?.historicalContext;

    if (!context?.available) {
      continue;
    }

    const month =
      safeNumber(
        context.returns?.m1
      );

    if (
      month !== null &&
      month <= -5
    ) {
      conditionAttention.push({
        id:
          'condition-' +
          symbol,
        symbol,
        change_category:
          'existing_condition',
        field_name:
          'historical_context',
        percentage_change:
          month,
        significance:
          month <= -10
            ? 'high'
            : 'medium',
        summary:
          symbol +
          ' is down ' +
          Math.abs(
            roundMemoryNumber(
              month,
              2
            )
          ) +
          '% over roughly 1 month' +
          (
            context.trend
              ? ' and is in a ' +
                String(
                  context.trend
                ).toLowerCase()
              : ''
          ) +
          '.',
        detected_at:
          state.evaluated_at ||
          new Date()
            .toISOString(),
        condition:
          context.condition,
        kind:
          'existing_condition'
      });
    }
  }

  const attention = [];
  const attentionKeys =
    new Set();

  for (
    const item
    of [
      ...conditionAttention,
      ...recentChanges
    ]
  ) {
    const key =
      String(
        item.symbol ||
        ''
      ) +
      '|' +
      String(
        item.field_name ||
        item.kind ||
        ''
      );

    if (
      attentionKeys.has(
        key
      )
    ) {
      continue;
    }

    attentionKeys.add(
      key
    );

    attention.push(
      item
    );

    if (
      attention.length >=
      12
    ) {
      break;
    }
  }

  let marketPulse =
    null;

  if (
    market &&
    market.officialMarketAvailable ===
      true &&
    Array.isArray(
      market.liveMarketRows
    ) &&
    market.liveMarketRows.length
  ) {
    // Market breadth and Top Movers are canonical Official PSX facts.
    // The default scope is verified Main Board ordinary equities. Rights,
    // legacy symbols and other special instruments never enter this pulse.
    const liveRows =
      market.liveMarketRows;

    const pulseData =
      buildMarketPulseFromRows(
        liveRows
      );

    marketPulse = {
      asOf:
        market.marketWatchAsOf ||
        market.asOf,
      gainers:
        pulseData.gainers,
      losers:
        pulseData.losers,
      breadth:
        pulseData.breadth,
      sessionChangeRows:
        pulseData.rowCount,
      sessionChangeSource:
        market.sessionChangeSource ||
        null,
      marketUniverse:
        market.liveMarketUniverse ||
        'PRIMARY_LIVE_ROWS',
      marketDataIntegrity:
        market.marketDataIntegrity ||
        null,
      marketStatus:
        marketStatus ||
        null
    };
  }

  return {
    configured: true,
    scannerSecretConfigured:
      scannerSecretConfigured(),
    latestRun:
      Array.isArray(runs) &&
      runs.length
        ? runs[0]
        : null,
    recentRuns:
      Array.isArray(runs)
        ? runs
        : [],
    stateCoverage:
      stateRows.length,
    historicalContextCoverage,
    coreUniverse:
      PSX_UNIVERSE_MASTER.summary
        .coreEquity,
    attention,
    marketPulse,
    portfolioConfigured:
      holdingsResult.configured,
    portfolioHoldingCount:
      holdingsResult.rows?.length ||
      0
  };
}

/* =========================================================
   AUTH
========================================================= */

function safeEqual(
  a,
  b
) {
  const hash =
    value =>
      crypto
        .createHash(
          'sha256'
        )
        .update(
          String(
            value
          )
        )
        .digest();

  return crypto
    .timingSafeEqual(
      hash(a),
      hash(b)
    );
}

function authorize(
  request,
  response
) {
  const password =
    process.env
      .NOMAD_PASSWORD;

  if (!password) {
    if (
      process.env.VERCEL
    ) {
      bad(
        'NOMAD_PASSWORD is not configured.',
        503
      );
    }

    return true;
  }

  let login = '';

  try {
    login =
      Buffer.from(
        (
          request.headers
            .authorization ||
          ''
        ).replace(
          /^Basic /,
          ''
        ),
        'base64'
      )
        .toString();
  } catch {}

  if (
    !safeEqual(
      login,
      `nomad:${password}`
    )
  ) {
    response.writeHead(
      401,
      {
        'WWW-Authenticate':
          'Basic realm="NOMAD Invest"'
      }
    );

    response.end(
      'Sign in with username nomad.'
    );

    return false;
  }

  return true;
}

/* =========================================================
   RESPONSE
========================================================= */

function sendJSON(
  response,
  data,
  status = 200
) {
  response.statusCode =
    status;

  response.setHeader(
    'Content-Type',
    'application/json; charset=utf-8'
  );

  response.end(
    JSON.stringify(
      data
    )
  );
}

/* =========================================================
   HANDLER
========================================================= */

async function handler(
  request,
  response
) {
  response.setHeader(
    'Cache-Control',
    'no-store'
  );

  response.setHeader(
    'X-Content-Type-Options',
    'nosniff'
  );

  response.setHeader(
    'Referrer-Policy',
    'no-referrer'
  );

  try {
    const url =
      new URL(
        request.url,
        'http://localhost'
      );

    const action =
      url.searchParams.get(
        'action'
      ) ||
      'app';

    const scannerAuthorized =
      action ===
        'intelligence-scan' &&
      scannerRequestAuthorized(
        request
      );

    if (
      !scannerAuthorized &&
      !authorize(
        request,
        response
      )
    ) {
      return;
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'app'
    ) {
      response.setHeader(
        'Content-Type',
        'text/html; charset=utf-8'
      );

      return response.end(
        page()
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'health'
    ) {
      return sendJSON(
        response,
        {
          version:
            VERSION,

          universeMasterVersion:
            PSX_UNIVERSE_MASTER.masterVersion,

          universeMasterSummary:
            PSX_UNIVERSE_MASTER.summary,

          marketProvider:
            'psxdata-api',

          companyMetadata:
            'NOMAD canonical universe master + runtime research sources',

          symbolNormalization:
            'VALIDATED_CANONICAL_STATUS_SEPARATION',

          metadataAudit:
            'CANONICAL_UNIVERSE_MASTER_LOCKED',

          fundamentalsProvider:
            'PSX Data Portal company page',

          technicalEngine:
            'IMPLEMENTED_DETERMINISTIC',

          continuousIntelligenceMemory:
            continuousMemoryConfigured()
              ? 'CONFIGURED'
              : 'NOT_CONFIGURED',

          intelligenceScanner:
            'MARKET_SNAPSHOT_PLUS_ROTATING_HISTORICAL_CONTEXT',

          scannerSecretConfigured:
            scannerSecretConfigured(),

          supabaseConfigured:
            continuousMemoryConfigured(),

          pyPSXConfigured:
            Boolean(
              PYPSX_API_KEY_ID &&
              PYPSX_API_SECRET_KEY
            ),

          decisionEngine:
            'SHADOW_DECISION_LAB_V0.1',

          decisionModels: {
            longTerm:
              DECISION_MODELS.long_term.id,
            shortTerm:
              DECISION_MODELS.short_term.id,
            realMoneyEligible:
              false
          },

          predictionEngine:
            'SHADOW_UNVALIDATED',

          brokerConnection:
            false,

          bankConnection:
            false,

          tradeExecution:
            false
        }
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'intelligence-feed'
    ) {
      return sendJSON(
        response,
        await getIntelligenceFeed()
      );
    }

    if (
      (
        request.method ===
          'GET' ||
        request.method ===
          'POST'
      ) &&
      action ===
        'intelligence-scan'
    ) {
      return sendJSON(
        response,
        await runMarketSnapshotScan(
          scannerAuthorized
            ? 'scheduled'
            : 'manual'
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'intelligence-memory-test'
    ) {
      return sendJSON(
        response,
        await runContinuousMemoryTest(
          url.searchParams.get(
            'symbol'
          ) ||
          'HBL'
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'situation'
    ) {
      return sendJSON(
        response,
        await getHistoricalSituation(
          url.searchParams.get(
            'symbol'
          )
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'portfolio'
    ) {
      return sendJSON(
        response,
        await getPortfolioSnapshot()
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'portfolio-chart'
    ) {
      return sendJSON(
        response,
        await getPortfolioIntradayChart()
      );
    }

    if (
      request.method ===
        'POST' &&
      action ===
        'portfolio-holding'
    ) {
      const body =
        await readJsonRequestBody(
          request
        );

      const saved =
        await savePortfolioHolding(
          body
        );

      try {
        const market =
          await loadPSXMarket();

        const marketRow =
          market.stocks.find(
            row =>
              normalizeSymbol(
                row.symbol
              ) ===
              normalizeSymbol(
                saved?.symbol ||
                body.symbol
              )
          ) ||
          null;

        await refreshHistoricalSituation(
          saved?.symbol ||
          body.symbol,
          marketRow
        );
      } catch {}

      return sendJSON(
        response,
        {
          status: 'OK',
          holding: saved
        }
      );
    }

    if (
      request.method ===
        'POST' &&
      action ===
        'portfolio-transaction'
    ) {
      const body =
        await readJsonRequestBody(
          request
        );

      const saved =
        await savePortfolioTransaction(
          body
        );

      try {
        const market =
          await loadPSXMarket();

        const marketRow =
          market.stocks.find(
            row =>
              normalizeSymbol(
                row.symbol
              ) ===
              normalizeSymbol(
                body.symbol
              )
          ) ||
          null;

        await refreshHistoricalSituation(
          body.symbol,
          marketRow
        );
      } catch {}

      return sendJSON(
        response,
        {
          status: 'OK',
          ...saved
        }
      );
    }

    if (
      (
        request.method ===
          'POST' ||
        request.method ===
          'DELETE'
      ) &&
      action ===
        'portfolio-transaction-delete'
    ) {
      const body =
        request.method ===
          'POST'
          ? await readJsonRequestBody(
              request
            )
          : {};

      return sendJSON(
        response,
        await deletePortfolioTransaction(
          body.id ||
          url.searchParams.get(
            'id'
          )
        )
      );
    }

    if (
      (
        request.method ===
          'POST' ||
        request.method ===
          'DELETE'
      ) &&
      action ===
        'portfolio-delete'
    ) {
      const body =
        request.method ===
          'POST'
          ? await readJsonRequestBody(
              request
            )
          : {};

      return sendJSON(
        response,
        await deletePortfolioHolding(
          body.symbol ||
          url.searchParams.get(
            'symbol'
          )
        )
      );
    }

    if (
      request.method ===
        'POST' &&
      action ===
        'ask-nomad'
    ) {
      if (!NOMAD_ASK_NOMAD_ENABLED) {
        return sendJSON(
          response,
          {
            message:
              'Ask NOMAD is disabled in the 0.9.6.5 production-hardening build. Use Decision Center, Research and Portfolio for validated core intelligence.'
          },
          404
        );
      }

      const body =
        await readJsonRequestBody(
          request
        );

      return sendJSON(
        response,
        await runAskNomad(
          body
        )
      );
    }

    if (
      request.method ===
        'POST' &&
      action ===
        'stock-strategy'
    ) {
      const body =
        await readJsonRequestBody(
          request
        );

      return sendJSON(
        response,
        await runSingleStockStrategy(
          body
        )
      );
    }

    if (
      request.method ===
        'POST' &&
      action ===
        'decision-lab'
    ) {
      const body =
        await readJsonRequestBody(
          request
        );

      return sendJSON(
        response,
        await runDecisionLab(
          body
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'universe-master'
    ) {
      return sendJSON(
        response,
        {
          version: VERSION,
          masterVersion: PSX_UNIVERSE_MASTER.masterVersion,
          generatedAt: PSX_UNIVERSE_MASTER.generatedAt,
          summary: PSX_UNIVERSE_MASTER.summary,
          policy: PSX_UNIVERSE_MASTER.policy,
          entries: PSX_UNIVERSE_MASTER.entries
        }
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'metadata-audit'
    ) {
      return sendJSON(
        response,
        await getMetadataAudit()
      );
    }


    if (
      request.method ===
        'GET' &&
      action ===
        'security-status-batch'
    ) {
      return sendJSON(
        response,
        await getSecurityStatusBatch(
          url.searchParams.get(
            'symbols'
          ) ||
          ''
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'resolve-symbol'
    ) {
      return sendJSON(
        response,
        await resolveSymbolContext(
          url.searchParams.get(
            'symbol'
          )
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'live-price'
    ) {
      const context =
        await resolveSymbolContext(
          url.searchParams.get(
            'symbol'
          )
        );

      const result =
        await getOverviewLiveForContext(
          context
        );

      return sendJSON(
        response,
        {
          symbol:
            context.canonicalSymbol,

          identity: {
            canonicalSymbol:
              context.canonicalSymbol,

            tradingSymbol:
              context.tradingSymbol,

            rawMarketSymbol:
              context.rawMarketSymbol,

            statusCodes:
              context.statusCodes,

            normalized:
              context.normalized
          },

          provider:
            result.provider,

          providerSymbol:
            result.providerSymbol,

          sourceType:
            result.sourceType,

          marketStatus:
            result.marketStatus,

          feedState:
            result.feedState,

          feedLabel:
            result.feedLabel,

          price:
            result.price,

          timestamp:
            result.timestamp,

          ageSeconds:
            result.ageSeconds,

          sessionDate:
            result.sessionDate,

          session:
            result.session
        }
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'live-chart'
    ) {
      const context =
        await resolveSymbolContext(
          url.searchParams.get(
            'symbol'
          )
        );

      const result =
        await getLiveForContext(
          context
        );

      return sendJSON(
        response,
        {
          ...result,

          symbol:
            context.canonicalSymbol,

          identity: {
            canonicalSymbol:
              context.canonicalSymbol,

            tradingSymbol:
              context.tradingSymbol,

            rawMarketSymbol:
              context.rawMarketSymbol,

            statusCodes:
              context.statusCodes,

            normalized:
              context.normalized
          }
        }
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'market'
    ) {
      return sendJSON(
        response,
        await loadPSXMarket()
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'quote'
    ) {
      return sendJSON(
        response,
        await getQuote(
          url.searchParams.get(
            'symbol'
          )
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'history'
    ) {
      return sendJSON(
        response,
        await getHistory(
          url.searchParams.get(
            'symbol'
          ),

          url.searchParams.get(
            'range'
          ) ||
          '1Y'
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'fundamentals'
    ) {
      return sendJSON(
        response,
        await getFundamentals(
          url.searchParams.get(
            'symbol'
          )
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'events'
    ) {
      return sendJSON(
        response,
        await getEvents(
          url.searchParams.get(
            'symbol'
          )
        )
      );
    }

    if (
      request.method ===
        'GET' &&
      action ===
        'technical'
    ) {
      return sendJSON(
        response,
        await getTechnicalAnalysis(
          url.searchParams.get(
            'symbol'
          )
        )
      );
    }

    bad(
      'Unknown endpoint.',
      404
    );
  } catch (error) {
    sendJSON(
      response,
      {
        status:
          'UNAVAILABLE',

        message:
          error.message ||
          'Operation failed.'
      },

      error.status ||
      500
    );
  }
}

