const NOMAD_ASK_NOMAD_ENABLED = false;

const NOMAD_APP_PAGES =
  new Set([
    'home',
    'portfolio',
    'decision',
    'research',
    'explore',
    'universe',
    'system'
  ]);

function normalizedAppPage(
  page
) {
  const normalized =
    String(
      page ||
      ''
    )
      .trim()
      .toLowerCase();

  return NOMAD_APP_PAGES.has(
    normalized
  )
    ? normalized
    : 'home';
}

function appPageFromLocation() {
  const rawHashPage =
    String(
      window.location.hash ||
      ''
    )
      .replace(
        /^#/,
        ''
      )
      .trim()
      .toLowerCase();

  if (
    rawHashPage &&
    NOMAD_APP_PAGES.has(
      rawHashPage
    )
  ) {
    return rawHashPage;
  }

  try {
    const stored =
      localStorage.getItem(
        'nomadActivePage'
      );

    if (
      stored &&
      NOMAD_APP_PAGES.has(
        stored
      )
    ) {
      return stored;
    }
  } catch {}

  return 'home';
}

