function relativeTime(
  value
) {
  const time =
    Date.parse(value);

  if (!Number.isFinite(time)) {
    return '';
  }

  const seconds =
    Math.max(
      0,
      Math.round(
        (
          Date.now() -
          time
        ) /
        1000
      )
    );

  if (seconds < 60) {
    return seconds + ' sec ago';
  }

  const minutes =
    Math.round(
      seconds / 60
    );

  if (minutes < 60) {
    return minutes + ' min ago';
  }

  const hours =
    Math.round(
      minutes / 60
    );

  if (hours < 24) {
    return hours + ' hr ago';
  }

  return Math.round(
    hours / 24
  ) + ' d ago';
}

function renderAttentionFeed(
  items
) {
  const target =
    $('attentionFeed');

  if (!target) {
    return;
  }

  if (
    !Array.isArray(items) ||
    !items.length
  ) {
    target.innerHTML =
      '<div class="emptyState">No material changes are waiting for you right now.</div>';
    return;
  }

  const severityRank = { critical: 4, high: 3, medium: 2, low: 1 };
  const seenSymbols = new Set();
  const focused = items
    .slice()
    .sort((a,b) => (severityRank[String(b?.significance || '').toLowerCase()] || 0) - (severityRank[String(a?.significance || '').toLowerCase()] || 0))
    .filter(item => {
      const symbol = String(item?.symbol || '').trim().toUpperCase();
      if (!symbol || seenSymbols.has(symbol)) return false;
      seenSymbols.add(symbol);
      return true;
    });
  const visible = focused.slice(0, 5);
  const hidden = focused.slice(5);

  target.innerHTML =
    visible
      .map(
        item =>
          '<div class="attentionItem">' +
          '<div class="attentionSymbol">' +
          escapeHtml(
            item.symbol || '-'
          ) +
          '</div>' +
          '<div>' +
          '<div class="attentionSummary">' +
          escapeHtml(
            item.summary ||
            'Meaningful state change detected.'
          ) +
          '</div>' +
          '<div class="attentionTime">' +
          escapeHtml(
            relativeTime(
              item.detected_at
            )
          ) +
          '</div>' +
          '</div>' +
          '<div class="severityPill ' +
          escapeHtml(
            item.significance ||
            'medium'
          ) +
          '">' +
          escapeHtml(
            item.significance ||
            'medium'
          ) +
          '</div>' +
          '</div>'
      )
      .join('') +
    (hidden.length
      ? '<details class="attentionMore"><summary>Show '+hidden.length+' more changes</summary>' +
        hidden.map(item => '<div class="attentionItem compact"><div class="attentionSymbol">'+escapeHtml(item.symbol || '-')+'</div><div><div class="attentionSummary">'+escapeHtml(item.summary || 'Meaningful state change detected.')+'</div><div class="attentionTime">'+escapeHtml(relativeTime(item.detected_at))+'</div></div><div class="severityPill '+escapeHtml(item.significance || 'medium')+'">'+escapeHtml(item.significance || 'medium')+'</div></div>').join('') +
        '</details>'
      : '');
}

