/* =========================================================
   OVERVIEW
========================================================= */

function decisionChangeValues(
  decision,
  live
) {
  const livePrice =
    finiteNumber(
      live?.price
    );

  const decisionPrice =
    finiteNumber(
      decision?.price
    );

  const price =
    livePrice ??
    decisionPrice;

  const previousClose =
    finiteNumber(
      decision?.previousClose
    );

  let change =
    finiteNumber(
      decision?.dayChange
    );

  let pct =
    finiteNumber(
      decision?.dayChangePct
    );

  if (
    Number.isFinite(
      price
    ) &&
    Number.isFinite(
      previousClose
    ) &&
    previousClose !==
      0
  ) {
    change =
      price -
      previousClose;

    pct =
      (
        change /
        previousClose
      ) *
      100;
  }

  return {
    price:
      Number.isFinite(
        price
      )
        ? price
        : null,

    change:
      Number.isFinite(
        change
      )
        ? change
        : null,

    pct:
      Number.isFinite(
        pct
      )
        ? pct
        : null
  };
}

function renderDecisionOverview(
  result
) {
  const decision =
    result?.decision ||
    {};

  const live =
    result?.live ||
    null;

  const session =
    decision.session ||
    live?.session ||
    {};

  const values =
    decisionChangeValues(
      decision,
      live
    );

  const changeClass =
    percentClass(
      values.pct
    );

  const arrow =
    values.pct > 0
      ? '▲'
      : values.pct < 0
        ? '▼'
        : '•';

  const sessionLabel =
    live?.marketStatus
      ?.known
      ? live.marketStatus.isOpen
        ? 'Today'
        : 'Last session'
      : 'Session';

  const changeText =
    values.change !==
      null &&
    values.pct !==
      null
      ? (
          arrow +
          ' PKR ' +
          formatNumber(
            Math.abs(
              values.change
            )
          ) +
          ' (' +
          formatPercent(
            Math.abs(
              values.pct
            )
          ) +
          ') ' +
          sessionLabel
        )
      : 'Session change unavailable';

  const averageVolume =
    decision
      .averageVolume30d;

  const sessionVolume =
    session.volume ??
    decision.sessionVolume;

  const volumeVsAverage =
    sessionVolume !==
      null &&
    averageVolume !==
      null &&
    Number(
      averageVolume
    ) > 0
      ? (
          Number(
            sessionVolume
          ) /
          Number(
            averageVolume
          )
        ) *
        100
      : decision
          .volumeVsAveragePct;

  const volumeSub =
    Number.isFinite(
      Number(
        volumeVsAverage
      )
    )
      ? (
          formatNumber(
            volumeVsAverage,
            0
          ) +
          '% of 30D avg'
        )
      : '';

  let html =
    identityNote(
      result.identity
    ) +

    '<div class="decisionHeader">' +

    '<div>' +

    '<div class="decisionPrice">' +
    'PKR ' +
    formatNumber(
      values.price
    ) +
    '</div>' +

    '<div class="decisionChange ' +
    changeClass +
    '">' +
    escapeHtml(
      changeText
    ) +
    '</div>' +

    '<div class="decisionTimestamp">' +
    escapeHtml(
      live?.feedLabel ||
      decision.feedLabel ||
      'Latest available price'
    ) +

    (
      decision.priceTimestamp
        ? (
            ' &bull; ' +
            escapeHtml(
              formatDateTime(
                decision
                  .priceTimestamp
              )
            )
          )
        : ''
    ) +

    '</div>' +

    '</div>' +

    '</div>';

  html +=
    '<div class="decisionSection">' +

    '<div class="decisionSectionTitle">' +
    'Market context' +
    '</div>' +

    '<div class="summaryGrid">' +

    metricCard(
      'Open',
      'PKR ' +
      formatNumber(
        session.open
      )
    ) +

    metricCard(
      'High',
      'PKR ' +
      formatNumber(
        session.high
      )
    ) +

    metricCard(
      'Low',
      'PKR ' +
      formatNumber(
        session.low
      )
    ) +

    metricCard(
      'Volume',
      formatNumber(
        sessionVolume,
        0
      ),
      volumeSub
    ) +

    '</div>' +

    buildRangeCard(
      'Day range',
      session.low,
      session.high,
      values.price
    ) +

    '<div class="sourceNote">' +

    (
      decision.sessionSource
        ? (
            'Session statistics: ' +
            escapeHtml(
              decision
                .sessionSource
            ) +
            '.'
          )
        : ''
    ) +

    '</div>' +

    '</div>';

  html +=
    '<div class="decisionSection">' +

    '<div class="decisionSectionTitle">' +
    'Performance' +
    '</div>' +

    '<div class="summaryGrid">' +

    '<div class="metric">' +

    '<div class="metricLabel">' +
    'YTD change' +
    '</div>' +

    '<div class="metricValue ' +
    percentClass(
      decision.ytdChangePct
    ) +
    '">' +

    formatPercent(
      decision.ytdChangePct
    ) +

    '</div>' +

    '</div>' +

    '<div class="metric">' +

    '<div class="metricLabel">' +
    '1Y change' +
    '</div>' +

    '<div class="metricValue ' +
    percentClass(
      decision.change1yPct
    ) +
    '">' +

    formatPercent(
      decision.change1yPct
    ) +

    '</div>' +

    '</div>' +

    '</div>' +

    buildRangeCard(
      '52-week range',
      decision.range52?.low,
      decision.range52?.high,
      values.price
    ) +

    '</div>';

  html +=
    '<div class="decisionSection">' +

    '<div class="decisionSectionTitle">' +
    'Valuation & income' +
    '</div>' +

    '<div class="summaryGrid">' +

    metricCard(
      'P/E',
      decision.peRatio ===
        null ||
      decision.peRatio ===
        undefined
        ? 'N/A'
        : formatNumber(
            decision.peRatio
          )
    ) +

    metricCard(
      'Dividend yield',
      decision.dividendYield ===
        null ||
      decision.dividendYield ===
        undefined
        ? 'N/A'
        : formatPercent(
            decision.dividendYield
          )
    ) +

    '</div>' +

    '</div>';

  $('research')
    .innerHTML =
      html;
}

