function renderMoreData(
  result
) {
  const decision =
    result?.decision ||
    {};

  const cards = [];

  if (
    decision.previousClose !==
      null &&
    decision.previousClose !==
      undefined
  ) {
    cards.push(
      metricCard(
        'Previous close',
        'PKR ' +
        formatNumber(
          decision.previousClose
        )
      )
    );
  }

  if (
    decision.averageVolume30d !==
      null &&
    decision.averageVolume30d !==
      undefined
  ) {
    cards.push(
      metricCard(
        '30D avg volume',
        formatNumber(
          decision
            .averageVolume30d,
          0
        )
      )
    );
  }

  if (
    decision.marketCapPkr !==
      null &&
    decision.marketCapPkr !==
      undefined
  ) {
    cards.push(
      metricCard(
        decision.marketCapSource ===
          'estimated'
          ? 'Estimated market cap'
          : 'Market cap',

        formatCompactPKR(
          decision
            .marketCapPkr
        ),

        decision.marketCapSource ===
          'estimated'
          ? 'Latest price × shares outstanding'
          : 'PSX / connected source'
      )
    );
  }

  if (
    decision.shares !==
      null &&
    decision.shares !==
      undefined
  ) {
    cards.push(
      metricCard(
        'Shares outstanding',
        formatNumber(
          decision.shares,
          0
        )
      )
    );
  }

  if (
    decision.freeFloatShares !==
      null &&
    decision.freeFloatShares !==
      undefined
  ) {
    cards.push(
      metricCard(
        'Free float shares',
        formatNumber(
          decision
            .freeFloatShares,
          0
        )
      )
    );
  }

  if (
    decision.freeFloatPercent !==
      null &&
    decision.freeFloatPercent !==
      undefined
  ) {
    cards.push(
      metricCard(
        'Free float',
        formatPercent(
          decision
            .freeFloatPercent
        )
      )
    );
  }

  let html =
    identityNote(
      result.identity
    ) +

    '<div class="decisionSectionTitle">' +
    'Advanced market data' +
    '</div>';

  html +=
    cards.length
      ? (
          '<div class="summaryGrid">' +
          cards.join('') +
          '</div>'
        )
      : (
          '<div class="emptyState">' +
          'No additional reliable market fields are available for this symbol.' +
          '</div>'
        );

  html +=
    '<details>' +

    '<summary>' +
    'Data & Sources' +
    '</summary>' +

    '<pre>' +
    escapeHtml(
      JSON.stringify(
        {
          canonicalSymbol:
            result.identity
              ?.canonicalSymbol ||
            result.symbol,

          marketSymbol:
            result.identity
              ?.tradingSymbol ||
            result.symbol,

          rawMarketSymbol:
            result.identity
              ?.rawMarketSymbol ||
            null,

          statusCodes:
            result.identity
              ?.statusCodes ||
            [],

          quoteProvider:
            'psxdata-api',

          quoteProviderSymbol:
            result.quoteProviderSymbol ||
            null,

          intradayProvider:
            result.live
              ? 'pyPSX'
              : null,

          intradayProviderSymbol:
            result.live
              ?.providerSymbol ||
            null,

          companyProvider:
            result.official
              ? 'PSX Data Portal'
              : null,

          sessionSource:
            decision.sessionSource ||
            null,

          marketCapSource:
            decision.marketCapSource ||
            null,

          quoteTimestamp:
            result.meta?.timestamp ||
            null,

          liveTimestamp:
            result.live?.timestamp ||
            null,

          companyFetchedAt:
            result.official
              ?.fetchedAt ||
            null,

          companySourceUrl:
            result.official
              ?.sourceUrl ||
            null
        },
        null,
        2
      )
    ) +
    '</pre>' +

    '</details>';

  $('research')
    .innerHTML =
      html;
}

/* =========================================================
   LIVE REFRESH
========================================================= */

function stopLiveRefresh() {
  if (
    liveRefreshTimer
  ) {
    clearInterval(
      liveRefreshTimer
    );
  }

  liveRefreshTimer =
    null;

  liveRefreshSymbol =
    null;

  liveView =
    null;

  lastLiveChartResult =
    null;
}

function renderFeedStatus(
  result
) {
  const state =
    result.feedState ||
    'LATEST';

  const dotClass =
    state === 'LIVE'
      ? 'live'
      : state === 'DELAYED'
        ? 'delayed'
        : 'closed';

  const marketClosed =
    Boolean(
      result?.marketStatus?.known &&
      !result.marketStatus.isOpen
    );

  if (marketClosed) {
    $('liveStatus')
      .innerHTML =
        '<span class="feedDot closed"></span>' +
        '<span class="feedPrice">' +
        escapeHtml(
          marketClosedLabel(
            result.marketStatus
          )
        ) +
        '</span>' +
        '<span class="feedMeta">Last market price PKR ' +
        formatNumber(
          result.price
        ) +
        ' · Updated ' +
        escapeHtml(
          formatDateTime(
            result.timestamp
          )
        ) +
        '</span>';

    return;
  }

  $('liveStatus')
    .innerHTML =
      '<span class="feedDot ' +
      dotClass +
      '"></span>' +

      '<span class="feedPrice">' +
      escapeHtml(
        result.feedLabel ||
        'Latest available'
      ) +
      ': PKR ' +
      formatNumber(
        result.price
      ) +
      '</span>' +

      '<span class="feedMeta">' +
      'Updated ' +
      escapeHtml(
        formatDateTime(
          result.timestamp
        )
      ) +
      '</span>';
}

function shouldAutoRefresh(
  result
) {
  return Boolean(
    result?.marketStatus?.known &&
    result?.marketStatus?.isOpen
  );
}

function scheduleLiveRefresh(
  callback,
  result
) {
  if (
    liveRefreshTimer
  ) {
    clearInterval(
      liveRefreshTimer
    );
  }

  liveRefreshTimer =
    null;

  if (
    !shouldAutoRefresh(
      result
    )
  ) {
    return;
  }

  liveRefreshTimer =
    setInterval(
      callback,
      15000
    );
}

async function refreshLiveOverview(
  symbol,
  silent = false
) {
  try {
    const result =
      await api(
        'live-price',
        {
          symbol
        }
      );

    if (
      liveRefreshSymbol ===
        symbol &&
      liveView ===
        'overview'
    ) {
      renderFeedStatus(
        result
      );

      if (
        lastQuoteResult &&
        lastQuoteResult.symbol ===
          result.symbol
      ) {
        lastQuoteResult.live =
          result;

        if (
          result.marketStatus
            ?.isOpen
        ) {
          lastQuoteResult
            .decision
            .session =
              result.session;

          lastQuoteResult
            .decision
            .sessionSource =
              'pyPSX';

          lastQuoteResult
            .decision
            .price =
              result.price;

          lastQuoteResult
            .decision
            .priceTimestamp =
              result.timestamp;
        }

        renderDecisionOverview(
          lastQuoteResult
        );
      }
    }

    return result;
  } catch (error) {
    if (
      !silent
    ) {
      const officialPrice =
        Number(
          lastQuoteResult
            ?.decision
            ?.price
        );

      if (
        Number.isFinite(
          officialPrice
        ) &&
        officialPrice > 0
      ) {
        $('liveStatus')
          .innerHTML =
            '<span class="feedDot delayed"></span>' +
            '<span class="feedPrice">Official PSX quote: PKR ' +
            formatNumber(
              officialPrice
            ) +
            '</span>' +
            '<span class="feedMeta">Secondary intraday feed unavailable</span>';
      } else {
        $('liveStatus')
          .innerHTML =
            '<span class="feedWarning">' +
            'Latest market price unavailable: ' +
            escapeHtml(
              error.message
            ) +
            '</span>';
      }
    }

    return null;
  }
}

async function startLiveOverview(
  symbol,
  initialResult = null
) {
  stopLiveRefresh();

  if (!symbol) {
    return;
  }

  liveRefreshSymbol =
    symbol;

  liveView =
    'overview';

  let result =
    initialResult;

  if (
    result
  ) {
    renderFeedStatus(
      result
    );
  } else {
    result =
      await refreshLiveOverview(
        symbol
      );
  }

  if (
    result
  ) {
    scheduleLiveRefresh(
      () =>
        refreshLiveOverview(
          symbol,
          true
        ),

      result
    );
  }
}

/* =========================================================
   LIVE CHART
========================================================= */

function chartDirectionClass(
  row,
  prefix
) {
  const open =
    Number(
      row.open
    );

  const close =
    Number(
      row.close
    );

  if (
    close > open
  ) {
    return prefix +
      'Up';
  }

  if (
    close < open
  ) {
    return prefix +
      'Down';
  }

  return prefix +
    'Flat';
}

function buildPriceGrid(
  min,
  max,
  width,
  paddingLeft,
  paddingRight,
  paddingTop,
  priceHeight
) {
  let lines = '';

  for (
    let index = 0;
    index < 5;
    index++
  ) {
    const fraction =
      index /
      4;

    const price =
      max -
      fraction *
      (
        max -
        min
      );

    const lineY =
      paddingTop +
      fraction *
      priceHeight;

    lines +=
      '<line x1="' +
      paddingLeft +
      '" x2="' +
      (
        width -
        paddingRight
      ) +
      '" y1="' +
      lineY +
      '" y2="' +
      lineY +
      '" class="chartAxis" />' +

      '<text x="5" y="' +
      (
        lineY +
        4
      ) +
      '" class="chartLabel">' +

      formatNumber(
        price,
        2
      ) +

      '</text>';
  }

  return lines;
}

function buildIntradayLineChart(
  rows
) {
  if (
    !rows ||
    rows.length < 2
  ) {
    return (
      '<div class="emptyState">' +
      'Not enough intraday data.' +
      '</div>'
    );
  }

  const width = 1000;
  const height = 410;
  const left = 65;
  const right = 20;
  const top = 20;
  const priceHeight = 265;

  const usableWidth =
    width -
    left -
    right;

  const closes =
    rows.map(
      row =>
        Number(
          row.close
        )
    );

  let min =
    Math.min(
      ...closes
    );

  let max =
    Math.max(
      ...closes
    );

  if (
    min === max
  ) {
    min *= .995;
    max *= 1.005;
  }

  const margin =
    Math.max(
      (
        max -
        min
      ) *
      .08,

      max *
      .002
    );

  min -= margin;
  max += margin;

  const x =
    index =>
      left +
      (
        index /
        (
          rows.length -
          1
        )
      ) *
      usableWidth;

  const y =
    price =>
      top +
      (
        1 -
        (
          (
            price -
            min
          ) /
          (
            max -
            min
          )
        )
      ) *
      priceHeight;

  const points =
    rows.map(
      (
        row,
        index
      ) =>
        x(index) +
        ',' +
        y(
          row.close
        )
    )
      .join(' ');

  const bottomY =
    top +
    priceHeight;

  const areaPoints =
    x(0) +
    ',' +
    bottomY +
    ' ' +
    points +
    ' ' +
    x(
      rows.length -
      1
    ) +
    ',' +
    bottomY;

  return (
    '<div class="chartBox">' +

    '<div class="chartTitle">' +
    'Intraday line + volume' +
    '</div>' +

    '<svg class="candleChart" viewBox="0 0 ' +
    width +
    ' ' +
    height +
    '" preserveAspectRatio="none">' +

    buildPriceGrid(
      min,
      max,
      width,
      left,
      right,
      top,
      priceHeight
    ) +

    '<polygon points="' +
    areaPoints +
    '" class="chartArea" />' +

    '<polyline points="' +
    points +
    '" class="chartLine" />' +

    '</svg>' +

    '</div>'
  );
}

function buildIntradayCandlestickChart(
  rows
) {
  if (
    !rows ||
    rows.length < 2
  ) {
    return (
      '<div class="emptyState">' +
      'Not enough intraday data.' +
      '</div>'
    );
  }

  const width = 1000;
  const height = 430;
  const left = 65;
  const right = 20;
  const top = 20;
  const priceHeight = 275;
  const volumeTop = 322;
  const volumeHeight = 64;

  const usableWidth =
    width -
    left -
    right;

  const normalized =
    rows.map(
      row => {
        const close =
          Number(
            row.close
          );

        const open =
          Number.isFinite(
            Number(
              row.open
            )
          )
            ? Number(
                row.open
              )
            : close;

        const high =
          Number.isFinite(
            Number(
              row.high
            )
          )
            ? Number(
                row.high
              )
            : Math.max(
                open,
                close
              );

        const low =
          Number.isFinite(
            Number(
              row.low
            )
          )
            ? Number(
                row.low
              )
            : Math.min(
                open,
                close
              );

        return {
          ...row,

          open,

          high:
            Math.max(
              high,
              open,
              close
            ),

          low:
            Math.min(
              low,
              open,
              close
            ),

          close,

          volume:
            Number(
              row.volume ||
              0
            )
        };
      }
    );

  let min =
    Math.min(
      ...normalized.map(
        row =>
          row.low
      )
    );

  let max =
    Math.max(
      ...normalized.map(
        row =>
          row.high
      )
    );

  const margin =
    Math.max(
      (
        max -
        min
      ) *
      .06,

      max *
      .0015
    );

  min -= margin;
  max += margin;

  const y =
    price =>
      top +
      (
        1 -
        (
          (
            price -
            min
          ) /
          (
            max -
            min
          )
        )
      ) *
      priceHeight;

  const step =
    usableWidth /
    normalized.length;

  const bodyWidth =
    Math.max(
      .8,
      Math.min(
        7,
        step *
        .68
      )
    );

  const maxVolume =
    Math.max(
      1,
      ...normalized.map(
        row =>
          row.volume
      )
    );

  const candles =
    normalized.map(
      (
        row,
        index
      ) => {
        const centerX =
          left +
          index *
          step +
          step /
          2;

        const openY =
          y(
            row.open
          );

        const closeY =
          y(
            row.close
          );

        const highY =
          y(
            row.high
          );

        const lowY =
          y(
            row.low
          );

        const bodyY =
          Math.min(
            openY,
            closeY
          );

        const bodyHeight =
          Math.max(
            1,
            Math.abs(
              closeY -
              openY
            )
          );

        const candleClass =
          chartDirectionClass(
            row,
            'candle'
          );

        const volumeClass =
          chartDirectionClass(
            row,
            'volume'
          );

        const volumeHeightPx =
          (
            row.volume /
            maxVolume
          ) *
          volumeHeight;

        const volumeY =
          volumeTop +
          volumeHeight -
          volumeHeightPx;

        return (
          '<g>' +

          '<title>' +
          escapeHtml(
            formatTime(
              row.timestamp
            ) +
            ' | O ' +
            formatNumber(
              row.open
            ) +
            ' H ' +
            formatNumber(
              row.high
            ) +
            ' L ' +
            formatNumber(
              row.low
            ) +
            ' C ' +
            formatNumber(
              row.close
            ) +
            ' | Volume ' +
            formatNumber(
              row.volume,
              0
            )
          ) +
          '</title>' +

          '<line x1="' +
          centerX +
          '" x2="' +
          centerX +
          '" y1="' +
          highY +
          '" y2="' +
          lowY +
          '" class="' +
          candleClass +
          '" />' +

          '<rect x="' +
          (
            centerX -
            bodyWidth /
            2
          ) +
          '" y="' +
          bodyY +
          '" width="' +
          bodyWidth +
          '" height="' +
          bodyHeight +
          '" class="' +
          candleClass +
          '" />' +

          '<rect x="' +
          (
            centerX -
            bodyWidth /
            2
          ) +
          '" y="' +
          volumeY +
          '" width="' +
          bodyWidth +
          '" height="' +
          Math.max(
            .5,
            volumeHeightPx
          ) +
          '" class="' +
          volumeClass +
          '" />' +

          '</g>'
        );
      }
    )
      .join('');

  return (
    '<div class="chartBox">' +

    '<div class="chartTitle">' +
    'Intraday candlesticks + volume - 1-minute candles' +
    '</div>' +

    '<div class="chartLegend">' +

    '<span>' +
    '<span class="legendSwatch up"></span>' +
    'Close ≥ open' +
    '</span>' +

    '<span>' +
    '<span class="legendSwatch down"></span>' +
    'Close < open' +
    '</span>' +

    '<span>' +
    'Hover for OHLCV' +
    '</span>' +

    '</div>' +

    '<svg class="candleChart" viewBox="0 0 ' +
    width +
    ' ' +
    height +
    '" preserveAspectRatio="none">' +

    buildPriceGrid(
      min,
      max,
      width,
      left,
      right,
      top,
      priceHeight
    ) +

    '<line x1="' +
    left +
    '" x2="' +
    (
      width -
      right
    ) +
    '" y1="' +
    (
      volumeTop -
      10
    ) +
    '" y2="' +
    (
      volumeTop -
      10
    ) +
    '" class="volumeSeparator" />' +

    candles +

    '<text x="5" y="' +
    (
      volumeTop +
      12
    ) +
    '" class="chartLabel">' +
    'Vol' +
    '</text>' +

    '</svg>' +

    '</div>'
  );
}

function bindLiveChartModeButtons() {
  document
    .querySelectorAll(
      '.chartModeButton'
    )
    .forEach(
      button => {
        button.onclick =
          () => {
            liveChartMode =
              button.dataset
                .mode;

            if (
              lastLiveChartResult
            ) {
              renderLiveChart(
                lastLiveChartResult
              );
            }
          };
      }
    );
}

function renderLiveChart(
  result
) {
  lastLiveChartResult =
    result;

  renderFeedStatus(
    result
  );

  const selectedStock =
    marketRows.find(
      row =>
        row.symbol ===
        result.symbol
    );

  if (
    selectedStock
  ) {
    updateSelectedCompany(
      {
        symbol:
          result.symbol,

        identity:
          result.identity,

        company: {
          name:
            selectedStock.companyName,

          sector:
            selectedStock.sector
        }
      }
    );
  }

  const stateNote =
    result.feedState ===
      'LIVE'
      ? 'Market open - refreshing every 15 seconds'
      : result.feedState ===
        'DELAYED'
        ? 'Market open, but latest candle is delayed'
        : marketClosedLabel(
            result.marketStatus
          ) +
          ' - showing latest trading session';

  const chart =
    liveChartMode ===
      'candles'
      ? buildIntradayCandlestickChart(
          result.data
        )
      : buildIntradayLineChart(
          result.data
        );

  $('research')
    .innerHTML =
      identityNote(
        result.identity
      ) +

      '<div class="liveChartHeader">' +

      '<div>' +

      '<div class="muted">' +
      escapeHtml(
        stateNote
      ) +
      '</div>' +

      '<div class="liveChartPrice">' +
      'PKR ' +
      formatNumber(
        result.price
      ) +
      '</div>' +

      '<div class="feedMeta">' +
      escapeHtml(
        result.sessionDate ||
        ''
      ) +
      ' &bull; pyPSX' +

      (
        result.providerSymbol
          ? (
              ' &bull; feed symbol ' +
              escapeHtml(
                result.providerSymbol
              )
            )
          : ''
      ) +

      '</div>' +

      '</div>' +

      '<div class="chartModeToggle">' +

      '<button class="chartModeButton ' +
      (
        liveChartMode ===
          'candles'
          ? 'active'
          : ''
      ) +
      '" data-mode="candles">' +
      'Candles' +
      '</button>' +

      '<button class="chartModeButton ' +
      (
        liveChartMode ===
          'line'
          ? 'active'
          : ''
      ) +
      '" data-mode="line">' +
      'Line' +
      '</button>' +

      '</div>' +

      '</div>' +

      '<div class="summaryGrid">' +

      metricCard(
        'Session open',
        'PKR ' +
        formatNumber(
          result.session?.open
        )
      ) +

      metricCard(
        'Session high',
        'PKR ' +
        formatNumber(
          result.session?.high
        )
      ) +

      metricCard(
        'Session low',
        'PKR ' +
        formatNumber(
          result.session?.low
        )
      ) +

      metricCard(
        'Session volume',
        formatNumber(
          result.session?.volume,
          0
        )
      ) +

      '</div>' +

      chart;

  bindLiveChartModeButtons();
}

async function refreshLiveChart(
  symbol,
  silent = false
) {
  try {
    const result =
      await api(
        'live-chart',
        {
          symbol
        }
      );

    if (
      liveRefreshSymbol ===
        symbol &&
      liveView ===
        'chart'
    ) {
      renderLiveChart(
        result
      );
    }

    return result;
  } catch (error) {
    if (
      !silent
    ) {
      $('error')
        .textContent =
          error.message;
    }

    return null;
  }
}

async function startLiveChart(
  symbol
) {
  stopLiveRefresh();

  liveRefreshSymbol =
    symbol;

  liveView =
    'chart';

  liveChartMode =
    'candles';

  $('research')
    .innerHTML =
      '<p class="muted">' +
      'Loading intraday chart...' +
      '</p>';

  const result =
    await refreshLiveChart(
      symbol
    );

  if (
    result
  ) {
    scheduleLiveRefresh(
      () =>
        refreshLiveChart(
          symbol,
          true
        ),

      result
    );
  }
}

/* =========================================================
   MARKET TABLE
========================================================= */

function getFilteredRows() {
  const query =
    $('search')
      .value
      .trim()
      .toLowerCase();

  const sector =
    $('sectorFilter')
      .value;

  let rows =
    marketRows.filter(
      stock =>
        (
          stock.symbol +
          ' ' +
          stock.tradingSymbol +
          ' ' +
          stock.rawSymbol +
          ' ' +
          (
            stock.statusCodes ||
            []
          ).join(' ') +
          ' ' +
          stock.companyName +
          ' ' +
          stock.sector
        )
          .toLowerCase()
          .includes(
            query
          ) &&
        (
          !sector ||
          stock.sector ===
            sector
        )
    );

  rows =
    [...rows];

  switch (
    $('sort').value
  ) {
    case 'priceAsc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            a.price ??
            Infinity
          ) -
          (
            b.price ??
            Infinity
          )
      );
      break;

    case 'priceDesc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            b.price ??
            -Infinity
          ) -
          (
            a.price ??
            -Infinity
          )
      );
      break;

    case 'dayChangeDesc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            b.dayChangePct ??
            -Infinity
          ) -
          (
            a.dayChangePct ??
            -Infinity
          )
      );
      break;

    case 'dayChangeAsc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            a.dayChangePct ??
            Infinity
          ) -
          (
            b.dayChangePct ??
            Infinity
          )
      );
      break;

    case 'sessionVolumeDesc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            b.sessionVolume ??
            -Infinity
          ) -
          (
            a.sessionVolume ??
            -Infinity
          )
      );
      break;

    case 'marketCapDesc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            b.marketCap ??
            -Infinity
          ) -
          (
            a.marketCap ??
            -Infinity
          )
      );
      break;

    case 'changeDesc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            b.change1yPct ??
            -Infinity
          ) -
          (
            a.change1yPct ??
            -Infinity
          )
      );
      break;

    case 'changeAsc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            a.change1yPct ??
            Infinity
          ) -
          (
            b.change1yPct ??
            Infinity
          )
      );
      break;

    case 'dividendDesc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            b.dividendYield ??
            -Infinity
          ) -
          (
            a.dividendYield ??
            -Infinity
          )
      );
      break;

    case 'peAsc':
      rows =
        rows
          .filter(
            row =>
              row.peRatio !==
                null &&
              row.peRatio > 0
          )
          .sort(
            (
              a,
              b
            ) =>
              a.peRatio -
              b.peRatio
          );
      break;

    case 'volumeDesc':
      rows.sort(
        (
          a,
          b
        ) =>
          (
            b.averageVolume30d ??
            -Infinity
          ) -
          (
            a.averageVolume30d ??
            -Infinity
          )
      );
      break;

    default:
      rows.sort(
        (
          a,
          b
        ) =>
          a.symbol
            .localeCompare(
              b.symbol
            )
      );
  }

  return rows;
}

function renderStocks() {
  const rows =
    getFilteredRows();

  const pageCount =
    Math.max(
      1,
      Math.ceil(
        rows.length /
        PAGE_SIZE
      )
    );

  if (
    currentPage >
    pageCount
  ) {
    currentPage =
      pageCount;
  }

  const start =
    (
      currentPage -
      1
    ) *
    PAGE_SIZE;

  const pageRows =
    rows.slice(
      start,
      start +
      PAGE_SIZE
    );

  if (
    !pageRows.length
  ) {
    $('stocks')
      .innerHTML =
        '<p>No matching stocks.</p>';

    $('pageInfo')
      .textContent =
        '';

    return;
  }

  $('stocks')
    .innerHTML =
      '<table class="exploreTable">' +

      '<thead>' +

      '<tr>' +

      '<th>Symbol</th>' +
      '<th>Company</th>' +
      '<th>Price</th>' +
      '<th>Today</th>' +
      '<th>Volume</th>' +
      '<th>P/E</th>' +
      '<th>Div Yield</th>' +
      '<th>1Y</th>' +

      '</tr>' +

      '</thead>' +

      '<tbody>' +

      pageRows.map(
        stock => {
          const differentMarketSymbol =
            stock.tradingSymbol &&
            stock.tradingSymbol !==
              stock.symbol;

          return (
            '<tr data-symbol="' +
            escapeHtml(
              stock.symbol
            ) +
            '">' +

            '<td class="symbol">' +

            escapeHtml(
              stock.symbol
            ) +

            (
              stock.statusCodes
                ?.length
                ? (
                    ' ' +
                    statusPills(
                      stock.statusCodes
                    )
                  )
                : ''
            ) +

            (
              differentMarketSymbol
                ? (
                    '<span class="symbolSub">' +
                    'Market: ' +
                    escapeHtml(
                      stock.tradingSymbol
                    ) +
                    '</span>'
                  )
                : ''
            ) +

            '</td>' +

            '<td class="company">' +
            escapeHtml(
              stock.companyName
            ) +
            '</td>' +

            '<td class="' +
            (
              explorePreviousPrices.has(
                stock.symbol
              ) &&
              Number(stock.price) >
                Number(
                  explorePreviousPrices.get(
                    stock.symbol
                  )
                )
                ? 'positive livePriceUp'
                : explorePreviousPrices.has(
                    stock.symbol
                  ) &&
                  Number(stock.price) <
                    Number(
                      explorePreviousPrices.get(
                        stock.symbol
                      )
                    )
                  ? 'negative livePriceDown'
                  : ''
            ) +
            '">PKR ' +
            formatNumber(
              stock.price
            ) +
            '</td>' +

            '<td class="' +
            percentClass(
              stock.dayChangePct
            ) +
            '">' +
            (
              stock.dayChangePct === null ||
              stock.dayChangePct === undefined
                ? '—'
                : formatPercent(
                    stock.dayChangePct
                  )
            ) +
            '</td>' +

            '<td class="volumeCell">' +
            '<span class="metricPrimary">' +
            (
              stock.sessionVolume === null ||
              stock.sessionVolume === undefined
                ? '—'
                : formatCompactNumber(
                    stock.sessionVolume
                  )
            ) +
            '</span>' +
            '<span class="metricSecondary">30D ' +
            (
              stock.averageVolume30d === null ||
              stock.averageVolume30d === undefined
                ? '—'
                : formatCompactNumber(
                    stock.averageVolume30d
                  )
            ) +
            '</span>' +
            '</td>' +

            '<td>' +
            (
              stock.peRatio ===
                null
                ? '—'
                : formatNumber(
                    stock.peRatio
                  )
            ) +
            '</td>' +

            '<td>' +
            (
              stock.dividendYield ===
                null
                ? '—'
                : formatPercent(
                    stock.dividendYield
                  )
            ) +
            '</td>' +

            '<td class="' +
            percentClass(
              stock.change1yPct
            ) +
            '">' +
            formatPercent(
              stock.change1yPct
            ) +
            '</td>' +

            '</tr>'
          );
        }
      )
        .join('') +

      '</tbody>' +

      '</table>';

  const first =
    start + 1;

  const last =
    Math.min(
      start +
      PAGE_SIZE,
      rows.length
    );

  $('pageInfo')
    .textContent =
      first +
      '-' +
      last +
      ' of ' +
      rows.length +
      ' results | Page ' +
      currentPage +
      ' of ' +
      pageCount;

  $('previousPage')
    .disabled =
      currentPage <= 1;

  $('nextPage')
    .disabled =
      currentPage >=
      pageCount;

  document.querySelectorAll(
    '#stocks tbody tr'
  )
    .forEach(
      row => {
        row.onclick =
          () => {
            const symbol =
              row.dataset
                .symbol;

            $('stockSymbol')
              .value =
                symbol;

            showSelectedCompany(
              symbol
            );

            $('researchSection')
              .scrollIntoView({
                behavior:
                  'smooth',

                block:
                  'start'
              });
          };
      }
    );
}

function populateSectors() {
  const sectors =
    [
      ...new Set(
        marketRows
          .map(
            row =>
              row.sector
          )
          .filter(
            value =>
              value &&
              value !==
                'Unknown'
          )
      )
    ]
      .sort();

  $('sectorFilter')
    .innerHTML =
      '<option value="">' +
      'All sectors' +
      '</option>' +

      sectors.map(
        sector =>
          '<option value="' +
          escapeHtml(
            sector
          ) +
          '">' +
          escapeHtml(
            sector
          ) +
          '</option>'
      )
        .join('');
}

async function loadDecisionUniverseEntries() {
  if (decisionUniverseEntries.length) {
    return decisionUniverseEntries;
  }

  if (!decisionUniversePromise) {
    decisionUniversePromise =
      api('universe-master')
        .then(
          universe => {
            decisionUniverseEntries =
              (universe.entries || [])
                .filter(
                  entry =>
                    entry &&
                    (
                      entry.recommendationEligible === true ||
                      entry.universeClass === 'CORE_EQUITY'
                    )
                );

            return decisionUniverseEntries;
          }
        )
        .catch(
          error => {
            decisionUniversePromise = null;
            throw error;
          }
        );
  }

  return decisionUniversePromise;
}

async function populateStrategySymbolOptions() {
  const target =
    $('strategySymbolOptions');

  if (!target) {
    return;
  }

  try {
    const entries =
      await loadDecisionUniverseEntries();

    target.innerHTML =
      entries
        .slice()
        .sort(
          (a, b) =>
            String(a.symbol || '')
              .localeCompare(
                String(b.symbol || '')
              )
        )
        .map(
          entry =>
            '<option value="' +
            escapeHtml(
              String(entry.symbol || '')
                .trim()
                .toUpperCase()
            ) +
            '">' +
            escapeHtml(
              entry.companyName ||
              entry.symbol ||
              ''
            ) +
            '</option>'
        )
        .join('');
  } catch {
    target.innerHTML = '';
  }
}

async function resolveStrategySymbolInput(
  rawValue
) {
  const raw =
    String(rawValue || '')
      .trim();

  const normalized =
    raw.toUpperCase();

  if (!normalized) {
    return '';
  }

  try {
    const entries =
      await loadDecisionUniverseEntries();

    const exactSymbol =
      entries.find(
        entry =>
          String(entry.symbol || '')
            .trim()
            .toUpperCase() ===
          normalized
      );

    if (exactSymbol) {
      return String(
        exactSymbol.symbol
      )
        .trim()
        .toUpperCase();
    }

    const exactName =
      entries.find(
        entry =>
          String(entry.companyName || '')
            .trim()
            .toUpperCase() ===
          normalized
      );

    if (exactName) {
      return String(
        exactName.symbol
      )
        .trim()
        .toUpperCase();
    }
  } catch {}

  // Fall back to the typed PSX symbol so the server remains the final validator.
  return normalized;
}

async function populateDecisionSectors() {
  const target =
    $('decisionSector');

  if (!target) {
    return;
  }

  const currentValue =
    target.value ||
    target.dataset.pendingValue ||
    '';

  let sectors =
    [
      ...new Set(
        marketRows
          .map(
            row =>
              String(
                row.sector ||
                ''
              ).trim()
          )
          .filter(
            value =>
              value &&
              value.toUpperCase() !==
                'UNKNOWN'
          )
      )
    ].sort();

  // Decision Center can be opened directly before Explore PSX has loaded.
  // In that case marketRows is still empty, so use the canonical universe.
  if (!sectors.length) {
    try {
      const entries =
        await loadDecisionUniverseEntries();

      sectors =
        [
          ...new Set(
            entries
              .map(
                entry =>
                  String(
                    entry.sector ||
                    ''
                  ).trim()
              )
              .filter(
                value =>
                  value &&
                  value.toUpperCase() !==
                    'UNKNOWN'
              )
          )
        ].sort();
    } catch {
      // Keep the default option if the universe request itself fails.
      sectors = [];
    }
  }

  target.innerHTML =
    '<option value="">All industries</option>' +
    sectors.map(
      sector =>
        '<option value="' +
        escapeHtml(sector) +
        '">' +
        escapeHtml(sector) +
        '</option>'
    ).join('');

  try {
    const storedContext =
      JSON.parse(
        localStorage.getItem(
          'nomadDecisionContext'
        ) ||
        'null'
      );

    const preferredSector =
      storedContext?.sector ||
      currentValue ||
      '';

    if (
      preferredSector &&
      sectors.includes(
        preferredSector
      )
    ) {
      target.value =
        preferredSector;
    }
  } catch {}
}

/* =========================================================
   METADATA / SECURITY UNIVERSE AUDIT UI
========================================================= */

function auditBucketClass(
  bucket
) {
  if (
    bucket ===
      'UNRESOLVED' ||
    bucket ===
      'LEGACY_STALE_CANDIDATE' ||
    bucket ===
      'HISTORICAL_SECURITY'
  ) {
    return 'danger';
  }

  if (
    bucket ===
      'LIKELY_SPECIAL_INSTRUMENT'
  ) {
    return 'warning';
  }

  return 'info';
}

function universeClassPill(
  row
) {
  const danger =
    row.universeClass ===
      'HISTORICAL_OR_INACTIVE' ||
    row.universeClass ===
      'LEGACY_STALE_CANDIDATE';

  const warning =
    row.universeClass ===
      'SPECIAL_INSTRUMENT' ||
    row.universeClass ===
      'SUSPENDED_SECURITY' ||
    row.universeClass ===
      'REVIEW_REQUIRED';

  const className =
    danger
      ? 'danger'
      : warning
        ? 'warning'
        : 'info';

  return (
    '<span class="auditPill ' +
    className +
    '">' +
    escapeHtml(
      row.universeLabel ||
      row.universeClass ||
      'Unverified'
    ) +
    '</span>'
  );
}

function tradingStatusPill(
  row
) {
  const status =
    row.tradingStatus ||
    'UNKNOWN';

  const dangerStatuses = [
    'DELISTED',
    'CHANGED',
    'MERGED',
    'MIGRATED_OR_SYMBOL_CHANGED',
    'HISTORICAL_OR_INACTIVE',
    'NO_COMPANY_PAGE_EVIDENCE'
  ];

  const warningStatuses = [
    'SUSPENDED',
    'PAGE_STATUS_UNCLEAR',
    'UNKNOWN'
  ];

  const className =
    dangerStatuses.includes(
      status
    )
      ? 'danger'
      : warningStatuses.includes(
          status
        )
        ? 'warning'
        : 'info';

  return (
    '<span class="auditPill ' +
    className +
    '">' +
    escapeHtml(
      row.tradingStatusLabel ||
      status
    ) +
    '</span>'
  );
}

function clientCountBy(
  rows,
  key
) {
  const counts = {};

  rows.forEach(
    row => {
      const value =
        row?.[key];

      if (!value) {
        return;
      }

      counts[value] =
        (
          counts[value] ||
          0
        ) +
        1;
    }
  );

  return counts;
}

function recalculateMetadataAuditResult(
  result
) {
  const universe =
    Array.isArray(
      result.universe
    )
      ? result.universe
      : [];

  const issues =
    universe.filter(
      row =>
        Boolean(
          row.issueType
        )
    );

  const namesResolved =
    universe.filter(
      row =>
        row.nameResolved
    ).length;

  const sectorsResolved =
    universe.filter(
      row =>
        row.sectorResolved
    ).length;

  const universeClasses =
    clientCountBy(
      universe,
      'universeClass'
    );

  const tradingStatusCounts =
    clientCountBy(
      universe,
      'tradingStatus'
    );

  const eligibilityCounts =
    clientCountBy(
      universe,
      'eligibility'
    );

  const sourceCoverage = {
    ...(
      result.sourceCoverage ||
      {}
    ),

    companyPage:
      universe.filter(
        row =>
          row.hasOfficialPageEvidence
      ).length
  };

  return {
    ...result,

    resolvedAt:
      new Date()
        .toISOString(),

    summary: {
      ...(
        result.summary ||
        {}
      ),

      totalCanonicalSecurities:
        universe.length,

      namesResolved,

      namesMissing:
        universe.length -
        namesResolved,

      sectorsResolved,

      sectorsMissing:
        universe.length -
        sectorsResolved,

      statusSymbolsNormalized:
        universe.filter(
          row =>
            row.normalizedStatus
        ).length,

      totalMetadataIssues:
        issues.length,

      totalSpecialInstrumentsDetected:
        universe.filter(
          row =>
            row.isSpecialSecurity
        ).length,

      verifiedCurrentSecurities:
        universeClasses.VERIFIED_CURRENT ||
        0,

      specialInstrumentSecurities:
        universeClasses.SPECIAL_INSTRUMENT ||
        0,

      legacyStaleCandidates:
        universeClasses.LEGACY_STALE_CANDIDATE ||
        0,

      historicalOrInactive:
        universeClasses.HISTORICAL_OR_INACTIVE ||
        0,

      suspendedSecurities:
        (
          tradingStatusCounts.SUSPENDED ||
          0
        ),

      delistedSecurities:
        tradingStatusCounts.DELISTED ||
        0,

      changedOrMigratedSymbols:
        (
          tradingStatusCounts.CHANGED ||
          0
        ) +
        (
          tradingStatusCounts.MERGED ||
          0
        ) +
        (
          tradingStatusCounts.MIGRATED_OR_SYMBOL_CHANGED ||
          0
        ),

      statusReviewRequired:
        (
          universeClasses.REVIEW_REQUIRED ||
          0
        ) +
        (
          universeClasses.UNVERIFIED ||
          0
        ),

      coreEquityCandidates:
        eligibilityCounts.CORE_EQUITY_CANDIDATE ||
        0,

      gemEquityCandidates:
        eligibilityCounts.GEM_EQUITY_CANDIDATE ||
        0
    },

    sourceCoverage,

    universeClasses,
    tradingStatusCounts,
    eligibilityCounts,

    issueBuckets:
      clientCountBy(
        issues,
        'bucket'
      ),

    issueTypes:
      clientCountBy(
        issues,
        'issueType'
      ),

    securityTypes:
      clientCountBy(
        universe,
        'securityType'
      ),

    issuerTypes:
      clientCountBy(
        universe,
        'issuerType'
      ),

    issues,
    universe
  };
}

