/* =========================================================
   FUNDAMENTALS
========================================================= */

function financialMetricRow(
  table,
  matcher
) {
  return table?.rows
    ?.find(
      row =>
        matcher.test(
          String(
            row.label ||
            ''
          )
        )
    ) ||
    null;
}

function financialMetricFromTable(
  table,
  matcher
) {
  const row =
    financialMetricRow(
      table,
      matcher
    );

  return row
    ?.values?.[0] ||
    null;
}

function financialYoYChange(
  table,
  matcher
) {
  const row =
    financialMetricRow(
      table,
      matcher
    );

  if (
    !row?.values ||
    row.values.length <
      2
  ) {
    return null;
  }

  const latest =
    finiteNumber(
      row.values[0]
        .value
    );

  const previous =
    finiteNumber(
      row.values[1]
        .value
    );

  if (
    latest === null ||
    previous === null ||
    previous === 0
  ) {
    return null;
  }

  return (
    (
      latest -
      previous
    ) /
    Math.abs(
      previous
    )
  ) *
  100;
}

function renderFinancialTable(
  title,
  table
) {
  if (
    !table?.periods?.length ||
    !table?.rows?.length
  ) {
    return '';
  }

  return (
    '<div class="decisionSection">' +

    '<div class="decisionSectionTitle">' +
    escapeHtml(
      title
    ) +
    '</div>' +

    '<div class="dataTable">' +

    '<table>' +

    '<thead>' +

    '<tr>' +

    '<th>Metric</th>' +

    table.periods.map(
      period =>
        '<th>' +
        escapeHtml(
          period
        ) +
        '</th>'
    )
      .join('') +

    '</tr>' +

    '</thead>' +

    '<tbody>' +

    table.rows.map(
      row =>
        '<tr>' +

        '<td><strong>' +
        escapeHtml(
          row.label
        ) +
        '</strong></td>' +

        row.values.map(
          value =>
            '<td>' +
            escapeHtml(
              value.raw ||
              'N/A'
            ) +
            '</td>'
        )
          .join('') +

        '</tr>'
    )
      .join('') +

    '</tbody>' +

    '</table>' +

    '</div>' +

    '</div>'
  );
}

