/* =========================================================
   MARKET BUTTON
========================================================= */

async function loadExploreMarket(
  manualRefresh = false
) {
  if (exploreRefreshInFlight) {
    return;
  }

  exploreRefreshInFlight =
    true;

  $('error')
    .textContent =
      '';

  if ($('loadMarket')) {
    $('loadMarket')
      .disabled =
        true;
  }

  const status =
    $('exploreLiveStatus');

  if (
    status &&
    !marketRows.length
  ) {
    status.innerHTML =
      '<span class="feedDot delayed"></span>' +
      '<span class="feedMeta">Loading latest PSX market feed...</span>';
  }

  try {
    const result =
      await api(
        'market'
      );

    explorePreviousPrices =
      new Map(
        marketRows.map(
          row => [
            row.symbol,
            row.price
          ]
        )
      );

    marketRows =
      (
        result.stocks ||
        []
      ).filter(
        row =>
          row.marketFactEligible ===
          true
      );

    if (
      manualRefresh ||
      currentPage < 1
    ) {
      currentPage = 1;
    }

    const marketStatus =
      result.marketStatus ||
      null;

    const marketOpen =
      Boolean(
        marketStatus?.known &&
        marketStatus.isOpen
      );

    const marketClosed =
      Boolean(
        marketStatus?.known &&
        !marketStatus.isOpen
      );

    const updatedLabel =
      relativeTime(
        result.marketWatchAsOf ||
        result.asOf
      ) ||
      'now';

    $('coverage')
      .textContent =
        marketOpen
          ? (
              (
                result.sessionChangeCoverage ||
                0
              ) +
              '/' +
              (
                result.marketFactCount ||
                marketRows.length
              ) +
              ' active equities · Official PSX · 10 sec refresh · Updated ' +
              updatedLabel
            )
          : marketClosed
            ? (
                (
                  result.marketFactCount ||
                  marketRows.length
                ) +
                ' active equities · ' +
                marketClosedLabel(
                  marketStatus
                ) +
                ' · Feed refreshed ' +
                updatedLabel
              )
            : (
                (
                  result.marketFactCount ||
                  marketRows.length
                ) +
                ' active equities · Market status unavailable · Updated ' +
                updatedLabel
              );

    populateSectors();
    populateDecisionSectors();

    renderStocks();

    if (status) {
      if (marketOpen) {
        status.innerHTML =
          '<span class="feedDot live"></span>' +
          '<span class="feedPrice">Official PSX market feed</span>' +
          '<span class="feedMeta">Active Main Board equities · PSX Data Portal (up to 5 min delayed) · ' +
          escapeHtml(
            updatedLabel
          ) +
          ' · refreshing every 10 sec</span>';
      } else if (marketClosed) {
        status.innerHTML =
          '<span class="feedDot closed"></span>' +
          '<span class="feedPrice">' +
          escapeHtml(
            marketClosedLabel(
              marketStatus
            )
          ) +
          '</span>' +
          '<span class="feedMeta">Showing latest completed Official PSX session · Active Main Board equities · ' +
          escapeHtml(
            updatedLabel
          ) +
          '</span>';
      } else {
        status.innerHTML =
          '<span class="feedDot delayed"></span>' +
          '<span class="feedPrice">Latest PSX snapshot</span>' +
          '<span class="feedMeta">Market status unavailable · ' +
          escapeHtml(
            updatedLabel
          ) +
          '</span>';
      }
    }
  } catch (error) {
    if (!marketRows.length) {
      $('error')
        .textContent =
          error.message;
    }

    if (status) {
      status.innerHTML =
        '<span class="feedDot delayed"></span>' +
        '<span class="feedWarning">Live refresh failed. Keeping the last successful market snapshot.</span>';
    }
  } finally {
    exploreRefreshInFlight =
      false;

    if ($('loadMarket')) {
      $('loadMarket')
        .disabled =
          false;
    }
  }
}

$('loadMarket')
  .onclick =
    () =>
      loadExploreMarket(
        true
      );

