function parseCsvLine(
  line
) {
  const output = [];
  let current = '';
  let quoted = false;

  for (
    let index = 0;
    index < line.length;
    index++
  ) {
    const char =
      line[index];

    if (char === '"') {
      if (
        quoted &&
        line[index + 1] === '"'
      ) {
        current += '"';
        index += 1;
      } else {
        quoted =
          !quoted;
      }

      continue;
    }

    if (
      char === ',' &&
      !quoted
    ) {
      output.push(
        current.trim()
      );
      current = '';
      continue;
    }

    current +=
      char;
  }

  output.push(
    current.trim()
  );

  return output;
}

function normalizeCsvHeader(
  value
) {
  return String(
    value ||
    ''
  )
    .trim()
    .toLowerCase()
    .replace(
      /[^a-z0-9]+/g,
      '_'
    )
    .replace(
      /^_+|_+$/g,
      ''
    );
}

function csvValue(
  row,
  keys
) {
  for (
    const key
    of keys
  ) {
    if (
      row[key] !==
        undefined &&
      row[key] !==
        null &&
      row[key] !==
        ''
    ) {
      return row[key];
    }
  }

  return '';
}

async function importPortfolioCsv(
  file
) {
  const text =
    await file.text();

  const lines =
    text
      .split(/\\r?\\n/)
      .filter(
        line =>
          line.trim()
      );

  if (lines.length < 2) {
    throw new Error(
      'CSV needs a header row and at least one data row.'
    );
  }

  const headers =
    parseCsvLine(
      lines[0]
    ).map(
      normalizeCsvHeader
    );

  const transactionMode =
    headers.some(
      header =>
        [
          'side',
          'type',
          'action',
          'transaction_type',
          'trade_type'
        ].includes(
          header
        )
    );

  let imported = 0;
  const errors = [];

  for (
    let index = 1;
    index < lines.length;
    index++
  ) {
    const values =
      parseCsvLine(
        lines[index]
      );

    const row = {};

    headers.forEach(
      (
        header,
        column
      ) => {
        row[header] =
          values[column] ||
          '';
      }
    );

    let action =
      'portfolio-holding';

    let payload;

    if (transactionMode) {
      action =
        'portfolio-transaction';

      payload = {
        side:
          csvValue(
            row,
            [
              'side',
              'type',
              'action',
              'transaction_type',
              'trade_type'
            ]
          ),
        symbol:
          csvValue(
            row,
            [
              'symbol',
              'ticker',
              'stock'
            ]
          ),
        quantity:
          csvValue(
            row,
            [
              'quantity',
              'qty',
              'shares'
            ]
          ) ||
          0,
        price:
          csvValue(
            row,
            [
              'price',
              'trade_price',
              'buy_price',
              'sell_price',
              'purchase_price'
            ]
          ) ||
          0,
        trade_date:
          csvValue(
            row,
            [
              'trade_date',
              'date',
              'purchase_date',
              'buy_date',
              'sell_date'
            ]
          ) ||
          null,
        fees:
          csvValue(
            row,
            [
              'fees',
              'fee',
              'charges',
              'brokerage'
            ]
          ) ||
          0,
        cash_amount:
          csvValue(
            row,
            [
              'cash_amount',
              'dividend_amount',
              'amount'
            ]
          ) ||
          0,
        notes:
          csvValue(
            row,
            [
              'notes',
              'note',
              'reference'
            ]
          ) ||
          ''
      };
    } else {
      payload = {
        symbol:
          csvValue(
            row,
            [
              'symbol',
              'ticker',
              'stock'
            ]
          ),
        quantity:
          csvValue(
            row,
            [
              'quantity',
              'qty',
              'shares'
            ]
          ),
        average_cost:
          csvValue(
            row,
            [
              'average_cost',
              'avg_cost',
              'cost',
              'buy_price',
              'purchase_price'
            ]
          ),
        purchase_date:
          csvValue(
            row,
            [
              'purchase_date',
              'buy_date',
              'date'
            ]
          ) ||
          null,
        fees:
          csvValue(
            row,
            [
              'fees',
              'fee'
            ]
          ) ||
          0
      };
    }

    try {
      await apiPost(
        action,
        payload
      );

      imported +=
        1;
    } catch (error) {
      errors.push(
        'Row ' +
        (index + 1) +
        ': ' +
        error.message
      );
    }
  }

  await loadDecisionCenter();

  return {
    imported,
    errors,
    mode:
      transactionMode
        ? 'transactions'
        : 'holdings'
  };
}

async function saveHoldingFromForm() {
  const button =
    $('saveHoldingButton');

  button.disabled =
    true;

  $('holdingFormStatus')
    .textContent =
      'Saving holding and checking its recent history...';

  try {
    await apiPost(
      'portfolio-holding',
      {
        symbol:
          $('holdingSymbol')
            .value,
        quantity:
          $('holdingQuantity')
            .value,
        average_cost:
          $('holdingAverageCost')
            .value,
        purchase_date:
          $('holdingPurchaseDate')
            .value ||
          null,
        fees:
          $('holdingFees')
            .value ||
          0
      }
    );

    closePortfolioModal();
    await loadDecisionCenter();
  } catch (error) {
    $('holdingFormStatus')
      .textContent =
        error.message;
  } finally {
    button.disabled =
      false;
  }
}

