function renderOpportunityBoard(
  result
) {
  const board =
    result?.opportunityBoard ||
    {};
  const isShortTerm =
    result?.input?.horizon ===
      'short_term';

  const priority1 =
    board.priority1 ||
    [];
  const priority2 =
    board.priority2 ||
    [];
  const research =
    board.evidenceResearch ||
    board.researchRequired ||
    [];
  const avoid =
    board.avoid ||
    [];

  const allocationSymbols =
    new Set(
      (result?.allocations || [])
        .map(item => item?.symbol)
        .filter(Boolean)
    );

  const fundedTriggerBySymbol =
    new Map(
      (result?.shortTermTriggerPlan?.plans || [])
        .filter(item => item?.symbol)
        .map(item => [item.symbol, item])
    );

  const unfundedTriggerBySymbol =
    new Map(
      (result?.shortTermTriggerPlan?.unfunded || [])
        .filter(item => item?.symbol)
        .map(item => [item.symbol, item])
    );

  const personalActionBySymbol =
    new Map(
      (result?.allocationDiagnostics?.personalActions || [])
        .filter(item => item?.symbol)
        .map(item => [item.symbol, item])
    );

  const decoratePersonalAction =
    item => {
      if (!isShortTerm || !item?.symbol) {
        return item;
      }

      const personal =
        personalActionBySymbol.get(
          item.symbol
        );
      const fundedTrigger =
        fundedTriggerBySymbol.get(
          item.symbol
        ) || null;
      const unfundedTrigger =
        unfundedTriggerBySymbol.get(
          item.symbol
        ) || null;

      let displayProfileAction =
        null;

      if (result?.shortTermStability?.ok === false) {
        displayProfileAction = 'WAIT_DATA';
      } else if (allocationSymbols.has(item.symbol)) {
        displayProfileAction =
          item?.shortTermExecution?.action === 'BUY_SMALL'
            ? 'BUY_SMALL'
            : 'BUY';
      } else if (personal?.portfolioAction) {
        displayProfileAction =
          personal.portfolioAction;
      } else if (fundedTrigger) {
        displayProfileAction =
          'FUNDED_TRIGGER';
      } else if (
        item?.shortTermExecution
          ?.reservationEligible === true
      ) {
        displayProfileAction =
          'READY_UNFUNDED';
      } else if (
        item?.shortTermExecution
          ?.actionableNow === true
      ) {
        displayProfileAction =
          'PASS';
      } else if (item?.shortTermExecution?.action) {
        displayProfileAction =
          item.shortTermExecution.action;
      }

      return {
        ...item,
        displayProfileAction,
        fundedTrigger,
        unfundedTrigger
      };
    };

  const priority1Display =
    priority1.map(decoratePersonalAction);
  const priority2Display =
    priority2.map(decoratePersonalAction);
  const researchDisplay =
    research.map(decoratePersonalAction);
  const avoidDisplay =
    avoid.map(decoratePersonalAction);

  if ($('priorityOneEyebrow')) {
    $('priorityOneEyebrow').textContent =
      isShortTerm ? 'ACTION NOW' : 'PRIORITY 1';
  }
  if ($('priorityOneTitle')) {
    $('priorityOneTitle').textContent =
      isShortTerm ? 'Active market setups' : 'Best current opportunities';
  }
  if ($('priorityTwoEyebrow')) {
    $('priorityTwoEyebrow').textContent =
      isShortTerm ? 'READY SETUPS' : 'PRIORITY 2';
  }
  if ($('priorityTwoTitle')) {
    $('priorityTwoTitle').textContent =
      isShortTerm ? 'Complete plans waiting for trigger' : 'Next best opportunities';
  }
  if ($('researchEyebrow')) {
    $('researchEyebrow').textContent =
      isShortTerm ? 'DEVELOPING / RESEARCH' : 'EVIDENCE RESEARCH';
  }
  if ($('researchTitle')) {
    $('researchTitle').textContent =
      isShortTerm ? 'Interesting, but setup not complete' : 'NOMAD is investigating missing evidence';
  }
  if ($('avoidEyebrow')) {
    $('avoidEyebrow').textContent =
      isShortTerm ? 'AVOID / INVALID' : 'LOW PRIORITY / AVOID';
  }
  if ($('avoidTitle')) {
    $('avoidTitle').textContent =
      isShortTerm ? 'Do not trade these setups now' : 'Not attractive enough now';
  }

  renderOpportunityList(
    'priorityOneList',
    priority1Display,
    isShortTerm
      ? 'No active market setup right now.'
      : 'No company currently earns Priority 1 under the tiered analyst-evidence gate.'
  );

  renderOpportunityList(
    'priorityTwoList',
    priority2Display,
    isShortTerm
      ? 'No ready setup right now.'
      : 'No Priority 2 opportunity currently stands out.'
  );

  renderOpportunityList(
    'researchRequiredList',
    researchDisplay,
    isShortTerm
      ? 'No developing setup right now.'
      : 'No shortlisted company is currently in automatic evidence research.'
  );

  renderOpportunityList(
    'avoidList',
    avoidDisplay,
    isShortTerm
      ? 'No avoid setup right now.'
      : 'No evidence-backed avoid candidate in the current deep shortlist.'
  );

  if ($('priorityOneCount')) {
    $('priorityOneCount').textContent =
      priority1.length;
  }
  if ($('priorityTwoCount')) {
    $('priorityTwoCount').textContent =
      priority2.length;
  }
  if ($('researchRequiredCount')) {
    $('researchRequiredCount').textContent =
      research.length;
  }
  if ($('avoidCount')) {
    $('avoidCount').textContent =
      avoid.length;
  }
}

