function classifyClientTriggerPrice(current, low, high, stop) {
  const price = Number(current);
  const entryLow = Number(low);
  const entryHigh = Number(high);
  const invalidation = Number(stop);

  if (!Number.isFinite(price) || !Number.isFinite(entryLow) || !Number.isFinite(entryHigh)) {
    return { status: 'waiting', label: 'Waiting for live price', distance: '' };
  }
  if (Number.isFinite(invalidation) && price <= invalidation) {
    return { status: 'invalidated', label: 'Invalidated', distance: 'Price is at or below the stop level' };
  }
  if (price >= entryLow && price <= entryHigh) {
    return { status: 'triggered', label: 'Entry zone active', distance: 'Entry zone reached' };
  }
  if (price < entryLow) {
    const pct = ((entryLow - price) / Math.max(price, 0.0001)) * 100;
    return {
      status: pct <= 1.5 ? 'near_trigger' : 'waiting',
      label: pct <= 1.5 ? 'Near trigger' : 'Waiting below trigger',
      distance: formatNumber(pct, 2) + '% below trigger'
    };
  }
  const pct = ((price - entryHigh) / Math.max(entryHigh, 0.0001)) * 100;
  return {
    status: pct <= 1 ? 'triggered' : 'above_entry_zone',
    label: pct <= 1 ? 'Entry still valid' : 'Above entry zone — do not chase',
    distance: formatNumber(pct, 2) + '% above entry zone'
  };
}

async function refreshDecisionTriggerStates() {
  const cards =
    [...document.querySelectorAll('[data-trigger-symbol]')];

  if (!cards.length || document.visibilityState !== 'visible') {
    return;
  }

  try {
    const market =
      await api('market');
    const rows =
      Array.isArray(market?.liveMarketRows)
        ? market.liveMarketRows
        : [];
    const bySymbol =
      new Map(
        rows.map(
          row => [
            String(row.canonicalSymbol || row.symbol || '').toUpperCase(),
            Number(row.price)
          ]
        )
      );

    cards.forEach(
      card => {
        const symbol =
          String(card.dataset.triggerSymbol || '').toUpperCase();
        const current =
          bySymbol.get(symbol);

        if (!Number.isFinite(current)) {
          return;
        }

        const state =
          classifyClientTriggerPrice(
            current,
            card.dataset.triggerLow,
            card.dataset.triggerHigh,
            card.dataset.triggerStop
          );

        card.classList.remove(
          'waiting',
          'near_trigger',
          'triggered',
          'invalidated',
          'above_entry_zone'
        );
        card.classList.add(state.status);

        const status =
          card.querySelector('[data-trigger-status]');
        if (status) {
          status.className =
            'triggerStatus ' + state.status;
          status.textContent =
            state.label;
        }

        const currentTarget =
          card.querySelector('[data-trigger-current]');
        if (currentTarget) {
          currentTarget.textContent =
            'PKR ' + formatNumber(current, 2);
        }

        const distanceTarget =
          card.querySelector('[data-trigger-distance]');
        if (distanceTarget) {
          distanceTarget.textContent =
            state.distance;
        }
      }
    );
  } catch {}
}

function startDecisionTriggerMonitor() {
  if (decisionTriggerRefreshTimer) {
    clearInterval(decisionTriggerRefreshTimer);
    decisionTriggerRefreshTimer = null;
  }

  if (!document.querySelector('[data-trigger-symbol]')) {
    return;
  }

  refreshDecisionTriggerStates();
  decisionTriggerRefreshTimer =
    setInterval(
      refreshDecisionTriggerStates,
      30000
    );
}


function syncOpportunityLayout() {
  const grid = document.querySelector('.opportunityBoardGrid');
  if (!grid) return;
  const pairs = [
    ['priorityOneCount', '.priorityOneCard'],
    ['priorityTwoCount', '.priorityTwoCard'],
    ['researchRequiredCount', '.researchCard'],
    ['avoidCount', '.avoidCard']
  ];
  let visible = 0;
  for (const [countId, selector] of pairs) {
    const count = Number(document.getElementById(countId)?.textContent || 0);
    const card = grid.querySelector(selector);
    if (!card) continue;
    const empty = !Number.isFinite(count) || count <= 0;
    card.classList.toggle('isEmptyOpportunity', empty);
    if (!empty) visible += 1;
  }
  grid.dataset.visibleSections = String(visible);
}

function renderShadowDecision(
  result
) {
  const target =
    $('decisionResult');

  if (!target) {
    return;
  }

  if (!result?.decision) {
    target.innerHTML =
      '<strong>Decision engine returned no result.</strong>';
    return;
  }

  const decision =
    result.decision;

  const decisionVerdictTitle =
    $('decisionVerdictTitle');

  if (decisionVerdictTitle) {
    const horizonLabel =
      result?.input?.horizon === 'short_term'
        ? 'Short-term'
        : 'Long-term';
    const riskLabel =
      String(
        result?.input?.risk ||
        'balanced'
      )
        .replace(/_/g, ' ')
        .replace(
          /\b\w/g,
          character => character.toUpperCase()
        );

    decisionVerdictTitle.textContent =
      'What NOMAD will do — ' +
      horizonLabel +
      ' / ' +
      riskLabel;
  }

  const allocations =
    Array.isArray(
      result.allocations
    )
      ? result.allocations
      : [];

  // 0.9.6.16.3: expose the active capital-plan allocation to the lower
  // opportunity cards so funded Priority 1 names repeat the exact share count.
  decisionFundedAllocationBySymbol =
    new Map(
      allocations
        .filter(item => item?.symbol)
        .map(item => [
          String(item.symbol).trim().toUpperCase(),
          item
        ])
    );

  const executionCeilings = {};
  for (const allocation of allocations) {
    const ceiling = Number(
      allocation?.executionGuidance
        ?.maxAcceptablePrice
    );
    const symbol = String(
      allocation?.symbol ||
      ''
    )
      .trim()
      .toUpperCase();
    if (symbol && Number.isFinite(ceiling) && ceiling > 0) {
      executionCeilings[symbol] = {
        maxBuyPrice: ceiling,
        horizon: result?.input?.horizon || null,
        risk: result?.input?.risk || null,
        recordedAt: new Date().toISOString()
      };
    }
  }
  if (Object.keys(executionCeilings).length) {
    latestNomadExecutionCeilings = executionCeilings;
    try {
      localStorage.setItem(
        'nomadExecutionCeilingsV1',
        JSON.stringify(
          latestNomadExecutionCeilings
        )
      );
    } catch {}
  }

  const triggerPlan =
    result?.shortTermTriggerPlan ||
    null;

  const isShortTermDecision =
    result?.input?.horizon === 'short_term';

  let html =
    '<div class="decisionShadowBanner">SHADOW</div>' +
    '<div class="decisionOutcome">' +
    '<div><strong>' +
    escapeHtml(
      decisionActionLabel(
        decision.action
      )
    ) +
    '</strong><div class="decisionMinor">' +
    escapeHtml(
      decision.headline ||
      ''
    ) +
    '</div></div>' +
    '<span>' +
    (
      result?.input?.horizon === 'short_term'
        ? 'Evidence ' +
          escapeHtml(decision.evidence?.confidence || 'UNRESOLVED') +
          ' · Plan ' +
          escapeHtml(decision.evidence?.setupCompleteness || 'INCOMPLETE')
        : 'Evidence ' +
          escapeHtml(decision.evidence?.confidence || 'UNRESOLVED')
    ) +
    '</span>' +
    '</div>' +
    '<div class="decisionMoneyLine ' +
    (isShortTermDecision ? 'shortTermMoneyLine' : '') +
    '">' +
    '<div><span>Requested</span><strong>PKR ' +
    formatNumber(
      result.input?.amount ||
      0,
      0
    ) +
    '</strong></div>' +
    '<div class="moneyAction"><span>Buy now</span><strong>PKR ' +
    formatNumber(
      decision.amountInvestedPkr ||
      0,
      0
    ) +
    '</strong></div>' +
    (isShortTermDecision
      ? '<div class="moneyTrigger"><span>Reserved for triggers</span><strong>PKR ' +
        formatNumber(
          triggerPlan?.plannedCapitalPkr ||
          0,
          0
        ) +
        '</strong></div><div class="moneyCash"><span>Free cash</span><strong>PKR ' +
        formatNumber(
          triggerPlan?.uncommittedCapitalPkr ??
          decision.cashRemainingPkr ??
          0,
          0
        ) +
        '</strong></div>'
      : '<div class="moneyCash"><span>Cash retained</span><strong>PKR ' +
        formatNumber(
          decision.cashRemainingPkr ||
          0,
          0
        ) +
        '</strong></div>') +
    '</div>' +
    '<div class="decisionQuickWhy">' +
    '<strong>Why this plan</strong>' +
    '<span>' +
    escapeHtml(
      isShortTermDecision
        ? ((triggerPlan?.fundedCount ?? triggerPlan?.count ?? 0) + ' funded trigger plan' + ((triggerPlan?.fundedCount ?? triggerPlan?.count ?? 0) === 1 ? '' : 's') + ' · ' + (triggerPlan?.technicalReadyCount ?? triggerPlan?.readyCount ?? result?.screening?.conditionalSetups ?? 0) + ' ready setup' + ((triggerPlan?.technicalReadyCount ?? triggerPlan?.readyCount ?? result?.screening?.conditionalSetups ?? 0) === 1 ? '' : 's') + ' · ' + (decision.amountInvestedPkr > 0 ? 'entry valid now' : 'no buy-now entry'))
        : ((allocations.length || 0) + ' funded position' + (allocations.length === 1 ? '' : 's') + ' · ' + formatNumber(decision.cashRemainingPkr || 0, 0) + ' PKR retained')
    ) +
    '</span>' +
    '</div>' +
    '<details class="decisionMethodDetails"><summary>Why / methodology</summary><div class="decisionMethodBody">' +
    '<div class="decisionLeadReason">' +
    escapeHtml(decision.reason || '') +
    '</div>';

  if (
    result?.input?.sector
  ) {
    html +=
      '<div class="decisionMetaLine"><strong>Industry-constrained plan:</strong> ' +
      escapeHtml(
        result.input.sector
      ) +
      ' only. NOMAD ranks, researches and allocates within this industry; normal cross-sector diversification is intentionally disabled, while stock-level evidence, profile suitability and sizing gates remain active.</div>';
  }

  if (
    result?.allocationDiagnostics
      ?.portfolioAware
  ) {
    html +=
      '<div class="decisionMetaLine"><strong>Portfolio-aware allocation:</strong> NOMAD considered your existing portfolio value of PKR ' +
      formatNumber(
        result.allocationDiagnostics
          .existingPortfolioValuePkr ||
        0,
        0
      ) +
      ' before applying stock and sector caps to this new capital.</div>';
  }

  if (
    result?.allocationDiagnostics
      ?.targetPositionCount
  ) {
    html +=
      '<div class="decisionMetaLine"><strong>Portfolio construction:</strong> target ' +
      formatNumber(
        result.allocationDiagnostics
          .targetPositionCount ||
        0,
        0
      ) +
      ' positions (minimum target ' +
      formatNumber(
        result.allocationDiagnostics
          .minimumTargetPositions ||
        3,
        0
      ) +
      ', maximum ' +
      formatNumber(
        result.allocationDiagnostics
          .maximumTargetPositions ||
        8,
        0
      ) +
      '); ' +
      formatNumber(
        result.allocationDiagnostics
          .eligibleAllocationCandidates ||
        0,
        0
      ) +
      ' currently pass the allocation gate (' +
      formatNumber(
        result.allocationDiagnostics
          .priorityOneAllocationCandidates ||
        0,
        0
      ) +
      ' Priority 1 + ' +
      formatNumber(
        result.allocationDiagnostics
          .priorityTwoAllocationCandidates ||
        0,
        0
      ) +
      ' actionable Priority 2). Current caps: ' +
      formatNumber(
        result.allocationDiagnostics
          .dynamicMaxStockPct ||
        0,
        1
      ) +
      '% per stock and ' +
      formatNumber(
        result.allocationDiagnostics
          .dynamicMaxSectorPct ||
        0,
        1
      ) +
      '% per sector. ' +
      (
        result.allocationDiagnostics
          .smallCapitalWholeShareMode
          ? 'Small-capital whole-share mode is active: the fixed PKR 1,000 position floor is disabled, while whole-share affordability and all risk/portfolio caps remain active.'
          : 'Minimum meaningful new-money position: PKR ' +
            formatNumber(
              result.allocationDiagnostics
                .minimumMeaningfulPositionPkr ||
              0,
              0
            ) +
            '.'
      ) +
      '</div>';

    if (
      result?.allocationDiagnostics
        ?.targetDeploymentPct !==
        undefined
    ) {
      html +=
        '<div class="decisionMetaLine"><strong>Intentional deployment:</strong> target ' +
        formatNumber(
          result.allocationDiagnostics
            .targetDeploymentPct ||
          0,
          1
        ) +
        '% deployed · deliberate cash reserve ' +
        formatNumber(
          result.allocationDiagnostics
            .intentionalCashReservePct ||
          0,
          1
        ) +
        '% · average conviction ' +
        formatNumber(
          result.allocationDiagnostics
            .averageConvictionScore ||
          0,
          1
        ) +
        '/100. ' +
        escapeHtml(
          result.allocationDiagnostics
            .cashReserveReason ||
          ''
        ) +
        '</div>';
    }

    if (
      result?.screening
        ?.actionableResearchTarget
    ) {
      html +=
        '<div class="decisionMetaLine"><strong>Capital-efficiency search:</strong> NOMAD continued deeper research until it found ' +
        formatNumber(
          result.screening
            .actionableProfileFit ||
          0,
          0
        ) +
        ' profile-suitable actionable ideas against a research target of ' +
        formatNumber(
          result.screening
            .actionableResearchTarget ||
          0,
          0
        ) +
        ', or exhausted the bounded deep-research budget. Cash is retained only after that search; WATCH, unresolved evidence and profile failures still receive PKR 0.</div>';
    }

    if (
      result.allocationDiagnostics
        ?.diversificationException
        ?.triggered
    ) {
      html +=
        '<div class="decisionMetaLine"><strong>Diversification exception:</strong> ' +
        escapeHtml(
          result.allocationDiagnostics
            .diversificationException
            .reason ||
          'The minimum three-stock diversification target could not be reached without weakening the professional allocation gates.'
        ) +
        '</div>';
    }
  }

  html +=
    '</div></details>';

  if (allocations.length) {
    html +=
      '<div class="decisionMetaLine allocationNote">Whole-share implementation · PSX regular-market equities use a one-share marketable lot; NOMAD additionally avoids economically trivial positions.</div>';

    html +=
      allocations.map(
        item =>
          '<div class="decisionAllocationRow">' +
          '<div class="decisionSymbol">' +
          escapeHtml(
            item.symbol
          ) +
          '</div>' +
          '<div><strong>' +
          formatNumber(
            item.shares,
            0
          ) +
          ' share' +
          (
            Number(
              item.shares
            ) === 1
              ? ''
              : 's'
          ) +
          ' · PKR ' +
          formatNumber(
            item.principalPkr,
            0
          ) +
          '</strong><div class="decisionMinor">' +
          escapeHtml(
            item.companyName ||
            ''
          ) +
          (
            item.postPortfolioWeightPct !==
              undefined &&
            item.postPortfolioWeightPct !==
              null
              ? ' · post-portfolio ' +
                formatNumber(
                  item.postPortfolioWeightPct,
                  1
                ) +
                '%'
              : ''
          ) +
          (
            item.executionGuidance
              ? ' · ' +
                escapeHtml(
                  decisionActionLabel(
                    item.executionGuidance.status ||
                    'WAIT'
                  )
                ) +
                (
                  item.executionGuidance.orderType === 'LIMIT' &&
                  item.executionGuidance.maxAcceptablePrice !== null &&
                  item.executionGuidance.maxAcceptablePrice !== undefined
                    ? ' · ' + (result?.input?.horizon === 'long_term' ? 'MAX BUY ≤ PKR ' : 'LIMIT ≤ PKR ') +
                      formatNumber(
                        item.executionGuidance.maxAcceptablePrice,
                        2
                      )
                    : ''
                )
              : ''
          ) +
          (
            item.traderPlan
              ? ' · setup ' +
                escapeHtml(
                  item.traderPlan.setup ||
                  'DEFINED'
                ) +
                (
                  item.traderPlan.stop !== null &&
                  item.traderPlan.stop !== undefined
                    ? ' · stop PKR ' +
                      formatNumber(
                        item.traderPlan.stop,
                        2
                      )
                    : ''
                ) +
                (
                  item.traderPlan.target1 !== null &&
                  item.traderPlan.target1 !== undefined
                    ? ' · target PKR ' +
                      formatNumber(
                        item.traderPlan.target1,
                        2
                      )
                    : ''
                ) +
                (
                  item.traderPlan.rewardRisk !== null &&
                  item.traderPlan.rewardRisk !== undefined
                    ? ' · R/R ' +
                      formatNumber(
                        item.traderPlan.rewardRisk,
                        2
                      ) + 'x'
                    : ''
                ) +
                (
                  item.traderPlan.riskBudgetPct !== null &&
                  item.traderPlan.riskBudgetPct !== undefined
                    ? ' · risk budget ' +
                      formatNumber(
                        item.traderPlan.riskBudgetPct,
                        2
                      ) + '%'
                    : ''
                )
              : ''
          ) +
          '</div></div>' +
          '<div class="allocationActionStack"><div class="decisionActionTag ' +
          escapeHtml(
            String(
              item.action ||
              ''
            ).toLowerCase()
          ) +
          '">' +
          escapeHtml(
            decisionActionLabel(
              item.action
            )
          ) +
          '</div>' +
          (
            result?.input?.horizon === 'long_term' &&
            item.executionGuidance?.orderType === 'LIMIT' &&
            Number(item.shares) > 0
              ? '<div class="allocationSuggestedLimit"><span>SUGGESTED LIMIT</span><strong>' +
                (
                  Number.isFinite(Number(item.executionGuidance.suggestedLimitPrice)) &&
                  Number(item.executionGuidance.suggestedLimitPrice) > 0
                    ? 'PKR ' + formatNumber(item.executionGuidance.suggestedLimitPrice, 2)
                    : 'Unavailable'
                ) +
                '</strong><em>' +
                escapeHtml(
                  item.executionGuidance.suggestedLimitStatus === 'AVAILABLE'
                    ? 'Preferred bid · not guaranteed'
                    : 'MAX BUY is not the bid'
                ) + '</em></div>'
              : ''
          ) +
          (
            item.executionGuidance?.orderType === 'LIMIT' &&
            item.executionGuidance?.maxAcceptablePrice !== null &&
            item.executionGuidance?.maxAcceptablePrice !== undefined
              ? '<div class="allocationMaxBuy"><span>MAX BUY PRICE</span><strong>PKR ' +
                formatNumber(
                  item.executionGuidance.maxAcceptablePrice,
                  2
                ) +
                '</strong><em>DO NOT EXCEED</em></div>'
              : ''
          ) +
          '</div></div>'
      ).join('');
  } else {
    html +=
      '<div class="decisionMetaLine allocationNote">No capital is allocated unless a canonical BUY or ACCUMULATE state has allocation permission and at least one whole share fits the portfolio/risk limits.</div>';
  }

  if (
    result?.input?.horizon === 'short_term' &&
    triggerPlan?.plans?.length
  ) {
    const closest =
      triggerPlan.plans[0];

    html +=
      '<div class="closestTriggerCard">' +
      '<div><span>Closest setup</span><strong>' +
      escapeHtml(closest.symbol || '') +
      '</strong></div>' +
      '<div><span>Current</span><strong>PKR ' +
      formatNumber(closest.currentPrice, 2) +
      '</strong></div>' +
      '<div class="highlightTrigger"><span>Entry</span><strong>PKR ' +
      formatNumber(closest.entryLow, 2) + '–' + formatNumber(closest.entryHigh, 2) +
      '</strong></div>' +
      '<div><span>Status</span><strong>' +
      escapeHtml(closest.triggerLabel || 'Waiting') +
      '</strong></div>' +
      '<div><span>Reserved</span><strong>PKR ' +
      formatNumber(closest.plannedPrincipalPkr || 0, 0) +
      ' · ' + formatNumber(closest.shares || 0, 0) +
      ' shares</strong></div>' +
      '</div>';
  }

  const unfunded =
    result?.allocationDiagnostics
      ?.unfundedPriorityOne ||
    [];

  if (unfunded.length) {
    html +=
      '<div class="decisionMetaLine"><strong>Priority 1 not fitted:</strong> ' +
      unfunded.map(
        item =>
          escapeHtml(
            item.symbol
          )
      ).join(', ') +
      '. NOMAD kept these ranked instead of replacing them with weaker cheaper stocks.</div>';
  }

  const personalActions =
    result?.allocationDiagnostics
      ?.personalActions ||
    [];

  const existingPortfolioActions =
    personalActions.filter(
      item =>
        Number(
          item.existingWeightPct ||
          0
        ) > 0
    );

  if (existingPortfolioActions.length) {
    html +=
      '<div class="decisionMetaLine"><strong>Your holdings changed the recommendation:</strong> ' +
      existingPortfolioActions
        .slice(0, 5)
        .map(
          item =>
            escapeHtml(
              item.symbol
            ) +
            ' = ' +
            escapeHtml(
              decisionActionLabel(
                item.portfolioAction
              )
            )
        )
        .join(' · ') +
      '.</div>';
  }

  html +=
    '<div class="decisionMetaLine">Model ' +
    escapeHtml(
      result.model?.id ||
      'N/A'
    ) +
    ' · ' +
    escapeHtml(
      result.riskPolicy?.id ||
      ''
    ) +
    ' · ' +
    (
      result.recording?.recorded
        ? 'recorded for accountability'
        : 'not recorded: ' +
          escapeHtml(
            result.recording?.reason ||
            'decision tables unavailable'
          )
    ) +
    '</div>' +
    '<div class="decisionMetaLine">Execution guidance now uses LIMIT ceilings and no-chase/invalidation guards. Brokerage, taxes and exchange charges are not included yet; confirm the final order cost before execution. This remains shadow decision intelligence.</div>';

  target.innerHTML =
    html;

  startDecisionTriggerMonitor();

  renderOwnershipContinuity(
    result
  );

  renderOpportunityBoard(
    result
  );

  syncOpportunityLayout();

  renderDecisionAudit(
    result
  );

  const summary =
    homeDecisionSummaryData(
      result
    );

  try {
    localStorage.setItem(
      'nomadLastDecisionSummary',
      JSON.stringify(
        summary
      )
    );
  } catch {}

  renderHomeDecisionSummary(
    summary
  );
}

