if ($('findBestOption')) {
  $('findBestOption')
    .onclick =
      async () => {
        const button =
          $('findBestOption');

        const amount =
          Number(
            String(
              $('decisionAmount')
                .value ||
              ''
            ).replace(
              /,/g,
              ''
            )
          );

        const context = {
          amount:
            Number.isFinite(amount) &&
            amount > 0
              ? amount
              : 5000,
          horizon:
            $('decisionHorizon')
              .value,
          risk:
            $('decisionRisk')
              .value,
          sector:
            $('decisionSector')
              ?.value ||
            ''
        };

        if ($('strategyHorizon')) {
          $('strategyHorizon').value = context.horizon;
        }
        if ($('strategyRisk')) {
          $('strategyRisk').value = context.risk;
        }

        localStorage.setItem(
          'nomadDecisionContext',
          JSON.stringify(
            context
          )
        );

        const originalText =
          button.textContent;

        button.disabled =
          true;

        button.textContent =
          'Analyzing PSX...';

        if ($('decisionVerdictTitle')) {
          const horizonLabel =
            context.horizon === 'short_term'
              ? 'Short-term'
              : 'Long-term';
          const riskLabel =
            String(context.risk || 'balanced')
              .replace(/_/g, ' ')
              .replace(/\b\w/g, character => character.toUpperCase());
          $('decisionVerdictTitle').textContent =
            'Analyzing — ' +
            horizonLabel +
            ' / ' +
            riskLabel;
        }

        $('decisionResult')
          .innerHTML =
            '<div class="decisionShadowBanner">SHADOW</div>' +
            '<strong>Analyzing PSX opportunities...</strong><br>' +
            '<span class="decisionMinor">Checking evidence, suitability and allocation.</span>';

        try {
          const result =
            await apiPost(
              'decision-lab',
              context
            );

          renderShadowDecision(
            result
          );
        } catch (error) {
          if ($('decisionVerdictTitle')) {
            const horizonLabel =
              context.horizon === 'short_term'
                ? 'Short-term'
                : 'Long-term';
            const riskLabel =
              String(context.risk || 'balanced')
                .replace(/_/g, ' ')
                .replace(/\b\w/g, character => character.toUpperCase());
            $('decisionVerdictTitle').textContent =
              'Analysis failed — ' +
              horizonLabel +
              ' / ' +
              riskLabel;
          }
          $('decisionResult')
            .innerHTML =
              '<strong>Decision engine unavailable.</strong><br>' +
              escapeHtml(
                error.message ||
                'The decision request failed.'
              ) +
              '<br>NOMAD did not substitute a guess.';
        } finally {
          button.disabled =
            false;

          button.textContent =
            originalText;
        }
      };
}

